module its_xlate #(
    parameter DEV_ENTRIES = 16,
    parameter CQ_DEPTH = 16,
    parameter DW = 64,
    parameter DEVW = 4,
    parameter AW = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            cmd_valid,
    output wire            cmd_ready,
    input  wire [1:0]      cmd_op,
    input  wire [DEVW-1:0] cmd_dev,
    input  wire [DW-1:0]   cmd_base,
    input  wire [DW-1:0]   cmd_coll,
    input  wire            exec_en,
    input  wire            req_valid,
    output wire            req_ready,
    input  wire [DEVW-1:0] req_dev,
    input  wire [DW-1:0]   req_event,
    output reg             out_valid,
    input  wire            out_ready,
    output reg  [DW-1:0]   out_intid,
    output reg  [DW-1:0]   out_coll,
    output reg  [DW-1:0]   xlat_count,
    output reg  [DW-1:0]   miss_count
);
    localparam [1:0] OP_MAPD = 2'd1;
    localparam [1:0] OP_UNMAPD = 2'd2;

    reg [1:0]      cq_op   [0:CQ_DEPTH-1];
    reg [DEVW-1:0] cq_dev  [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_base [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_coll [0:CQ_DEPTH-1];
    reg [AW:0]     wptr;
    reg [AW:0]     rptr;

    reg [DEV_ENTRIES-1:0] dev_valid;
    reg [DW-1:0]   dt_base [0:DEV_ENTRIES-1];
    reg [DW-1:0]   dt_coll [0:DEV_ENTRIES-1];

    reg seen_map;

    wire [AW:0] cq_count = wptr - rptr;
    assign cmd_ready = (cq_count != CQ_DEPTH);
    assign req_ready = !out_valid || out_ready;

    wire [1:0]      ex_op   = cq_op[rptr[AW-1:0]];
    wire [DEVW-1:0] ex_dev  = cq_dev[rptr[AW-1:0]];
    wire [DW-1:0]   ex_base = cq_base[rptr[AW-1:0]];
    wire [DW-1:0]   ex_coll = cq_coll[rptr[AW-1:0]];

    integer i;
    initial begin
        wptr = 0;
        rptr = 0;
        dev_valid = 0;
        seen_map = 1'b0;
        out_valid = 1'b0;
        out_intid = 0;
        out_coll = 0;
        xlat_count = 0;
        miss_count = 0;
        for (i = 0; i < CQ_DEPTH; i = i + 1) begin
            cq_op[i] = 0;
            cq_dev[i] = 0;
            cq_base[i] = 0;
            cq_coll[i] = 0;
        end
        for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
            dt_base[i] = 0;
            dt_coll[i] = 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= 0;
            rptr <= 0;
            dev_valid <= 0;
            seen_map <= 1'b0;
            out_valid <= 1'b0;
            out_intid <= 0;
            out_coll <= 0;
            xlat_count <= 0;
            miss_count <= 0;
            for (i = 0; i < CQ_DEPTH; i = i + 1) begin
                cq_op[i] <= 0;
                cq_dev[i] <= 0;
                cq_base[i] <= 0;
                cq_coll[i] <= 0;
            end
            for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
                dt_base[i] <= 0;
                dt_coll[i] <= 0;
            end
        end else begin
            if (cmd_valid && cmd_ready) begin
                cq_op[wptr[AW-1:0]]   <= cmd_op;
                cq_dev[wptr[AW-1:0]]  <= cmd_dev;
                cq_base[wptr[AW-1:0]] <= cmd_base;
                cq_coll[wptr[AW-1:0]] <= cmd_coll;
                wptr <= wptr + 1'b1;
            end
            if (exec_en && (cq_count != 0)) begin
                if (ex_op == OP_MAPD) begin
                    dev_valid[ex_dev] <= 1'b1;
                    dt_base[ex_dev] <= ex_base;
                    dt_coll[ex_dev] <= ex_coll;
                    seen_map <= 1'b1;
                end else if (ex_op == OP_UNMAPD) begin
                    dev_valid[ex_dev] <= 1'b0;
                end
                rptr <= rptr + 1'b1;
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
            if (req_valid && req_ready) begin
                if (dev_valid[req_dev]) begin
                    out_valid <= 1'b1;
                    out_intid <= dt_base[req_dev] + req_event;
                    out_coll <= dt_coll[req_dev];
                    xlat_count <= xlat_count + 1'b1;
                end else begin
                    miss_count <= miss_count + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (xlat_count != {DW{1'b0}}) assert (seen_map);
endmodule

module sw_reset_ctrl #(
    parameter NPERIPH = 4,
    parameter IDXW = 2,
    parameter [31:0] PULSE_LEN = 32'd8
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               cmd_valid,
    output wire               cmd_ready,
    input  wire [1:0]         cmd_op,
    input  wire [IDXW-1:0]    cmd_idx,
    input  wire               tick,
    output wire [NPERIPH-1:0] periph_rst,
    output wire               pulse_busy
);
    typedef enum logic [1:0] {IDLE = 2'd0, PULSE = 2'd1} state_t;

    localparam [1:0] OP_SET   = 2'd0;
    localparam [1:0] OP_CLR   = 2'd1;
    localparam [1:0] OP_PULSE = 2'd2;

    state_t            state     = IDLE;
    reg [NPERIPH-1:0]  rst_ctrl  = {NPERIPH{1'b0}};
    reg [31:0]         n_held    = 32'd0;
    reg [31:0]         pulse_cnt = 32'd0;
    reg [31:0]         remain    = 32'd0;
    reg [IDXW-1:0]     pulse_idx = {IDXW{1'b0}};
    reg                win       = 1'b0;

    assign cmd_ready = (state == IDLE) || (cmd_op != OP_PULSE);
    wire fire     = cmd_valid && cmd_ready;
    wire do_set   = fire && (cmd_op == OP_SET) && !rst_ctrl[cmd_idx];
    wire do_clr   = fire && (cmd_op == OP_CLR) &&  rst_ctrl[cmd_idx];
    wire do_pulse = fire && (cmd_op == OP_PULSE);

    assign pulse_busy = (state == PULSE);
    assign periph_rst = rst_ctrl | ((state == PULSE) ? ({{(NPERIPH-1){1'b0}}, 1'b1} << pulse_idx) : {NPERIPH{1'b0}});

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            rst_ctrl  <= {NPERIPH{1'b0}};
            n_held    <= 32'd0;
            pulse_cnt <= 32'd0;
            remain    <= 32'd0;
            pulse_idx <= {IDXW{1'b0}};
            win       <= 1'b0;
        end else begin
            if (do_set) begin
                rst_ctrl[cmd_idx] <= 1'b1;
                n_held <= n_held + 32'd1;
            end else if (do_clr) begin
                rst_ctrl[cmd_idx] <= 1'b0;
                n_held <= n_held - 32'd1;
            end
            case (state)
                IDLE: begin
                    if (do_pulse) begin
                        state     <= PULSE;
                        win       <= 1'b1;
                        pulse_cnt <= 32'd0;
                        remain    <= PULSE_LEN - 32'd1;
                        pulse_idx <= cmd_idx;
                    end
                end
                PULSE: begin
                    if (tick) begin
                        if (remain == 32'd0) begin
                            state <= IDLE;
                            win   <= 1'b0;
                        end else begin
                            pulse_cnt <= pulse_cnt + 32'd1;
                            remain    <= remain - 32'd1;
                        end
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk) if (win) assert (pulse_cnt < PULSE_LEN);
    always @(posedge clk) if (win) assert (n_held <= NPERIPH);
endmodule

module lockable_cfg #(
    parameter WIDTH = 32
) (
    input  wire             clk,
    input  wire             i_reset,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [1:0]       in_cmd,
    input  wire [WIDTH-1:0] in_data,
    output wire [WIDTH-1:0] cfg_out,
    output wire             cfg_locked
);
    localparam [1:0] CMD_ARM   = 2'd1;
    localparam [1:0] CMD_WRITE = 2'd2;
    localparam [1:0] CMD_LOCK  = 2'd3;
    localparam [WIDTH-1:0] CFG_DEFAULT = {WIDTH{1'b0}};

    typedef enum logic [1:0] {S_OPEN, S_ARMED, S_WRITTEN, S_LOCKED} state_t;

    state_t state;
    initial state = S_OPEN;

    reg [WIDTH-1:0] cfg_word = CFG_DEFAULT;
    reg locked     = 1'b0;
    reg arm_seen   = 1'b0;
    reg start_seen = 1'b0;
    reg before_r   = 1'b1;
    reg pv         = 1'b0;

    assign in_ready   = (state != S_LOCKED);
    assign cfg_out    = cfg_word;
    assign cfg_locked = locked;

    wire xfer       = in_valid && in_ready;
    wire fire_arm   = xfer && (state == S_OPEN) && (in_cmd == CMD_ARM);
    wire fire_write = xfer && ((state == S_ARMED) || (state == S_WRITTEN)) && (in_cmd == CMD_WRITE);
    wire fire_lock  = xfer && (state == S_WRITTEN) && (in_cmd == CMD_LOCK);

    always @(posedge clk) begin
        if (i_reset) begin
            state      <= S_OPEN;
            cfg_word   <= CFG_DEFAULT;
            locked     <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
        end else begin
            if (fire_arm) begin
                state    <= S_ARMED;
                arm_seen <= 1'b1;
            end
            if (fire_write) begin
                cfg_word   <= in_data;
                start_seen <= 1'b1;
                if (state == S_ARMED)
                    state <= S_WRITTEN;
            end
            if (fire_lock) begin
                locked <= 1'b1;
                state  <= S_LOCKED;
            end
        end
    end

    always @(posedge clk)
        if (i_reset)
            before_r <= 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && before_r && $past(fire_lock))
            assert ($past(arm_seen) && $past(start_seen));
endmodule

module dualrail_asr #(
    parameter WIDTH = 32,
    parameter [WIDTH-1:0] INIT = 32'h8000_0000
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             en,
    input  wire             dir,
    input  wire             load,
    input  wire [WIDTH-1:0] din,
    output reg  [WIDTH-1:0] data,
    output reg  [WIDTH-1:0] nd,
    output reg              armed
);
    initial data  = INIT;
    initial nd    = ~INIT;
    initial armed = 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            data  <= INIT;
            nd    <= ~INIT;
            armed <= 1'b1;
        end else if (en) begin
            if (load) begin
                data <= din;
                nd   <= ~din;
            end else if (dir) begin
                data  <= {data[WIDTH-2:0], 1'b0};
                nd    <= {nd[WIDTH-2:0], 1'b0};
                armed <= 1'b0;
            end else begin
                data <= {data[WIDTH-1], data[WIDTH-1:1]};
                nd   <= {nd[WIDTH-1], nd[WIDTH-1:1]};
            end
        end
    end

    always @(posedge clk)
        assert (!armed || (data[0] != nd[0]));
endmodule

module bar_req_queue #(
    parameter DEPTH = 8,
    parameter AW = 3
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    output wire       in_ready,
    input  wire [7:0] in_addr,
    output wire       out_valid,
    input  wire       out_ready,
    output wire [7:0] out_addr,
    input  wire       irq_on_done,
    input  wire       host_wr,
    input  wire       host_wdata,
    output wire       irq
);
    localparam [7:0] CAP = DEPTH;

    reg [7:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = 0;
    reg [AW-1:0] rptr = 0;
    reg [7:0] count = 8'd0;
    reg [7:0] credits = CAP;
    reg irq_pend = 1'b0;
    reg armed = 1'b0;
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = 8'd0;
    end

    assign in_ready  = (credits != 8'd0);
    assign out_valid = (count != 8'd0);
    assign out_addr  = mem[rptr];
    assign irq       = irq_pend;

    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    // request storage and credit accounting
    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0;
            rptr <= 0;
            count <= 8'd0;
            credits <= CAP;
        end else begin
            if (in_fire) begin
                mem[wptr] <= in_addr;
                wptr <= wptr + 1'b1;
            end
            if (out_fire) rptr <= rptr + 1'b1;
            case ({in_fire, out_fire})
                2'b10: begin count <= count + 8'd1; credits <= credits - 8'd1; end
                2'b01: begin count <= count - 8'd1; credits <= credits + 8'd1; end
                default: begin count <= count; credits <= credits; end
            endcase
        end
    end

    // dual-port latch: completion port and host port both write the shared pending bit
    wire en_a = out_fire;
    wire d_a  = irq_on_done;
    wire en_b = host_wr;
    wire d_b  = host_wdata;
    always @(posedge clk) begin
        if (rst)       irq_pend <= 1'b0;
        else if (en_a) irq_pend <= d_a;
        else if (en_b) irq_pend <= d_b;
        else           irq_pend <= irq_pend;
    end

    // after-Q scope: armed by the first accepted request, never cleared
    always @(posedge clk) begin
        if (in_fire) armed <= 1'b1;
    end

    always @(posedge clk) if (armed) assert (count <= CAP);
    always @(posedge clk) if (armed) assert (credits <= CAP);
endmodule

module aes_keyexp64 #(
    parameter [63:0] NR = 64'd10
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    output wire         s_ready,
    input  wire [255:0] s_key,
    input  wire         step,
    output reg          m_valid,
    input  wire         m_ready,
    output wire [255:0] m_key,
    output wire [63:0]  m_round
);
    reg [63:0] kw0, kw1, kw2, kw3;
    reg [63:0] round;
    reg [63:0] countdown;
    reg        busy;
    reg        armed;

    initial begin
        kw0 = 64'd0; kw1 = 64'd0; kw2 = 64'd0; kw3 = 64'd0;
        round = 64'd0;
        countdown = 64'd0;
        busy = 1'b0;
        armed = 1'b0;
        m_valid = 1'b0;
    end

    assign s_ready = !busy;
    wire accept = s_valid && s_ready;
    wire adv    = busy && armed && step;

    wire [63:0] rcon = 64'h1 << round[5:0];
    wire [63:0] g    = {kw3[55:0], kw3[63:56]} ^ rcon;
    wire [63:0] n0   = kw0 ^ g;
    wire [63:0] n1   = kw1 ^ n0;
    wire [63:0] n2   = kw2 ^ n1;
    wire [63:0] n3   = kw3 ^ n2;

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            armed     <= 1'b0;
            m_valid   <= 1'b0;
            round     <= 64'd0;
            countdown <= 64'd0;
        end else if (accept) begin
            busy      <= 1'b1;
            armed     <= 1'b1;
            m_valid   <= 1'b0;
            round     <= 64'd0;
            countdown <= NR;
            kw0 <= s_key[63:0];
            kw1 <= s_key[127:64];
            kw2 <= s_key[191:128];
            kw3 <= s_key[255:192];
        end else if (adv) begin
            round     <= round + 64'd1;
            countdown <= countdown - 64'd1;
            kw0 <= n0;
            kw1 <= n1;
            kw2 <= n2;
            kw3 <= n3;
            if (round + 64'd1 == NR) begin
                armed   <= 1'b0;
                m_valid <= 1'b1;
            end
        end else if (m_valid && m_ready) begin
            m_valid <= 1'b0;
            busy    <= 1'b0;
        end
    end

    assign m_key   = {kw3, kw2, kw1, kw0};
    assign m_round = round;

    assert property (!armed || countdown != 64'd0);
endmodule

module xdom_pulse_demux #(
    parameter N = 64,
    parameter SELW = 6
) (
    input  wire            clk,
    input  wire            rst,
    input  wire            in_valid,
    output wire            in_ready,
    input  wire [SELW-1:0] in_sel,
    input  wire            dst_ce,
    output wire [N-1:0]    out_pulse,
    output wire            busy_o
);
    localparam [63:0] LAT = 64'd3;

    reg [N-1:0] src_tog = {N{1'b0}};
    reg [N-1:0] s1 = {N{1'b0}};
    reg [N-1:0] s2 = {N{1'b0}};
    reg [N-1:0] s3 = {N{1'b0}};
    reg         busy = 1'b0;
    reg [63:0]  countdown = 64'd0;

    assign in_ready  = !busy;
    wire   accept    = in_valid && in_ready;
    assign out_pulse = s2 ^ s3;
    assign busy_o    = busy;

    always @(posedge clk) begin
        if (rst) begin
            src_tog   <= {N{1'b0}};
            s1        <= {N{1'b0}};
            s2        <= {N{1'b0}};
            s3        <= {N{1'b0}};
            busy      <= 1'b0;
            countdown <= 64'd0;
        end else begin
            if (accept)
                src_tog <= src_tog ^ ({{(N-1){1'b0}}, 1'b1} << in_sel);
            if (dst_ce) begin
                s1 <= src_tog;
                s2 <= s1;
                s3 <= s2;
            end
            if (accept) begin
                busy      <= 1'b1;
                countdown <= LAT;
            end else if (busy && dst_ce) begin
                if (|out_pulse) begin
                    busy      <= 1'b0;
                    countdown <= 64'd0;
                end else begin
                    countdown <= countdown - 64'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (busy) assert (countdown != 64'd0);
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
endmodule

module assoc_bitserial #(
    parameter N  = 8,
    parameter W  = 32,
    parameter CW = 6,
    parameter TW = 4
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire          in_op,
    input  wire [2:0]    in_addr,
    input  wire [W-1:0]  in_data,
    input  wire [W-1:0]  in_mask,
    input  wire          i_step,
    output reg           res_valid,
    input  wire          res_ready,
    output wire [N-1:0]  res_tag,
    output wire          res_any
);
    reg [N*W-1:0] words;
    reg [W-1:0]   comparand;
    reg [W-1:0]   mask;
    reg [N-1:0]   tag;
    reg [TW-1:0]  hit_cnt;
    reg [CW-1:0]  col;
    reg           busy;

    initial begin
        words = {N*W{1'b0}};
        comparand = {W{1'b0}};
        mask = {W{1'b0}};
        tag = {N{1'b0}};
        hit_cnt = {TW{1'b0}};
        col = {CW{1'b0}};
        busy = 1'b0;
        res_valid = 1'b0;
    end

    assign in_ready = !busy && !res_valid;
    assign res_tag  = tag;
    assign res_any  = (hit_cnt != {TW{1'b0}});

    wire [4:0] bit_idx = col[4:0];
    wire cmp_bit = comparand[bit_idx];
    wire msk_bit = mask[bit_idx];

    wire [N-1:0] keep;
    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : g_col
            assign keep[g] = !msk_bit || (words[g*W + bit_idx] == cmp_bit);
        end
    endgenerate

    wire [N-1:0] cleared = tag & ~keep;
    reg [TW-1:0] drop;
    integer k;
    always @(*) begin
        drop = {TW{1'b0}};
        for (k = 0; k < N; k = k + 1)
            drop = drop + {{(TW-1){1'b0}}, cleared[k]};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            words <= {N*W{1'b0}};
            comparand <= {W{1'b0}};
            mask <= {W{1'b0}};
            tag <= {N{1'b0}};
            hit_cnt <= {TW{1'b0}};
            col <= {CW{1'b0}};
            busy <= 1'b0;
            res_valid <= 1'b0;
        end else begin
            if (res_valid && res_ready)
                res_valid <= 1'b0;
            if (in_valid && in_ready) begin
                if (in_op) begin
                    comparand <= in_data;
                    mask <= in_mask;
                    tag <= {N{1'b1}};
                    hit_cnt <= N[TW-1:0];
                    col <= {CW{1'b0}};
                    busy <= 1'b1;
                end else begin
                    words[in_addr*W +: W] <= in_data;
                end
            end else if (busy && i_step) begin
                tag <= tag & keep;
                hit_cnt <= hit_cnt - drop;
                if (col == W-1) begin
                    col <= W[CW-1:0];
                    busy <= 1'b0;
                    res_valid <= 1'b1;
                end else begin
                    col <= col + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert ((hit_cnt != {TW{1'b0}}) == (tag != {N{1'b0}}));
endmodule

module shader_alu_seq #(
    parameter W = 32
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         i_ce,
    input  wire         i_frame,
    input  wire         i_arm,
    input  wire         i_go,
    input  wire [2:0]   i_op,
    input  wire [W-1:0] i_operand,
    output wire [W-1:0] o_acc,
    output wire [3:0]   o_flags
);
    localparam [1:0] PH_IDLE    = 2'd0;
    localparam [1:0] PH_ARMED   = 2'd1;
    localparam [1:0] PH_STARTED = 2'd2;

    localparam [2:0] OP_ADD = 3'd0;
    localparam [2:0] OP_SUB = 3'd1;
    localparam [2:0] OP_AND = 3'd2;
    localparam [2:0] OP_OR  = 3'd3;
    localparam [2:0] OP_XOR = 3'd4;

    reg [1:0]   phase     = PH_IDLE;
    reg         armed_f   = 1'b0;
    reg         started_f = 1'b0;
    reg         q_seen    = 1'b0;
    reg [W-1:0] acc       = {W{1'b0}};
    reg [W-1:0] opnd      = {W{1'b0}};
    reg [2:0]   opsel     = 3'd0;
    reg [W-1:0] res       = {W{1'b0}};
    reg         c_r       = 1'b0;
    reg         v_r       = 1'b0;
    reg [3:0]   flags     = 4'd0; // {C, Z, N, V}

    wire arm_evt   = i_ce && (phase == PH_IDLE)    && i_arm;
    wire start_evt = i_ce && (phase == PH_ARMED)   && i_go;
    wire fin_evt   = i_ce && (phase == PH_STARTED);

    wire [W:0] sum  = {1'b0, acc} + {1'b0, opnd};
    wire [W:0] diff = {1'b0, acc} - {1'b0, opnd};

    reg [W-1:0] alu_res;
    reg         alu_c;
    reg         alu_v;
    always @(*) begin
        alu_c = 1'b0;
        alu_v = 1'b0;
        case (opsel)
            OP_ADD: begin
                alu_res = sum[W-1:0];
                alu_c   = sum[W];
                alu_v   = (acc[W-1] == opnd[W-1]) && (sum[W-1] != acc[W-1]);
            end
            OP_SUB: begin
                alu_res = diff[W-1:0];
                alu_c   = diff[W];
                alu_v   = (acc[W-1] != opnd[W-1]) && (diff[W-1] != acc[W-1]);
            end
            OP_AND:  alu_res = acc & opnd;
            OP_OR:   alu_res = acc | opnd;
            OP_XOR:  alu_res = acc ^ opnd;
            default: alu_res = opnd;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase     <= PH_IDLE;
            armed_f   <= 1'b0;
            started_f <= 1'b0;
            q_seen    <= 1'b0;
            acc       <= {W{1'b0}};
            opnd      <= {W{1'b0}};
            opsel     <= 3'd0;
            res       <= {W{1'b0}};
            c_r       <= 1'b0;
            v_r       <= 1'b0;
            flags     <= 4'd0;
        end else begin
            if (i_ce && i_frame)
                q_seen <= 1'b1;
            if (arm_evt) begin
                phase   <= PH_ARMED;
                armed_f <= 1'b1;
                opnd    <= i_operand;
                opsel   <= i_op;
            end else if (start_evt) begin
                phase     <= PH_STARTED;
                armed_f   <= 1'b0;
                started_f <= 1'b1;
                res       <= alu_res;
                c_r       <= alu_c;
                v_r       <= alu_v;
            end else if (fin_evt) begin
                phase     <= PH_IDLE;
                started_f <= 1'b0;
                acc       <= res;
                flags     <= {c_r, (res == {W{1'b0}}), res[W-1], v_r};
            end
        end
    end

    assign o_acc   = acc;
    assign o_flags = flags;

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && q_seen)
            assert ((!$past(fin_evt) || $past(started_f)) &&
                    (!$past(start_evt) || $past(armed_f)));
endmodule

module comma_align_search #(
    parameter W = 16,
    parameter NOFF = 16,
    parameter [15:0] COMMA = 16'hFA0C
) (
    input  wire clk,
    input  wire rst_n,
    input  wire ce,
    input  wire start,
    input  wire [W-1:0] din,
    output reg  [$clog2(NOFF)-1:0] align_off,
    output reg  locked,
    output reg  searching
);
    localparam OW = $clog2(NOFF);

    reg [W-1:0]  prev_word = {W{1'b0}};
    reg [15:0]   timer     = 16'd0;
    reg [OW-1:0] scan_off  = {OW{1'b0}};
    initial align_off = {OW{1'b0}};
    initial locked    = 1'b0;
    initial searching = 1'b0;

    wire [2*W-1:0] win  = {prev_word, din};
    wire [2*W-1:0] shft = win >> scan_off;
    wire [W-1:0]   cand = shft[W-1:0];
    wire           match = (cand == COMMA);
    wire           expired = (timer == 16'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            prev_word <= {W{1'b0}};
            timer     <= 16'd0;
            scan_off  <= {OW{1'b0}};
            align_off <= {OW{1'b0}};
            locked    <= 1'b0;
            searching <= 1'b0;
        end else if (ce) begin
            prev_word <= din;
            if (!searching) begin
                if (start) begin
                    searching <= 1'b1;
                    locked    <= 1'b0;
                    timer     <= NOFF;
                    scan_off  <= {OW{1'b0}};
                end
            end else begin
                if (match) begin
                    align_off <= scan_off;
                    locked    <= 1'b1;
                    searching <= 1'b0;
                    timer     <= 16'd0;
                    scan_off  <= {OW{1'b0}};
                end else if (scan_off == NOFF - 1) begin
                    searching <= 1'b0;
                    timer     <= 16'd0;
                    scan_off  <= {OW{1'b0}};
                end else begin
                    timer     <= timer - 16'd1;
                    scan_off  <= scan_off + 1'b1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(expired)) assert (!searching);
endmodule

module rtc_calendar #(
    parameter W = 16,
    parameter [W-1:0] SEC_LAST   = 16'd59,
    parameter [W-1:0] MIN_LAST   = 16'd59,
    parameter [W-1:0] HOUR_LAST  = 16'd23,
    parameter [W-1:0] DAY_LAST   = 16'd30,
    parameter [W-1:0] MONTH_LAST = 16'd12
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         tick,
    input  wire         alarm_arm,
    input  wire         alarm_clear,
    output wire [W-1:0] o_sec,
    output wire [W-1:0] o_min,
    output wire [W-1:0] o_hour,
    output wire [W-1:0] o_day,
    output wire [W-1:0] o_month,
    output wire         o_minute_strobe,
    output wire         o_window
);
    reg [W-1:0] sec, sec_left, minute, hour, day, month;
    reg         in_window;

    initial begin
        sec       = {W{1'b0}};
        sec_left  = SEC_LAST;
        minute    = {W{1'b0}};
        hour      = {W{1'b0}};
        day       = 16'd1;
        month     = 16'd1;
        in_window = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            sec       <= {W{1'b0}};
            sec_left  <= SEC_LAST;
            minute    <= {W{1'b0}};
            hour      <= {W{1'b0}};
            day       <= 16'd1;
            month     <= 16'd1;
            in_window <= 1'b0;
        end else if (ce) begin
            if (alarm_clear)
                in_window <= 1'b0;
            else if (alarm_arm)
                in_window <= 1'b1;

            if (tick) begin
                if (sec_left == {W{1'b0}})
                    sec_left <= SEC_LAST;
                else
                    sec_left <= sec_left - 16'd1;

                if (sec == SEC_LAST) begin
                    sec <= {W{1'b0}};
                    if (minute == MIN_LAST) begin
                        minute <= {W{1'b0}};
                        if (hour == HOUR_LAST) begin
                            hour <= {W{1'b0}};
                            if (day == DAY_LAST) begin
                                day <= 16'd1;
                                if (month == MONTH_LAST)
                                    month <= 16'd1;
                                else
                                    month <= month + 16'd1;
                            end else begin
                                day <= day + 16'd1;
                            end
                        end else begin
                            hour <= hour + 16'd1;
                        end
                    end else begin
                        minute <= minute + 16'd1;
                    end
                end else begin
                    sec <= sec + 16'd1;
                end
            end
        end
    end

    assign o_sec           = sec;
    assign o_min           = minute;
    assign o_hour          = hour;
    assign o_day           = day;
    assign o_month         = month;
    assign o_minute_strobe = (sec_left == {W{1'b0}});
    assign o_window        = in_window;

    // Absence, between arm and clear: start-of-minute and end-of-minute
    // are never flagged at the same time while the alarm window is open.
    always @(posedge clk)
        if (in_window)
            assert (!(sec == {W{1'b0}} && sec_left == {W{1'b0}}));
endmodule

module rename_table #(
    parameter NARCH = 4,
    parameter NPHYS = 8,
    parameter AW = $clog2(NARCH),
    parameter TW = $clog2(NPHYS),
    parameter CW = 16
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          i_req,
    input  wire [AW-1:0] i_dst,
    output wire [TW-1:0] o_tag,
    output wire [CW-1:0] o_cnt
);
    typedef enum logic [1:0] {S_IDLE, S_ARM, S_START, S_FINISH} state_t;

    state_t state = S_IDLE;

    // rename map: architectural register -> physical tag
    reg [NARCH-1:0][TW-1:0] map_q;
    // free-tag list as a bit vector (1 = tag free)
    reg [NPHYS-1:0] free_vec = {NPHYS{1'b1}} << NARCH;
    reg [AW-1:0]    dst       = {AW{1'b0}};
    reg [TW-1:0]    alloc_tag = {TW{1'b0}};
    reg [CW-1:0]    rename_cnt = {CW{1'b0}};
    reg             seen_q    = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < NARCH; i = i + 1)
            map_q[i] = i;
    end

    // lowest free physical tag
    reg [TW-1:0] pick;
    integer k;
    always @(*) begin
        pick = {TW{1'b0}};
        for (k = NPHYS-1; k >= 0; k = k - 1)
            if (free_vec[k]) pick = k;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        dst    <= i_dst;
                        seen_q <= 1'b1;
                        state  <= S_ARM;
                    end
                end
                S_ARM: begin
                    if (free_vec != {NPHYS{1'b0}}) begin
                        alloc_tag      <= pick;
                        free_vec[pick] <= 1'b0;
                        state          <= S_START;
                    end
                end
                S_START: begin
                    map_q[dst]           <= alloc_tag;
                    free_vec[map_q[dst]] <= 1'b1;
                    state                <= S_FINISH;
                end
                S_FINISH: begin
                    rename_cnt <= rename_cnt + 1'b1;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    assign o_tag = alloc_tag;
    assign o_cnt = rename_cnt;

    // after the first accepted rename request: a finished rename must have
    // passed through allocation (tag taken off the free list)
    always @(posedge clk)
        if (seen_q && state == S_FINISH)
            assert (!free_vec[alloc_tag]);
endmodule

module thr_cross_det #(
    parameter W = 32,
    parameter [W-1:0] THR_INIT = 32'h8000_0000
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire [W-1:0] i_thr,
    input  wire [W-1:0] i_sample,
    output reg          o_xflag,
    output reg          o_xdir,
    output reg  [W-1:0] o_xcnt
);
    reg [W-1:0] thr;
    reg [W-1:0] prev;
    reg         have_prev;
    reg         seen_below;

    initial begin
        thr        = THR_INIT;
        prev       = {W{1'b0}};
        have_prev  = 1'b0;
        seen_below = 1'b0;
        o_xflag    = 1'b0;
        o_xdir     = 1'b0;
        o_xcnt     = {W{1'b0}};
    end

    wire s_below = (i_sample < thr);
    wire p_below = (prev < thr);
    wire cross   = have_prev && (s_below != p_below);

    always @(posedge clk) begin
        if (rst) begin
            thr        <= THR_INIT;
            prev       <= {W{1'b0}};
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
            o_xdir     <= 1'b0;
            o_xcnt     <= {W{1'b0}};
        end else if (i_load) begin
            thr        <= i_thr;
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
        end else if (i_ce) begin
            prev      <= i_sample;
            have_prev <= 1'b1;
            if (s_below)
                seen_below <= 1'b1;
            o_xflag <= cross;
            if (cross) begin
                o_xdir <= p_below;
                o_xcnt <= o_xcnt + 1'b1;
            end
        end
    end

    always @(*) assert (!(o_xflag && o_xdir) || seen_below);
endmodule

module mn_clken_gen #(
    parameter W = 64,
    parameter [W-1:0] M_DEF = 64'd3,
    parameter [W-1:0] N_DEF = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         req,
    input  wire         cfg_load,
    input  wire [W-1:0] cfg_m,
    input  wire [W-1:0] cfg_n,
    output wire         ce_out,
    output wire         busy
);
    reg [W-1:0] m_r = M_DEF;
    reg [W-1:0] n_r = N_DEF;
    reg [W-1:0] err = {W{1'b0}};
    reg [W-1:0] cd  = {W{1'b0}};
    reg         armed = 1'b0;
    reg         timeout = 1'b0;

    wire [W:0]   sum  = {1'b0, err} + {1'b0, m_r};
    wire         hit  = (sum >= {1'b0, n_r});
    wire [W:0]   diff = sum - {1'b0, n_r};
    wire [W-1:0] err_nxt = step ? (hit ? diff[W-1:0] : sum[W-1:0]) : err;
    wire         cfg_ok = (cfg_n != {W{1'b0}}) && (cfg_m != {W{1'b0}}) && (cfg_m <= cfg_n);

    assign ce_out = step && hit;
    assign busy   = armed;

    always @(posedge clk) begin
        if (rst) begin
            m_r     <= M_DEF;
            n_r     <= N_DEF;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else if (cfg_load && cfg_ok) begin
            m_r     <= cfg_m;
            n_r     <= cfg_n;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else begin
            err <= err_nxt;
            if (!armed) begin
                if (req) begin
                    armed <= 1'b1;
                    cd    <= n_r - err_nxt;
                end
            end else if (step) begin
                if (hit)
                    armed <= 1'b0;
                else if (cd <= m_r)
                    timeout <= 1'b1;
                else
                    cd <= cd - m_r;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(armed))
            assert ($stable(timeout));
endmodule

module oc_csum_acc #(
    parameter W = 32
) (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    input  wire         i_ce,
    output wire [W-1:0] o_csum
);
    reg [W-1:0] acc;
    reg [W-1:0] hold_data;
    reg         hold_valid;
    reg         seen_nz;
    reg         armed;
    initial acc = {W{1'b0}};
    initial hold_data = {W{1'b0}};
    initial hold_valid = 1'b0;
    initial seen_nz = 1'b0;
    initial armed = 1'b1;

    wire drain = i_ce && hold_valid;
    assign in_ready = !hold_valid || drain;
    wire accept = in_valid && in_ready;

    // end-around-carry (one's-complement) adder, purely combinational
    wire [W:0]   raw     = {1'b0, acc} + {1'b0, hold_data};
    wire         eac     = raw[W];
    wire [W-1:0] eac_sum = raw[W-1:0] + {{(W-1){1'b0}}, eac};

    always @(posedge clk) begin
        if (i_reset) begin
            acc        <= {W{1'b0}};
            hold_data  <= {W{1'b0}};
            hold_valid <= 1'b0;
            seen_nz    <= 1'b0;
            armed      <= 1'b1;
        end else begin
            if (drain) begin
                acc <= eac_sum;
                if (eac)
                    armed <= 1'b0;
            end
            if (accept) begin
                hold_data  <= in_data;
                hold_valid <= 1'b1;
                if (in_data != {W{1'b0}})
                    seen_nz <= 1'b1;
            end else if (drain) begin
                hold_valid <= 1'b0;
            end
        end
    end

    assign o_csum = ~acc;

    always @(*)
        assert (!armed || seen_nz || acc == {W{1'b0}});
endmodule

module burst_hold_arb #(
    parameter NREQ = 4,
    parameter LW   = 16,
    parameter OW   = 2
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire [NREQ-1:0] req,
    input  wire [LW-1:0]   req_len,
    output wire [NREQ-1:0] gnt,
    output wire            busy,
    output wire            last_beat
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_ARM  = 2'd1;
    localparam [1:0] S_XFER = 2'd2;

    reg [1:0]    phase      = S_IDLE;
    reg [OW-1:0] owner      = {OW{1'b0}};
    reg [LW-1:0] beats      = {LW{1'b0}};
    reg          seen_grant = 1'b0;
    reg          pv         = 1'b0;

    reg [OW-1:0] winner;
    integer i;
    always @(*) begin
        winner = {OW{1'b0}};
        for (i = NREQ-1; i >= 0; i = i - 1)
            if (req[i]) winner = i;
    end

    wire [LW-1:0] eff_len = (req_len == {LW{1'b0}}) ? {{(LW-1){1'b0}}, 1'b1} : req_len;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase      <= S_IDLE;
            owner      <= {OW{1'b0}};
            beats      <= {LW{1'b0}};
            seen_grant <= 1'b0;
        end else if (ce) begin
            case (phase)
                S_IDLE: begin
                    if (|req) begin
                        owner      <= winner;
                        beats      <= eff_len;
                        phase      <= S_ARM;
                        seen_grant <= 1'b1;
                    end
                end
                S_ARM: begin
                    phase <= S_XFER;
                end
                S_XFER: begin
                    beats <= beats - {{(LW-1){1'b0}}, 1'b1};
                    if (beats == {{(LW-1){1'b0}}, 1'b1})
                        phase <= S_IDLE;
                end
                default: begin
                    phase <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    assign gnt       = (phase == S_XFER) ? ({{(NREQ-1){1'b0}}, 1'b1} << owner) : {NREQ{1'b0}};
    assign busy      = (phase != S_IDLE);
    assign last_beat = (phase == S_XFER) && (beats == {{(LW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (pv && seen_grant && $stable(beats))
            assert ($stable(owner));
endmodule

module morse_decoder #(
    parameter SRW = 8,
    parameter [7:0] MAXSYM = 8'd7,
    parameter [7:0] DOT_MAX = 8'd3,
    parameter [7:0] CHAR_GAP = 8'd5
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire key,
    output reg [SRW-1:0] char_code,
    output reg [7:0] char_len,
    output reg char_valid
);
    typedef enum logic [1:0] {IDLE = 2'd0, MARK = 2'd1, SPACE = 2'd2} state_t;
    state_t state;
    reg [7:0] dur;
    reg [SRW-1:0] sym_sr;
    reg [7:0] sym_cnt;
    reg armed;

    initial begin
        state = IDLE;
        dur = 8'd0;
        sym_sr = {{(SRW-1){1'b0}}, 1'b1};
        sym_cnt = 8'd0;
        armed = 1'b0;
        char_code = {SRW{1'b0}};
        char_len = 8'd0;
        char_valid = 1'b0;
    end

    wire is_dash = (dur > DOT_MAX);
    wire [7:0] dur_inc = (dur == 8'hFF) ? dur : (dur + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            dur <= 8'd0;
            sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
            sym_cnt <= 8'd0;
            armed <= 1'b0;
            char_code <= {SRW{1'b0}};
            char_len <= 8'd0;
            char_valid <= 1'b0;
        end else if (step) begin
            char_valid <= 1'b0;
            case (state)
                IDLE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end
                end
                MARK: begin
                    if (key) begin
                        dur <= dur_inc;
                    end else begin
                        if (sym_cnt < MAXSYM) begin
                            sym_sr <= {sym_sr[SRW-2:0], is_dash};
                            sym_cnt <= sym_cnt + 8'd1;
                        end
                        armed <= 1'b1;
                        state <= SPACE;
                        dur <= 8'd1;
                    end
                end
                SPACE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end else if (dur_inc >= CHAR_GAP) begin
                        char_code <= sym_sr;
                        char_len <= sym_cnt;
                        char_valid <= 1'b1;
                        sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
                        sym_cnt <= 8'd0;
                        armed <= 1'b0;
                        state <= IDLE;
                        dur <= 8'd0;
                    end else begin
                        dur <= dur_inc;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    // Scope: after a symbol is accepted (armed set) until the character is emitted (armed cleared)
    always @(posedge clk)
        if (armed)
            assert (sym_sr != {{(SRW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (armed && sym_cnt < MAXSYM)
            assert (sym_sr[SRW-1] == 1'b0);
endmodule

module sqrt_restoring #(
    parameter W  = 128,
    parameter SW = 7
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           ce,
    input  wire           start,
    input  wire [W-1:0]   radicand,
    output wire [W/2-1:0] root,
    output wire           busy,
    output wire           done
);
    typedef enum logic [1:0] {IDLE = 2'd0, BUSY = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0]  TOP   = {2'b01, {(W-2){1'b0}}};
    localparam [SW-1:0] STEPS = W / 2;

    state_t        state;
    reg [W-1:0]    rem;
    reg [W-1:0]    res;
    reg [W-1:0]    bit_r;
    reg [SW-1:0]   step;

    initial begin
        state = IDLE;
        rem   = {W{1'b0}};
        res   = {W{1'b0}};
        bit_r = TOP;
        step  = {SW{1'b0}};
    end

    wire [W-1:0] trial = res + bit_r;
    wire         fits  = (rem >= trial);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            rem   <= {W{1'b0}};
            res   <= {W{1'b0}};
            bit_r <= TOP;
            step  <= {SW{1'b0}};
        end else if (ce) begin
            case (state)
                IDLE, DONE: begin
                    if (start) begin
                        state <= BUSY;
                        rem   <= radicand;
                        res   <= {W{1'b0}};
                        bit_r <= TOP;
                        step  <= {SW{1'b0}};
                    end
                end
                BUSY: begin
                    if (bit_r == {W{1'b0}}) begin
                        state <= DONE;
                    end else begin
                        if (fits) begin
                            rem <= rem - trial;
                            res <= (res >> 1) + bit_r;
                        end else begin
                            res <= res >> 1;
                        end
                        bit_r <= bit_r >> 2;
                        step  <= step + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    assign root = res[W/2-1:0];
    assign busy = (state == BUSY);
    assign done = (state == DONE);

    always @(*) assert (step <= STEPS);
endmodule

module atpg_pattern_buf #(
    parameter W = 128,
    parameter DEPTH = 24
) (
    input  wire                           clk,
    input  wire                           rst,
    input  wire                           in_valid,
    output wire                           in_ready,
    input  wire [W-1:0]                   in_data,
    output wire                           out_valid,
    input  wire                           out_ready,
    output wire [W-1:0]                   out_data,
    input  wire                           load_limit,
    input  wire [$clog2(DEPTH+1)-1:0]     limit_in
);
    localparam CW = $clog2(DEPTH+1);
    localparam PW = $clog2(DEPTH);

    // occupancy held in a DICE-style quadruple of interlocked storage nodes
    reg [CW-1:0] n0, n1, n2, n3;
    reg [CW-1:0] limit;
    reg [PW-1:0] wptr, rptr;
    reg          armed;
    reg [W-1:0]  mem [0:DEPTH-1];

    integer i;
    initial begin
        n0 = 0; n1 = 0; n2 = 0; n3 = 0;
        limit = DEPTH;
        wptr = 0; rptr = 0;
        armed = 1'b0;
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {W{1'b0}};
    end

    // interlock restoration: a node is overridden when its two neighbours agree
    wire [CW-1:0] b0 = (n1 == n3) ? n1 : n0;
    wire [CW-1:0] b1 = (n2 == n0) ? n2 : n1;
    wire [CW-1:0] b2 = (n3 == n1) ? n3 : n2;
    wire [CW-1:0] b3 = (n0 == n2) ? n0 : n3;

    wire [CW-1:0] cap = (limit > DEPTH) ? DEPTH[CW-1:0] : limit;

    assign in_ready  = (n0 < cap);
    assign out_valid = (n0 != {CW{1'b0}});
    assign out_data  = mem[rptr];

    wire do_push = in_valid && in_ready;
    wire do_pop  = out_valid && out_ready;

    wire [PW-1:0] wptr_nx = (wptr == DEPTH-1) ? {PW{1'b0}} : wptr + 1'b1;
    wire [PW-1:0] rptr_nx = (rptr == DEPTH-1) ? {PW{1'b0}} : rptr + 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            n0 <= 0; n1 <= 0; n2 <= 0; n3 <= 0;
            wptr <= 0; rptr <= 0;
            limit <= limit_in;
        end else begin
            if (load_limit) limit <= limit_in;
            if (do_push) begin
                mem[wptr] <= in_data;
                wptr <= wptr_nx;
            end
            if (do_pop) rptr <= rptr_nx;
            if (do_push != do_pop) begin
                n0 <= do_push ? b0 + 1'b1 : b0 - 1'b1;
                n1 <= do_push ? b1 + 1'b1 : b1 - 1'b1;
                n2 <= do_push ? b2 + 1'b1 : b2 - 1'b1;
                n3 <= do_push ? b3 + 1'b1 : b3 - 1'b1;
            end
        end
    end

    // sticky scope: armed by the first accepted pattern, never cleared
    always @(posedge clk)
        if (do_push) armed <= 1'b1;

    assert property (!armed || n0 <= DEPTH);
endmodule

module usb_stream_writer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire ack,
    input wire s_valid,
    input wire s_last,
    input wire [31:0] s_data,
    input wire trig_arm,
    input wire trig_disarm,
    output wire busy,
    output wire full,
    output wire [31:0] o_pkt_len,
    output wire o_eop
);
    parameter DEPTH = 16;
    parameter AW = 4;
    parameter DW = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, CAPTURE = 2'd1, DONE = 2'd2} state_t;

    state_t state = IDLE;
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [DW-1:0] byte_cnt = {DW{1'b0}};
    reg [DW-1:0] pkt_len = {DW{1'b0}};
    reg eop = 1'b0;
    reg win = 1'b0;
    reg [DW-1:0] mem [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    assign busy = (state == CAPTURE);
    assign full = (byte_cnt == DEPTH);
    assign o_pkt_len = pkt_len;
    assign o_eop = eop;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            wr_ptr <= {AW{1'b0}};
            byte_cnt <= {DW{1'b0}};
            pkt_len <= {DW{1'b0}};
            eop <= 1'b0;
            win <= 1'b0;
        end else if (ce) begin
            if (trig_arm)
                win <= 1'b1;
            else if (trig_disarm)
                win <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= CAPTURE;
                        wr_ptr <= {AW{1'b0}};
                        byte_cnt <= {DW{1'b0}};
                        eop <= 1'b0;
                    end
                end
                CAPTURE: begin
                    if (s_valid) begin
                        mem[wr_ptr] <= s_data;
                        wr_ptr <= wr_ptr + 1'b1;
                        byte_cnt <= byte_cnt + 1;
                        if (s_last || (wr_ptr == DEPTH-1)) begin
                            state <= DONE;
                            pkt_len <= byte_cnt + 1;
                            eop <= s_last;
                        end
                    end
                end
                DONE: begin
                    if (ack)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(*)
        if (win) assert (!(busy && full));
endmodule

module karatsuba_mul_hs #(
    parameter WIDTH = 16
) (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               in_valid,
    output wire               in_ready,
    input  wire [WIDTH-1:0]   in_a,
    input  wire [WIDTH-1:0]   in_b,
    output wire               out_valid,
    input  wire               out_ready,
    output wire [2*WIDTH-1:0] out_prod
);
    localparam HALF = WIDTH / 2;
    localparam [15:0] LAT = 16'd4;

    reg               busy = 1'b0;
    reg [15:0]        cnt  = 16'd0;
    reg [3:0]         done = 4'b0000;
    reg [WIDTH-1:0]   a_q  = {WIDTH{1'b0}};
    reg [WIDTH-1:0]   b_q  = {WIDTH{1'b0}};
    reg [WIDTH-1:0]   z0   = {WIDTH{1'b0}};
    reg [WIDTH-1:0]   z2   = {WIDTH{1'b0}};
    reg [WIDTH+1:0]   z1   = {(WIDTH+2){1'b0}};
    reg [2*WIDTH-1:0] prod = {(2*WIDTH){1'b0}};

    wire [HALF-1:0] a_lo = a_q[HALF-1:0];
    wire [HALF-1:0] a_hi = a_q[WIDTH-1:HALF];
    wire [HALF-1:0] b_lo = b_q[HALF-1:0];
    wire [HALF-1:0] b_hi = b_q[WIDTH-1:HALF];
    wire [HALF:0]   a_sum = {1'b0, a_lo} + {1'b0, a_hi};
    wire [HALF:0]   b_sum = {1'b0, b_lo} + {1'b0, b_hi};

    wire [2*WIDTH-1:0] z0_w  = {{WIDTH{1'b0}}, z0};
    wire [2*WIDTH-1:0] z2_w  = {{WIDTH{1'b0}}, z2};
    wire [2*WIDTH-1:0] z1_w  = {{(WIDTH-2){1'b0}}, z1};
    wire [2*WIDTH-1:0] mid_w = z1_w - z2_w - z0_w;

    assign in_ready  = !busy;
    assign out_valid = done[3];
    assign out_prod  = prod;

    wire adv = busy && !done[3] && out_ready;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0;
            cnt  <= 16'd0;
            done <= 4'b0000;
            a_q  <= {WIDTH{1'b0}};
            b_q  <= {WIDTH{1'b0}};
            z0   <= {WIDTH{1'b0}};
            z2   <= {WIDTH{1'b0}};
            z1   <= {(WIDTH+2){1'b0}};
            prod <= {(2*WIDTH){1'b0}};
        end else if (in_valid && in_ready) begin
            a_q  <= in_a;
            b_q  <= in_b;
            busy <= 1'b1;
            cnt  <= LAT;
            done <= 4'b0000;
        end else if (adv) begin
            cnt  <= cnt - 16'd1;
            done <= {done[2:0], 1'b1};
            if (!done[0])
                z0 <= a_lo * b_lo;
            else if (!done[1])
                z2 <= a_hi * b_hi;
            else if (!done[2])
                z1 <= a_sum * b_sum;
            else
                prod <= (z2_w << WIDTH) + (mid_w << HALF) + z0_w;
        end else if (out_valid && out_ready) begin
            busy <= 1'b0;
            cnt  <= 16'd0;
            done <= 4'b0000;
        end
    end

    // Bounded response: the countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy && cnt == 16'd0)
            assert (out_valid);

    // Completion only when the countdown has fully run out
    always @(posedge clk)
        if (busy && out_valid)
            assert (cnt == 16'd0);
endmodule

module ps2_frame_rx #(
    parameter W = 128
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         in_valid,
    input  wire         in_bit,
    output wire         in_ready,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] code
);
    localparam CW = $clog2(W);

    reg [W-1:0]  shreg;
    reg [CW-1:0] bitcnt;
    reg          armed;

    initial shreg     = {W{1'b0}};
    initial bitcnt    = {CW{1'b0}};
    initial code      = {W{1'b0}};
    initial out_valid = 1'b0;
    initial armed     = 1'b1;

    assign in_ready = !out_valid;

    wire take = in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            shreg     <= {W{1'b0}};
            bitcnt    <= {CW{1'b0}};
            code      <= {W{1'b0}};
            out_valid <= 1'b0;
        end else begin
            if (out_valid && out_ready)
                out_valid <= 1'b0;
            if (take) begin
                if (bitcnt == W-1) begin
                    code      <= {in_bit, shreg[W-1:1]};
                    out_valid <= 1'b1;
                    shreg     <= {W{1'b0}};
                    bitcnt    <= {CW{1'b0}};
                end else begin
                    shreg  <= {in_bit, shreg[W-1:1]};
                    bitcnt <= bitcnt + 1'b1;
                end
            end
            if (take && in_bit)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed) assert (code == {W{1'b0}});
endmodule

module btb_vec #(
    parameter NUM_ENTRIES = 12,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         upd_taken,
    input  wire         upd_nottaken,
    input  wire [W-1:0] upd_pc,
    input  wire [W-1:0] upd_target,
    input  wire [W-1:0] lookup_pc,
    output wire         hit,
    output wire [W-1:0] pred_target,
    output wire         full
);
    localparam [3:0] NE4 = NUM_ENTRIES;

    reg [NUM_ENTRIES-1:0]   valid;
    reg [NUM_ENTRIES*W-1:0] tag_flat;
    reg [NUM_ENTRIES*W-1:0] tgt_flat;
    reg [31:0]              n_valid;

    initial begin
        valid    = {NUM_ENTRIES{1'b0}};
        tag_flat = {(NUM_ENTRIES*W){1'b0}};
        tgt_flat = {(NUM_ENTRIES*W){1'b0}};
        n_valid  = 32'd0;
    end

    wire [3:0] u_raw = upd_pc[5:2];
    wire [3:0] uidx  = (u_raw >= NE4) ? (u_raw - NE4) : u_raw;
    wire [3:0] l_raw = lookup_pc[5:2];
    wire [3:0] lidx  = (l_raw >= NE4) ? (l_raw - NE4) : l_raw;

    wire [W-1:0] u_tag = tag_flat[uidx*W +: W];
    wire [W-1:0] l_tag = tag_flat[lidx*W +: W];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid    <= {NUM_ENTRIES{1'b0}};
            tag_flat <= {(NUM_ENTRIES*W){1'b0}};
            tgt_flat <= {(NUM_ENTRIES*W){1'b0}};
            n_valid  <= 32'd0;
        end else if (upd_taken) begin
            tag_flat[uidx*W +: W] <= upd_pc;
            tgt_flat[uidx*W +: W] <= upd_target;
            valid[uidx] <= 1'b1;
            if (!valid[uidx])
                n_valid <= n_valid + 32'd1;
        end else if (upd_nottaken) begin
            if (valid[uidx] && (u_tag == upd_pc)) begin
                valid[uidx] <= 1'b0;
                n_valid <= n_valid - 32'd1;
            end
        end
    end

    assign hit         = valid[lidx] && (l_tag == lookup_pc);
    assign pred_target = tgt_flat[lidx*W +: W];
    assign full        = (n_valid == NUM_ENTRIES);

    always @(posedge clk)
        if ($rose(full))
            assert (&valid);
endmodule

module i2c_arb_monitor #(
    parameter FRAME_BITS = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire        drv_bit,
    input  wire        sda_in,
    output reg         lost,
    output reg  [31:0] lost_pos,
    output reg         last_drv
);
    localparam [31:0] FRAME = FRAME_BITS;

    reg        busy    = 1'b0;
    reg [31:0] bit_cnt = 32'd0;
    reg        win     = 1'b0;
    reg [31:0] sh_cnt  = 32'd0;

    initial begin
        lost     = 1'b0;
        lost_pos = 32'd0;
        last_drv = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            bit_cnt  <= 32'd0;
            lost     <= 1'b0;
            lost_pos <= 32'd0;
            last_drv <= 1'b1;
            win      <= 1'b0;
            sh_cnt   <= 32'd0;
        end else if (ce) begin
            if (stop) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (start && !busy) begin
                busy     <= 1'b1;
                bit_cnt  <= 32'd0;
                lost     <= 1'b0;
                lost_pos <= 32'd0;
                last_drv <= 1'b1;
                win      <= 1'b0;
                sh_cnt   <= 32'd0;
            end else if (busy) begin
                last_drv <= lost ? 1'b1 : drv_bit;
                if (!lost && drv_bit && !sda_in) begin
                    lost     <= 1'b1;
                    lost_pos <= bit_cnt;
                    win      <= 1'b1;
                    sh_cnt   <= 32'd0;
                end else if (win) begin
                    sh_cnt <= sh_cnt + 32'd1;
                end
                bit_cnt <= bit_cnt + 32'd1;
                if (bit_cnt == FRAME - 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win) assert (lost_pos < bit_cnt);

    always @(posedge clk)
        if (win) assert (sh_cnt < bit_cnt);
endmodule

module desc_own_table #(
    parameter DEPTH = 8,
    parameter AW = 3,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          ce,
    input  wire          we,
    input  wire [AW-1:0] waddr,
    input  wire [DW-1:0] wdata,
    input  wire          dma_take,
    input  wire          adv,
    input  wire          start,
    input  wire          stop,
    output wire [DW-1:0] rdata,
    output wire          cpu_own,
    output wire          dma_own
);
    // asynchronous-read distributed descriptor RAM
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] ptr = {AW{1'b0}};
    reg armed = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    // combinational read of the word addressed by the DMA fetch pointer
    assign rdata   = mem[ptr];
    assign cpu_own = rdata[0];
    assign dma_own = rdata[1];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1)
                mem[i] <= {DW{1'b0}};
            ptr   <= {AW{1'b0}};
            armed <= 1'b0;
        end else if (ce) begin
            if (we)
                // CPU write: CPU ownership bit wins, DMA bit is cleared if CPU claims
                mem[waddr] <= {wdata[DW-1:2], wdata[1] & ~wdata[0], wdata[0]};
            else if (dma_take && !rdata[0])
                // DMA claims the fetched descriptor only if CPU does not own it
                mem[ptr] <= {rdata[DW-1:2], 2'b10};
            if (adv)
                ptr <= ptr + 1'b1;
            if (start)
                armed <= 1'b1;
            else if (stop)
                armed <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pv <= 1'b0;
        else
            pv <= 1'b1;
    end

    // after start until stop: the fetched descriptor never has two owners
    always @(posedge clk)
        if (pv && $past(armed))
            assert (!($past(cpu_own) && $past(dma_own)));
endmodule

module axi_w_upsizer #(
    parameter NW    = 16,
    parameter LANES = 16,
    parameter LW    = 4,
    parameter SW    = 2*LANES
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              i_awvalid,
    output wire              o_awready,
    input  wire [15:0]       i_awlen,
    input  wire [2:0]        i_awsize,
    input  wire              i_wvalid,
    output wire              o_wready,
    input  wire [NW-1:0]     i_wdata,
    output wire              o_wvalid,
    input  wire              i_wready,
    output wire [NW*LANES-1:0] o_wdata,
    output wire [SW-1:0]     o_wstrb,
    output wire              o_wlast,
    output wire [2:0]        o_cap_size,
    output wire [15:0]       o_beats_left
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_PACK = 2'd2, P_OUT = 2'd3;

    reg [1:0]          phase      = P_IDLE;
    reg                aw_seen    = 1'b0;
    reg [LW-1:0]       lane       = {LW{1'b0}};
    reg [SW-1:0]       strb       = {SW{1'b0}};
    reg [NW*LANES-1:0] pbuf       = {(NW*LANES){1'b0}};
    reg [15:0]         beats_left = 16'd0;
    reg [2:0]          cap_size   = 3'd0;
    reg                last_q     = 1'b0;

    assign o_awready    = (phase == P_IDLE);
    assign o_wready     = (phase == P_ARMED) || (phase == P_PACK);
    assign o_wvalid     = (phase == P_OUT);
    assign o_wdata      = pbuf;
    assign o_wstrb      = strb;
    assign o_wlast      = last_q;
    assign o_cap_size   = cap_size;
    assign o_beats_left = beats_left;

    wire aw_hs  = i_awvalid && o_awready;
    wire w_hs   = i_wvalid  && o_wready;
    wire out_hs = o_wvalid  && i_wready;

    wire          end_wide  = (lane == LANES-1) || (beats_left == 16'd0);
    wire [SW-1:0] lane_strb = {{(SW-2){1'b0}}, 2'b11} << {lane, 1'b0};

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            aw_seen    <= 1'b0;
            lane       <= {LW{1'b0}};
            strb       <= {SW{1'b0}};
            pbuf       <= {(NW*LANES){1'b0}};
            beats_left <= 16'd0;
            cap_size   <= 3'd0;
            last_q     <= 1'b0;
        end else begin
            if (aw_hs) begin
                phase      <= P_ARMED;
                aw_seen    <= 1'b1;
                beats_left <= i_awlen;
                cap_size   <= i_awsize;
                lane       <= {LW{1'b0}};
                strb       <= {SW{1'b0}};
            end
            if (w_hs) begin
                pbuf[lane*NW +: NW] <= i_wdata;
                strb <= strb | lane_strb;
                if (end_wide) begin
                    phase  <= P_OUT;
                    last_q <= (beats_left == 16'd0);
                end else begin
                    phase <= P_PACK;
                    lane  <= lane + 1'b1;
                end
                if (beats_left != 16'd0)
                    beats_left <= beats_left - 16'd1;
            end
            if (out_hs) begin
                strb <= {SW{1'b0}};
                lane <= {LW{1'b0}};
                pbuf <= {(NW*LANES){1'b0}};
                if (last_q) begin
                    phase   <= P_IDLE;
                    aw_seen <= 1'b0;
                    last_q  <= 1'b0;
                end else begin
                    phase <= P_PACK;
                end
            end
        end
    end

    // chain precedence: a wide beat (finish) is never offered unless the
    // address was captured (arm) and the first lane was packed (start)
    assert property (!o_wvalid || (aw_seen && strb[1:0] == 2'b11));
endmodule

module adc_scan_mux #(
    parameter N_CH = 16,
    parameter [63:0] SETTLE_CYC = 64'd6
) (
    input  wire                     clk,
    input  wire                     rst,
    input  wire                     cfg_we,
    input  wire [$clog2(N_CH)-1:0]  cfg_addr,
    input  wire [63:0]              cfg_data,
    input  wire                     start_valid,
    output wire                     start_ready,
    input  wire [$clog2(N_CH)-1:0]  start_last,
    input  wire                     tick,
    output wire                     out_valid,
    input  wire                     out_ready,
    output wire [63:0]              out_chan,
    output wire [$clog2(N_CH)-1:0]  out_idx
);
    localparam IDXW = $clog2(N_CH);

    typedef enum logic [1:0] {S_IDLE = 2'd0, S_SETTLE = 2'd1, S_OUT = 2'd2} state_t;

    state_t state;
    reg [63:0] chan_mem [0:N_CH-1];
    reg [IDXW-1:0] idx;
    reg [IDXW-1:0] last_idx;
    reg [63:0] settle;
    reg [63:0] deadline;
    reg win;

    integer i;
    initial begin
        state = S_IDLE;
        idx = {IDXW{1'b0}};
        last_idx = {IDXW{1'b0}};
        settle = SETTLE_CYC;
        deadline = SETTLE_CYC + 64'd1;
        win = 1'b0;
        for (i = 0; i < N_CH; i = i + 1) chan_mem[i] = i;
    end

    assign start_ready = (state == S_IDLE);
    assign out_valid   = (state == S_OUT);
    assign out_chan    = chan_mem[idx];
    assign out_idx     = idx;

    // channel-list memory: CSR-style programming only while idle
    always @(posedge clk) begin
        if (!rst && cfg_we && state == S_IDLE)
            chan_mem[cfg_addr] <= cfg_data;
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            idx      <= {IDXW{1'b0}};
            last_idx <= {IDXW{1'b0}};
            settle   <= SETTLE_CYC;
            deadline <= SETTLE_CYC + 64'd1;
            win      <= 1'b0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (start_valid) begin
                        last_idx <= start_last;
                        idx      <= {IDXW{1'b0}};
                        settle   <= SETTLE_CYC;
                        deadline <= SETTLE_CYC + 64'd1;
                        state    <= S_SETTLE;
                        win      <= 1'b1;
                    end
                end
                S_SETTLE: begin
                    if (tick) begin
                        if (settle == 64'd0) begin
                            state <= S_OUT;
                        end else begin
                            settle   <= settle - 64'd1;
                            deadline <= deadline - 64'd1;
                        end
                    end
                end
                S_OUT: begin
                    if (out_ready) begin
                        if (idx == last_idx) begin
                            state <= S_IDLE;
                            win   <= 1'b0;
                        end else begin
                            idx      <= idx + 1'b1;
                            settle   <= SETTLE_CYC;
                            deadline <= SETTLE_CYC + 64'd1;
                            state    <= S_SETTLE;
                        end
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // bounded response: a settle step taken inside the scan window never expires the deadline
    always @(posedge clk)
        if (pv && $past(win) && $past(state) == S_SETTLE && $past(tick))
            assert (deadline != 64'd0);
endmodule

module pkt_framer #(
    parameter W = 16,
    parameter DEPTH = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_start,
    input  wire [W-1:0] i_len,
    input  wire [W-1:0] i_data,
    output reg  [W-1:0] o_word,
    output reg          o_sof,
    output reg          o_eof
);
    localparam [W-1:0] MAX_LEN    = DEPTH;
    localparam [W-1:0] START_DELIM = 16'hA5A5;
    localparam [W-1:0] END_DELIM   = 16'h5A5A;
    localparam [1:0] S_IDLE = 2'd0, S_HDR = 2'd1, S_PAY = 2'd2, S_TRL = 2'd3;

    reg [1:0]   frame_state = S_IDLE;
    reg [W-1:0] byte_cnt    = {W{1'b0}};
    reg [W-1:0] len_reg     = {{(W-1){1'b0}}, 1'b1};
    reg         armed       = 1'b0;
    reg         pv          = 1'b0;
    initial o_word = {W{1'b0}};
    initial o_sof  = 1'b0;
    initial o_eof  = 1'b0;

    wire [W-1:0] len_clamped = (i_len == {W{1'b0}}) ? {{(W-1){1'b0}}, 1'b1} :
                               ((i_len > MAX_LEN) ? MAX_LEN : i_len);
    wire over_lim = (byte_cnt > MAX_LEN);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            frame_state <= S_IDLE;
            byte_cnt    <= {W{1'b0}};
            len_reg     <= {{(W-1){1'b0}}, 1'b1};
            o_word      <= {W{1'b0}};
            o_sof       <= 1'b0;
            o_eof       <= 1'b0;
        end else if (i_ce) begin
            case (frame_state)
                S_IDLE: begin
                    o_sof <= 1'b0;
                    o_eof <= 1'b0;
                    if (i_start) begin
                        len_reg     <= len_clamped;
                        o_word      <= START_DELIM;
                        o_sof       <= 1'b1;
                        armed       <= 1'b1;
                        frame_state <= S_HDR;
                    end
                end
                S_HDR: begin
                    o_sof       <= 1'b0;
                    o_word      <= len_reg;
                    byte_cnt    <= {W{1'b0}};
                    frame_state <= S_PAY;
                end
                S_PAY: begin
                    o_word <= i_data;
                    if (byte_cnt == len_reg - 1'b1) begin
                        byte_cnt    <= {W{1'b0}};
                        frame_state <= S_TRL;
                    end else begin
                        byte_cnt <= byte_cnt + 1'b1;
                    end
                end
                S_TRL: begin
                    o_word      <= END_DELIM;
                    o_eof       <= 1'b1;
                    frame_state <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && armed && $stable(frame_state))
            assert ($stable(over_lim));
endmodule

module search_fifo #(
    parameter DEPTH = 32,
    parameter DW = 16,
    parameter AW = $clog2(DEPTH)
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            in_valid,
    output wire            in_ready,
    input  wire [DW-1:0]   in_data,
    output wire            out_valid,
    input  wire            out_ready,
    output wire [DW-1:0]   out_data,
    input  wire            srch_valid,
    output wire            srch_ready,
    input  wire [DW-1:0]   srch_key,
    output wire            srch_present,
    output wire [DEPTH-1:0] srch_vec,
    output wire            res_valid,
    input  wire            res_ready,
    output wire [AW-1:0]   res_pos,
    output wire            res_hit,
    output wire            res_last,
    input  wire            cfg_we,
    input  wire [15:0]     cfg_timeout
);
    localparam [15:0] DEPTH16 = DEPTH;

    reg [DEPTH*DW-1:0] mem;
    reg [DEPTH-1:0]    vld;
    reg [AW-1:0]       head, tail;
    reg [15:0]         count;
    reg                busy;
    reg [DW-1:0]       key_q;
    reg [AW-1:0]       scan_idx;
    reg [15:0]         scan_left;
    reg [15:0]         timer;
    reg [15:0]         timeout_q;
    reg                armed;

    initial begin
        mem = {(DEPTH*DW){1'b0}};
        vld = {DEPTH{1'b0}};
        head = {AW{1'b0}};
        tail = {AW{1'b0}};
        count = 16'd0;
        busy = 1'b0;
        key_q = {DW{1'b0}};
        scan_idx = {AW{1'b0}};
        scan_left = 16'd0;
        timer = 16'd0;
        timeout_q = DEPTH16;
        armed = 1'b1;
    end

    assign in_ready   = (count != DEPTH16) && !busy;
    assign out_valid  = (count != 16'd0);
    assign out_data   = mem[head*DW +: DW];
    assign srch_ready = !busy;
    assign res_valid  = busy;
    assign res_pos    = scan_idx;
    assign res_hit    = vld[scan_idx] && (mem[scan_idx*DW +: DW] == key_q);
    assign res_last   = (scan_left == 16'd1);

    genvar gi;
    generate
        for (gi = 0; gi < DEPTH; gi = gi + 1) begin : g_cmp
            assign srch_vec[gi] = vld[gi] && (mem[gi*DW +: DW] == srch_key);
        end
    endgenerate
    assign srch_present = |srch_vec;

    wire push_fire = in_valid && in_ready;
    wire pop_fire  = out_valid && out_ready;
    wire srch_fire = srch_valid && srch_ready;
    wire res_fire  = res_valid && res_ready;
    wire cfg_fire  = cfg_we && !busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mem <= {(DEPTH*DW){1'b0}};
            vld <= {DEPTH{1'b0}};
            head <= {AW{1'b0}};
            tail <= {AW{1'b0}};
            count <= 16'd0;
            busy <= 1'b0;
            key_q <= {DW{1'b0}};
            scan_idx <= {AW{1'b0}};
            scan_left <= 16'd0;
            timer <= 16'd0;
            timeout_q <= DEPTH16;
            armed <= 1'b1;
        end else begin
            if (push_fire) begin
                mem[tail*DW +: DW] <= in_data;
                vld[tail] <= 1'b1;
                tail <= tail + 1'b1;
            end
            if (pop_fire) begin
                vld[head] <= 1'b0;
                head <= head + 1'b1;
            end
            case ({push_fire, pop_fire})
                2'b10: count <= count + 16'd1;
                2'b01: count <= count - 16'd1;
                default: ;
            endcase

            if (srch_fire) begin
                key_q     <= srch_key;
                scan_idx  <= head;
                scan_left <= count;
                timer     <= timeout_q;
                busy      <= (count != 16'd0);
            end else if (res_fire) begin
                scan_idx  <= scan_idx + 1'b1;
                scan_left <= scan_left - 16'd1;
                if (timer != 16'd0)
                    timer <= timer - 16'd1;
                if (scan_left == 16'd1)
                    busy <= 1'b0;
            end

            if (cfg_fire) begin
                timeout_q <= cfg_timeout;
                armed     <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed && busy)
            assert (timer != 16'd0);
endmodule

module agu_burst #(
    parameter AW     = 32,
    parameter BURST  = 8,
    parameter STRIDE = 4
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          start,
    input  wire          pre_inc,
    input  wire [AW-1:0] base_in,
    input  wire [AW-1:0] index_in,
    input  wire [AW-1:0] disp_in,
    input  wire [1:0]    scale_in,
    output wire [AW-1:0] ea,
    output wire          fault
);
    typedef enum logic [1:0] {IDLE = 2'd0, RUN = 2'd1, DONE = 2'd2} state_t;

    state_t state = IDLE;
    reg [AW-1:0] base_r = {AW{1'b0}};
    reg [AW-1:0] end_r  = {AW{1'b0}};
    reg [AW-1:0] ea_r   = {AW{1'b0}};
    reg [AW-1:0] beats  = {AW{1'b0}};
    reg          fault_r = 1'b0;
    reg          armed   = 1'b1;

    wire [AW-1:0] step_base = base_r + STRIDE;
    wire [AW-1:0] scaled_ix = index_in << scale_in;
    wire [AW-1:0] ea_next   = (pre_inc ? step_base : base_r) + scaled_ix + disp_in;
    wire          misaligned = |ea_next[1:0];

    always @(posedge clk) begin
        if (rst) begin
            state   <= IDLE;
            base_r  <= {AW{1'b0}};
            end_r   <= {AW{1'b0}};
            ea_r    <= {AW{1'b0}};
            beats   <= {AW{1'b0}};
            fault_r <= 1'b0;
        end else if (ce) begin
            case (state)
                IDLE: if (start) begin
                    base_r  <= base_in;
                    end_r   <= base_in + BURST * STRIDE;
                    beats   <= {AW{1'b0}};
                    fault_r <= 1'b0;
                    state   <= RUN;
                end
                RUN: begin
                    ea_r    <= ea_next;
                    fault_r <= misaligned;
                    base_r  <= step_base;
                    beats   <= beats + 1'b1;
                    if (step_base == end_r)
                        state <= DONE;
                end
                DONE: state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (!rst && ce && state == RUN && misaligned)
            armed <= 1'b0;

    assign ea    = ea_r;
    assign fault = fault_r;

    assert property (!armed || beats <= BURST);
endmodule

module seg_rot_shifter #(
    parameter W = 32,
    parameter SEGS = 4
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [W-1:0]      in_data,
    input  wire [31:0]       in_amt,
    input  wire              step,
    output reg               out_valid,
    input  wire              out_ready,
    output wire [SEGS*W-1:0] out_data
);
    reg [SEGS*W-1:0] segs;
    reg [SEGS-1:0]   spill;
    reg              par;
    reg              busy;
    reg [31:0]       cnt;

    initial segs = {SEGS*W{1'b0}};
    initial spill = {SEGS{1'b0}};
    initial par = 1'b0;
    initial busy = 1'b0;
    initial cnt = 32'd0;
    initial out_valid = 1'b0;

    assign in_ready = !busy && !out_valid;
    assign out_data = segs;

    reg [SEGS*W-1:0] seg_nxt;
    reg [SEGS-1:0]   sp_nxt;
    integer i;
    always @(*) begin
        for (i = 0; i < SEGS; i = i + 1) begin
            seg_nxt[i*W +: W] = {segs[i*W +: (W-1)], spill[(i+SEGS-1)%SEGS]};
            sp_nxt[i] = segs[i*W + W - 2];
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            segs <= {SEGS*W{1'b0}};
            spill <= {SEGS{1'b0}};
            par <= 1'b0;
            busy <= 1'b0;
            cnt <= 32'd0;
            out_valid <= 1'b0;
        end else begin
            if (in_valid && in_ready) begin
                segs <= {{((SEGS-1)*W){1'b0}}, in_data};
                spill <= {{(SEGS-1){1'b0}}, in_data[W-1]};
                par <= ^in_data;
                cnt <= in_amt;
                busy <= 1'b1;
            end else if (busy && step) begin
                if (cnt == 32'd0) begin
                    busy <= 1'b0;
                    out_valid <= 1'b1;
                end else begin
                    segs <= seg_nxt;
                    spill <= sp_nxt;
                    cnt <= cnt - 32'd1;
                end
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    always @(posedge clk)
        if (busy) assert ((^segs) == par);
endmodule

module pkt_stream_mux #(
    parameter NSRC = 4,
    parameter DW   = 128,
    parameter CNTW = 3,
    parameter SRCW = $clog2(NSRC)
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire [NSRC-1:0]      s_valid,
    input  wire [NSRC*DW-1:0]   s_data,
    input  wire [NSRC-1:0]      s_last,
    output wire [NSRC-1:0]      s_ready,
    output reg                  o_valid,
    output reg  [DW-1:0]        o_data,
    output reg                  o_last,
    output reg  [SRCW-1:0]      o_src,
    input  wire                 o_ready
);
    reg [SRCW-1:0] cur_src  = {SRCW{1'b0}};
    reg            locked   = 1'b0;
    reg [CNTW-1:0] beat_cnt = {CNTW{1'b0}};
    initial begin
        o_valid = 1'b0;
        o_data  = {DW{1'b0}};
        o_last  = 1'b0;
        o_src   = {SRCW{1'b0}};
    end

    wire            can_load = !o_valid || o_ready;
    wire            take     = can_load && s_valid[cur_src];
    wire [DW-1:0]   sel_data = s_data[cur_src*DW +: DW];
    wire            sel_last = s_last[cur_src];
    wire [SRCW-1:0] next_src = (cur_src == NSRC-1) ? {SRCW{1'b0}} : cur_src + {{(SRCW-1){1'b0}},1'b1};

    assign s_ready = can_load ? ({{(NSRC-1){1'b0}},1'b1} << cur_src) : {NSRC{1'b0}};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cur_src  <= {SRCW{1'b0}};
            locked   <= 1'b0;
            beat_cnt <= {CNTW{1'b0}};
            o_valid  <= 1'b0;
            o_data   <= {DW{1'b0}};
            o_last   <= 1'b0;
            o_src    <= {SRCW{1'b0}};
        end else begin
            if (take) begin
                o_valid <= 1'b1;
                o_data  <= sel_data;
                o_last  <= sel_last;
                o_src   <= cur_src;
                if (sel_last) begin
                    locked   <= 1'b0;
                    beat_cnt <= {CNTW{1'b0}};
                    cur_src  <= next_src;
                end else begin
                    locked   <= 1'b1;
                    beat_cnt <= (beat_cnt == {CNTW{1'b1}}) ? beat_cnt : beat_cnt + {{(CNTW-1){1'b0}},1'b1};
                end
            end else begin
                if (o_valid && o_ready)
                    o_valid <= 1'b0;
                if (!locked && !s_valid[cur_src] && (|s_valid))
                    cur_src <= next_src;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $rose(locked))
            assert (beat_cnt == {{(CNTW-1){1'b0}},1'b1});
endmodule

module frac_xmul_cmp #(
    parameter W = 16,
    parameter [15:0] LAT = 16'd3
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         ce,
    input  wire         req,
    input  wire [W-1:0] a_num,
    input  wire [W-1:0] a_den,
    input  wire [W-1:0] c_num,
    input  wire [W-1:0] c_den,
    output wire         busy_o,
    output wire         done_o,
    output wire         lt_o,
    output wire         eq_o
);
    reg           busy    = 1'b0;
    reg  [1:0]    stage   = 2'd0;
    reg  [15:0]   cnt     = 16'd0;
    reg           armed   = 1'b0;
    reg  [W-1:0]  ra      = {W{1'b0}};
    reg  [W-1:0]  rb      = {W{1'b0}};
    reg  [W-1:0]  rc      = {W{1'b0}};
    reg  [W-1:0]  rd      = {W{1'b0}};
    reg  [2*W-1:0] prod_ad = {2*W{1'b0}};
    reg  [2*W-1:0] prod_cb = {2*W{1'b0}};
    reg           lt_r    = 1'b0;
    reg           eq_r    = 1'b0;
    reg           done_r  = 1'b0;

    assign busy_o = busy;
    assign done_o = done_r;
    assign lt_o   = lt_r;
    assign eq_o   = eq_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy    <= 1'b0;
            stage   <= 2'd0;
            cnt     <= 16'd0;
            armed   <= 1'b0;
            ra      <= {W{1'b0}};
            rb      <= {W{1'b0}};
            rc      <= {W{1'b0}};
            rd      <= {W{1'b0}};
            prod_ad <= {2*W{1'b0}};
            prod_cb <= {2*W{1'b0}};
            lt_r    <= 1'b0;
            eq_r    <= 1'b0;
            done_r  <= 1'b0;
        end else if (ce) begin
            done_r <= 1'b0;
            if (!busy) begin
                if (req) begin
                    busy  <= 1'b1;
                    armed <= 1'b1;
                    stage <= 2'd0;
                    cnt   <= LAT;
                    ra    <= a_num;
                    rb    <= a_den;
                    rc    <= c_num;
                    rd    <= c_den;
                end
            end else begin
                cnt <= cnt - 16'd1;
                case (stage)
                    2'd0: begin
                        prod_ad <= ra * rd;
                        prod_cb <= rc * rb;
                        stage   <= 2'd1;
                    end
                    2'd1: begin
                        lt_r  <= (prod_ad < prod_cb);
                        eq_r  <= (prod_ad == prod_cb);
                        stage <= 2'd2;
                    end
                    default: begin
                        busy   <= 1'b0;
                        done_r <= 1'b1;
                        stage  <= 2'd0;
                    end
                endcase
            end
        end
    end

    assert property (!armed || !busy || cnt != 16'd0);
endmodule

module uart_break_detect #(
    parameter [31:0] FRAME = 32'd10
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    input  wire s_line,
    output wire s_ready,
    output reg  m_valid,
    input  wire m_ready,
    output reg  brk_sticky
);
    reg [31:0] low_cnt = 32'd0;
    reg        in_brk  = 1'b0;
    reg        win     = 1'b0;
    initial m_valid    = 1'b0;
    initial brk_sticky = 1'b0;

    assign s_ready = !m_valid;
    wire acc = s_valid && s_ready;

    always @(posedge clk) begin
        if (rst) begin
            low_cnt    <= 32'd0;
            in_brk     <= 1'b0;
            win        <= 1'b0;
            m_valid    <= 1'b0;
            brk_sticky <= 1'b0;
        end else begin
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (acc) begin
                if (!s_line) begin
                    win <= 1'b1;
                    if (!in_brk) begin
                        if (low_cnt == FRAME - 32'd1) begin
                            low_cnt    <= FRAME;
                            in_brk     <= 1'b1;
                            brk_sticky <= 1'b1;
                            m_valid    <= 1'b1;
                        end else begin
                            low_cnt <= low_cnt + 32'd1;
                        end
                    end
                end else begin
                    low_cnt <= 32'd0;
                    in_brk  <= 1'b0;
                    win     <= 1'b0;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win)
            assert (low_cnt <= FRAME && $past(low_cnt) <= FRAME);
endmodule

module warm_reset_quiesce #(
    parameter NPORTS = 64,
    parameter [31:0] TIMEOUT = 32'd16
) (
    input  wire              clk,
    input  wire              ce,
    input  wire              req_valid,
    output wire              req_ready,
    input  wire [NPORTS-1:0] port_idle,
    output wire              quiesce_req,
    output wire              block_new,
    output reg               warm_rst,
    output reg               timed_out
);
    reg              quiesce;
    reg [31:0]       timer;
    reg [31:0]       elapsed;
    reg [NPORTS-1:0] ack;
    reg              before_rst;

    initial begin
        quiesce    = 1'b0;
        timer      = 32'd0;
        elapsed    = 32'd0;
        ack        = {NPORTS{1'b0}};
        warm_rst   = 1'b0;
        timed_out  = 1'b0;
        before_rst = 1'b1;
    end

    assign req_ready   = ce && !quiesce;
    assign quiesce_req = quiesce;
    assign block_new   = quiesce;

    wire accept   = req_valid && req_ready;
    wire all_idle = &(ack | port_idle);
    wire expire   = (elapsed == TIMEOUT - 32'd1);

    always @(posedge clk) begin
        if (ce) begin
            warm_rst <= 1'b0;
            if (!quiesce) begin
                if (accept) begin
                    quiesce <= 1'b1;
                    timer   <= TIMEOUT;
                    elapsed <= 32'd0;
                    ack     <= {NPORTS{1'b0}};
                end
            end else begin
                ack <= ack | port_idle;
                if (all_idle || expire) begin
                    quiesce    <= 1'b0;
                    warm_rst   <= 1'b1;
                    timed_out  <= !all_idle;
                    before_rst <= 1'b0;
                end else begin
                    timer   <= timer - 32'd1;
                    elapsed <= elapsed + 32'd1;
                end
            end
        end
    end

    always @(*) assert (!(before_rst && quiesce) || timer != 32'd0);
endmodule

module csc_pipe #(
    parameter DW    = 64,
    parameter NCOEF = 8,
    parameter AW    = 3
) (
    input  wire          clk,
    input  wire          i_reset,
    // coefficient configuration port
    input  wire          cfg_valid,
    output wire          cfg_ready,
    input  wire [AW-1:0] cfg_addr,
    input  wire [DW-1:0] cfg_data,
    input  wire          cfg_last,
    // pixel input stream (R,G,B)
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_r,
    input  wire [DW-1:0] in_g,
    input  wire [DW-1:0] in_b,
    // pixel output stream (Cb,Cr)
    output reg           o_valid,
    input  wire          out_ready,
    output reg  [DW-1:0] o_cb,
    output reg  [DW-1:0] o_cr
);
    // coefficient bank: 0..2 Cb row, 3..5 Cr row, 6 Cb offset, 7 Cr offset
    reg [NCOEF*DW-1:0] coef;
    initial coef = {(NCOEF*DW){1'b0}};

    reg armed;    // window: coefficients committed (arm)
    reg started;  // a pixel has been accepted (start)
    reg s1_valid; // multiply stage holds a pixel
    initial armed    = 1'b0;
    initial started  = 1'b0;
    initial s1_valid = 1'b0;
    initial o_valid  = 1'b0;

    reg [DW-1:0] p0, p1, p2, p3, p4, p5;
    initial begin
        p0 = {DW{1'b0}}; p1 = {DW{1'b0}}; p2 = {DW{1'b0}};
        p3 = {DW{1'b0}}; p4 = {DW{1'b0}}; p5 = {DW{1'b0}};
        o_cb = {DW{1'b0}}; o_cr = {DW{1'b0}};
    end

    // whole pipeline stalls when downstream is not ready
    wire advance = out_ready;
    assign cfg_ready = !s1_valid && !o_valid;
    wire cfg_fire = cfg_valid && cfg_ready;
    assign in_ready  = armed && out_ready && !cfg_valid;
    wire in_fire  = in_valid && in_ready;

    always @(posedge clk) begin
        if (i_reset) begin
            armed    <= 1'b0;
            started  <= 1'b0;
            s1_valid <= 1'b0;
            o_valid  <= 1'b0;
        end else begin
            if (cfg_fire) begin
                coef[cfg_addr*DW +: DW] <= cfg_data;
                if (cfg_last)
                    armed <= 1'b1;
            end
            if (in_fire)
                started <= 1'b1;
            if (advance) begin
                s1_valid <= in_fire;
                o_valid  <= s1_valid;
            end
        end
    end

    // datapath: matrix multiply stage then sum/offset output register
    always @(posedge clk) begin
        if (advance) begin
            p0 <= in_r * coef[0*DW +: DW];
            p1 <= in_g * coef[1*DW +: DW];
            p2 <= in_b * coef[2*DW +: DW];
            p3 <= in_r * coef[3*DW +: DW];
            p4 <= in_g * coef[4*DW +: DW];
            p5 <= in_b * coef[5*DW +: DW];
            o_cb <= p0 + p1 + p2 + coef[6*DW +: DW];
            o_cr <= p3 + p4 + p5 + coef[7*DW +: DW];
        end
    end

    // chain precedence after commit: a delivered pixel implies a pixel was started
    always @(posedge clk)
        assert (!(armed && o_valid) || started);
endmodule

module axi_w_cdc_bridge #(
    parameter DW    = 16,
    parameter AW    = 8,
    parameter DEPTH = 256
) (
    input  wire          clk,
    input  wire          rst_n,
    // slave side (write domain): AXI W channel beats enter here
    input  wire          s_valid,
    output wire          s_ready,
    input  wire [DW-1:0] s_data,
    input  wire          s_last,
    // master side (read domain): beats leave here
    output wire          m_valid,
    input  wire          m_ready,
    output wire [DW-1:0] m_data,
    output wire          m_last
);
    // dual-clock payload storage (data + last flag)
    reg [DW:0] mem [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {(DW+1){1'b0}};
    end

    // write-side pointers and synchronized copy of the read pointer
    reg [AW:0]   wptr_bin  = {(AW+1){1'b0}};
    reg [AW:0]   wptr_gray = {(AW+1){1'b0}};
    reg [AW:0]   rq1       = {(AW+1){1'b0}};
    reg [AW:0]   rq2       = {(AW+1){1'b0}};
    reg          win       = 1'b0;
    reg [15:0]   beat_cnt  = 16'd0;

    // read-side pointers and synchronized copy of the write pointer
    reg [AW:0]   rptr_bin  = {(AW+1){1'b0}};
    reg [AW:0]   rptr_gray = {(AW+1){1'b0}};
    reg [AW:0]   wq1       = {(AW+1){1'b0}};
    reg [AW:0]   wq2       = {(AW+1){1'b0}};

    wire [AW:0] wbin_nxt  = wptr_bin + 1'b1;
    wire [AW:0] wgray_nxt = wbin_nxt ^ (wbin_nxt >> 1);
    wire [AW:0] rbin_nxt  = rptr_bin + 1'b1;
    wire [AW:0] rgray_nxt = rbin_nxt ^ (rbin_nxt >> 1);

    wire full  = (wptr_gray == {~rq2[AW:AW-1], rq2[AW-2:0]});
    wire empty = (rptr_gray == wq2);

    assign s_ready = !full;
    assign m_valid = !empty;

    wire do_push = s_valid && s_ready;
    wire do_pop  = m_valid && m_ready;

    assign {m_last, m_data} = mem[rptr_bin[AW-1:0]];

    always @(posedge clk)
        if (do_push) mem[wptr_bin[AW-1:0]] <= {s_last, s_data};

    // write domain
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr_bin  <= {(AW+1){1'b0}};
            wptr_gray <= {(AW+1){1'b0}};
            rq1       <= {(AW+1){1'b0}};
            rq2       <= {(AW+1){1'b0}};
            win       <= 1'b0;
            beat_cnt  <= 16'd0;
        end else begin
            if (do_push) begin
                wptr_bin  <= wbin_nxt;
                wptr_gray <= wgray_nxt;
                if (s_last) begin
                    win      <= 1'b0;
                    beat_cnt <= 16'd0;
                end else begin
                    win      <= 1'b1;
                    beat_cnt <= beat_cnt + 16'd1;
                end
            end
            if (s_valid) begin
                rq1 <= rptr_gray;
                rq2 <= rq1;
            end
        end
    end

    // read domain
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rptr_bin  <= {(AW+1){1'b0}};
            rptr_gray <= {(AW+1){1'b0}};
            wq1       <= {(AW+1){1'b0}};
            wq2       <= {(AW+1){1'b0}};
        end else begin
            if (do_pop) begin
                rptr_bin  <= rbin_nxt;
                rptr_gray <= rgray_nxt;
            end
            if (m_ready) begin
                wq1 <= wptr_gray;
                wq2 <= wq1;
            end
        end
    end

    // past-valid, cleared by reset
    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;

    // inside a burst window: the gray write pointer never holds still while
    // the binary write pointer moves
    always @(posedge clk)
        if (pv && win && $stable(wptr_gray))
            assert ($stable(wptr_bin));
endmodule

module lane_tile_transpose #(
    parameter N = 4,
    parameter W = 64
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_data
);
    localparam IW = $clog2(N);
    localparam ENTRIES = N * N;

    typedef enum logic [0:0] {FILL = 1'b0, DRAIN = 1'b1} state_t;
    state_t state;
    initial state = FILL;

    // lane-sensor tile: rows = approach lanes, columns = signal phases
    reg [W-1:0] mem [0:ENTRIES-1];
    integer k;
    initial begin
        for (k = 0; k < ENTRIES; k = k + 1)
            mem[k] = {W{1'b0}};
    end

    reg [IW-1:0] wrow, wcol, rrow, rcol;
    initial wrow = 0;
    initial wcol = 0;
    initial rrow = 0;
    initial rcol = 0;

    // shadow history registers
    reg [63:0] wr_total, rd_total;
    initial wr_total = 64'd0;
    initial rd_total = 64'd0;

    // scope register: high until the first tile has been fully drained
    reg armed;
    initial armed = 1'b1;

    assign in_ready  = (state == FILL);
    assign out_valid = (state == DRAIN);
    assign out_data  = mem[{rrow, rcol}];

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wrow == N-1) && (wcol == N-1);
    wire rd_last = (rrow == N-1) && (rcol == N-1);

    always @(posedge clk) begin
        if (wr_fire) begin
            mem[{wrow, wcol}] <= in_data;
            wr_total <= wr_total + 64'd1;
            if (wcol == N-1) begin
                wcol <= 0;
                wrow <= wrow + 1'b1;
            end else begin
                wcol <= wcol + 1'b1;
            end
            if (wr_last)
                state <= DRAIN;
        end
        if (rd_fire) begin
            rd_total <= rd_total + 64'd1;
            if (rrow == N-1) begin
                rrow <= 0;
                rcol <= rcol + 1'b1;
            end else begin
                rrow <= rrow + 1'b1;
            end
            if (rd_last) begin
                state <= FILL;
                armed <= 1'b0;
            end
        end
    end

    // Precedence, before first drain completes: a phase column is offered only after the whole tile was written
    always @(posedge clk)
        if (armed && out_valid)
            assert (wr_total == ENTRIES);

    // Precedence, before first drain completes: every item read was written earlier
    always @(posedge clk)
        if (armed)
            assert (rd_total <= wr_total);
endmodule

module islip_alloc #(
    parameter N = 4
) (
    input  wire           clk,
    input  wire           rst_n,
    input  wire           en,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   release_i,
    output wire [N-1:0]   o_in_busy,
    output wire [31:0]    o_active
);
    localparam PW = (N <= 2) ? 1 : $clog2(N);

    reg [N-1:0]    in_busy    = {N{1'b0}};
    reg [N-1:0]    out_busy   = {N{1'b0}};
    reg [N*PW-1:0] g_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] a_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] conn       = {(N*PW){1'b0}};
    reg [31:0]     active_cnt = 32'd0;
    reg            armed      = 1'b0;

    reg [N*N-1:0]  ereq, gnt, acc;
    reg [N-1:0]    new_in, new_out, rel_in, rel_out;
    reg [N*PW-1:0] acc_out, acc_in;
    reg [31:0]     new_cnt, rel_cnt;
    integer i, j, k, idx;
    reg found;

    always @(*) begin
        ereq = {(N*N){1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                ereq[i*N+j] = req[i*N+j] & ~in_busy[i] & ~out_busy[j];
        gnt = {(N*N){1'b0}};
        for (j = 0; j < N; j = j + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (g_ptr[j*PW +: PW] + k) % N;
                for (i = 0; i < N; i = i + 1)
                    if (!found && (i == idx) && ereq[i*N+j]) begin
                        gnt[j*N+i] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        acc = {(N*N){1'b0}};
        acc_out = {(N*PW){1'b0}};
        acc_in = {(N*PW){1'b0}};
        new_in = {N{1'b0}};
        new_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (a_ptr[i*PW +: PW] + k) % N;
                for (j = 0; j < N; j = j + 1)
                    if (!found && (j == idx) && gnt[j*N+i]) begin
                        acc[i*N+j] = 1'b1;
                        acc_out[i*PW +: PW] = j;
                        acc_in[j*PW +: PW] = i;
                        new_in[i] = 1'b1;
                        new_out[j] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        rel_in = release_i & in_busy;
        rel_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                if (rel_in[i] && (conn[i*PW +: PW] == j))
                    rel_out[j] = 1'b1;
        new_cnt = 32'd0;
        rel_cnt = 32'd0;
        for (i = 0; i < N; i = i + 1) begin
            new_cnt = new_cnt + new_in[i];
            rel_cnt = rel_cnt + rel_in[i];
        end
    end

    integer p;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            in_busy    <= {N{1'b0}};
            out_busy   <= {N{1'b0}};
            g_ptr      <= {(N*PW){1'b0}};
            a_ptr      <= {(N*PW){1'b0}};
            conn       <= {(N*PW){1'b0}};
            active_cnt <= 32'd0;
            armed      <= 1'b0;
        end else if (en) begin
            in_busy  <= (in_busy & ~rel_in) | new_in;
            out_busy <= (out_busy & ~rel_out) | new_out;
            for (p = 0; p < N; p = p + 1) begin
                if (new_in[p]) begin
                    conn[p*PW +: PW]  <= acc_out[p*PW +: PW];
                    a_ptr[p*PW +: PW] <= (acc_out[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_out[p*PW +: PW] + 1'b1;
                end
                if (new_out[p])
                    g_ptr[p*PW +: PW] <= (acc_in[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_in[p*PW +: PW] + 1'b1;
            end
            active_cnt <= active_cnt + new_cnt - rel_cnt;
            if (new_cnt != 32'd0)
                armed <= 1'b1;
        end
    end

    assign o_in_busy = in_busy;
    assign o_active  = active_cnt;

    always @(posedge clk)
        if (armed)
            assert (active_cnt <= N);
endmodule

module pam4_gray_mapper #(
    parameter CW = 32
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       slip,
    input  wire       precode_en,
    input  wire       din,
    output reg  [1:0] sym_out,
    output reg        sym_valid,
    output wire       pair_pending
);
    // bit-pair staging register
    reg          stage_bit;
    reg          half;
    // precoder previous-symbol register
    reg  [1:0]   prev_sym;
    // statistics
    reg  [CW-1:0] bit_cnt;
    reg  [CW-1:0] sym_cnt;
    reg  [CW-1:0] drop_cnt;
    // scope register: high until the first bit slip
    reg          armed;

    initial begin
        stage_bit = 1'b0;
        half      = 1'b0;
        prev_sym  = 2'd0;
        bit_cnt   = {CW{1'b0}};
        sym_cnt   = {CW{1'b0}};
        drop_cnt  = {CW{1'b0}};
        armed     = 1'b1;
        sym_out   = 2'd0;
        sym_valid = 1'b0;
    end

    wire [1:0] pair  = {stage_bit, din};
    // Gray map: 00->0, 01->1, 11->2, 10->3
    wire [1:0] level = {pair[1], pair[1] ^ pair[0]};
    wire [1:0] coded = precode_en ? (level - prev_sym) : level;

    always @(posedge clk) begin
        if (rst) begin
            stage_bit <= 1'b0;
            half      <= 1'b0;
            prev_sym  <= 2'd0;
            bit_cnt   <= {CW{1'b0}};
            sym_cnt   <= {CW{1'b0}};
            drop_cnt  <= {CW{1'b0}};
            armed     <= 1'b1;
            sym_out   <= 2'd0;
            sym_valid <= 1'b0;
        end else if (ce) begin
            if (slip) begin
                armed     <= 1'b0;
                sym_valid <= 1'b0;
                if (half) begin
                    half     <= 1'b0;
                    drop_cnt <= drop_cnt + {{(CW-1){1'b0}}, 1'b1};
                end
            end else begin
                bit_cnt <= bit_cnt + {{(CW-1){1'b0}}, 1'b1};
                if (!half) begin
                    stage_bit <= din;
                    half      <= 1'b1;
                    sym_valid <= 1'b0;
                end else begin
                    half      <= 1'b0;
                    sym_cnt   <= sym_cnt + {{(CW-1){1'b0}}, 1'b1};
                    sym_out   <= coded;
                    prev_sym  <= coded;
                    sym_valid <= 1'b1;
                end
            end
        end
    end

    assign pair_pending = half;

    // Absence, before the first slip: the staging register is never occupied
    // while the bit count sits on a pair boundary.
    always @(posedge clk)
        if (armed)
            assert (!(half && (bit_cnt[0] == 1'b0)));
endmodule

module preload_timer #(
    parameter W = 16
) (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire [W-1:0] o_cnt,
    output wire         o_match,
    output wire         o_wrap
);
    reg [W-1:0] cnt        = {W{1'b0}};
    reg [W-1:0] period_act = 16'd9;
    reg [W-1:0] period_sh  = 16'd9;
    reg [W-1:0] cmp_act    = 16'd4;
    reg [W-1:0] cmp_sh     = 16'd4;
    reg         pend       = 1'b0;
    reg         armed      = 1'b0;
    reg         pv         = 1'b0;

    assign in_ready = !pend;
    wire accept = in_valid && in_ready;
    wire wrap   = i_ce && (cnt >= period_act);

    assign o_cnt   = cnt;
    assign o_match = (cnt == cmp_act);
    assign o_wrap  = wrap;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (cnt >= period_act) begin
                cnt        <= {W{1'b0}};
                period_act <= period_sh;
                cmp_act    <= cmp_sh;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
        if (accept) begin
            period_sh <= in_period;
            cmp_sh    <= in_cmp;
            pend      <= 1'b1;
        end else if (wrap) begin
            pend      <= 1'b0;
        end
        if (accept)
            armed <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed && $stable(pend))
            assert ($stable(period_act));
endmodule

module idle_autopd #(
    parameter DATA_W = 128,
    parameter CNT_W  = 4,
    parameter [CNT_W-1:0] DEF_THR = 4'd6
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [DATA_W-1:0] in_data,
    input  wire              tick,
    input  wire              cfg_thr_we,
    input  wire [CNT_W-1:0]  cfg_thr,
    input  wire              cfg_en,
    input  wire              cfg_dis,
    output wire              pwr_down_req,
    output reg  [DATA_W-1:0] blk_data
);
    reg [CNT_W-1:0] idle_cnt = {CNT_W{1'b0}};
    reg [CNT_W-1:0] thresh   = DEF_THR;
    reg             pd_req   = 1'b0;
    reg             apd_en   = 1'b0;
    initial blk_data = {DATA_W{1'b0}};

    assign in_ready     = !pd_req;
    assign pwr_down_req = pd_req && apd_en;

    wire accept = in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            idle_cnt <= {CNT_W{1'b0}};
            thresh   <= DEF_THR;
            pd_req   <= 1'b0;
        end else if (cfg_thr_we) begin
            thresh   <= (cfg_thr == {CNT_W{1'b0}}) ? {{(CNT_W-1){1'b0}}, 1'b1} : cfg_thr;
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (in_valid) begin
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (tick && !pd_req) begin
            idle_cnt <= idle_cnt + 1'b1;
            if (idle_cnt + 1'b1 == thresh)
                pd_req <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (!rst && accept)
            blk_data <= in_data;
    end

    always @(posedge clk) begin
        if (rst)
            apd_en <= 1'b0;
        else if (cfg_dis)
            apd_en <= 1'b0;
        else if (cfg_en)
            apd_en <= 1'b1;
    end

    always @(*) assert (!apd_en || idle_cnt <= thresh);
endmodule

module exp_scale_unit #(
    parameter W = 32,
    parameter signed EMAX = 127,
    parameter signed EMIN = -126
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [W-1:0] i_exp,
    input  wire [W-1:0] i_scale,
    input  wire [W-1:0] i_sig,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [W-1:0] o_exp,
    output reg  [W-1:0] o_sig,
    output reg          o_ovf,
    output reg          o_uf,
    output reg  [W-1:0] ovf_in_cnt,
    output reg  [W-1:0] ovf_out_cnt
);
    initial begin
        o_valid = 1'b0; o_exp = {W{1'b0}}; o_sig = {W{1'b0}};
        o_ovf = 1'b0; o_uf = 1'b0;
        ovf_in_cnt = {W{1'b0}}; ovf_out_cnt = {W{1'b0}};
    end

    assign i_ready = !o_valid || o_ready;
    wire accept = i_valid && i_ready;
    wire fire   = o_valid && o_ready;

    // scaleB: exponent + signed scale, computed wide to avoid wrap
    wire signed [W+1:0] sum = $signed({{2{i_exp[W-1]}}, i_exp}) + $signed({{2{i_scale[W-1]}}, i_scale});
    wire ovf_now = (sum > EMAX);
    wire uf_now  = (sum < EMIN);
    wire signed [W+1:0] ushift = EMIN - sum;
    wire flush = uf_now && (ushift >= W);
    wire [W-1:0] den_sig = flush ? {W{1'b0}} : (i_sig >> ushift[$clog2(W):0]);
    wire [W-1:0] emax_p1 = EMAX + 1;
    wire [W-1:0] emin_m1 = EMIN - 1;
    wire [W-1:0] res_exp = ovf_now ? emax_p1 : (uf_now ? emin_m1 : sum[W-1:0]);
    wire [W-1:0] res_sig = ovf_now ? {W{1'b0}} : (uf_now ? den_sig : i_sig);

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0; o_exp <= {W{1'b0}}; o_sig <= {W{1'b0}};
            o_ovf <= 1'b0; o_uf <= 1'b0;
            ovf_in_cnt <= {W{1'b0}}; ovf_out_cnt <= {W{1'b0}};
        end else begin
            if (accept) begin
                o_valid <= 1'b1;
                o_exp   <= res_exp;
                o_sig   <= res_sig;
                o_ovf   <= ovf_now;
                o_uf    <= uf_now;
            end else if (fire) begin
                o_valid <= 1'b0;
            end
            if (accept && ovf_now) ovf_in_cnt  <= ovf_in_cnt + 1'b1;
            if (fire && o_ovf)     ovf_out_cnt <= ovf_out_cnt + 1'b1;
        end
    end

    // Precedence: an overflow result delivered now must have been preceded by
    // an accepted overflowing input that has not yet been delivered.
    always @(posedge clk)
        if (o_valid && o_ready && o_ovf)
            assert (ovf_in_cnt != ovf_out_cnt);
endmodule

module bcd_divider #(
    parameter DIGITS = 16
) (
    input  wire                  clk,
    input  wire                  i_clr,
    input  wire                  i_ce,
    input  wire                  i_go,
    input  wire [4*DIGITS-1:0]   i_dividend,
    input  wire [4*DIGITS-1:0]   i_divisor,
    output wire [4*DIGITS-1:0]   o_quotient,
    output wire [4*DIGITS+3:0]   o_remainder,
    output wire                  o_done
);
    localparam W  = 4*DIGITS;
    localparam RW = W + 4;
    localparam PW = $clog2(DIGITS);

    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_TABLE = 2'd1;
    localparam [1:0] P_DIV   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    function [RW-1:0] bcd_add;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] s;
        reg c;
        begin
            c = 1'b0;
            bcd_add = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                s = {1'b0, a[4*i +: 4]} + {1'b0, b[4*i +: 4]} + {4'd0, c};
                if (s > 5'd9) begin s = s + 5'd6; c = 1'b1; end
                else c = 1'b0;
                bcd_add[4*i +: 4] = s[3:0];
            end
        end
    endfunction

    function [RW-1:0] bcd_sub;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] d;
        reg br;
        begin
            br = 1'b0;
            bcd_sub = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                d = {1'b0, a[4*i +: 4]} - {1'b0, b[4*i +: 4]} - {4'd0, br};
                if (d[4]) begin d = d + 5'd10; br = 1'b1; end
                else br = 1'b0;
                bcd_sub[4*i +: 4] = d[3:0];
            end
        end
    endfunction

    reg [1:0]    phase      = P_IDLE;
    reg [3:0]    tbl_idx    = 4'd0;
    reg [PW-1:0] pos        = {PW{1'b0}};
    reg [W-1:0]  dvd        = {W{1'b0}};
    reg [W-1:0]  quo        = {W{1'b0}};
    reg [RW-1:0] rem        = {RW{1'b0}};
    reg [RW-1:0] acc        = {RW{1'b0}};
    reg [RW-1:0] mult [0:9];
    reg          seen_arm   = 1'b0;
    reg          seen_start = 1'b0;
    reg          done       = 1'b0;
    reg          win        = 1'b0;

    integer k;
    initial begin
        for (k = 0; k < 10; k = k + 1) mult[k] = {RW{1'b0}};
    end

    wire [RW-1:0] shifted = {rem[RW-5:0], dvd[pos*4 +: 4]};
    wire [RW-1:0] acc_sum = bcd_add(acc, mult[1]);

    reg [3:0]    qdig;
    reg [RW-1:0] qmul;
    integer j;
    always @(*) begin
        qdig = 4'd0;
        qmul = {RW{1'b0}};
        for (j = 1; j < 10; j = j + 1)
            if (shifted >= mult[j]) begin
                qdig = j;
                qmul = mult[j];
            end
    end

    wire [RW-1:0] rem_next = bcd_sub(shifted, qmul);

    always @(posedge clk) begin
        if (i_clr) begin
            phase      <= P_IDLE;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            done       <= 1'b0;
            win        <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE, P_DONE: begin
                    if (i_go) begin
                        dvd        <= i_dividend;
                        quo        <= {W{1'b0}};
                        rem        <= {RW{1'b0}};
                        mult[0]    <= {RW{1'b0}};
                        mult[1]    <= {4'd0, i_divisor};
                        acc        <= {4'd0, i_divisor};
                        tbl_idx    <= 4'd2;
                        phase      <= P_TABLE;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        done       <= 1'b0;
                        win        <= 1'b1;
                    end
                end
                P_TABLE: begin
                    for (k = 2; k < 10; k = k + 1)
                        if (tbl_idx == k) mult[k] <= acc_sum;
                    acc <= acc_sum;
                    if (tbl_idx == 4'd9) begin
                        phase      <= P_DIV;
                        seen_start <= 1'b1;
                        pos        <= DIGITS - 1;
                    end else begin
                        tbl_idx <= tbl_idx + 4'd1;
                    end
                end
                P_DIV: begin
                    rem <= rem_next;
                    quo <= {quo[W-5:0], qdig};
                    if (pos == {PW{1'b0}}) begin
                        phase <= P_DONE;
                        done  <= 1'b1;
                    end else begin
                        pos <= pos - 1'b1;
                    end
                end
                default: phase <= P_IDLE;
            endcase
        end
    end

    assign o_quotient  = quo;
    assign o_remainder = rem;
    assign o_done      = done;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $rose(done))
            assert (seen_arm && seen_start);
endmodule

module ola_block_conv #(
    parameter W = 32,
    parameter BLK = 64,
    parameter TAPS = 4,
    parameter [TAPS*W-1:0] COEF = {32'd1, 32'd3, 32'd3, 32'd1}
)(
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire [W-1:0] i_sample,
    output reg  [W-1:0] o_y,
    output reg          o_valid,
    output wire         o_busy,
    output wire [31:0]  o_blocks
);
    localparam [31:0] LAST  = BLK + TAPS - 2;
    localparam [31:0] TLAST = TAPS - 2;

    reg [W-1:0] in_buf [0:BLK-1];
    reg [W-1:0] tail   [0:TAPS-2];
    reg [31:0] wr_idx   = 32'd0;
    reg [31:0] out_idx  = 32'd0;
    reg [31:0] tail_idx = 32'd0;
    reg [31:0] blk_cnt  = 32'd0;
    reg        phase    = 1'b0;

    integer i;
    initial begin
        o_y = 0;
        o_valid = 1'b0;
        for (i = 0; i < BLK; i = i + 1) in_buf[i] = 0;
        for (i = 0; i < TAPS-1; i = i + 1) tail[i] = 0;
    end

    assign o_busy   = phase;
    assign o_blocks = blk_cnt;

    reg [W-1:0] acc;
    reg [31:0]  src;
    integer j;
    always @(*) begin
        acc = 0;
        src = 0;
        for (j = 0; j < TAPS; j = j + 1) begin
            src = out_idx - j;
            if (out_idx >= j && src < BLK)
                acc = acc + COEF[j*W +: W] * in_buf[src];
        end
        if (out_idx < TAPS-1)
            acc = acc + tail[out_idx];
    end

    always @(posedge clk) begin
        if (i_reset) begin
            wr_idx   <= 32'd0;
            out_idx  <= 32'd0;
            tail_idx <= 32'd0;
            blk_cnt  <= 32'd0;
            phase    <= 1'b0;
            o_valid  <= 1'b0;
            o_y      <= 0;
        end else if (i_ce) begin
            o_valid <= 1'b0;
            if (!phase) begin
                in_buf[wr_idx] <= i_sample;
                if (wr_idx == BLK-1) begin
                    wr_idx   <= 32'd0;
                    phase    <= 1'b1;
                    out_idx  <= 32'd0;
                    tail_idx <= 32'd0;
                end else begin
                    wr_idx <= wr_idx + 32'd1;
                end
            end else begin
                if (out_idx >= BLK) begin
                    tail[tail_idx] <= acc;
                    if (tail_idx == TLAST) begin
                        phase    <= 1'b0;
                        out_idx  <= 32'd0;
                        tail_idx <= 32'd0;
                        blk_cnt  <= blk_cnt + 32'd1;
                    end else begin
                        tail_idx <= tail_idx + 32'd1;
                        out_idx  <= out_idx + 32'd1;
                    end
                end else begin
                    o_y     <= acc;
                    o_valid <= 1'b1;
                    out_idx <= out_idx + 32'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv) assert (!$past(i_ce) || out_idx <= LAST);
endmodule

module arduboy_tone_ripple #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         in_valid,
    output wire         in_ready,
    output reg          out_valid,
    input  wire         out_ready,
    output wire         pin_a,
    output wire         pin_b,
    output wire [W-1:0] o_count
);
    localparam [W-1:0] HALF = {1'b1, {(W-1){1'b0}}};

    // a tone tick is accepted only when valid and ready are both high
    assign in_ready = !out_valid;
    wire accept = in_valid && in_ready;

    // ripple chain of toggle flip-flops: each stage toggles when the
    // previous stage falls (synchronous model of the ripple carry)
    wire [W:0]   t;
    wire [W-1:0] q;
    assign t[0] = accept;

    genvar i;
    generate
        for (i = 0; i < W; i = i + 1) begin : stage
            reg tff = 1'b0;
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    tff <= 1'b0;
                else if (t[i])
                    tff <= ~tff;
            end
            assign q[i]   = tff;
            assign t[i+1] = t[i] & tff;
        end
    endgenerate

    // shadow record of every tick accepted earlier
    reg [W-1:0] shadow = {W{1'b0}};
    initial out_valid = 1'b0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shadow    <= {W{1'b0}};
            out_valid <= 1'b0;
        end else begin
            if (accept)
                shadow <= shadow + 1'b1;
            if (t[W])
                out_valid <= 1'b1;          // full buzzer period completed
            else if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    // piezo wired between two pins, driven in antiphase
    assign pin_a   = q[W-1];
    assign pin_b   = ~q[W-1];
    assign o_count = q;

    // precedence: buzzer phase high now => half a period of ticks accepted earlier
    always @(*) assert (!q[W-1] || shadow >= HALF);
    // precedence: period-done offered now => the accepted-tick record has wrapped
    always @(*) assert (!out_valid || shadow == {W{1'b0}});
endmodule

module apb_reg_ctrl #(
    parameter NREGS = 16,
    parameter AW    = 4,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          psel,
    input  wire          penable,
    input  wire          pwrite,
    input  wire [AW-1:0] paddr,
    input  wire [DW-1:0] pwdata,
    input  wire          dev_ready,
    output wire          pready,
    output reg  [DW-1:0] prdata
);
    typedef enum logic [1:0] {IDLE = 2'd0, SETUP = 2'd1, ACCESS = 2'd2} state_t;

    state_t        state    = IDLE;
    reg            phase    = 1'b0;
    reg [AW-1:0]   sel_idx  = {AW{1'b0}};
    reg            wr_q     = 1'b0;
    reg [DW-1:0]   wdata_q  = {DW{1'b0}};
    reg            in_xfer  = 1'b0;
    reg [DW-1:0]   xfer_cnt = {DW{1'b0}};
    reg [DW-1:0]   done_cnt = {DW{1'b0}};
    reg [DW-1:0]   regs [0:NREGS-1];

    integer i;
    initial begin
        prdata = {DW{1'b0}};
        for (i = 0; i < NREGS; i = i + 1) regs[i] = {DW{1'b0}};
    end

    assign pready = (state == ACCESS) && dev_ready;

    wire start        = (state == IDLE)   && psel && !penable;
    wire enter_access = (state == SETUP)  && psel && penable;
    wire xfer_done    = (state == ACCESS) && psel && penable && pready;

    always @(posedge clk) begin
        case (state)
            IDLE: if (start) begin
                state    <= SETUP;
                phase    <= 1'b0;
                sel_idx  <= paddr;
                wr_q     <= pwrite;
                wdata_q  <= pwdata;
                in_xfer  <= 1'b1;
                xfer_cnt <= xfer_cnt + 32'd1;
            end
            SETUP: if (enter_access) begin
                state <= ACCESS;
                phase <= 1'b1;
            end
            ACCESS: if (xfer_done) begin
                state    <= IDLE;
                phase    <= 1'b0;
                in_xfer  <= 1'b0;
                done_cnt <= done_cnt + 32'd1;
                if (wr_q) regs[sel_idx] <= wdata_q;
                else      prdata        <= regs[sel_idx];
            end
            default: state <= state;
        endcase
    end

    assert property (!in_xfer || (xfer_cnt == done_cnt + 32'd1));
endmodule

module irq_claim_gateway #(
    parameter NSRC = 4,
    parameter IDW  = 2,
    parameter W    = 64
) (
    input  wire            clk,
    input  wire            i_reset,
    input  wire            i_ce,
    input  wire [NSRC-1:0] irq_in,
    input  wire            claim_rd,
    input  wire            cmpl_wr,
    input  wire [IDW-1:0]  cmpl_id,
    output wire [W-1:0]    o_claim_id,
    output wire            o_cmpl_ack
);
    reg [NSRC-1:0] pending  = {NSRC{1'b0}};
    reg [NSRC-1:0] inflight = {NSRC{1'b0}};
    reg [W-1:0]    last_id   = {W{1'b0}};
    reg [W-1:0]    ack_id    = {W{1'b0}};
    reg [W-1:0]    claim_cnt = {W{1'b0}};
    reg [W-1:0]    cmpl_cnt  = {W{1'b0}};
    reg            cmpl_ack  = 1'b0;
    reg            seen_q    = 1'b0;
    reg            pv        = 1'b0;

    reg [IDW-1:0] sel_id;
    reg           any_pend;
    integer i;
    always @(*) begin
        sel_id   = {IDW{1'b0}};
        any_pend = 1'b0;
        for (i = 0; i < NSRC; i = i + 1)
            if (pending[i]) begin
                sel_id   = i;
                any_pend = 1'b1;
            end
    end

    wire do_claim = i_ce && claim_rd && any_pend && (inflight == {NSRC{1'b0}});
    wire do_cmpl  = i_ce && cmpl_wr && inflight[cmpl_id];

    wire [NSRC-1:0] one_hot1   = {{(NSRC-1){1'b0}}, 1'b1};
    wire [NSRC-1:0] claim_mask = do_claim ? (one_hot1 << sel_id)  : {NSRC{1'b0}};
    wire [NSRC-1:0] cmpl_mask  = do_cmpl  ? (one_hot1 << cmpl_id) : {NSRC{1'b0}};

    always @(posedge clk) begin
        if (i_reset) begin
            pending   <= {NSRC{1'b0}};
            inflight  <= {NSRC{1'b0}};
            last_id   <= {W{1'b0}};
            ack_id    <= {W{1'b0}};
            claim_cnt <= {W{1'b0}};
            cmpl_cnt  <= {W{1'b0}};
            cmpl_ack  <= 1'b0;
        end else if (i_ce) begin
            pending  <= (pending | (irq_in & ~inflight)) & ~claim_mask;
            inflight <= (inflight | claim_mask) & ~cmpl_mask;
            if (do_claim) begin
                last_id   <= {{(W-IDW){1'b0}}, sel_id};
                claim_cnt <= claim_cnt + {{(W-1){1'b0}}, 1'b1};
                seen_q    <= 1'b1;
            end
            cmpl_ack <= do_cmpl;
            if (do_cmpl) begin
                ack_id   <= {{(W-IDW){1'b0}}, cmpl_id};
                cmpl_cnt <= cmpl_cnt + {{(W-1){1'b0}}, 1'b1};
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    assign o_claim_id = last_id;
    assign o_cmpl_ack = cmpl_ack;

    always @(posedge clk)
        if (pv && seen_q && $rose(cmpl_ack))
            assert (ack_id == last_id);
endmodule

module freq_meter #(
    parameter DATA_W = 128,
    parameter GATE_W = 4,
    parameter [GATE_W-1:0] DEFAULT_GATE = 4'd8
) (
    input  wire              clk,
    input  wire              ce,
    input  wire              load,
    input  wire [GATE_W-1:0] gate_len_in,
    input  wire              arm_cmd,
    input  wire              start_cmd,
    input  wire              fx,
    output reg  [DATA_W-1:0] res0,
    output reg  [DATA_W-1:0] res1,
    output reg               res_valid
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_GATE = 2'd2, S_DONE = 2'd3;

    reg [1:0]        phase    = S_IDLE;
    reg              after_q  = 1'b0;
    reg              st_seen  = 1'b0;
    reg [GATE_W-1:0] gate_len = DEFAULT_GATE;
    reg [GATE_W-1:0] gate_cnt = {GATE_W{1'b0}};
    reg [DATA_W-1:0] ev_cnt   = {DATA_W{1'b0}};
    reg              fx_q     = 1'b0;

    initial res0 = {DATA_W{1'b0}};
    initial res1 = {DATA_W{1'b0}};
    initial res_valid = 1'b0;

    wire edge_det = fx & ~fx_q;

    always @(posedge clk) begin
        if (ce) begin
            fx_q <= fx;
            if (load)
                gate_len <= gate_len_in;
            case (phase)
                S_IDLE: begin
                    if (arm_cmd) begin
                        phase     <= S_ARMED;
                        after_q   <= 1'b1;
                        st_seen   <= 1'b0;
                        res_valid <= 1'b0;
                    end
                end
                S_ARMED: begin
                    if (start_cmd) begin
                        phase    <= S_GATE;
                        st_seen  <= 1'b1;
                        gate_cnt <= {GATE_W{1'b0}};
                        ev_cnt   <= {DATA_W{1'b0}};
                    end
                end
                S_GATE: begin
                    gate_cnt <= gate_cnt + 1'b1;
                    if (edge_det)
                        ev_cnt <= ev_cnt + {{(DATA_W-1){1'b0}}, 1'b1};
                    if (gate_cnt >= gate_len) begin
                        phase     <= S_DONE;
                        res_valid <= 1'b1;
                        res1      <= res0;
                        res0      <= ev_cnt;
                    end
                end
                S_DONE: begin
                    if (arm_cmd) begin
                        phase     <= S_ARMED;
                        st_seen   <= 1'b0;
                        res_valid <= 1'b0;
                    end
                end
            endcase
        end
    end

    // Chain precedence after the first arm: finish is never seen without start
    always @(posedge clk)
        if (after_q && phase == S_DONE) assert (st_seen);

    always @(posedge clk)
        if (after_q && res_valid) assert (st_seen);
endmodule

module sha2_sched_expander #(
    parameter WIDTH  = 8,
    parameter NW     = 16,
    parameter ROUNDS = 48
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  start,
    input  wire [WIDTH*NW-1:0]   blk,
    output wire [WIDTH-1:0]      o_word,
    output wire                  o_busy,
    output wire                  o_done
);
    localparam [7:0] NR = ROUNDS;

    typedef enum logic [1:0] {IDLE = 2'd0, EXPAND = 2'd1, DONE = 2'd2} state_t;
    state_t state;

    reg [WIDTH*NW-1:0] sched;
    reg [7:0] rnd;
    reg [7:0] tmr;
    reg       win;

    initial begin
        state = IDLE;
        sched = {(WIDTH*NW){1'b0}};
        rnd   = 8'd0;
        tmr   = 8'd0;
        win   = 1'b0;
    end

    function [WIDTH-1:0] rotr(input [WIDTH-1:0] x, input integer n);
        rotr = (x >> n) | (x << (WIDTH - n));
    endfunction

    function [WIDTH-1:0] sig0(input [WIDTH-1:0] x);
        sig0 = rotr(x, 1) ^ rotr(x, 4) ^ (x >> 2);
    endfunction

    function [WIDTH-1:0] sig1(input [WIDTH-1:0] x);
        sig1 = rotr(x, 3) ^ rotr(x, 5) ^ (x >> 1);
    endfunction

    wire [WIDTH-1:0] w0  = sched[0*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w1  = sched[1*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w9  = sched[9*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w14 = sched[14*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w_new = sig1(w14) + w9 + sig0(w1) + w0;

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                IDLE: begin
                    if (start) begin
                        sched <= blk;
                        rnd   <= 8'd0;
                        tmr   <= NR;
                        state <= EXPAND;
                        win   <= 1'b1;
                    end
                end
                EXPAND: begin
                    sched <= {w_new, sched[WIDTH*NW-1:WIDTH]};
                    rnd   <= rnd + 8'd1;
                    tmr   <= tmr - 8'd1;
                    if (rnd == NR - 8'd1) begin
                        state <= DONE;
                        win   <= 1'b0;
                    end
                end
                DONE: state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    assign o_word = sched[WIDTH*NW-1 -: WIDTH];
    assign o_busy = win;
    assign o_done = (state == DONE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(win))
            assert (tmr != 8'd0 && (!$stable(rnd) || $stable(tmr)));
endmodule

module psg_minority_tally #(
    parameter [31:0] FRAME = 32'd64
) (
    input  wire clk,
    input  wire step,
    input  wire start,
    input  wire stop,
    input  wire ch_a,
    input  wire ch_b,
    input  wire ch_c,
    output wire minority,
    output wire busy
);
    typedef enum logic [1:0] {S_IDLE = 2'd0, S_RUN = 2'd1, S_DONE = 2'd2} state_t;

    // Minority gate: complement of the majority of the three channel bits
    wire majority = (ch_a & ch_b) | (ch_a & ch_c) | (ch_b & ch_c);
    assign minority = ~majority;

    state_t state;
    reg [31:0] pos;
    reg [31:0] cnt;
    reg armed;

    initial state = S_IDLE;
    initial pos = 32'd0;
    initial cnt = 32'd0;
    initial armed = 1'b0;

    assign busy = (state == S_RUN);

    always @(posedge clk) begin
        if (step) begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        state <= S_RUN;
                        pos <= 32'd0;
                        cnt <= 32'd0;
                    end
                end
                S_RUN: begin
                    pos <= pos + 32'd1;
                    cnt <= cnt + {31'd0, minority};
                    if (pos == FRAME - 32'd1)
                        state <= S_DONE;
                end
                S_DONE: begin
                    if (start) begin
                        state <= S_RUN;
                        pos <= 32'd0;
                        cnt <= 32'd0;
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    // Window register: opened by a frame start, closed by stop (which may never come)
    always @(posedge clk) begin
        if (step) begin
            if (start)
                armed <= 1'b1;
            else if (stop)
                armed <= 1'b0;
        end
    end

    assert property (!armed || cnt <= FRAME);
endmodule

module branch_resolve_unit #(
    parameter integer XLEN = 64,
    parameter [63:0] INSN_BYTES = 64'd4
) (
    input  wire            clk,
    input  wire            ce,
    input  wire            br_valid,
    input  wire [XLEN-1:0] br_pc,
    input  wire [XLEN-1:0] br_offset,
    input  wire            br_cond,
    input  wire [XLEN-1:0] br_pred_tgt,
    input  wire [XLEN-1:0] br_pred_meta,
    output wire            o_redirect,
    output wire            o_flush,
    output wire [XLEN-1:0] o_redirect_addr,
    output wire            o_busy
);
    typedef enum logic [1:0] {S_IDLE, S_RESOLVE, S_REDIRECT, S_FLUSH} state_t;

    state_t state = S_IDLE;
    reg            win = 1'b0;
    reg [XLEN-1:0] pc_q = {XLEN{1'b0}};
    reg [XLEN-1:0] off_q = {XLEN{1'b0}};
    reg            cond_q = 1'b0;
    reg [XLEN-1:0] pred_target = {XLEN{1'b0}};
    reg [XLEN-1:0] pred_meta = {XLEN{1'b0}};
    reg [XLEN-1:0] redirect_addr = {XLEN{1'b0}};
    reg [XLEN-1:0] mispred_cnt = {XLEN{1'b0}};

    wire [XLEN-1:0] actual_tgt = cond_q ? (pc_q + off_q) : (pc_q + INSN_BYTES);
    wire            mispredict = (actual_tgt != pred_target);

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                S_IDLE: begin
                    if (br_valid) begin
                        pc_q        <= br_pc;
                        off_q       <= br_offset;
                        cond_q      <= br_cond;
                        pred_target <= br_pred_tgt;
                        pred_meta   <= br_pred_meta;
                        state       <= S_RESOLVE;
                    end
                end
                S_RESOLVE: begin
                    if (mispredict) begin
                        redirect_addr <= actual_tgt;
                        mispred_cnt   <= mispred_cnt + 64'd1;
                        win           <= 1'b1;
                        state         <= S_REDIRECT;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_REDIRECT: begin
                    state <= S_FLUSH;
                end
                S_FLUSH: begin
                    win   <= 1'b0;
                    state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    assign o_redirect      = (state == S_REDIRECT);
    assign o_flush         = (state == S_FLUSH);
    assign o_redirect_addr = redirect_addr;
    assign o_busy          = (state != S_IDLE);

    always @(posedge clk)
        if (win)
            assert (redirect_addr != pred_target);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module ckpt_regfile #(
    parameter W = 32,
    parameter NREG = 4,
    parameter NCKPT = 4,
    parameter [31:0] TIMEOUT = 32'd6,
    parameter SW = $clog2(NCKPT),
    parameter RW = $clog2(NREG)
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire branch,
    input wire resolve,
    input wire mispredict,
    input wire [SW-1:0] rsv_id,
    input wire wr_en,
    input wire [RW-1:0] wr_addr,
    input wire [W-1:0] wr_data,
    output wire [NCKPT-1:0] o_mask,
    output wire [W-1:0] o_acc0,
    output wire o_busy
);
    // active accumulator register file and checkpoint shadow copies
    reg [NREG*W-1:0] regs_q;
    reg [NCKPT*NREG*W-1:0] shadow_q;
    reg [NCKPT-1:0] ckpt_mask;
    reg [31:0] n_live;
    reg [31:0] wd;
    reg armed;

    initial begin
        regs_q = {NREG*W{1'b0}};
        shadow_q = {NCKPT*NREG*W{1'b0}};
        ckpt_mask = {NCKPT{1'b0}};
        n_live = 32'd0;
        wd = 32'd0;
        armed = 1'b1;
    end

    // lowest free checkpoint slot
    reg [SW-1:0] free_slot;
    integer k;
    always @(*) begin
        free_slot = {SW{1'b0}};
        for (k = NCKPT-1; k >= 0; k = k - 1)
            if (!ckpt_mask[k]) free_slot = k;
    end

    wire live        = (n_live != 32'd0);
    wire timeout     = live && (wd == 32'd1);
    wire do_rollback = mispredict && ckpt_mask[rsv_id];
    wire do_free     = resolve && ckpt_mask[rsv_id];
    wire do_alloc    = branch && (n_live != NCKPT);

    reg [NCKPT-1:0] mask_nxt;
    reg [31:0] live_nxt;
    always @(*) begin
        mask_nxt = ckpt_mask;
        live_nxt = n_live;
        if (do_free) begin
            mask_nxt[rsv_id] = 1'b0;
            live_nxt = live_nxt - 32'd1;
        end
        if (do_alloc) begin
            mask_nxt[free_slot] = 1'b1;
            live_nxt = live_nxt + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            regs_q <= {NREG*W{1'b0}};
            ckpt_mask <= {NCKPT{1'b0}};
            n_live <= 32'd0;
            wd <= 32'd0;
        end else if (step) begin
            if (timeout) begin
                // deadline reached: force-commit all outstanding checkpoints
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
            end else if (do_rollback) begin
                regs_q <= shadow_q[rsv_id*NREG*W +: NREG*W];
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
                armed <= 1'b0;
            end else begin
                if (do_alloc)
                    shadow_q[free_slot*NREG*W +: NREG*W] <= regs_q;
                if (wr_en)
                    regs_q[wr_addr*W +: W] <= wr_data;
                ckpt_mask <= mask_nxt;
                n_live <= live_nxt;
                if (live_nxt == 32'd0)
                    wd <= 32'd0;
                else if (!live)
                    wd <= TIMEOUT;
                else
                    wd <= wd - 32'd1;
            end
        end
    end

    assign o_mask = ckpt_mask;
    assign o_acc0 = regs_q[W-1:0];
    assign o_busy = live;

    // before the first rollback: an outstanding checkpoint never sees an expired deadline
    always @(*) assert (!armed || ckpt_mask == {NCKPT{1'b0}} || wd != 32'd0);
endmodule

module twiddle_rom_seq #(
    parameter N   = 256,
    parameter LGN = 8,
    parameter DW  = 64
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_ce,
    output reg  [DW-1:0] o_re,
    output reg  [DW-1:0] o_im,
    output reg           o_unity,
    output reg           o_negj,
    output reg           o_win
);
    localparam HALF = N / 2;
    localparam QW   = N / 4;
    localparam SH   = DW - 2 - 2*(LGN-2);
    localparam [DW-1:0] ONE = {2'b01, {(DW-2){1'b0}}};

    // quarter-wave magnitude table: cos(pi*x/(N/2)) approximated as 1-(x/QW)^2
    function [DW-1:0] cmag;
        input [LGN-2:0] x;
        reg [2*(LGN-1)-1:0] sq;
        begin
            sq   = x * x;
            cmag = ONE - ({{(DW-2*(LGN-1)){1'b0}}, sq} << SH);
        end
    endfunction

    // real coefficient table: cos(2*pi*k/N), quadrant folded
    function [DW-1:0] re_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    re_rom =  cmag(r);
                2'd1:    re_rom = -cmag(QW - r);
                2'd2:    re_rom = -cmag(r);
                default: re_rom =  cmag(QW - r);
            endcase
        end
    endfunction

    // imaginary coefficient table: -sin(2*pi*k/N), quadrant folded
    function [DW-1:0] im_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    im_rom = -cmag(QW - r);
                2'd1:    im_rom = -cmag(r);
                2'd2:    im_rom =  cmag(QW - r);
                default: im_rom =  cmag(r);
            endcase
        end
    endfunction

    reg [DW-1:0]  pos;
    reg [DW-1:0]  stage;
    reg [LGN-1:0] re_addr;
    reg [LGN-1:0] im_addr;

    initial pos     = 0;
    initial stage   = 0;
    initial re_addr = 0;
    initial im_addr = 0;
    initial o_re    = 0;
    initial o_im    = 0;
    initial o_unity = 1'b0;
    initial o_negj  = 1'b0;
    initial o_win   = 1'b0;

    // twiddle index for butterfly position pos in stage: (pos << stage) mod N
    wire [LGN-1:0] tw_k = pos[LGN-1:0] << stage[2:0];

    always @(posedge clk) begin
        if (i_reset) begin
            pos     <= 0;
            stage   <= 0;
            re_addr <= 0;
            im_addr <= 0;
            o_re    <= 0;
            o_im    <= 0;
            o_unity <= 1'b0;
            o_negj  <= 1'b0;
            o_win   <= 1'b0;
        end else if (i_ce) begin
            // separate address registers for the real and imaginary ROM ports
            re_addr <= tw_k;
            im_addr <= tw_k;
            // registered coefficient output pair
            o_re    <= re_rom(re_addr);
            o_im    <= im_rom(im_addr);
            o_unity <= (re_addr == 0);
            o_negj  <= (im_addr == QW);
            if (pos == HALF-1) begin
                pos   <= 0;
                stage <= (stage == LGN-1) ? 0 : stage + 1;
            end else begin
                pos   <= pos + 1;
            end
            // stage window: opens at first butterfly, closes at last
            if (pos == 0)
                o_win <= 1'b1;
            else if (pos == HALF-1)
                o_win <= 1'b0;
        end
    end

    // within a stage window, the unity and -j coefficient markers never coincide
    assert property (!o_win || !(o_unity && o_negj));
endmodule

module irq_first_arrival #(
    parameter NCH  = 8,
    parameter IDXW = 3,
    parameter TW   = 64
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire            clr,
    input  wire [NCH-1:0]  irq,
    output reg             captured,
    output reg [IDXW-1:0]  win_idx,
    output reg [NCH-1:0]   win_mask,
    output reg [TW-1:0]    cap_time
);
    localparam [NCH-1:0] ONE = 1;

    reg [TW-1:0] tick;

    initial begin
        captured = 1'b0;
        win_idx  = {IDXW{1'b0}};
        win_mask = {NCH{1'b0}};
        cap_time = {TW{1'b0}};
        tick     = {TW{1'b0}};
    end

    function [IDXW-1:0] first_idx;
        input [NCH-1:0] v;
        integer i;
        begin
            first_idx = {IDXW{1'b0}};
            for (i = NCH-1; i >= 0; i = i - 1)
                if (v[i]) first_idx = i;
        end
    endfunction

    wire [IDXW-1:0] enc = first_idx(irq);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            captured <= 1'b0;
            win_idx  <= {IDXW{1'b0}};
            win_mask <= {NCH{1'b0}};
            cap_time <= {TW{1'b0}};
            tick     <= {TW{1'b0}};
        end else if (ce) begin
            tick <= tick + {{(TW-1){1'b0}}, 1'b1};
            if (!captured && (|irq)) begin
                captured <= 1'b1;
                win_idx  <= enc;
                win_mask <= ONE << enc;
                cap_time <= tick;
            end else if (captured && clr) begin
                captured <= 1'b0;
                win_mask <= win_mask & ~(ONE << win_idx);
            end
        end
    end

    always @(*) assert (captured || win_mask == {NCH{1'b0}});
endmodule

module eye_scan_monitor #(
    parameter [63:0] NSAMP = 64'd16,
    parameter [63:0] H_PTS = 64'd4,
    parameter [63:0] V_PTS = 64'd4
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire        abort,
    input  wire        data_bit,
    input  wire        offset_bit,
    output wire        busy,
    output wire [63:0] o_mismatch,
    output wire [63:0] o_h_off,
    output wire [63:0] o_v_off
);
    typedef enum logic [1:0] {S_IDLE, S_SAMPLE, S_STEP, S_DONE} state_t;

    state_t     state;
    reg [63:0]  h_off;
    reg [63:0]  v_off;
    reg [63:0]  sample_cnt;
    reg [63:0]  mismatch_cnt;
    reg         window;

    initial begin
        state        = S_IDLE;
        h_off        = 64'd0;
        v_off        = 64'd0;
        sample_cnt   = 64'd0;
        mismatch_cnt = 64'd0;
        window       = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state        <= S_IDLE;
            h_off        <= 64'd0;
            v_off        <= 64'd0;
            sample_cnt   <= 64'd0;
            mismatch_cnt <= 64'd0;
            window       <= 1'b0;
        end else if (en) begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        state        <= S_SAMPLE;
                        h_off        <= 64'd0;
                        v_off        <= 64'd0;
                        sample_cnt   <= 64'd0;
                        mismatch_cnt <= 64'd0;
                        window       <= 1'b1;
                    end
                end
                S_SAMPLE: begin
                    if (abort) begin
                        state  <= S_IDLE;
                        window <= 1'b0;
                    end else begin
                        sample_cnt <= sample_cnt + 64'd1;
                        if (data_bit != offset_bit)
                            mismatch_cnt <= mismatch_cnt + 64'd1;
                        if (sample_cnt == NSAMP - 64'd1)
                            state <= S_STEP;
                    end
                end
                S_STEP: begin
                    sample_cnt   <= 64'd0;
                    mismatch_cnt <= 64'd0;
                    if (h_off == H_PTS - 64'd1) begin
                        h_off <= 64'd0;
                        if (v_off == V_PTS - 64'd1) begin
                            v_off <= 64'd0;
                            state <= S_DONE;
                        end else begin
                            v_off <= v_off + 64'd1;
                            state <= S_SAMPLE;
                        end
                    end else begin
                        h_off <= h_off + 64'd1;
                        state <= S_SAMPLE;
                    end
                end
                S_DONE: begin
                    window <= 1'b0;
                    state  <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    assign busy       = (state != S_IDLE);
    assign o_mismatch = mismatch_cnt;
    assign o_h_off    = h_off;
    assign o_v_off    = v_off;

    always @(posedge clk)
        if (window)
            assert (mismatch_cnt <= NSAMP);
endmodule

module requant_unit #(
    parameter W  = 64,
    parameter SW = 6
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          arm,
    input  wire          start,
    input  wire          ack,
    input  wire          clr,
    input  wire [W-1:0]  cfg_mult,
    input  wire [SW-1:0] cfg_shift,
    input  wire [W-1:0]  acc_in,
    output reg  [W-1:0]  out_q,
    output reg  [1:0]    phase
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, BUSY = 2'd2, DONE = 2'd3;

    reg [W-1:0]  mult_cfg  = {W{1'b0}};
    reg [SW-1:0] shift_cfg = {SW{1'b0}};
    reg [W-1:0]  work      = {W{1'b0}};
    reg [SW-1:0] cnt       = {SW{1'b0}};
    reg          run       = 1'b0;
    reg          win       = 1'b0;
    initial out_q = {W{1'b0}};
    initial phase = IDLE;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            run   <= 1'b0;
            cnt   <= {SW{1'b0}};
            work  <= {W{1'b0}};
            win   <= 1'b0;
        end else if (ce) begin
            if (clr)
                win <= 1'b0;
            if (phase == IDLE && arm) begin
                mult_cfg  <= cfg_mult;
                shift_cfg <= cfg_shift;
                phase     <= ARMED;
                win       <= 1'b1;
            end
            if (phase == ARMED && start) begin
                work  <= acc_in * mult_cfg;
                cnt   <= shift_cfg;
                run   <= 1'b1;
                phase <= BUSY;
            end
            if (phase == DONE && ack)
                phase <= IDLE;
            if (run) begin
                if (cnt == {SW{1'b0}}) begin
                    out_q <= work;
                    run   <= 1'b0;
                    phase <= DONE;
                end else begin
                    work <= work >> 1;
                    cnt  <= cnt - 1'b1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(phase))
            assert ($stable(out_q));
endmodule

module tage_predictor #(
    parameter ENTRIES = 32,
    parameter IDXW    = 5,
    parameter TAGW    = 4,
    parameter CTRW    = 3,
    parameter BCTRW   = 2,
    parameter HISTW   = 16,
    parameter CW      = 16,
    parameter [15:0] TICK_MAX = 16'd15
)(
    input  wire          clk,
    input  wire          rst_n,
    input  wire          i_ce,
    input  wire [15:0]   i_pc,
    input  wire          i_taken,
    input  wire          i_arm,
    output wire          o_pred,
    output wire [CW-1:0] o_ucnt
);
    // base bimodal table and two tagged tables (history lengths 4 and 8)
    reg [ENTRIES*BCTRW-1:0] base_ctr;
    reg [ENTRIES*TAGW-1:0]  t1_tag;
    reg [ENTRIES*CTRW-1:0]  t1_ctr;
    reg [ENTRIES-1:0]       t1_u;
    reg [ENTRIES*TAGW-1:0]  t2_tag;
    reg [ENTRIES*CTRW-1:0]  t2_ctr;
    reg [ENTRIES-1:0]       t2_u;
    reg [HISTW-1:0]         ghist;
    reg [CW-1:0]            t1_ucnt;
    reg [CW-1:0]            tick;
    reg                     armed;

    initial begin
        base_ctr = 0; t1_tag = 0; t1_ctr = 0; t1_u = 0;
        t2_tag = 0; t2_ctr = 0; t2_u = 0; ghist = 0;
        t1_ucnt = 0; tick = 0; armed = 0;
    end

    // folded global history, geometric lengths 4 (T1) and 8 (T2)
    wire [IDXW-1:0] fold1 = {1'b0, ghist[3:0]};
    wire [IDXW-1:0] fold2 = ghist[4:0] ^ {2'b00, ghist[7:5]};
    wire [IDXW-1:0] idx0  = i_pc[IDXW-1:0];
    wire [IDXW-1:0] idx1  = i_pc[IDXW-1:0] ^ fold1;
    wire [IDXW-1:0] idx2  = i_pc[IDXW-1:0] ^ fold2;
    wire [TAGW-1:0] tag1  = i_pc[8:5] ^ ghist[3:0];
    wire [TAGW-1:0] tag2  = i_pc[8:5] ^ ghist[7:4] ^ {ghist[2:0], ghist[3]};

    wire [BCTRW-1:0] b_c   = base_ctr[idx0*BCTRW +: BCTRW];
    wire [TAGW-1:0]  t1_t  = t1_tag[idx1*TAGW +: TAGW];
    wire [CTRW-1:0]  t1_c  = t1_ctr[idx1*CTRW +: CTRW];
    wire             t1_uo = t1_u[idx1];
    wire [TAGW-1:0]  t2_t  = t2_tag[idx2*TAGW +: TAGW];
    wire [CTRW-1:0]  t2_c  = t2_ctr[idx2*CTRW +: CTRW];
    wire             t2_uo = t2_u[idx2];

    wire hit1 = (t1_t == tag1);
    wire hit2 = (t2_t == tag2);
    wire base_pred = b_c[BCTRW-1];
    wire t1_pred   = t1_c[CTRW-1];
    wire t2_pred   = t2_c[CTRW-1];
    wire prov_t2 = hit2;
    wire prov_t1 = !hit2 && hit1;
    wire prov_b  = !hit2 && !hit1;
    wire alt_pred = prov_t2 ? (hit1 ? t1_pred : base_pred) : base_pred;
    wire pred     = prov_t2 ? t2_pred : (prov_t1 ? t1_pred : base_pred);
    wire mispred  = (pred != i_taken);
    assign o_pred = pred;
    assign o_ucnt = t1_ucnt;

    // saturating counter next values
    wire [BCTRW-1:0] b_nxt  = i_taken ? ((b_c  == 2'd3) ? b_c  : b_c  + 2'd1) : ((b_c  == 2'd0) ? b_c  : b_c  - 2'd1);
    wire [CTRW-1:0]  t1_nxt = i_taken ? ((t1_c == 3'd7) ? t1_c : t1_c + 3'd1) : ((t1_c == 3'd0) ? t1_c : t1_c - 3'd1);
    wire [CTRW-1:0]  t2_nxt = i_taken ? ((t2_c == 3'd7) ? t2_c : t2_c + 3'd1) : ((t2_c == 3'd0) ? t2_c : t2_c - 3'd1);
    wire [CTRW-1:0]  weak   = i_taken ? 3'd4 : 3'd3;

    // usefulness and allocation
    wire u1_set      = prov_t1 && !mispred && (alt_pred != t1_pred);
    wire u1_dec      = prov_t1 &&  mispred && (alt_pred != t1_pred);
    wire alloc1_try  = prov_b && mispred;
    wire alloc1_ok   = alloc1_try && !t1_uo;
    wire alloc1_fail = alloc1_try &&  t1_uo;
    wire alloc2_try  = prov_t1 && mispred;
    wire alloc2_ok   = alloc2_try && !t2_uo;
    wire alloc2_fail = alloc2_try &&  t2_uo;
    wire u1_clr      = u1_dec || alloc1_fail;
    wire u2_set      = prov_t2 && !mispred && (alt_pred != t2_pred);
    wire u2_clr      = (prov_t2 && mispred && (alt_pred != t2_pred)) || alloc2_fail;
    wire any_fail    = alloc1_fail || alloc2_fail;
    wire u_reset     = any_fail && (tick == TICK_MAX);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            base_ctr <= 0; t1_tag <= 0; t1_ctr <= 0; t1_u <= 0;
            t2_tag <= 0; t2_ctr <= 0; t2_u <= 0; ghist <= 0;
            t1_ucnt <= 0; tick <= 0; armed <= 0;
        end else if (i_ce) begin
            ghist <= {ghist[HISTW-2:0], i_taken};
            if (prov_b)  base_ctr[idx0*BCTRW +: BCTRW] <= b_nxt;
            if (prov_t1) t1_ctr[idx1*CTRW +: CTRW] <= t1_nxt;
            if (alloc1_ok) begin
                t1_tag[idx1*TAGW +: TAGW] <= tag1;
                t1_ctr[idx1*CTRW +: CTRW] <= weak;
            end
            if (prov_t2) t2_ctr[idx2*CTRW +: CTRW] <= t2_nxt;
            if (alloc2_ok) begin
                t2_tag[idx2*TAGW +: TAGW] <= tag2;
                t2_ctr[idx2*CTRW +: CTRW] <= weak;
            end
            if (u_reset) begin
                t1_u <= 0; t2_u <= 0; t1_ucnt <= 0; tick <= 0;
            end else begin
                if (any_fail) tick <= tick + 16'd1;
                if (u1_set && !t1_uo) begin
                    t1_u[idx1] <= 1'b1;
                    t1_ucnt <= t1_ucnt + 16'd1;
                end else if (u1_clr && t1_uo) begin
                    t1_u[idx1] <= 1'b0;
                    t1_ucnt <= t1_ucnt - 16'd1;
                end
                if (u2_set) t2_u[idx2] <= 1'b1;
                else if (u2_clr) t2_u[idx2] <= 1'b0;
            end
            // scope window: opened by i_arm, closed by the periodic usefulness reset
            if (u_reset) armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;
        end
    end

    // absence: the useful-entry count never reads zero while some T1 entry is marked useful
    always @(posedge clk)
        if (armed)
            assert (!((t1_ucnt == 16'd0) && (t1_u != 32'd0)));
endmodule

module ddr3_cmd_queue #(
    parameter DEPTH = 12,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data,
    input  wire          cfg_load,
    input  wire [31:0]   cfg_wm,
    output wire          almost_full,
    output wire [31:0]   occupancy
);
    localparam AW = $clog2(DEPTH);
    localparam [AW-1:0] LAST = DEPTH - 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = {AW{1'b0}};
    reg [AW-1:0] rptr = {AW{1'b0}};
    reg          wr_lap = 1'b0;
    reg          rd_lap = 1'b0;
    reg [31:0]   count = 32'd0;
    reg [31:0]   wm = 32'd8;
    reg          armed = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    wire full  = (wptr == rptr) && (wr_lap != rd_lap);
    wire empty = (wptr == rptr) && (wr_lap == rd_lap);
    assign in_ready  = !full;
    assign out_valid = !empty;
    assign out_data  = mem[rptr];

    wire push = in_valid && in_ready;
    wire pop  = out_valid && out_ready;

    // T inputs of the two lap toggle flip-flops
    wire wr_t = push && (wptr == LAST);
    wire rd_t = pop  && (rptr == LAST);

    always @(posedge clk) begin
        if (push) begin
            mem[wptr] <= in_data;
            wptr <= (wptr == LAST) ? {AW{1'b0}} : wptr + 1'b1;
        end
        if (pop)
            rptr <= (rptr == LAST) ? {AW{1'b0}} : rptr + 1'b1;
        if (wr_t) wr_lap <= ~wr_lap;
        if (rd_t) rd_lap <= ~rd_lap;
        case ({push, pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
        if (cfg_load) begin
            wm    <= cfg_wm;
            armed <= 1'b0;
        end
    end

    assign almost_full = (count >= wm);
    assign occupancy   = count;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $rose(wr_lap))
            assert (count <= DEPTH);
endmodule

module xbar_cfg #(
    parameter N_IN  = 16,
    parameter N_OUT = 16,
    parameter DW    = 8,
    parameter SW    = $clog2(N_IN),
    parameter PW    = $clog2(N_OUT)
) (
    input  wire                 clk,
    input  wire                 rst,
    input  wire                 cfg_valid,
    output wire                 cfg_ready,
    input  wire [PW-1:0]        cfg_port,
    input  wire [SW-1:0]        cfg_sel,
    input  wire                 commit,
    input  wire                 lock,
    input  wire [N_IN*DW-1:0]   in_data,
    output wire [N_OUT*DW-1:0]  out_data
);
    typedef enum logic [1:0] {IDLE = 2'd0, PEND = 2'd1, LOCKED = 2'd2} state_t;

    state_t state = IDLE;
    reg [SW-1:0] sel [0:N_OUT-1];
    reg [PW-1:0] pend_port = '0;
    reg [SW-1:0] pend_sel  = '0;
    reg          cfg_seen  = 1'b0;
    reg          armed     = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < N_OUT; i = i + 1) sel[i] = '0;
    end

    assign cfg_ready = (state == IDLE);

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            for (i = 0; i < N_OUT; i = i + 1) sel[i] <= '0;
            pend_port <= '0;
            pend_sel  <= '0;
            cfg_seen  <= 1'b0;
            armed     <= 1'b1;
        end else begin
            case (state)
                IDLE: begin
                    if (cfg_valid && cfg_ready) begin
                        pend_port <= cfg_port;
                        pend_sel  <= cfg_sel;
                        cfg_seen  <= 1'b1;
                        state     <= PEND;
                    end else if (lock) begin
                        armed <= 1'b0;
                        state <= LOCKED;
                    end
                end
                PEND: begin
                    if (commit) begin
                        sel[pend_port] <= pend_sel;
                        state          <= IDLE;
                    end
                end
                LOCKED: begin
                end
                default: state <= IDLE;
            endcase
        end
    end

    genvar o;
    generate
        for (o = 0; o < N_OUT; o = o + 1) begin : g_out
            assign out_data[o*DW +: DW] = in_data[sel[o]*DW +: DW];
        end
    endgenerate

    reg any_sel;
    integer j;
    always @(*) begin
        any_sel = 1'b0;
        for (j = 0; j < N_OUT; j = j + 1)
            any_sel = any_sel | (sel[j] != '0);
    end

    always @(posedge clk) assert (!armed || cfg_seen || !any_sel);
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b
);
    localparam NBF = NCOEF / 2;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end

    assign in_ready = !busy && !out_valid;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (accept) begin
            a_r   <= in_a;
            b_r   <= in_b;
            w_r   <= in_w;
            lat_q <= lat_eff;
            cd    <= lat_eff;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module zi_mux_chain #(
    parameter N  = 16,
    parameter W  = 64,
    parameter SW = 4
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_ce,
    input  wire          i_arm,
    input  wire [SW-1:0] i_sel,
    input  wire          i_start,
    input  wire [SW-1:0] i_idx,
    input  wire [W-1:0]  i_data,
    output wire [W-1:0]  o_data,
    output wire          o_vld
);
    // arm: latch the mux select; start: load an entry and mark it valid;
    // finish: the zero-insertion mux forwards a valid entry.
    reg            armed   = 1'b0;
    reg            started = 1'b0;
    reg [SW-1:0]   sel     = {SW{1'b0}};
    reg [N-1:0]    vmask   = {N{1'b0}};
    reg [N*W-1:0]  store   = {(N*W){1'b0}};
    reg [W-1:0]    odata   = {W{1'b0}};
    reg            ovld    = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            armed   <= 1'b0;
            started <= 1'b0;
            sel     <= {SW{1'b0}};
            vmask   <= {N{1'b0}};
            store   <= {(N*W){1'b0}};
            odata   <= {W{1'b0}};
            ovld    <= 1'b0;
        end else if (i_ce) begin
            if (i_arm) begin
                armed <= 1'b1;
                sel   <= i_sel;
            end
            if (i_start && armed) begin
                started              <= 1'b1;
                vmask[i_idx]         <= 1'b1;
                store[i_idx*W +: W]  <= i_data;
            end
            ovld  <= vmask[sel];
            odata <= vmask[sel] ? store[sel*W +: W] : {W{1'b0}};
        end
    end

    assign o_data = odata;
    assign o_vld  = ovld;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Chain precedence: a forwarded (finished) word is never observed unless
    // the start and arm steps had already happened by the previous cycle.
    always @(posedge clk)
        if (pv && ovld)
            assert ($past(started) && $past(armed));
endmodule

module fll_cnt_cmp #(
    parameter W = 64,
    parameter [W-1:0] WINDOW = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         osc_tick,
    input  wire         tgt_load,
    input  wire [W-1:0] tgt_in,
    output reg  [W-1:0] osc_code,
    output reg          locked
);
    typedef enum logic [1:0] {S_IDLE = 2'd0, S_COUNT = 2'd1, S_CMP = 2'd2, S_ADJ = 2'd3} state_t;

    state_t state = S_IDLE;
    reg [W-1:0] cyc_cnt = {W{1'b0}};
    reg [W-1:0] win_tmr = {W{1'b0}};
    reg [W-1:0] target  = {W{1'b0}};
    reg up_req = 1'b0;
    reg dn_req = 1'b0;
    reg armed  = 1'b0;

    initial osc_code = {W{1'b0}};
    initial locked   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state   <= S_IDLE;
            cyc_cnt <= {W{1'b0}};
            win_tmr <= {W{1'b0}};
            up_req  <= 1'b0;
            dn_req  <= 1'b0;
            locked  <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (tgt_load) target <= tgt_in;
                    cyc_cnt <= {W{1'b0}};
                    win_tmr <= WINDOW;
                    armed   <= 1'b1;
                    state   <= S_COUNT;
                end
                S_COUNT: begin
                    if (osc_tick) cyc_cnt <= cyc_cnt + 1'b1;
                    win_tmr <= win_tmr - 1'b1;
                    if (win_tmr == 1) state <= S_CMP;
                end
                S_CMP: begin
                    up_req <= (cyc_cnt < target);
                    dn_req <= (cyc_cnt > target);
                    state  <= S_ADJ;
                end
                S_ADJ: begin
                    if (up_req)      osc_code <= osc_code + 1'b1;
                    else if (dn_req) osc_code <= osc_code - 1'b1;
                    locked <= !up_req && !dn_req;
                    up_req <= 1'b0;
                    dn_req <= 1'b0;
                    state  <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        assert (!armed || !(state == S_CMP && cyc_cnt > WINDOW));
endmodule

module wc_buffer #(
    parameter LINE_BYTES = 8
) (
    input  wire                      clk,
    input  wire                      in_valid,
    output wire                      in_ready,
    input  wire [63:0]               in_addr,
    input  wire [8*LINE_BYTES-1:0]   in_data,
    input  wire [LINE_BYTES-1:0]     in_be,
    input  wire                      i_flush,
    output wire                      out_valid,
    input  wire                      out_ready,
    output wire [63:0]               out_addr,
    output wire [8*LINE_BYTES-1:0]   out_data,
    output wire [LINE_BYTES-1:0]     out_mask,
    output wire [63:0]               o_bursts
);
    localparam W = 8*LINE_BYTES;
    localparam [LINE_BYTES-1:0] FULL = {LINE_BYTES{1'b1}};

    reg                  buf_valid      = 1'b0;
    reg [63:0]           buf_addr       = 64'd0;
    reg [W-1:0]          buf_data       = {W{1'b0}};
    reg [LINE_BYTES-1:0] buf_mask       = {LINE_BYTES{1'b0}};
    reg [63:0]           buf_cnt        = 64'd0;
    reg                  draining       = 1'b0;
    reg [63:0]           acc_stores     = 64'd0;
    reg [63:0]           flushed_stores = 64'd0;
    reg [63:0]           bursts         = 64'd0;

    wire [W-1:0] be_bits;
    genvar i;
    generate
        for (i = 0; i < LINE_BYTES; i = i + 1) begin : g_be
            assign be_bits[8*i +: 8] = {8{in_be[i]}};
        end
    endgenerate

    wire same_line = buf_valid && (in_addr == buf_addr);
    assign in_ready  = !draining && (!buf_valid || same_line);
    wire in_fire     = in_valid && in_ready;
    assign out_valid = draining;
    wire out_fire    = out_valid && out_ready;

    wire [W-1:0]          base     = buf_valid ? buf_data : {W{1'b0}};
    wire [W-1:0]          merged   = (base & ~be_bits) | (in_data & be_bits);
    wire [LINE_BYTES-1:0] new_mask = (buf_valid ? buf_mask : {LINE_BYTES{1'b0}}) | in_be;

    always @(posedge clk) begin
        if (out_fire) begin
            buf_valid      <= 1'b0;
            buf_mask       <= {LINE_BYTES{1'b0}};
            buf_cnt        <= 64'd0;
            draining       <= 1'b0;
            flushed_stores <= flushed_stores + buf_cnt;
            bursts         <= bursts + 64'd1;
        end else if (in_fire && (in_be != {LINE_BYTES{1'b0}})) begin
            buf_valid  <= 1'b1;
            if (!buf_valid) buf_addr <= in_addr;
            buf_data   <= merged;
            buf_mask   <= new_mask;
            buf_cnt    <= buf_cnt + 64'd1;
            acc_stores <= acc_stores + 64'd1;
            if (new_mask == FULL) draining <= 1'b1;
        end else if (buf_valid && !draining && ((in_valid && !same_line) || i_flush)) begin
            draining <= 1'b1;
        end
    end

    assign out_addr = buf_addr;
    assign out_data = buf_data;
    assign out_mask = buf_mask;
    assign o_bursts = bursts;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(out_valid && out_ready))
            assert (acc_stores == flushed_stores);
endmodule

module an_arbiter #(
    parameter W = 64,
    parameter NPAGES = 2,
    parameter [63:0] LINK_TIME = 64'd6,
    parameter [63:0] LOCAL_ABIL = 64'h0000_0000_0000_01E0
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          page_valid,
    input  wire [W-1:0]  page_data,
    output wire          page_ready,
    input  wire          tick,
    input  wire          restart,
    output wire          link_up,
    output reg  [W-1:0]  resolved_mode
);
    localparam [1:0] ST_BASE = 2'd0;
    localparam [1:0] ST_NEXT = 2'd1;
    localparam [1:0] ST_WAIT = 2'd2;
    localparam [1:0] ST_DONE = 2'd3;

    reg [1:0]          neg_state  = ST_BASE;
    reg [W-1:0]        link_timer = {W{1'b0}};
    reg [NPAGES*W-1:0] rx_abil    = {(NPAGES*W){1'b0}};
    reg                win        = 1'b0;
    reg                pv         = 1'b0;
    initial resolved_mode = {W{1'b0}};

    assign page_ready = (neg_state == ST_BASE) || (neg_state == ST_NEXT);
    wire accept = page_valid && page_ready;
    assign link_up = (neg_state == ST_DONE);
    wire tmr_expired = (link_timer == {W{1'b0}});
    wire tmr_last    = (link_timer == {{(W-1){1'b0}}, 1'b1});

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            neg_state     <= ST_BASE;
            link_timer    <= {W{1'b0}};
            rx_abil       <= {(NPAGES*W){1'b0}};
            win           <= 1'b0;
            resolved_mode <= {W{1'b0}};
        end else begin
            if (tick && !tmr_expired)
                link_timer <= link_timer - {{(W-1){1'b0}}, 1'b1};
            case (neg_state)
                ST_BASE: if (accept) begin
                    rx_abil[W-1:0] <= page_data;
                    neg_state      <= ST_NEXT;
                end
                ST_NEXT: if (accept) begin
                    rx_abil[2*W-1:W] <= page_data;
                    neg_state        <= ST_WAIT;
                    link_timer       <= LINK_TIME;
                    win              <= 1'b1;
                end
                ST_WAIT: if (tick && tmr_last) begin
                    neg_state     <= ST_DONE;
                    win           <= 1'b0;
                    resolved_mode <= (rx_abil[W-1:0] | rx_abil[2*W-1:W]) & LOCAL_ABIL;
                end
                ST_DONE: if (restart) begin
                    neg_state <= ST_BASE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win) assert (!$rose(tmr_expired));
endmodule

module wallace_pipe_mul #(
    parameter W = 16
) (
    input  wire           clk,
    input  wire           rst_n,
    input  wire           ce,
    input  wire           in_valid,
    input  wire           clr_window,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    output wire [2*W-1:0] o_product,
    output wire           o_valid,
    output wire [31:0]    o_inflight
);
    localparam P = 2*W;
    localparam [31:0] STAGES = 32'd3;

    function integer rows_at;
        input integer lvl;
        integer k, r;
        begin
            r = W;
            for (k = 0; k < lvl; k = k + 1)
                if (r > 2) r = 2*(r/3) + (r%3);
            rows_at = r;
        end
    endfunction

    function integer num_levels;
        input integer dummy;
        integer k, r, n;
        begin
            r = W; n = 0;
            for (k = 0; k < 64; k = k + 1)
                if (r > 2) begin
                    r = 2*(r/3) + (r%3);
                    n = n + 1;
                end
            num_levels = n;
        end
    endfunction

    localparam integer NLEV = num_levels(0);

    reg [W-1:0] s1_a = {W{1'b0}};
    reg [W-1:0] s1_b = {W{1'b0}};
    reg         v1 = 1'b0;
    reg [P-1:0] s2_sum = {P{1'b0}};
    reg [P-1:0] s2_carry = {P{1'b0}};
    reg         v2 = 1'b0;
    reg [P-1:0] s3_prod = {P{1'b0}};
    reg         v3 = 1'b0;
    reg [31:0]  inflight = 32'd0;
    reg         armed = 1'b0;

    wire [(NLEV+1)*W*P-1:0] tree;

    genvar j, L, i;
    generate
        for (j = 0; j < W; j = j + 1) begin : pp
            assign tree[j*P +: P] = s1_b[j] ? ({{W{1'b0}}, s1_a} << j) : {P{1'b0}};
        end
        for (L = 0; L < NLEV; L = L + 1) begin : lev
            localparam integer NR = rows_at(L);
            localparam integer NG = NR / 3;
            localparam integer NP = NR - 3*NG;
            for (i = 0; i < NG; i = i + 1) begin : csa
                wire [P-1:0] xa = tree[(L*W + 3*i)*P +: P];
                wire [P-1:0] xb = tree[(L*W + 3*i + 1)*P +: P];
                wire [P-1:0] xc = tree[(L*W + 3*i + 2)*P +: P];
                assign tree[((L+1)*W + 2*i)*P +: P]     = xa ^ xb ^ xc;
                assign tree[((L+1)*W + 2*i + 1)*P +: P] = ((xa & xb) | (xa & xc) | (xb & xc)) << 1;
            end
            for (i = 0; i < NP; i = i + 1) begin : pass
                assign tree[((L+1)*W + 2*NG + i)*P +: P] = tree[(L*W + 3*NG + i)*P +: P];
            end
            for (i = 2*NG + NP; i < W; i = i + 1) begin : unused
                assign tree[((L+1)*W + i)*P +: P] = {P{1'b0}};
            end
        end
    endgenerate

    wire [P-1:0] cs_sum   = tree[(NLEV*W)*P +: P];
    wire [P-1:0] cs_carry = tree[(NLEV*W + 1)*P +: P];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s1_a     <= {W{1'b0}};
            s1_b     <= {W{1'b0}};
            v1       <= 1'b0;
            s2_sum   <= {P{1'b0}};
            s2_carry <= {P{1'b0}};
            v2       <= 1'b0;
            s3_prod  <= {P{1'b0}};
            v3       <= 1'b0;
            inflight <= 32'd0;
            armed    <= 1'b0;
        end else if (ce) begin
            s1_a     <= in_a;
            s1_b     <= in_b;
            v1       <= in_valid;
            s2_sum   <= cs_sum;
            s2_carry <= cs_carry;
            v2       <= v1;
            s3_prod  <= s2_sum + s2_carry;
            v3       <= v2;
            inflight <= inflight + {31'd0, in_valid} - {31'd0, v3};
            if (clr_window)
                armed <= 1'b0;
            else if (in_valid)
                armed <= 1'b1;
        end
    end

    assign o_product  = s3_prod;
    assign o_valid    = v3;
    assign o_inflight = inflight;

    assert property (!armed || (inflight <= STAGES));
endmodule

module ecc_scrubber #(
    parameter LINES = 16,
    parameter AW = 4,
    parameter DW = 128,
    parameter SW = 7,
    parameter TW = 4,
    parameter [TW-1:0] INTERVAL = 4'd9,
    parameter CW = 8
)(
    input  wire          clk,
    input  wire          tick,
    input  wire          rd_valid,
    output wire          rd_ready,
    input  wire [DW-1:0] rd_data,
    input  wire          rd_err,
    input  wire [SW-1:0] rd_syn,
    output wire [AW-1:0] rd_addr,
    output wire          wb_valid,
    input  wire          wb_ready,
    output reg  [AW-1:0] wb_addr,
    output reg  [DW-1:0] wb_data,
    output reg  [CW-1:0] err_count,
    output reg  [AW-1:0] scrub_addr,
    output reg  [LINES-1:0] err_map
);
    localparam [1:0] S_WAIT = 2'd0;
    localparam [1:0] S_READ = 2'd1;
    localparam [1:0] S_WB   = 2'd2;

    reg [1:0]    phase;
    reg [TW-1:0] timer;
    reg          first_pass;

    initial begin
        phase      = S_WAIT;
        timer      = INTERVAL;
        wb_addr    = {AW{1'b0}};
        wb_data    = {DW{1'b0}};
        err_count  = {CW{1'b0}};
        scrub_addr = {AW{1'b0}};
        err_map    = {LINES{1'b0}};
        first_pass = 1'b1;
    end

    assign rd_ready = (phase == S_READ);
    assign wb_valid = (phase == S_WB);
    assign rd_addr  = scrub_addr;

    wire rd_fire    = rd_valid && rd_ready;
    wire done_clean = rd_fire && !rd_err;
    wire done_wb    = wb_valid && wb_ready;
    wire wrap_event = (done_clean && scrub_addr == LINES-1) ||
                      (done_wb && wb_addr == LINES-1);

    wire [DW-1:0] flip_mask = {{(DW-1){1'b0}}, 1'b1} << rd_syn;

    always @(posedge clk) begin
        case (phase)
            S_WAIT: begin
                if (tick) begin
                    if (timer == {TW{1'b0}}) begin
                        phase <= S_READ;
                        timer <= INTERVAL;
                    end else begin
                        timer <= timer - 1'b1;
                    end
                end
            end
            S_READ: begin
                if (rd_fire) begin
                    if (rd_err) begin
                        wb_data <= rd_data ^ flip_mask;
                        wb_addr <= scrub_addr;
                        phase   <= S_WB;
                    end else begin
                        scrub_addr <= scrub_addr + 1'b1;
                        phase      <= S_WAIT;
                    end
                end
            end
            S_WB: begin
                if (wb_ready) begin
                    scrub_addr       <= wb_addr + 1'b1;
                    err_map[wb_addr] <= 1'b1;
                    if (err_count != {CW{1'b1}})
                        err_count <= err_count + 1'b1;
                    phase <= S_WAIT;
                end
            end
            default: phase <= S_WAIT;
        endcase
        if (wrap_event)
            first_pass <= 1'b0;
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && first_pass && $stable(scrub_addr))
            assert ($stable(err_count));
endmodule

module heap_pq #(
    parameter DEPTH = 4,
    parameter KW    = 8,
    parameter IW    = 2,
    parameter SW    = 3,
    parameter LVL   = 2
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          in_valid,
    input  wire          in_op,
    input  wire [KW-1:0] in_key,
    output wire          in_ready,
    output reg  [KW-1:0] o_key,
    output wire [SW-1:0] o_size,
    output wire          o_busy
);
    reg [DEPTH*KW-1:0] heap = {(DEPTH*KW){1'b0}};
    reg [SW-1:0] size  = {SW{1'b0}};
    reg          busy  = 1'b0;
    reg          dir   = 1'b0;
    reg [IW-1:0] idx   = {IW{1'b0}};
    reg [1:0]    timer = 2'd0;
    reg          armed = 1'b0;
    initial o_key = {KW{1'b0}};

    assign in_ready = i_ce && !busy && (in_op ? (size != {SW{1'b0}}) : (size != DEPTH));
    wire accept = in_valid && in_ready;
    assign o_size = size;
    assign o_busy = busy;

    wire [IW-1:0] last   = size - 1'b1;
    wire [KW-1:0] k_root = heap[KW-1:0];
    wire [KW-1:0] k_last = heap[last*KW +: KW];
    wire [KW-1:0] k_idx  = heap[idx*KW +: KW];

    // sift-up
    wire [IW-1:0] up_par  = (idx - 1'b1) >> 1;
    wire [KW-1:0] k_par   = heap[up_par*KW +: KW];
    wire          up_swap = (idx != {IW{1'b0}}) && (k_idx < k_par);

    // sift-down
    wire [SW:0]   lc    = {idx, 1'b1};
    wire [SW:0]   rc    = lc + 1'b1;
    wire [IW-1:0] lci   = lc[IW-1:0];
    wire [IW-1:0] rci   = rc[IW-1:0];
    wire [KW-1:0] k_lc  = heap[lci*KW +: KW];
    wire [KW-1:0] k_rc  = heap[rci*KW +: KW];
    wire          lc_ok = lc < {1'b0, size};
    wire          rc_ok = rc < {1'b0, size};
    wire          l_lt  = lc_ok && (k_lc < k_idx);
    wire [IW-1:0] sm1   = l_lt ? lci : idx;
    wire [KW-1:0] k_sm1 = l_lt ? k_lc : k_idx;
    wire          r_lt  = rc_ok && (k_rc < k_sm1);
    wire [IW-1:0] sm    = r_lt ? rci : sm1;
    wire [KW-1:0] k_sm  = r_lt ? k_rc : k_sm1;
    wire          dn_swap = (sm != idx);
    wire [SW:0]   sm_lc = {sm, 1'b1};
    wire          dn_more = sm_lc < {1'b0, size};

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                armed <= 1'b1;
                timer <= LVL;
                if (!in_op) begin
                    heap[size[IW-1:0]*KW +: KW] <= in_key;
                    idx  <= size[IW-1:0];
                    size <= size + 1'b1;
                    busy <= (size != {SW{1'b0}});
                    dir  <= 1'b0;
                end else begin
                    o_key <= k_root;
                    heap[KW-1:0] <= k_last;
                    size  <= size - 1'b1;
                    idx   <= {IW{1'b0}};
                    busy  <= (size > 3'd2);
                    dir   <= 1'b1;
                end
            end else if (busy) begin
                if (!dir) begin
                    if (up_swap) begin
                        heap[idx*KW +: KW]    <= k_par;
                        heap[up_par*KW +: KW] <= k_idx;
                        idx   <= up_par;
                        timer <= timer - 1'b1;
                        busy  <= (up_par != {IW{1'b0}});
                        if (up_par == {IW{1'b0}}) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end else begin
                    if (dn_swap) begin
                        heap[idx*KW +: KW] <= k_sm;
                        heap[sm*KW +: KW]  <= k_idx;
                        idx   <= sm;
                        timer <= timer - 1'b1;
                        busy  <= dn_more;
                        if (!dn_more) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end
            end else begin
                armed <= 1'b0;
            end
        end
    end

    // bounded response: while the accepted request is still sifting, its budget never runs out
    always @(posedge clk)
        if (armed) assert (!busy || timer != 2'd0);
endmodule

module div3_serial_checker (
    input  wire clk,
    input  wire i_ce,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_bit,
    output wire o_verdict,
    output wire o_done
);
    parameter WIDTH = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3} ctl_t;
    typedef enum logic [1:0] {R0 = 2'd0, R1 = 2'd1, R2 = 2'd2} rem_t;

    ctl_t ctl = IDLE;
    rem_t rem = R0;
    reg [WIDTH-1:0] value = {WIDTH{1'b0}};
    reg [WIDTH-1:0] nbits = {WIDTH{1'b0}};
    reg armed = 1'b0;
    reg started = 1'b0;

    rem_t rem_next;
    always @(*) begin
        case (rem)
            R0: rem_next = i_bit ? R1 : R0;
            R1: rem_next = i_bit ? R0 : R2;
            R2: rem_next = i_bit ? R2 : R1;
            default: rem_next = R0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (ctl)
                IDLE: begin
                    if (i_arm) begin
                        ctl   <= ARMED;
                        armed <= 1'b1;
                    end
                end
                ARMED: begin
                    if (i_start) begin
                        ctl     <= RUN;
                        started <= 1'b1;
                        value   <= {WIDTH{1'b0}};
                        nbits   <= {WIDTH{1'b0}};
                        rem     <= R0;
                    end
                end
                RUN: begin
                    value <= {value[WIDTH-2:0], i_bit};
                    nbits <= nbits + 1'b1;
                    rem   <= rem_next;
                    if (nbits == WIDTH-1)
                        ctl <= DONE;
                end
                DONE: begin
                    if (i_arm)
                        ctl <= ARMED;
                end
                default: ctl <= IDLE;
            endcase
        end
    end

    assign o_done    = (ctl == DONE);
    assign o_verdict = (ctl == DONE) && (rem == R0);

    always @(*)
        assert (!(armed && ctl == DONE && rem == R0) || (started && (value % 32'd3) == 32'd0));
endmodule

module desc_prefetch_cache #(
    parameter DEPTH = 32,
    parameter AW = $clog2(DEPTH)
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        step,
    input  wire        fetch_req,
    input  wire        consume_req,
    input  wire        flush,
    input  wire [63:0] desc_in,
    input  wire [63:0] lookup_addr,
    output reg         out_valid,
    output reg  [63:0] out_tag,
    output reg  [63:0] out_desc,
    output reg         lookup_hit
);
    localparam [63:0] DEPTH64 = DEPTH;

    reg [DEPTH-1:0] valid;
    reg [63:0] tag_mem  [0:DEPTH-1];
    reg [63:0] data_mem [0:DEPTH-1];
    reg [AW-1:0] wr_ptr;
    reg [AW-1:0] rd_ptr;
    reg [AW:0]   count;
    reg [63:0] next_fetch;
    reg [63:0] head_addr;
    reg [63:0] fetch_seen;
    reg [63:0] consume_seen;
    reg        before_flush;

    integer i;
    initial begin
        valid = {DEPTH{1'b0}};
        for (i = 0; i < DEPTH; i = i + 1) begin
            tag_mem[i]  = 64'd0;
            data_mem[i] = 64'd0;
        end
        wr_ptr = {AW{1'b0}};
        rd_ptr = {AW{1'b0}};
        count = {(AW+1){1'b0}};
        next_fetch = 64'd0;
        head_addr = 64'd0;
        fetch_seen = 64'd0;
        consume_seen = 64'd0;
        before_flush = 1'b1;
        out_valid = 1'b0;
        out_tag = 64'd0;
        out_desc = 64'd0;
    end

    wire do_fetch   = step && !flush && fetch_req && (count < DEPTH);
    wire do_consume = step && !flush && consume_req && (count != 0);

    integer j;
    always @(*) begin
        lookup_hit = 1'b0;
        for (j = 0; j < DEPTH; j = j + 1)
            if (valid[j] && tag_mem[j] == lookup_addr)
                lookup_hit = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid <= {DEPTH{1'b0}};
            wr_ptr <= {AW{1'b0}};
            rd_ptr <= {AW{1'b0}};
            count <= {(AW+1){1'b0}};
            next_fetch <= 64'd0;
            head_addr <= 64'd0;
            fetch_seen <= 64'd0;
            consume_seen <= 64'd0;
            before_flush <= 1'b1;
            out_valid <= 1'b0;
            out_tag <= 64'd0;
            out_desc <= 64'd0;
        end else if (step) begin
            if (flush) begin
                valid <= {DEPTH{1'b0}};
                count <= {(AW+1){1'b0}};
                rd_ptr <= wr_ptr;
                head_addr <= next_fetch;
                out_valid <= 1'b0;
                before_flush <= 1'b0;
            end else begin
                out_valid <= do_consume;
                if (do_fetch) begin
                    tag_mem[wr_ptr]  <= next_fetch;
                    data_mem[wr_ptr] <= desc_in;
                    valid[wr_ptr] <= 1'b1;
                    wr_ptr <= wr_ptr + 1'b1;
                    next_fetch <= next_fetch + 64'd1;
                    fetch_seen <= fetch_seen + 64'd1;
                end
                if (do_consume) begin
                    valid[rd_ptr] <= 1'b0;
                    rd_ptr <= rd_ptr + 1'b1;
                    head_addr <= head_addr + 64'd1;
                    consume_seen <= consume_seen + 64'd1;
                    out_tag <= head_addr;
                    out_desc <= data_mem[rd_ptr];
                end
                case ({do_fetch, do_consume})
                    2'b10:   count <= count + 1'b1;
                    2'b01:   count <= count - 1'b1;
                    default: count <= count;
                endcase
            end
        end
    end

    // Precedence, before flush: a delivered descriptor must have been fetched earlier
    always @(posedge clk)
        if (before_flush && out_valid)
            assert ((fetch_seen - out_tag - 64'd1) <= DEPTH64);

    // Precedence, before flush: every consume was preceded by a fetch
    always @(posedge clk)
        if (before_flush)
            assert ((fetch_seen - consume_seen) <= DEPTH64);
endmodule

module wallace_pipe_mul (
    input  wire          i_clk,
    input  wire          i_reset,
    input  wire          i_ce,
    input  wire          i_valid,
    input  wire [15:0]   i_a,
    input  wire [15:0]   i_b,
    input  wire          i_open,
    input  wire          i_close,
    output wire [31:0]   o_prod,
    output wire          o_valid,
    output wire          o_empty
);
    parameter W = 16;
    localparam PW = 2*W;

    function [PW-1:0] csa_s;
        input [PW-1:0] x, y, z;
        csa_s = x ^ y ^ z;
    endfunction

    function [PW-1:0] csa_c;
        input [PW-1:0] x, y, z;
        csa_c = ((x & y) | (x & z) | (y & z)) << 1;
    endfunction

    // partial products
    wire [PW-1:0] pp [0:W-1];
    genvar g;
    generate
        for (g = 0; g < W; g = g + 1) begin : g_pp
            assign pp[g] = i_a[g] ? ({{W{1'b0}}, i_b} << g) : {PW{1'b0}};
        end
    endgenerate

    // Wallace level 1: 16 -> 11
    wire [PW-1:0] l1 [0:10];
    generate
        for (g = 0; g < 5; g = g + 1) begin : g_l1
            assign l1[2*g]   = csa_s(pp[3*g], pp[3*g+1], pp[3*g+2]);
            assign l1[2*g+1] = csa_c(pp[3*g], pp[3*g+1], pp[3*g+2]);
        end
    endgenerate
    assign l1[10] = pp[15];

    // level 2: 11 -> 8
    wire [PW-1:0] l2 [0:7];
    generate
        for (g = 0; g < 3; g = g + 1) begin : g_l2
            assign l2[2*g]   = csa_s(l1[3*g], l1[3*g+1], l1[3*g+2]);
            assign l2[2*g+1] = csa_c(l1[3*g], l1[3*g+1], l1[3*g+2]);
        end
    endgenerate
    assign l2[6] = l1[9];
    assign l2[7] = l1[10];

    // level 3: 8 -> 6
    wire [PW-1:0] l3 [0:5];
    generate
        for (g = 0; g < 2; g = g + 1) begin : g_l3
            assign l3[2*g]   = csa_s(l2[3*g], l2[3*g+1], l2[3*g+2]);
            assign l3[2*g+1] = csa_c(l2[3*g], l2[3*g+1], l2[3*g+2]);
        end
    endgenerate
    assign l3[4] = l2[6];
    assign l3[5] = l2[7];

    // level 4: 6 -> 4
    wire [PW-1:0] l4 [0:3];
    generate
        for (g = 0; g < 2; g = g + 1) begin : g_l4
            assign l4[2*g]   = csa_s(l3[3*g], l3[3*g+1], l3[3*g+2]);
            assign l4[2*g+1] = csa_c(l3[3*g], l3[3*g+1], l3[3*g+2]);
        end
    endgenerate

    // stage 1 pipeline registers (4 rows)
    reg [PW-1:0] r1_0, r1_1, r1_2, r1_3;
    reg          v1;
    initial begin r1_0 = 0; r1_1 = 0; r1_2 = 0; r1_3 = 0; v1 = 1'b0; end

    // level 5: 4 -> 3, level 6: 3 -> 2
    wire [PW-1:0] s5 = csa_s(r1_0, r1_1, r1_2);
    wire [PW-1:0] c5 = csa_c(r1_0, r1_1, r1_2);
    wire [PW-1:0] s6 = csa_s(s5, c5, r1_3);
    wire [PW-1:0] c6 = csa_c(s5, c5, r1_3);

    // stage 2 pipeline registers (carry-save pair)
    reg [PW-1:0] s2, c2;
    reg          v2;
    initial begin s2 = 0; c2 = 0; v2 = 1'b0; end

    // stage 3: final carry-propagate adder
    reg [PW-1:0] prod;
    reg          v3;
    initial begin prod = 0; v3 = 1'b0; end

    // occupancy counter and observation window
    reg [W-1:0] inflight;
    reg         win;
    initial begin inflight = {W{1'b0}}; win = 1'b0; end

    always @(posedge i_clk) begin
        if (i_reset) begin
            r1_0 <= 0; r1_1 <= 0; r1_2 <= 0; r1_3 <= 0;
            s2 <= 0; c2 <= 0; prod <= 0;
            v1 <= 1'b0; v2 <= 1'b0; v3 <= 1'b0;
            inflight <= {W{1'b0}};
            win <= 1'b0;
        end else if (i_ce) begin
            r1_0 <= l4[0]; r1_1 <= l4[1]; r1_2 <= l4[2]; r1_3 <= l4[3];
            s2   <= s6;    c2   <= c6;
            prod <= s2 + c2;
            v1 <= i_valid;
            v2 <= v1;
            v3 <= v2;
            inflight <= inflight + {{(W-1){1'b0}}, i_valid} - {{(W-1){1'b0}}, v3};
            if (i_open)
                win <= 1'b1;
            else if (i_close)
                win <= 1'b0;
        end
    end

    wire empty = (inflight == {W{1'b0}});

    assign o_prod  = prod;
    assign o_valid = v3;
    assign o_empty = empty;

    // Absence, between open and close: empty flag and output-valid never together
    always @(*)
        assert (!win || !(empty && v3));
endmodule

module ldpc_cnp #(
    parameter DEG = 32,
    parameter W   = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_data
);
    localparam IW = $clog2(DEG);

    reg [W-1:0]   cnt       = {W{1'b0}};
    reg [W-1:0]   oidx      = {W{1'b0}};
    reg           out_phase = 1'b0;
    reg [W-2:0]   min1      = {(W-1){1'b1}};
    reg [W-2:0]   min2      = {(W-1){1'b1}};
    reg [W-1:0]   min_idx   = {W{1'b0}};
    reg           sign_prod = 1'b0;
    reg [DEG-1:0] sign_mem  = {DEG{1'b0}};
    reg           armed     = 1'b0;

    assign in_ready  = !out_phase;
    assign out_valid = out_phase;

    wire          accept = in_valid && in_ready;
    wire          emit   = out_valid && out_ready;
    wire          in_sgn = in_data[W-1];
    wire [W-2:0]  in_mag = in_data[W-2:0];

    assign out_data = { sign_prod ^ sign_mem[oidx[IW-1:0]],
                        (oidx == min_idx) ? min2 : min1 };

    always @(posedge clk) begin
        if (accept) armed <= 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= {W{1'b0}};
            oidx      <= {W{1'b0}};
            out_phase <= 1'b0;
            min1      <= {(W-1){1'b1}};
            min2      <= {(W-1){1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
        end else if (accept) begin
            sign_mem[cnt[IW-1:0]] <= in_sgn;
            sign_prod <= sign_prod ^ in_sgn;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= cnt;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            cnt <= cnt + 1'b1;
            if (cnt == DEG - 1)
                out_phase <= 1'b1;
        end else if (emit) begin
            if (oidx == DEG - 1) begin
                oidx      <= {W{1'b0}};
                cnt       <= {W{1'b0}};
                out_phase <= 1'b0;
                min1      <= {(W-1){1'b1}};
                min2      <= {(W-1){1'b1}};
                min_idx   <= {W{1'b0}};
                sign_prod <= 1'b0;
            end else begin
                oidx <= oidx + 1'b1;
            end
        end
    end

    assert property (!armed || cnt <= DEG);
endmodule

module frame_beat_ripple #(
    parameter W = 32,
    parameter MAX_BEATS = 12
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    input  wire         s_last,
    output wire         s_ready,
    output wire         m_valid,
    input  wire         m_ready,
    output wire [W-1:0] m_count
);
    typedef enum logic [1:0] {IDLE = 2'd0, COUNTING = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0] LIMIT    = MAX_BEATS;
    localparam [W-1:0] LAST_IDX = MAX_BEATS - 1;

    state_t state;
    reg in_frame;
    reg [W-1:0] q;
    integer i;

    initial begin
        state    = IDLE;
        in_frame = 1'b0;
        q        = {W{1'b0}};
    end

    assign s_ready = (state != DONE);
    assign m_valid = (state == DONE);
    assign m_count = q;

    wire accept = s_valid && s_ready;
    wire drain  = m_valid && m_ready;

    // Ripple chain of toggle flip-flops: stage 0 toggles on each accepted
    // beat; stage g toggles when stage g-1 falls from 1 to 0 (its 'clock').
    wire [W-1:0] t;
    assign t[0] = accept;
    genvar g;
    generate
        for (g = 1; g < W; g = g + 1) begin : rip
            assign t[g] = t[g-1] & q[g-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            state    <= IDLE;
            in_frame <= 1'b0;
            q        <= {W{1'b0}};
        end else begin
            if (drain)
                q <= {W{1'b0}};
            else
                for (i = 0; i < W; i = i + 1)
                    if (t[i]) q[i] <= ~q[i];

            case (state)
                IDLE: begin
                    if (accept) begin
                        in_frame <= 1'b1;
                        state    <= (s_last || q == LAST_IDX) ? DONE : COUNTING;
                    end
                end
                COUNTING: begin
                    if (accept && (s_last || q == LAST_IDX))
                        state <= DONE;
                end
                DONE: begin
                    if (drain) begin
                        state    <= IDLE;
                        in_frame <= 1'b0;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (in_frame) assert (q <= LIMIT);
endmodule

module ntt_butterfly #(
    parameter N = 64,
    parameter LOGN = 6,
    parameter [31:0] Q = 32'd3329
)(
    input  wire        clk,
    // twiddle factor channel (arm)
    input  wire        tw_valid,
    output wire        tw_ready,
    input  wire [31:0] tw_in,
    // coefficient operand channel (start)
    input  wire        in_valid,
    output wire        in_ready,
    input  wire [31:0] in_a,
    input  wire [31:0] in_b,
    // butterfly result channel (finish)
    output wire        out_valid,
    input  wire        out_ready,
    output wire [31:0] out_a,
    output wire [31:0] out_b,
    output wire [31:0] o_stage,
    output wire [31:0] o_idx
);
    localparam [31:0] HALF = N / 2;
    localparam [23:0] Q24  = Q;
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_DONE  = 2'd2;

    reg [1:0]  phase   = P_IDLE;
    reg [31:0] tw      = 32'd0;
    reg [31:0] res_a   = 32'd0;
    reg [31:0] res_b   = 32'd0;
    reg [31:0] stage   = 32'd0;
    reg [31:0] idx     = 32'd0;
    reg [31:0] grp_cnt = 32'd0;
    reg        arm_seen   = 1'b0;
    reg        start_seen = 1'b0;
    reg        before_r   = 1'b1;

    assign tw_ready  = (phase == P_IDLE);
    assign in_ready  = (phase == P_ARMED);
    assign out_valid = (phase == P_DONE);
    assign out_a     = res_a;
    assign out_b     = res_b;
    assign o_stage   = stage;
    assign o_idx     = idx;

    wire tw_fire  = tw_valid && tw_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    wire [31:0] glen          = HALF >> stage;
    wire        last_in_stage = (idx == HALF - 32'd1);
    wire        last_stage    = (stage == LOGN - 1);
    wire        last_in_group = (grp_cnt + 32'd1 == glen);

    // Cooley-Tukey butterfly: (a + w*b, a - w*b) mod Q
    wire [23:0] prod = tw[11:0] * in_b[11:0];
    wire [23:0] t24  = prod % Q24;
    wire [31:0] t    = {8'd0, t24};
    wire [31:0] sum  = in_a + t;
    wire [31:0] bf_a = (sum >= Q) ? (sum - Q) : sum;
    wire [31:0] dif  = in_a + Q - t;
    wire [31:0] bf_b = (dif >= Q) ? (dif - Q) : dif;

    always @(posedge clk) begin
        if (tw_fire) begin
            tw       <= tw_in;
            phase    <= P_ARMED;
            arm_seen <= 1'b1;
        end
        if (in_fire) begin
            res_a      <= bf_a;
            res_b      <= bf_b;
            phase      <= P_DONE;
            start_seen <= 1'b1;
        end
        if (out_fire) begin
            if (last_in_stage) begin
                idx     <= 32'd0;
                grp_cnt <= 32'd0;
                phase   <= P_IDLE;
                if (last_stage) begin
                    stage    <= 32'd0;
                    before_r <= 1'b0;
                end else begin
                    stage <= stage + 32'd1;
                end
            end else begin
                idx <= idx + 32'd1;
                if (last_in_group) begin
                    grp_cnt <= 32'd0;
                    phase   <= P_IDLE;
                end else begin
                    grp_cnt <= grp_cnt + 32'd1;
                    phase   <= P_ARMED;
                end
            end
        end
    end

    // Chain precedence, before the first transform completes:
    // a result can only be offered after a twiddle was armed and operands started.
    always @(posedge clk) assert (!(before_r && out_valid) || (arm_seen && start_seen));
endmodule

module preload_timer #(
    parameter W = 64,
    parameter [W-1:0] INIT_PERIOD = 64'd7
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         tick,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire         match,
    output wire         reload_evt
);
    reg [W-1:0] cnt           = INIT_PERIOD;
    reg [W-1:0] period        = INIT_PERIOD;
    reg [W-1:0] cmp_active    = {W{1'b0}};
    reg [W-1:0] shadow_period = INIT_PERIOD;
    reg [W-1:0] shadow_cmp    = {W{1'b0}};
    reg [W-1:0] deadline      = {W{1'b0}};
    reg         pending       = 1'b0;
    reg         armed         = 1'b0;
    reg         pv            = 1'b0;

    assign in_ready   = !pending;
    wire   accept     = in_valid && in_ready;
    wire   due        = (deadline == {W{1'b0}});
    assign reload_evt = tick && (cnt == {W{1'b0}});
    assign match      = (cnt == cmp_active);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cnt           <= INIT_PERIOD;
            period        <= INIT_PERIOD;
            cmp_active    <= {W{1'b0}};
            shadow_period <= INIT_PERIOD;
            shadow_cmp    <= {W{1'b0}};
            pending       <= 1'b0;
            deadline      <= {W{1'b0}};
        end else begin
            if (tick) begin
                if (cnt == {W{1'b0}}) begin
                    if (pending) begin
                        cnt        <= shadow_period;
                        period     <= shadow_period;
                        cmp_active <= shadow_cmp;
                        pending    <= 1'b0;
                    end else begin
                        cnt <= period;
                    end
                end else begin
                    cnt <= cnt - 1'b1;
                end
                if (pending && (cnt != {W{1'b0}}) && !due)
                    deadline <= deadline - 1'b1;
            end
            if (accept) begin
                shadow_period <= in_period;
                shadow_cmp    <= in_cmp;
                pending       <= 1'b1;
                armed         <= 1'b1;
                deadline      <= tick ? ((cnt == {W{1'b0}}) ? period : (cnt - 1'b1)) : cnt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && pending && $rose(due))
            assert (cnt == {W{1'b0}});
endmodule

module desc_prefetch_cache #(
    parameter DEPTH = 32,
    parameter DW = 16
)(
    input  wire          clk,
    input  wire          flush,
    input  wire [DW-1:0] flush_addr,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_desc,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_desc,
    output wire [DW-1:0] out_tag,
    output wire [DW-1:0] fetch_req_addr,
    input  wire [DW-1:0] lk_addr,
    output wire          lk_hit
);
    localparam AW = $clog2(DEPTH);

    reg [DW-1:0] desc_mem [0:DEPTH-1];
    reg [DW-1:0] tag_mem  [0:DEPTH-1];
    reg [DEPTH-1:0] valid = {DEPTH{1'b0}};
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [AW-1:0] rd_ptr = {AW{1'b0}};
    reg [DW-1:0] count = {DW{1'b0}};
    reg [DW-1:0] fetch_addr = {DW{1'b0}};
    reg armed = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            desc_mem[i] = {DW{1'b0}};
            tag_mem[i]  = {DW{1'b0}};
        end
    end

    assign in_ready = !flush && (count != DEPTH);
    wire in_fire = in_valid && in_ready;
    wire push = in_fire && !valid[wr_ptr];
    assign out_valid = !flush && valid[rd_ptr];
    wire pop = out_valid && out_ready;

    assign out_desc = desc_mem[rd_ptr];
    assign out_tag = tag_mem[rd_ptr];
    assign fetch_req_addr = fetch_addr;

    wire [DEPTH-1:0] set_mask = push ? ({{(DEPTH-1){1'b0}}, 1'b1} << wr_ptr) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_mask = pop  ? ({{(DEPTH-1){1'b0}}, 1'b1} << rd_ptr) : {DEPTH{1'b0}};

    wire [DEPTH-1:0] exp_valid;
    wire [DEPTH-1:0] hit_vec;
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : g_slot
            wire [AW-1:0] off = g - rd_ptr;
            assign exp_valid[g] = ({{(DW-AW){1'b0}}, off} < count);
            assign hit_vec[g] = valid[g] && (tag_mem[g] == lk_addr);
        end
    endgenerate
    assign lk_hit = |hit_vec;

    always @(posedge clk) begin
        if (flush) begin
            valid <= {DEPTH{1'b0}};
            count <= {DW{1'b0}};
            rd_ptr <= wr_ptr;
            fetch_addr <= flush_addr;
            armed <= 1'b0;
        end else begin
            if (push) begin
                desc_mem[wr_ptr] <= in_desc;
                tag_mem[wr_ptr] <= fetch_addr;
                wr_ptr <= wr_ptr + 1'b1;
                armed <= 1'b1;
            end
            if (in_fire)
                fetch_addr <= fetch_addr + {{(DW-1){1'b0}}, 1'b1};
            if (pop)
                rd_ptr <= rd_ptr + 1'b1;
            valid <= (valid | set_mask) & ~clr_mask;
            count <= count + {{(DW-1){1'b0}}, push} - {{(DW-1){1'b0}}, pop};
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(wr_ptr))
            assert ($stable(fetch_addr));
endmodule

module mem_autopd #(
    parameter W = 64,
    parameter [W-1:0] DEF_THRESH = 64'd4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         activity,
    input  wire         thr_we,
    input  wire [W-1:0] thr_din,
    output reg          pd_req,
    output reg  [W-1:0] idle_cnt
);
    typedef enum logic [1:0] {ACTIVE = 2'd0, COUNTING = 2'd1, POWERDN = 2'd2} state_t;

    state_t state;
    reg [W-1:0] threshold;
    reg pv;

    initial begin
        state     = ACTIVE;
        threshold = DEF_THRESH;
        pd_req    = 1'b0;
        idle_cnt  = {W{1'b0}};
        pv        = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (thr_we && state == ACTIVE)
                threshold <= thr_din;
            if (activity) begin
                state    <= ACTIVE;
                idle_cnt <= {W{1'b0}};
                pd_req   <= 1'b0;
            end else begin
                case (state)
                    ACTIVE: begin
                        state    <= COUNTING;
                        idle_cnt <= {{(W-1){1'b0}}, 1'b1};
                    end
                    COUNTING: begin
                        if (idle_cnt >= threshold) begin
                            state  <= POWERDN;
                            pd_req <= 1'b1;
                        end else begin
                            idle_cnt <= idle_cnt + {{(W-1){1'b0}}, 1'b1};
                        end
                    end
                    POWERDN: begin
                        state <= POWERDN;
                    end
                    default: begin
                        state    <= ACTIVE;
                        idle_cnt <= {W{1'b0}};
                        pd_req   <= 1'b0;
                    end
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && pd_req && $stable(pd_req))
            assert ($stable(idle_cnt));
endmodule

module fll_cmp #(
    parameter [31:0] WINDOW      = 32'd32,
    parameter [31:0] TARGET_INIT = 32'd20
) (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_osc_tick,
    input  wire        i_set_target,
    input  wire [31:0] i_target,
    output wire [31:0] o_code,
    output wire        o_searching
);
    reg [31:0] cyc_cnt  = 32'd0;
    reg [31:0] win_tmr  = 32'd0;
    reg [31:0] target   = TARGET_INIT;
    reg [31:0] osc_code = 32'h80000000;
    reg        searching = 1'b1;

    wire        win_end   = (win_tmr == WINDOW - 32'd1);
    wire [31:0] final_cnt = cyc_cnt + {31'd0, i_osc_tick};

    always @(posedge clk) begin
        if (i_reset) begin
            cyc_cnt  <= 32'd0;
            win_tmr  <= 32'd0;
            target   <= TARGET_INIT;
            osc_code <= 32'h80000000;
        end else if (i_ce) begin
            if (i_set_target)
                target <= i_target;
            if (win_end) begin
                cyc_cnt <= 32'd0;
                win_tmr <= 32'd0;
                if (final_cnt < target) begin
                    if (osc_code != 32'hFFFFFFFF)
                        osc_code <= osc_code + 32'd1;
                end else if (final_cnt > target) begin
                    if (osc_code != 32'd0)
                        osc_code <= osc_code - 32'd1;
                end else begin
                    searching <= 1'b0;
                end
            end else begin
                win_tmr <= win_tmr + 32'd1;
                cyc_cnt <= final_cnt;
            end
        end
    end

    assign o_code      = osc_code;
    assign o_searching = searching;

    assert property (!searching || (cyc_cnt < WINDOW));
endmodule

module requant_unit #(
    parameter DATA_W  = 32,
    parameter OUT_W   = 8,
    parameter SHIFT_W = 6
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               ce,
    input  wire               cfg_we,
    input  wire [DATA_W-1:0]  cfg_mult,
    input  wire [SHIFT_W-1:0] cfg_shift,
    input  wire               in_valid,
    input  wire [DATA_W-1:0]  acc_in,
    output wire [OUT_W-1:0]   q_out,
    output wire               q_valid
);
    localparam [DATA_W-1:0] CNT_MAX = {DATA_W{1'b1}};
    localparam signed [2*DATA_W-1:0] QMAX = {{(2*DATA_W-OUT_W+1){1'b0}}, {(OUT_W-1){1'b1}}};
    localparam signed [2*DATA_W-1:0] QMIN = {{(2*DATA_W-OUT_W+1){1'b1}}, {(OUT_W-1){1'b0}}};

    // configuration registers
    reg [DATA_W-1:0]  mult_r  = {DATA_W{1'b0}};
    reg [SHIFT_W-1:0] shift_r = {SHIFT_W{1'b0}};
    reg               armed   = 1'b0;            // sticky: first config write seen
    reg [DATA_W-1:0]  cfg_cnt = {DATA_W{1'b0}};  // config epoch (saturating)

    // output stage
    reg               out_valid = 1'b0;
    reg [OUT_W-1:0]   out_q     = {OUT_W{1'b0}};
    reg [DATA_W-1:0]  out_tag   = {DATA_W{1'b0}}; // shadow: epoch used by current output
    reg [DATA_W-1:0]  out_cnt   = {DATA_W{1'b0}}; // outputs produced (saturating)
    reg [DATA_W-1:0]  first_tag = {DATA_W{1'b0}}; // shadow: epoch used by first output

    wire fire = in_valid && armed;

    // requantization datapath: (acc * mult + round) >>> shift, saturated
    wire signed [2*DATA_W-1:0] prod   = $signed(acc_in) * $signed(mult_r);
    wire        [2*DATA_W-1:0] rnd_u  = (shift_r == {SHIFT_W{1'b0}}) ? {2*DATA_W{1'b0}} :
                                        ({{(2*DATA_W-1){1'b0}}, 1'b1} << (shift_r - 1'b1));
    wire signed [2*DATA_W-1:0] summed = prod + $signed(rnd_u);
    wire signed [2*DATA_W-1:0] scaled = summed >>> shift_r;
    wire        [OUT_W-1:0]    sat    = (scaled > QMAX) ? QMAX[OUT_W-1:0] :
                                        (scaled < QMIN) ? QMIN[OUT_W-1:0] :
                                        scaled[OUT_W-1:0];

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            out_q     <= {OUT_W{1'b0}};
        end else if (ce) begin
            if (cfg_we) begin
                mult_r  <= cfg_mult;
                shift_r <= cfg_shift;
                armed   <= 1'b1;
                if (cfg_cnt != CNT_MAX)
                    cfg_cnt <= cfg_cnt + 1'b1;
            end
            out_valid <= fire;
            if (fire) begin
                out_q   <= sat;
                out_tag <= cfg_cnt;
                if (out_cnt == {DATA_W{1'b0}})
                    first_tag <= cfg_cnt;
                if (out_cnt != CNT_MAX)
                    out_cnt <= out_cnt + 1'b1;
            end
        end
    end

    assign q_out   = out_q;
    assign q_valid = out_valid;

    // Precedence, after first config write: an emitted sample must have been
    // produced under a configuration that was written earlier.
    always @(posedge clk)
        if (armed && out_valid)
            assert (out_tag != 32'd0);

    always @(posedge clk)
        if (armed && out_cnt != 32'd0)
            assert (first_tag != 32'd0);
endmodule

module heap_pq #(
    parameter DEPTH = 4,
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_key,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_key
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] IDLE = 2'd0, LOAD = 2'd1, SIFT_UP = 2'd2, SIFT_DN = 2'd3;

    reg [1:0] state = IDLE;
    reg [DEPTH*W-1:0] heap = {(DEPTH*W){1'b0}};

    reg [31:0]  size      = 32'd0;
    reg [31:0]  idx       = 32'd0;
    reg [31:0]  armed_cnt = 32'd0;
    reg [31:0]  start_cnt = 32'd0;
    reg [31:0]  done_cnt  = 32'd0;
    reg [W-1:0] stage_key = {W{1'b0}};
    reg         win       = 1'b0;

    wire [31:0] szm1   = size - 32'd1;
    wire [31:0] parent = (idx - 32'd1) >> 1;
    wire [31:0] lc     = {idx[30:0], 1'b0} + 32'd1;
    wire [31:0] rc     = lc + 32'd1;

    wire [AW-1:0] a_idx = idx[AW-1:0];
    wire [AW-1:0] a_par = parent[AW-1:0];
    wire [AW-1:0] a_lc  = lc[AW-1:0];
    wire [AW-1:0] a_rc  = rc[AW-1:0];
    wire [AW-1:0] a_szm = szm1[AW-1:0];
    wire [AW-1:0] a_sz  = size[AW-1:0];

    wire [W-1:0] k_idx = heap[a_idx*W +: W];
    wire [W-1:0] k_par = heap[a_par*W +: W];
    wire [W-1:0] k_lc  = heap[a_lc*W +: W];
    wire [W-1:0] k_rc  = heap[a_rc*W +: W];
    wire [W-1:0] k_szm = heap[a_szm*W +: W];

    assign out_valid = (state == IDLE) && (size != 32'd0);
    assign out_key   = heap[W-1:0];
    wire pop  = step && out_valid && out_ready;
    assign in_ready  = step && (state == IDLE) && (size < DEPTH) && !pop;
    wire push = in_valid && in_ready;

    reg [31:0]  sm;
    reg [W-1:0] sm_key;
    always @(*) begin
        sm = idx;
        sm_key = k_idx;
        if (lc < size && k_lc < sm_key) begin sm = lc; sm_key = k_lc; end
        if (rc < size && k_rc < sm_key) begin sm = rc; sm_key = k_rc; end
    end
    wire [AW-1:0] a_sm = sm[AW-1:0];

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            size      <= 32'd0;
            idx       <= 32'd0;
            armed_cnt <= 32'd0;
            start_cnt <= 32'd0;
            done_cnt  <= 32'd0;
            stage_key <= {W{1'b0}};
            win       <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (pop) begin
                        heap[W-1:0] <= k_szm;
                        size   <= szm1;
                        idx    <= 32'd0;
                        state  <= SIFT_DN;
                        if (size == 32'd1) win <= 1'b0;
                    end else if (push) begin
                        stage_key <= in_key;
                        armed_cnt <= armed_cnt + 32'd1;
                        state     <= LOAD;
                        win       <= 1'b1;
                    end
                end
                LOAD: begin
                    if (step) begin
                        heap[a_sz*W +: W] <= stage_key;
                        idx       <= size;
                        size      <= size + 32'd1;
                        start_cnt <= start_cnt + 32'd1;
                        state     <= SIFT_UP;
                    end
                end
                SIFT_UP: begin
                    if (step) begin
                        if (idx == 32'd0 || k_par <= k_idx) begin
                            done_cnt <= done_cnt + 32'd1;
                            state    <= IDLE;
                        end else begin
                            heap[a_par*W +: W] <= k_idx;
                            heap[a_idx*W +: W] <= k_par;
                            idx <= parent;
                        end
                    end
                end
                SIFT_DN: begin
                    if (step) begin
                        if (sm == idx) begin
                            state <= IDLE;
                        end else begin
                            heap[a_idx*W +: W] <= sm_key;
                            heap[a_sm*W +: W]  <= k_idx;
                            idx <= sm;
                        end
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(state) == SIFT_UP && state == IDLE)
            assert ($past(start_cnt) == $past(done_cnt) + 32'd1 && $past(armed_cnt) == $past(start_cnt));
endmodule

module eye_scan_mon #(
    parameter W  = 128,
    parameter NS = 8,
    parameter NH = 8,
    parameter NV = 4,
    parameter CW = $clog2(NS),
    parameter HW = $clog2(NH),
    parameter VW = $clog2(NV),
    parameter EW = $clog2(NS) + 1
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          s_valid,
    output wire          s_ready,
    input  wire [W-1:0]  s_data,
    input  wire [W-1:0]  s_off,
    output reg           m_valid,
    input  wire          m_ready,
    output reg  [HW-1:0] m_hoff,
    output reg  [VW-1:0] m_voff,
    output reg  [EW-1:0] m_errs
);
    reg [HW-1:0]    hoff       = {HW{1'b0}};
    reg [VW-1:0]    voff       = {VW{1'b0}};
    reg [CW-1:0]    sample_cnt = {CW{1'b0}};
    reg [EW-1:0]    err_cnt    = {EW{1'b0}};
    reg [NH*EW-1:0] emap       = {(NH*EW){1'b0}};
    reg             armed      = 1'b1;

    initial m_valid = 1'b0;
    initial m_hoff  = {HW{1'b0}};
    initial m_voff  = {VW{1'b0}};
    initial m_errs  = {EW{1'b0}};

    assign s_ready = !m_valid;

    wire          s_fire    = s_valid && s_ready;
    wire          mis       = |(s_data ^ s_off);
    wire [EW-1:0] err_next  = err_cnt + {{(EW-1){1'b0}}, mis};
    wire          last      = (sample_cnt == NS-1);
    wire          scan_done = s_fire && last && (hoff == NH-1) && (voff == NV-1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hoff       <= {HW{1'b0}};
            voff       <= {VW{1'b0}};
            sample_cnt <= {CW{1'b0}};
            err_cnt    <= {EW{1'b0}};
            emap       <= {(NH*EW){1'b0}};
            armed      <= 1'b1;
            m_valid    <= 1'b0;
            m_hoff     <= {HW{1'b0}};
            m_voff     <= {VW{1'b0}};
            m_errs     <= {EW{1'b0}};
        end else begin
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (s_fire) begin
                if (last) begin
                    sample_cnt <= {CW{1'b0}};
                    err_cnt    <= {EW{1'b0}};
                    m_valid    <= 1'b1;
                    m_errs     <= err_next;
                    m_hoff     <= hoff;
                    m_voff     <= voff;
                    emap[hoff*EW +: EW] <= err_next;
                    if (hoff == NH-1) begin
                        hoff <= {HW{1'b0}};
                        voff <= voff + 1'b1;
                    end else begin
                        hoff <= hoff + 1'b1;
                    end
                end else begin
                    sample_cnt <= sample_cnt + 1'b1;
                    err_cnt    <= err_next;
                end
            end
            if (scan_done)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed) assert (err_cnt < NS);
endmodule

module warm_rst_quiesce #(
    parameter NPORTS = 4,
    parameter DW = 128,
    parameter TMO_CYCLES = 10,
    parameter TW = $clog2(TMO_CYCLES + 1)
) (
    input  wire              clk,
    // warm reset request stream (valid/ready), carries a 128-bit reset context word
    input  wire              wr_valid,
    output wire              wr_ready,
    input  wire [DW-1:0]     wr_ctx,
    // per-port drain/idle acknowledgments
    input  wire [NPORTS-1:0] ack_valid,
    output wire [NPORTS-1:0] ack_ready,
    // timeout timebase strobe
    input  wire              tick,
    // outgoing warm reset command (valid/ready)
    output wire              rst_valid,
    input  wire              rst_ready,
    output wire [DW-1:0]     rst_ctx,
    output wire              rst_forced,
    // block new bus transactions while quiescing / resetting
    output wire              blk_new
);
    localparam [TW-1:0] TMO_MAX = TMO_CYCLES;

    reg              qreq      = 1'b0;
    reg [NPORTS-1:0] ack       = {NPORTS{1'b0}};
    reg [TW-1:0]     tmo       = {TW{1'b0}};
    reg              rst_v     = 1'b0;
    reg              forced    = 1'b0;
    reg [DW-1:0]     ctx       = {DW{1'b0}};
    reg              qreq_seen = 1'b0;

    wire all_ack = &ack;

    assign wr_ready   = !qreq && !rst_v;
    assign ack_ready  = {NPORTS{qreq}};
    assign rst_valid  = rst_v;
    assign rst_ctx    = ctx;
    assign rst_forced = forced;
    assign blk_new    = qreq || rst_v;

    always @(posedge clk) begin
        if (wr_valid && wr_ready) begin
            qreq      <= 1'b1;
            ack       <= {NPORTS{1'b0}};
            tmo       <= {TW{1'b0}};
            ctx       <= wr_ctx;
            qreq_seen <= 1'b1;
        end else if (qreq) begin
            if (tick && (all_ack || tmo == TMO_MAX)) begin
                qreq   <= 1'b0;
                rst_v  <= 1'b1;
                forced <= !all_ack;
            end else begin
                ack <= ack | ack_valid;
                if (tick)
                    tmo <= tmo + 1'b1;
            end
        end else if (rst_v && rst_ready) begin
            rst_v     <= 1'b0;
            forced    <= 1'b0;
            qreq_seen <= 1'b0;
        end
    end

    // Precedence: a warm reset command is only presented after a quiesce request was accepted
    always @(posedge clk)
        if (rst_v)
            assert (qreq_seen);
endmodule

module fft_twiddle_rom #(
    parameter ENTRIES = 16,
    parameter AW = 4,
    parameter W = 16,
    parameter CW = 6
) (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [W-1:0] re_q,
    output reg [W-1:0] im_q,
    output reg [AW-1:0] idx_q
);
    // butterfly sequencing counter: position and stage fields
    reg [CW-1:0] cnt;
    wire [1:0]    stage = cnt[5:4];
    wire [AW-1:0] pos   = cnt[AW-1:0];
    wire [AW-1:0] k     = pos << stage;

    // ROM contents: cos(pi*k/16) and -sin(pi*k/16) in Q15
    wire [W-1:0] cos_k =
        (k == 4'd0)  ? 16'h7FFF :
        (k == 4'd1)  ? 16'h7D89 :
        (k == 4'd2)  ? 16'h7641 :
        (k == 4'd3)  ? 16'h6A6D :
        (k == 4'd4)  ? 16'h5A82 :
        (k == 4'd5)  ? 16'h471D :
        (k == 4'd6)  ? 16'h30FC :
        (k == 4'd7)  ? 16'h18F9 :
        (k == 4'd8)  ? 16'h0000 :
        (k == 4'd9)  ? 16'hE707 :
        (k == 4'd10) ? 16'hCF04 :
        (k == 4'd11) ? 16'hB8E3 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'h9593 :
        (k == 4'd14) ? 16'h89BF :
                       16'h8277;
    wire [W-1:0] msin_k =
        (k == 4'd0)  ? 16'h0000 :
        (k == 4'd1)  ? 16'hE707 :
        (k == 4'd2)  ? 16'hCF04 :
        (k == 4'd3)  ? 16'hB8E3 :
        (k == 4'd4)  ? 16'hA57E :
        (k == 4'd5)  ? 16'h9593 :
        (k == 4'd6)  ? 16'h89BF :
        (k == 4'd7)  ? 16'h8277 :
        (k == 4'd8)  ? 16'h8001 :
        (k == 4'd9)  ? 16'h8277 :
        (k == 4'd10) ? 16'h89BF :
        (k == 4'd11) ? 16'h9593 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'hB8E3 :
        (k == 4'd14) ? 16'hCF04 :
                       16'hE707;

    // registered ROM read stage
    reg [W-1:0]  re_d;
    reg [W-1:0]  im_d;
    reg [AW-1:0] idx_d;

    initial cnt = {CW{1'b0}};
    initial re_d = 16'h7FFF;
    initial im_d = 16'h0000;
    initial idx_d = {AW{1'b0}};
    initial re_q = 16'h7FFF;
    initial im_q = 16'h0000;
    initial idx_q = {AW{1'b0}};

    always @(posedge clk) begin
        if (rst) begin
            cnt   <= {CW{1'b0}};
            re_d  <= 16'h7FFF;
            im_d  <= 16'h0000;
            idx_d <= {AW{1'b0}};
            re_q  <= 16'h7FFF;
            im_q  <= 16'h0000;
            idx_q <= {AW{1'b0}};
        end else if (ce) begin
            cnt   <= cnt + 1'b1;
            idx_d <= k;
            re_d  <= cos_k;
            im_d  <= msin_k;
            idx_q <= idx_d;
            re_q  <= re_d;
            im_q  <= im_d;
        end
    end

    // unity twiddle W^0 = 1
    always @(*) assert (idx_q != 4'd0 || (re_q == 16'h7FFF && im_q == 16'h0000));
    // quarter twiddle W^8 = -j
    always @(*) assert (idx_q != 4'd8 || (re_q == 16'h0000 && im_q == 16'h8001));
endmodule

module ola_convolver #(
    parameter DW    = 128,
    parameter BLOCK = 24,
    parameter TAPS  = 4
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          in_valid,
    input  wire [DW-1:0] in_data,
    output reg  [DW-1:0] y_out,
    output reg           y_valid,
    output reg  [7:0]    blk_cnt,
    output wire          busy
);
    localparam TOTAL = BLOCK + TAPS - 1;
    localparam IW = $clog2(TOTAL);
    localparam CW = $clog2(TOTAL + 1);
    localparam FW = $clog2(BLOCK);
    localparam [CW-1:0] TOTAL_C = TOTAL;
    localparam [IW-1:0] LAST_C  = TOTAL - 1;
    localparam [FW-1:0] BLAST_C = BLOCK - 1;

    typedef enum logic [0:0] {FILL, CONV} state_t;
    state_t state;
    initial state = FILL;

    reg [DW-1:0] xbuf [0:BLOCK-1];
    reg [DW-1:0] tail [0:TAPS-2];
    reg [FW-1:0] fill_idx = 0;
    reg [IW-1:0] out_idx  = 0;
    reg [CW-1:0] cd       = 0;
    reg          win      = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < BLOCK; i = i + 1) xbuf[i] = {DW{1'b0}};
        for (i = 0; i < TAPS-1; i = i + 1) tail[i] = {DW{1'b0}};
        y_out   = {DW{1'b0}};
        y_valid = 1'b0;
        blk_cnt = 8'd0;
    end

    assign busy = (state == CONV);

    // one output sample of the block convolution, plus overlap tail
    reg [DW-1:0] acc;
    integer k, j;
    always @(*) begin
        acc = {DW{1'b0}};
        for (k = 0; k < TAPS; k = k + 1) begin
            j = out_idx - k;
            if (j >= 0 && j < BLOCK) begin
                if (k == 1 || k == 2)
                    acc = acc + (xbuf[j] << 1);
                else
                    acc = acc + xbuf[j];
            end
        end
        if (out_idx < TAPS-1)
            acc = acc + tail[out_idx];
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= FILL;
            fill_idx <= 0;
            out_idx  <= 0;
            cd       <= 0;
            win      <= 1'b0;
            y_valid  <= 1'b0;
            blk_cnt  <= 8'd0;
        end else if (ce) begin
            case (state)
                FILL: begin
                    y_valid <= 1'b0;
                    if (in_valid) begin
                        xbuf[fill_idx] <= in_data;
                        if (fill_idx == BLAST_C) begin
                            fill_idx <= 0;
                            state    <= CONV;
                            win      <= 1'b1;
                            cd       <= TOTAL_C;
                            out_idx  <= 0;
                        end else begin
                            fill_idx <= fill_idx + 1'b1;
                        end
                    end
                end
                CONV: begin
                    if (out_idx < BLOCK) begin
                        y_out   <= acc;
                        y_valid <= 1'b1;
                    end else begin
                        tail[out_idx - BLOCK] <= acc;
                        y_valid <= 1'b0;
                    end
                    if (out_idx == LAST_C) begin
                        state   <= FILL;
                        win     <= 1'b0;
                        cd      <= 0;
                        out_idx <= 0;
                        blk_cnt <= blk_cnt + 8'd1;
                    end else begin
                        cd      <= cd - 1'b1;
                        out_idx <= out_idx + 1'b1;
                    end
                end
                default: state <= FILL;
            endcase
        end
    end

    // bounded response: while a accepted block is outstanding, its countdown never expires
    always @(posedge clk)
        assert (!win || cd != {CW{1'b0}});
endmodule

module sha256_msg_sched #(
    parameter WIDTH = 32,
    parameter NWIN  = 16,
    parameter NEXP  = 48
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire             out_last
);
    typedef enum logic [1:0] {IDLE = 2'd0, LOAD = 2'd1, EXPAND = 2'd2} state_t;

    state_t state;
    initial state = IDLE;
    reg [31:0] cnt;
    initial cnt = 32'd0;
    reg armed;
    initial armed = 1'b1;
    reg [NWIN*WIDTH-1:0] win;
    initial win = {(NWIN*WIDTH){1'b0}};

    function [31:0] ssig0(input [31:0] x);
        ssig0 = {x[6:0], x[31:7]} ^ {x[17:0], x[31:18]} ^ (x >> 3);
    endfunction
    function [31:0] ssig1(input [31:0] x);
        ssig1 = {x[16:0], x[31:17]} ^ {x[18:0], x[31:19]} ^ (x >> 10);
    endfunction

    wire [WIDTH-1:0] w0  = win[0*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w1  = win[1*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w9  = win[9*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w14 = win[14*WIDTH +: WIDTH];

    assign out_data  = ssig1(w14) + w9 + ssig0(w1) + w0;
    assign in_ready  = (state == IDLE) || (state == LOAD);
    assign out_valid = (state == EXPAND);
    assign out_last  = out_valid && (cnt == NEXP - 1);

    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            cnt   <= 32'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (in_fire) begin
                        win   <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        cnt   <= 32'd1;
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    if (in_fire) begin
                        win <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NWIN - 1) begin
                            cnt   <= 32'd0;
                            state <= EXPAND;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                EXPAND: begin
                    if (out_fire) begin
                        win <= {out_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NEXP - 1) begin
                            cnt   <= 32'd0;
                            state <= IDLE;
                            armed <= 1'b0;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                default: begin
                    state <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assert property (!armed || cnt <= NEXP);
endmodule

module pam4_gray_mapper #(
    parameter W = 64
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         load,
    input  wire         precode,
    input  wire [W-1:0] data,
    output reg  [1:0]   sym_out,
    output reg          sym_valid
);
    localparam [63:0] NSYM = W / 2;

    reg [W-1:0] stage;
    reg [63:0]  sym_left;
    reg [63:0]  deadline;
    reg [1:0]   prev_sym;
    reg         armed;

    initial begin
        stage     = {W{1'b0}};
        sym_left  = 64'd0;
        deadline  = 64'd0;
        prev_sym  = 2'd0;
        sym_out   = 2'd0;
        sym_valid = 1'b0;
        armed     = 1'b0;
    end

    wire [1:0] pair  = stage[1:0];
    wire [1:0] gray  = {pair[1], pair[1] ^ pair[0]};
    wire [1:0] sum4  = gray + prev_sym;
    wire [1:0] coded = precode ? sum4 : gray;

    always @(posedge clk) begin
        if (rst) begin
            stage     <= {W{1'b0}};
            sym_left  <= 64'd0;
            deadline  <= 64'd0;
            prev_sym  <= 2'd0;
            sym_out   <= 2'd0;
            sym_valid <= 1'b0;
        end else if (ce) begin
            sym_valid <= 1'b0;
            if (sym_left == 64'd0) begin
                if (load) begin
                    stage    <= data;
                    sym_left <= NSYM;
                    deadline <= NSYM;
                    armed    <= 1'b1;
                end
            end else begin
                sym_out   <= coded;
                sym_valid <= 1'b1;
                prev_sym  <= coded;
                stage     <= stage >> 2;
                sym_left  <= sym_left - 64'd1;
                deadline  <= deadline - 64'd1;
            end
        end
    end

    always @(posedge clk)
        if (armed && sym_left != 64'd0)
            assert (deadline != 64'd0);

    always @(posedge clk)
        if (armed && sym_left == 64'd0)
            assert (deadline == 64'd0);
endmodule

module ecc_scrubber #(
    parameter ENTRIES  = 64,
    parameter AW       = 6,
    parameter DW       = 64,
    parameter CW       = 7,
    parameter [63:0] INTERVAL = 64'd16,
    parameter [63:0] BUDGET   = 64'd5
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          fill_en,
    input  wire [AW-1:0] fill_addr,
    input  wire [DW-1:0] fill_data,
    input  wire [CW-1:0] fill_chk,
    output reg  [63:0]   corr_count,
    output reg  [63:0]   uncorr_count,
    output reg  [AW-1:0] scrub_addr
);
    typedef enum logic [2:0] {IDLE = 3'd0, READ = 3'd1, CHECK = 3'd2, WRITE = 3'd3, LOG = 3'd4} state_t;

    state_t state = IDLE;
    reg [63:0]   deadline   = 64'd0;
    reg [63:0]   timer      = INTERVAL;
    reg [DW-1:0] line_data  = {DW{1'b0}};
    reg [CW-1:0] line_chk   = {CW{1'b0}};

    reg [DW-1:0] mem_data [0:ENTRIES-1];
    reg [CW-1:0] mem_chk  [0:ENTRIES-1];

    integer k;
    initial begin
        corr_count   = 64'd0;
        uncorr_count = 64'd0;
        scrub_addr   = {AW{1'b0}};
        for (k = 0; k < ENTRIES; k = k + 1) begin
            mem_data[k] = {DW{1'b0}};
            mem_chk[k]  = {CW{1'b0}};
        end
    end

    function [CW-1:0] hcode;
        input [DW-1:0] d;
        integer i;
        begin
            hcode = {CW{1'b0}};
            for (i = 0; i < DW; i = i + 1)
                if (d[i]) hcode = hcode ^ (i + 1);
        end
    endfunction

    wire [CW-1:0] syndrome = line_chk ^ hcode(line_data);

    always @(posedge clk) begin
        if (!rst && ce) begin
            if (state == WRITE) begin
                mem_data[scrub_addr] <= line_data;
                mem_chk[scrub_addr]  <= hcode(line_data);
            end else if (fill_en) begin
                mem_data[fill_addr] <= fill_data;
                mem_chk[fill_addr]  <= fill_chk;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            state        <= IDLE;
            deadline     <= 64'd0;
            timer        <= INTERVAL;
            scrub_addr   <= {AW{1'b0}};
            corr_count   <= 64'd0;
            uncorr_count <= 64'd0;
            line_data    <= {DW{1'b0}};
            line_chk     <= {CW{1'b0}};
        end else if (ce) begin
            case (state)
                IDLE: begin
                    if (timer == 64'd0) begin
                        state    <= READ;
                        deadline <= BUDGET;
                        timer    <= INTERVAL;
                    end else begin
                        timer <= timer - 64'd1;
                    end
                end
                READ: begin
                    line_data <= mem_data[scrub_addr];
                    line_chk  <= mem_chk[scrub_addr];
                    deadline  <= deadline - 64'd1;
                    state     <= CHECK;
                end
                CHECK: begin
                    deadline <= deadline - 64'd1;
                    if (syndrome == {CW{1'b0}}) begin
                        state <= LOG;
                    end else if (syndrome <= DW) begin
                        line_data <= line_data ^ ({{(DW-1){1'b0}}, 1'b1} << (syndrome - 7'd1));
                        state     <= WRITE;
                    end else begin
                        uncorr_count <= uncorr_count + 64'd1;
                        state        <= LOG;
                    end
                end
                WRITE: begin
                    deadline   <= deadline - 64'd1;
                    corr_count <= corr_count + 64'd1;
                    state      <= LOG;
                end
                LOG: begin
                    deadline   <= 64'd0;
                    scrub_addr <= scrub_addr + 1'b1;
                    state      <= IDLE;
                end
                default: begin
                    deadline <= 64'd0;
                    state    <= IDLE;
                end
            endcase
        end
    end

    wire expired = (deadline == 64'd0);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(expired))
            assert (state == IDLE);
endmodule

module pkt_boundary_mux #(
    parameter NSRC = 4,
    parameter DW   = 64,
    parameter CW   = 64
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               step,
    input  wire [NSRC-1:0]    valid,
    input  wire [NSRC-1:0]    eop,
    input  wire [NSRC*DW-1:0] in_data,
    output wire               out_valid,
    output wire               out_eop,
    output wire [DW-1:0]      out_data,
    output wire [$clog2(NSRC)-1:0] out_src
);
    localparam SW = $clog2(NSRC);

    reg [SW-1:0] cur_src;
    reg          locked;
    reg          win;
    reg          started;
    reg [CW-1:0] arm_cnt;
    reg [CW-1:0] start_cnt;
    reg [CW-1:0] fin_cnt;
    reg [CW-1:0] tot_beats;

    initial begin
        cur_src   = {SW{1'b0}};
        locked    = 1'b0;
        win       = 1'b0;
        started   = 1'b0;
        arm_cnt   = {CW{1'b0}};
        start_cnt = {CW{1'b0}};
        fin_cnt   = {CW{1'b0}};
        tot_beats = {CW{1'b0}};
    end

    reg [SW-1:0] pick;
    reg          any_valid;
    integer i;
    always @(*) begin
        any_valid = 1'b0;
        pick = {SW{1'b0}};
        for (i = NSRC-1; i >= 0; i = i - 1)
            if (valid[i]) begin
                any_valid = 1'b1;
                pick = i;
            end
    end

    wire sel_valid = valid[cur_src];
    wire sel_eop   = eop[cur_src];
    wire beat      = locked && sel_valid;

    assign out_valid = step && beat;
    assign out_eop   = step && beat && sel_eop;
    assign out_data  = in_data[cur_src*DW +: DW];
    assign out_src   = cur_src;

    always @(posedge clk) begin
        if (rst) begin
            cur_src   <= {SW{1'b0}};
            locked    <= 1'b0;
            win       <= 1'b0;
            started   <= 1'b0;
            arm_cnt   <= {CW{1'b0}};
            start_cnt <= {CW{1'b0}};
            fin_cnt   <= {CW{1'b0}};
            tot_beats <= {CW{1'b0}};
        end else if (step) begin
            if (!locked) begin
                if (any_valid) begin
                    cur_src <= pick;
                    locked  <= 1'b1;
                    win     <= 1'b1;
                    arm_cnt <= arm_cnt + 1'b1;
                end
            end else if (sel_valid) begin
                tot_beats <= tot_beats + 1'b1;
                if (!started)
                    start_cnt <= start_cnt + 1'b1;
                if (sel_eop) begin
                    fin_cnt <= fin_cnt + 1'b1;
                    locked  <= 1'b0;
                    win     <= 1'b0;
                    started <= 1'b0;
                end else begin
                    started <= 1'b1;
                end
            end
        end
    end

    always @(*)
        assert (!win || (((arm_cnt - start_cnt) <= 64'd1) && ((start_cnt - fin_cnt) <= 64'd1)));
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
endmodule

module spi_sclk_tff #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         step,
    input  wire         miso,
    output wire         spi_clk_o,
    output wire [W-1:0] o_edges,
    output wire [W-1:0] o_rx
);
    localparam [W-1:0] MAXC = {W{1'b1}};

    // T flip-flop generating the SPI serial clock (mode 0)
    reg         sclk      = 1'b0;
    // number of rising SPI clock edges (saturating)
    reg [W-1:0] edges     = {W{1'b0}};
    // shadow register: a falling SPI clock edge has happened earlier
    reg         fell_seen = 1'b0;
    // MISO capture shift register, sampled on rising edges
    reg [W-1:0] rx        = {W{1'b0}};

    wire t    = step;
    wire rise = t && !sclk;
    wire fall = t &&  sclk;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk      <= 1'b0;
            edges     <= {W{1'b0}};
            fell_seen <= 1'b0;
            rx        <= {W{1'b0}};
        end else begin
            if (t)
                sclk <= ~sclk;
            if (rise && edges != MAXC)
                edges <= edges + 1'b1;
            if (rise)
                rx <= {rx[W-2:0], miso};
            if (fall)
                fell_seen <= 1'b1;
        end
    end

    assign spi_clk_o = sclk;
    assign o_edges   = edges;
    assign o_rx      = rx;

    // Precedence: a second rising SPI clock edge requires an earlier falling edge
    always @(*) assert ((edges <= 8'd1) || fell_seen);
endmodule

module branch_resolve_unit #(
    parameter XLEN = 64,
    parameter INST_BYTES = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    // resolved branch packet from execute (valid/ready)
    input  wire            br_valid,
    output wire            br_ready,
    input  wire [XLEN-1:0] br_pc,
    input  wire            br_pred_taken,
    input  wire [XLEN-1:0] br_pred_target,
    input  wire            br_taken,
    input  wire [XLEN-1:0] br_target,
    // redirect / flush request to fetch (valid/ready)
    output reg             redir_valid,
    input  wire            redir_ready,
    output reg  [XLEN-1:0] redir_addr,
    output wire            flush,
    // monitor window control
    input  wire            mon_open,
    input  wire            mon_close
);
    localparam [XLEN-1:0] ONE  = 1;
    localparam [XLEN-1:0] STEP = INST_BYTES;

    reg [XLEN-1:0] pred_target_q = 0;
    reg            pred_taken_q  = 1'b0;
    reg            act_taken_q   = 1'b0;
    reg [XLEN-1:0] mispred_cnt   = 0;
    reg [XLEN-1:0] correct_cnt   = 0;
    reg [XLEN-1:0] redir_cnt     = 0;
    reg            win           = 1'b0;
    reg            pv            = 1'b0;
    initial begin redir_valid = 1'b0; redir_addr = 0; end

    assign br_ready = !redir_valid;
    wire accept   = br_valid && br_ready;
    wire send     = redir_valid && redir_ready;
    assign flush  = send;

    wire mispredict = (br_pred_taken != br_taken) ||
                      (br_taken && (br_pred_target != br_target));
    wire [XLEN-1:0] fix_addr = br_taken ? br_target : (br_pc + STEP);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pred_target_q <= 0;
            pred_taken_q  <= 1'b0;
            act_taken_q   <= 1'b0;
            mispred_cnt   <= 0;
            correct_cnt   <= 0;
            redir_cnt     <= 0;
            redir_valid   <= 1'b0;
            redir_addr    <= 0;
        end else begin
            if (accept) begin
                pred_target_q <= br_pred_target;
                pred_taken_q  <= br_pred_taken;
                act_taken_q   <= br_taken;
                if (mispredict) begin
                    mispred_cnt <= mispred_cnt + ONE;
                    redir_valid <= 1'b1;
                    redir_addr  <= fix_addr;
                end else begin
                    correct_cnt <= correct_cnt + ONE;
                end
            end else if (send) begin
                redir_valid <= 1'b0;
                redir_cnt   <= redir_cnt + ONE;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            win <= 1'b0;
        end else begin
            if (mon_open)       win <= 1'b1;
            else if (mon_close) win <= 1'b0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win && $rose(redir_valid))
            assert (mispred_cnt == redir_cnt + ONE);
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
endmodule

module uart_break_det #(
    parameter FRAME_BITS = 10,
    parameter BREAK_LEN  = FRAME_BITS + 1
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        tick,
    input  wire        rx,
    input  wire        clr_status,
    output reg  [31:0] low_cnt,
    output reg         in_break,
    output reg         break_rcvd
);
    localparam [31:0] BRK = BREAK_LEN;

    initial low_cnt    = 32'd0;
    initial in_break   = 1'b0;
    initial break_rcvd = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            low_cnt    <= 32'd0;
            in_break   <= 1'b0;
            break_rcvd <= 1'b0;
        end else begin
            if (clr_status)
                break_rcvd <= 1'b0;
            if (tick) begin
                if (rx) begin
                    low_cnt  <= 32'd0;
                    in_break <= 1'b0;
                end else if (!in_break) begin
                    low_cnt <= low_cnt + 32'd1;
                    if (low_cnt == BRK - 32'd1) begin
                        in_break   <= 1'b1;
                        break_rcvd <= 1'b1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (low_cnt <= BRK);
endmodule

module dds_tmr_minority #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire [W-1:0] i_tw,
    input  wire         i_sweep_start,
    input  wire         i_sweep_stop,
    output wire         o_sq,
    output wire         o_min
);
    // Triple-redundant phase accumulators of a DDS core
    reg [W-1:0] acc_a;
    reg [W-1:0] acc_b;
    reg [W-1:0] acc_c;
    reg         sweep_win;
    initial acc_a = {W{1'b0}};
    initial acc_b = {W{1'b0}};
    initial acc_c = {W{1'b0}};
    initial sweep_win = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            acc_a     <= {W{1'b0}};
            acc_b     <= {W{1'b0}};
            acc_c     <= {W{1'b0}};
            sweep_win <= 1'b0;
        end else if (i_ce) begin
            acc_a <= acc_a + i_tw;
            acc_b <= acc_b + i_tw;
            acc_c <= acc_c + i_tw;
            if (i_sweep_start)
                sweep_win <= 1'b1;
            else if (i_sweep_stop)
                sweep_win <= 1'b0;
        end
    end

    // Square-wave output taken from replica A's MSB
    assign o_sq = acc_a[W-1];

    // Minority gate over the three replica MSBs: complement of the majority
    wire ma = acc_a[W-1];
    wire mb = acc_b[W-1];
    wire mc = acc_c[W-1];
    assign o_min = ~((ma & mb) | (mb & mc) | (ma & mc));

    // Absence, after sweep start until sweep stop:
    // square output and minority output are never high together
    assert property (!sweep_win || !(o_sq && o_min));
endmodule

module claim_gateway #(
    parameter NSRC = 24,
    parameter IDW  = 16
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire [NSRC-1:0] irq,
    input  wire            claim,
    input  wire            complete,
    input  wire [IDW-1:0]  complete_id,
    output wire [IDW-1:0]  claim_rdata,
    output reg  [IDW-1:0]  last_id,
    output reg  [15:0]     inflight_cnt
);
    reg [NSRC-1:0] pending;
    reg [NSRC-1:0] inflight;
    reg            armed;
    reg            pv;

    initial begin
        pending      = {NSRC{1'b0}};
        inflight     = {NSRC{1'b0}};
        last_id      = {IDW{1'b0}};
        inflight_cnt = 16'd0;
        armed        = 1'b0;
        pv           = 1'b0;
    end

    wire [NSRC-1:0] elig = pending & ~inflight;

    reg [IDW-1:0]  sel_id;
    reg [NSRC-1:0] sel_oh;
    reg [NSRC-1:0] comp_oh;
    integer i;
    always @(*) begin
        sel_id  = {IDW{1'b0}};
        sel_oh  = {NSRC{1'b0}};
        comp_oh = {NSRC{1'b0}};
        for (i = 0; i < NSRC; i = i + 1) begin
            if (elig[i]) begin
                sel_id    = i + 1;
                sel_oh    = {NSRC{1'b0}};
                sel_oh[i] = 1'b1;
            end
            if (complete_id == i + 1)
                comp_oh[i] = 1'b1;
        end
    end

    wire claim_ok = claim && (sel_id != {IDW{1'b0}});
    wire comp_hit = complete && !claim && (|(comp_oh & inflight));
    wire do_dec   = comp_hit && (inflight_cnt != 16'd0);

    assign claim_rdata = claim_ok ? sel_id : {IDW{1'b0}};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending      <= {NSRC{1'b0}};
            inflight     <= {NSRC{1'b0}};
            last_id      <= {IDW{1'b0}};
            inflight_cnt <= 16'd0;
            armed        <= 1'b0;
        end else begin
            pending  <= (pending | (irq & ~inflight)) & ~(claim_ok ? sel_oh : {NSRC{1'b0}});
            inflight <= (inflight | (claim_ok ? sel_oh : {NSRC{1'b0}}))
                        & ~(comp_hit ? comp_oh : {NSRC{1'b0}});
            if (claim_ok)
                last_id <= sel_id;
            if (claim_ok)
                inflight_cnt <= inflight_cnt + 16'd1;
            else if (do_dec)
                inflight_cnt <= inflight_cnt - 16'd1;
            if (claim_ok)
                armed <= 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed)
            assert (!$stable(inflight_cnt) || $stable(inflight));
endmodule

module bcd_div_resp #(
    parameter DIGITS = 8,
    parameter PHASES = 5
) (
    input  wire        clk,
    input  wire        ce,
    input  wire        flush,
    input  wire        in_valid,
    output wire        in_ready,
    input  wire [31:0] in_dividend,
    input  wire [31:0] in_divisor,
    output wire        out_valid,
    input  wire        out_ready,
    output wire [31:0] out_quotient,
    output wire [31:0] out_remainder
);
    localparam [31:0] LAT     = DIGITS * PHASES;
    localparam [31:0] LASTPOS = DIGITS - 1;
    localparam [2:0]  LASTPH  = PHASES - 1;

    function [35:0] bcd_add36;
        input [35:0] a;
        input [35:0] b;
        integer i;
        reg [4:0] s;
        reg c;
        begin
            c = 1'b0;
            bcd_add36 = 36'd0;
            for (i = 0; i < 9; i = i + 1) begin
                s = {1'b0, a[i*4 +: 4]} + {1'b0, b[i*4 +: 4]} + {4'd0, c};
                if (s > 5'd9) begin s = s + 5'd6; c = 1'b1; end
                else c = 1'b0;
                bcd_add36[i*4 +: 4] = s[3:0];
            end
        end
    endfunction

    function [35:0] bcd_sub36;
        input [35:0] a;
        input [35:0] b;
        integer i;
        reg [4:0] s;
        reg br;
        begin
            br = 1'b0;
            bcd_sub36 = 36'd0;
            for (i = 0; i < 9; i = i + 1) begin
                s = {1'b0, a[i*4 +: 4]} - {1'b0, b[i*4 +: 4]} - {4'd0, br};
                if (s[4]) begin s = s + 5'd10; br = 1'b1; end
                else br = 1'b0;
                bcd_sub36[i*4 +: 4] = s[3:0];
            end
        end
    endfunction

    reg        busy;
    reg        ovalid;
    reg        before_flush;
    reg [31:0] cd;
    reg [31:0] pos;
    reg [2:0]  phase;
    reg [31:0] dvd;
    reg [31:0] quo;
    reg [35:0] rem;
    reg [35:0] mult1x;
    reg [35:0] mult2x;
    reg [35:0] mult4x;
    reg [3:0]  qdig;

    initial begin
        busy = 1'b0; ovalid = 1'b0; before_flush = 1'b1;
        cd = 32'd0; pos = 32'd0; phase = 3'd0;
        dvd = 32'd0; quo = 32'd0; rem = 36'd0;
        mult1x = 36'd0; mult2x = 36'd0; mult4x = 36'd0;
        qdig = 4'd0;
    end

    wire [35:0] d1 = {4'd0, in_divisor};
    wire [35:0] d2 = bcd_add36(d1, d1);
    wire [35:0] d4 = bcd_add36(d2, d2);

    wire [35:0] msel = (phase == 3'd3) ? mult2x : (phase == 3'd4) ? mult1x : mult4x;
    wire [3:0]  minc = (phase == 3'd3) ? 4'd2 : (phase == 3'd4) ? 4'd1 : 4'd4;
    wire        take = (rem >= msel);
    wire [35:0] rem_sub = bcd_sub36(rem, msel);
    wire [3:0]  qnext = qdig + (take ? minc : 4'd0);

    assign in_ready = ce && !busy && !ovalid;
    wire accept = in_valid && in_ready;

    assign out_valid     = ovalid;
    assign out_quotient  = quo;
    assign out_remainder = rem[31:0];

    always @(posedge clk) begin
        if (flush) begin
            busy <= 1'b0;
            ovalid <= 1'b0;
            cd <= 32'd0;
            pos <= 32'd0;
            phase <= 3'd0;
            before_flush <= 1'b0;
        end else begin
            if (ovalid && out_ready)
                ovalid <= 1'b0;
            if (accept) begin
                busy <= 1'b1;
                cd <= LAT;
                pos <= 32'd0;
                phase <= 3'd0;
                dvd <= in_dividend;
                mult1x <= d1;
                mult2x <= d2;
                mult4x <= d4;
                rem <= 36'd0;
                qdig <= 4'd0;
                quo <= 32'd0;
            end else if (ce && busy) begin
                cd <= cd - 32'd1;
                if (phase == 3'd0) begin
                    rem <= {rem[31:0], dvd[31:28]};
                    dvd <= {dvd[27:0], 4'd0};
                    qdig <= 4'd0;
                    phase <= 3'd1;
                end else begin
                    if (take)
                        rem <= rem_sub;
                    qdig <= qnext;
                    if (phase == LASTPH) begin
                        quo <= {quo[27:0], qnext};
                        phase <= 3'd0;
                        if (pos == LASTPOS) begin
                            busy <= 1'b0;
                            ovalid <= 1'b1;
                            pos <= 32'd0;
                        end else begin
                            pos <= pos + 32'd1;
                        end
                    end else begin
                        phase <= phase + 3'd1;
                    end
                end
            end
        end
    end

    always @(*)
        if (before_flush && busy)
            assert (cd != 32'd0);
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
    output wire [1:0]   o_rem
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0]   phase   = S_IDLE;
    reg [1:0]   rem     = 2'd0;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;

    assign in_ready = (phase == S_ARM) || (phase == S_RUN);
    wire acc = in_valid && in_ready;

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (acc) begin
            rem     <= rnext(rem, in_bit);
            val     <= {val[W-2:0], in_bit};
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
endmodule

module first_ready_latch #(
    parameter NCH  = 4,
    parameter IDXW = 2,
    parameter CW   = 64
) (
    input  wire            clk,
    input  wire            rst,
    input  wire            ce,
    input  wire            arm,
    input  wire            clr,
    input  wire [NCH-1:0]  ch_rdy,
    output reg  [IDXW-1:0] winner,
    output reg             captured,
    output reg             armed,
    output reg  [CW-1:0]   cap_cnt
);
    initial begin
        winner   = {IDXW{1'b0}};
        captured = 1'b0;
        armed    = 1'b0;
        cap_cnt  = {CW{1'b0}};
    end

    reg [IDXW-1:0] first_idx;
    integer i;
    always @(*) begin
        first_idx = {IDXW{1'b0}};
        for (i = NCH-1; i >= 0; i = i - 1)
            if (ch_rdy[i]) first_idx = i[IDXW-1:0];
    end

    wire any_rdy = |ch_rdy;

    always @(posedge clk) begin
        if (rst) begin
            winner   <= {IDXW{1'b0}};
            captured <= 1'b0;
            armed    <= 1'b0;
            cap_cnt  <= {CW{1'b0}};
        end else if (ce) begin
            if (clr) begin
                armed    <= 1'b0;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (arm) begin
                armed    <= 1'b1;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (armed && !captured && any_rdy) begin
                captured <= 1'b1;
                winner   <= first_idx;
                cap_cnt  <= cap_cnt + {{(CW-1){1'b0}}, 1'b1};
            end
        end
    end

    always @(*) assert (!armed || cap_cnt <= 64'd1);
endmodule

module noc_freq_meter #(
    parameter GATE = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        in_valid,
    output wire        in_ready,
    input  wire        in_edge,
    output reg         out_valid,
    input  wire        out_ready,
    output reg  [31:0] result
);
    reg [31:0] gate_cnt;
    reg [31:0] ev_cnt;
    reg [31:0] gate_snap;
    reg        armed;

    initial begin
        gate_cnt  = 32'd0;
        ev_cnt    = 32'd0;
        gate_snap = 32'd0;
        result    = 32'd0;
        out_valid = 1'b0;
        armed     = 1'b0;
    end

    assign in_ready = !out_valid;
    wire in_fire    = in_valid && in_ready;
    wire out_fire   = out_valid && out_ready;
    wire gate_close = in_fire && (gate_cnt == GATE - 1);

    always @(posedge clk) begin
        if (rst) begin
            gate_cnt  <= 32'd0;
            ev_cnt    <= 32'd0;
            gate_snap <= 32'd0;
            result    <= 32'd0;
            out_valid <= 1'b0;
            armed     <= 1'b0;
        end else begin
            if (in_fire)
                armed <= 1'b1;
            if (in_fire) begin
                if (gate_close) begin
                    gate_cnt  <= 32'd0;
                    ev_cnt    <= 32'd0;
                    result    <= ev_cnt + {31'd0, in_edge};
                    gate_snap <= gate_cnt + 32'd1;
                    out_valid <= 1'b1;
                end else begin
                    gate_cnt <= gate_cnt + 32'd1;
                    ev_cnt   <= ev_cnt + {31'd0, in_edge};
                end
            end else if (out_fire) begin
                out_valid <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed && out_valid)
            assert (result <= gate_snap);
endmodule

module wc_buffer #(
    parameter WORDS = 4,
    parameter [31:0] TIMEOUT = 32'd8
)(
    input wire clk,
    input wire rst,
    input wire ce,
    input wire st_valid,
    input wire [31:0] st_line,
    input wire [$clog2(WORDS)-1:0] st_word,
    input wire [31:0] st_data,
    input wire [3:0] st_be,
    output reg wr_burst,
    output reg [31:0] wr_line,
    output reg [WORDS*32-1:0] wr_data,
    output reg [WORDS*4-1:0] wr_mask
);
    localparam MW = WORDS*4;
    localparam DW = WORDS*32;

    reg v = 1'b0;
    reg [31:0] line_addr = 32'd0;
    reg [DW-1:0] line_data = {DW{1'b0}};
    reg [MW-1:0] mask = {MW{1'b0}};
    reg [31:0] timer = 32'd0;
    reg [31:0] age = 32'd0;
    reg armed = 1'b0;
    reg pv = 1'b0;

    initial begin
        wr_burst = 1'b0;
        wr_line = 32'd0;
        wr_data = {DW{1'b0}};
        wr_mask = {MW{1'b0}};
    end

    wire hit = v && st_valid && (st_line == line_addr);
    wire miss = st_valid && !hit;

    reg [DW-1:0] in_data;
    reg [DW-1:0] in_bits;
    reg [MW-1:0] in_mask;
    integer b;
    always @(*) begin
        in_data = {DW{1'b0}};
        in_bits = {DW{1'b0}};
        in_mask = {MW{1'b0}};
        for (b = 0; b < 4; b = b + 1) begin
            in_data[st_word*32 + b*8 +: 8] = st_data[b*8 +: 8];
            in_bits[st_word*32 + b*8 +: 8] = {8{st_be[b]}};
            in_mask[st_word*4 + b] = st_be[b];
        end
    end

    wire [DW-1:0] n_data = hit ? ((line_data & ~in_bits) | (in_data & in_bits)) : line_data;
    wire [MW-1:0] n_mask = hit ? (mask | in_mask) : mask;
    wire timeout = (age == TIMEOUT - 32'd1);
    wire full = (n_mask == {MW{1'b1}});
    wire flush = v && (miss || timeout || full);
    wire expired = (timer == 32'd0);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            v <= 1'b0;
            line_addr <= 32'd0;
            line_data <= {DW{1'b0}};
            mask <= {MW{1'b0}};
            timer <= 32'd0;
            age <= 32'd0;
            wr_burst <= 1'b0;
            wr_line <= 32'd0;
            wr_data <= {DW{1'b0}};
            wr_mask <= {MW{1'b0}};
        end else if (ce) begin
            if (st_valid) armed <= 1'b1;
            wr_burst <= flush;
            if (flush) begin
                wr_line <= line_addr;
                wr_data <= n_data;
                wr_mask <= n_mask;
            end
            if (miss) begin
                v <= 1'b1;
                line_addr <= st_line;
                line_data <= in_data & in_bits;
                mask <= in_mask;
                timer <= TIMEOUT;
                age <= 32'd0;
            end else if (flush) begin
                v <= 1'b0;
                line_data <= {DW{1'b0}};
                mask <= {MW{1'b0}};
                timer <= 32'd0;
                age <= 32'd0;
            end else if (v) begin
                line_data <= n_data;
                mask <= n_mask;
                timer <= timer - 32'd1;
                age <= age + 32'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $rose(expired))
            assert (!v);
endmodule

module qp_zins_mux #(
    parameter DEPTH = 16,
    parameter DW = 32,
    parameter SW = $clog2(DEPTH)
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_load,
    input  wire [31:0]   i_limit,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [SW-1:0] in_qp,
    input  wire [DW-1:0] in_data,
    input  wire          i_drain,
    output wire [DW-1:0] o_data,
    output wire          o_valid
);
    reg [DEPTH*DW-1:0] data_flat;
    reg [DEPTH-1:0]    mask;
    reg [SW-1:0]       sel;
    reg [31:0]         cnt;
    reg [31:0]         limit;
    reg                win;

    initial data_flat = {(DEPTH*DW){1'b0}};
    initial mask = {DEPTH{1'b0}};
    initial sel = {SW{1'b0}};
    initial cnt = 32'd0;
    initial limit = DEPTH;
    initial win = 1'b0;

    wire hit = mask[sel];
    assign in_ready = !mask[in_qp] && (cnt < limit);
    wire in_fire = in_valid && in_ready;
    wire drn_hit = i_drain && hit;

    wire [DEPTH-1:0] one_m = {{(DEPTH-1){1'b0}}, 1'b1};
    wire [DEPTH-1:0] set_m = in_fire ? (one_m << in_qp) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_m = drn_hit ? (one_m << sel) : {DEPTH{1'b0}};

    // zero-insertion multiplexer: selected slot if valid, else constant zero
    assign o_valid = hit;
    assign o_data  = hit ? data_flat[sel*DW +: DW] : {DW{1'b0}};

    always @(posedge clk) begin
        if (i_reset) begin
            mask  <= {DEPTH{1'b0}};
            sel   <= {SW{1'b0}};
            cnt   <= 32'd0;
            win   <= 1'b0;
            limit <= i_limit;
        end else begin
            if (i_load)
                limit <= i_limit;
            if (in_fire)
                data_flat[in_qp*DW +: DW] <= in_data;
            mask <= (mask & ~clr_m) | set_m;
            cnt  <= cnt + (in_fire ? 32'd1 : 32'd0) - (drn_hit ? 32'd1 : 32'd0);
            if (i_drain)
                sel <= (sel == DEPTH-1) ? {SW{1'b0}} : sel + 1'b1;
            if (i_load)
                win <= 1'b0;
            else if (in_fire)
                win <= 1'b1;
        end
    end

    always @(posedge clk)
        if (win) assert (cnt <= DEPTH);

    always @(posedge clk)
        if (win) assert (cnt != 32'd0 || o_data == {DW{1'b0}});
endmodule

module autoneg_arb #(
    parameter [63:0] LINK_TIME  = 64'd12,
    parameter [63:0] LOCAL_ABIL = 64'h0000_0000_0000_01E0
) (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire        i_rx_valid,
    input  wire [63:0] i_rx_page,
    input  wire        i_link_fail,
    output wire        o_link_up,
    output wire [63:0] o_mode
);
    typedef enum logic [2:0] {AN_IDLE, AN_ABILITY, AN_ACK, AN_COMPLETE, AN_LINK_OK} an_state_t;

    an_state_t state;
    reg [63:0] link_tmr;
    reg [63:0] remain;
    reg [63:0] rx_abil;
    reg [63:0] mode;
    reg        win;

    initial state    = AN_IDLE;
    initial link_tmr = 64'd0;
    initial remain   = LINK_TIME;
    initial rx_abil  = 64'd0;
    initial mode     = 64'd0;
    initial win      = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            state    <= AN_IDLE;
            link_tmr <= 64'd0;
            remain   <= LINK_TIME;
            rx_abil  <= 64'd0;
            mode     <= 64'd0;
            win      <= 1'b0;
        end else if (i_ce) begin
            case (state)
                AN_IDLE: begin
                    if (i_start) begin
                        state    <= AN_ABILITY;
                        link_tmr <= 64'd0;
                        remain   <= LINK_TIME;
                        win      <= 1'b1;
                    end
                end
                AN_ABILITY: begin
                    if (i_rx_valid) begin
                        rx_abil  <= i_rx_page;
                        link_tmr <= 64'd0;
                        remain   <= LINK_TIME;
                        state    <= AN_ACK;
                    end else if (remain == 64'd0) begin
                        state <= AN_IDLE;
                    end else begin
                        link_tmr <= link_tmr + 64'd1;
                        remain   <= remain - 64'd1;
                    end
                end
                AN_ACK: begin
                    if (remain == 64'd0) begin
                        mode  <= rx_abil & LOCAL_ABIL;
                        state <= AN_COMPLETE;
                    end else begin
                        link_tmr <= link_tmr + 64'd1;
                        remain   <= remain - 64'd1;
                    end
                end
                AN_COMPLETE: begin
                    state <= AN_LINK_OK;
                    win   <= 1'b0;
                end
                AN_LINK_OK: begin
                    if (i_link_fail)
                        state <= AN_IDLE;
                end
                default: state <= AN_IDLE;
            endcase
        end
    end

    assign o_link_up = (state == AN_LINK_OK);
    assign o_mode    = mode;

    always @(posedge clk)
        if (win)
            assert (link_tmr <= LINK_TIME);
endmodule

module apb_periph_ctrl #(
    parameter NREG = 12,
    parameter [31:0] WAIT = 32'd3,
    parameter [31:0] K = WAIT + 32'd2
)(
    input  wire        clk,
    input  wire        i_ce,
    input  wire        req_valid,
    output wire        req_ready,
    input  wire        req_write,
    input  wire [3:0]  req_addr,
    input  wire [31:0] req_wdata,
    output reg  [31:0] rdata,
    output reg         pslverr_o,
    output wire        psel,
    output reg         penable
);
    typedef enum logic [1:0] {IDLE = 2'd0, SETUP = 2'd1, ACCESS = 2'd2} state_t;

    state_t     state;
    reg [31:0]  timer;
    reg [31:0]  wait_cnt;
    reg [3:0]   sel;
    reg         wr;
    reg [31:0]  wdata;
    reg         err;
    reg         armed;
    reg [31:0]  regs [0:NREG-1];

    integer i;
    initial begin
        state     = IDLE;
        timer     = 32'd0;
        wait_cnt  = 32'd0;
        sel       = 4'd0;
        wr        = 1'b0;
        wdata     = 32'd0;
        err       = 1'b0;
        armed     = 1'b1;
        rdata     = 32'd0;
        pslverr_o = 1'b0;
        penable   = 1'b0;
        for (i = 0; i < NREG; i = i + 1) regs[i] = 32'd0;
    end

    assign req_ready = i_ce && (state == IDLE);
    assign psel      = (state != IDLE);

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                IDLE: begin
                    if (req_valid) begin
                        state <= SETUP;
                        timer <= K;
                        wr    <= req_write;
                        wdata <= req_wdata;
                        if (req_addr < NREG) begin
                            sel <= req_addr;
                            err <= 1'b0;
                        end else begin
                            sel <= 4'd0;
                            err <= 1'b1;
                        end
                    end
                end
                SETUP: begin
                    state    <= ACCESS;
                    penable  <= 1'b1;
                    timer    <= timer - 32'd1;
                    wait_cnt <= WAIT;
                end
                ACCESS: begin
                    if (wait_cnt == 32'd0) begin
                        state     <= IDLE;
                        penable   <= 1'b0;
                        timer     <= 32'd0;
                        pslverr_o <= err;
                        if (err)
                            armed <= 1'b0;
                        else if (wr)
                            regs[sel] <= wdata;
                        else
                            rdata <= regs[sel];
                    end else begin
                        wait_cnt <= wait_cnt - 32'd1;
                        timer    <= timer - 32'd1;
                    end
                end
                default: begin
                    state   <= IDLE;
                    penable <= 1'b0;
                    timer   <= 32'd0;
                end
            endcase
        end
    end

    // Bounded response, before the first slave error:
    // the completion countdown never expires while a transfer is outstanding
    always @(posedge clk)
        if (armed && state != IDLE) assert (timer != 32'd0);

    // during the access phase the countdown always outlasts the remaining wait states
    always @(posedge clk)
        if (armed && penable) assert (timer > wait_cnt);
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, i_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, i_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, i_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    assign i_ready = !o_valid || o_ready;
    wire in_fire  = i_valid && i_ready;
    wire out_fire = o_valid && o_ready;

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= i_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && i_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
endmodule

module ckpt_regfile #(
    parameter NREG = 256,
    parameter NCK  = 4,
    parameter DW   = 32,
    parameter AW   = 8,
    parameter TW   = 2
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          cmd_valid,
    output wire          cmd_ready,
    input  wire [1:0]    cmd_op,
    input  wire [AW-1:0] cmd_addr,
    input  wire [DW-1:0] cmd_data,
    input  wire [TW-1:0] cmd_tag,
    input  wire [AW-1:0] rd_addr,
    output reg  [DW-1:0] rd_data,
    output reg  [TW-1:0] alloc_tag,
    output reg           alloc_found,
    output wire [NCK-1:0] ckpt_mask_o,
    output wire [31:0]   ckpt_count_o
);
    localparam [1:0] OP_WRITE   = 2'd0;
    localparam [1:0] OP_BRANCH  = 2'd1;
    localparam [1:0] OP_RESOLVE = 2'd2;
    localparam [1:0] OP_MISPRED = 2'd3;
    localparam W = NREG * DW;

    reg [W-1:0]     rf       = {W{1'b0}};
    reg [NCK*W-1:0] ck       = {(NCK*W){1'b0}};
    reg [NCK-1:0]   ck_mask  = {NCK{1'b0}};
    reg [31:0]      ck_count = 32'd0;

    assign ckpt_mask_o  = ck_mask;
    assign ckpt_count_o = ck_count;

    assign cmd_ready = !(cmd_op == OP_BRANCH && ck_count >= NCK);
    wire fire    = cmd_valid && cmd_ready;
    wire br_fire = fire && (cmd_op == OP_BRANCH);

    integer i;
    always @(*) begin
        alloc_found = 1'b0;
        alloc_tag   = {TW{1'b0}};
        for (i = 0; i < NCK; i = i + 1)
            if (!alloc_found && !ck_mask[i]) begin
                alloc_found = 1'b1;
                alloc_tag   = i;
            end
    end

    integer j;
    always @(*) begin
        rd_data = {DW{1'b0}};
        for (j = 0; j < NREG; j = j + 1)
            if (rd_addr == j) rd_data = rf[j*DW +: DW];
    end

    integer k;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rf       <= {W{1'b0}};
            ck       <= {(NCK*W){1'b0}};
            ck_mask  <= {NCK{1'b0}};
            ck_count <= 32'd0;
        end else if (fire) begin
            case (cmd_op)
                OP_WRITE: begin
                    for (k = 0; k < NREG; k = k + 1)
                        if (cmd_addr == k) rf[k*DW +: DW] <= cmd_data;
                end
                OP_BRANCH: begin
                    if (alloc_found) begin
                        for (k = 0; k < NCK; k = k + 1)
                            if (alloc_tag == k) ck[k*W +: W] <= rf;
                        ck_mask[alloc_tag] <= 1'b1;
                    end
                    ck_count <= ck_count + 32'd1;
                end
                OP_RESOLVE: begin
                    if (ck_mask[cmd_tag]) begin
                        ck_mask[cmd_tag] <= 1'b0;
                        ck_count <= ck_count - 32'd1;
                    end
                end
                OP_MISPRED: begin
                    if (ck_mask[cmd_tag]) begin
                        for (k = 0; k < NCK; k = k + 1)
                            if (cmd_tag == k) rf <= ck[k*W +: W];
                        ck_mask  <= {NCK{1'b0}};
                        ck_count <= 32'd0;
                    end
                end
            endcase
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $past(br_fire))
            assert (ck_mask != $past(ck_mask));
endmodule

module exp_scale_unit #(
    parameter EW = 8,
    parameter SW = 8,
    parameter MAXSH = 9
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          ce,
    input  wire          arm,
    input  wire          start,
    input  wire [EW-1:0] exp_in,
    input  wire [SW-1:0] sig_in,
    input  wire [7:0]    scale_in,
    output wire [EW-1:0] o_exp,
    output wire [SW-1:0] o_sig,
    output wire          o_ovf,
    output wire          o_uf,
    output wire          o_done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2, FINISHED = 2'd3;
    localparam [EW-1:0] EXP_INF = {EW{1'b1}};
    localparam [3:0] MAXSH4 = MAXSH;

    reg [1:0]    phase    = IDLE;
    reg          busy     = 1'b0;
    reg [3:0]    sh_cnt   = 4'd0;
    reg [EW-1:0] op_exp   = {EW{1'b0}};
    reg [SW-1:0] op_sig   = {SW{1'b0}};
    reg [7:0]    op_scale = 8'd0;
    reg [EW-1:0] work_exp = {EW{1'b0}};
    reg [SW-1:0] work_sig = {SW{1'b0}};
    reg          work_ovf = 1'b0;
    reg          work_uf  = 1'b0;
    reg          sticky   = 1'b0;
    reg [EW-1:0] res_exp  = {EW{1'b0}};
    reg [SW-1:0] res_sig  = {SW{1'b0}};
    reg          res_ovf  = 1'b0;
    reg          res_uf   = 1'b0;
    reg          no_ovf   = 1'b1;
    reg          pv       = 1'b0;

    wire [EW+1:0] sum   = {2'b00, op_exp} + {{2{op_scale[7]}}, op_scale};
    wire [EW+1:0] under = {{(EW+1){1'b0}}, 1'b1} - sum;
    wire          sum_neg = sum[EW+1];
    wire          sum_ovf = !sum_neg && (sum[EW:0] >= {1'b0, EXP_INF});
    wire          sum_unf = sum_neg || (sum == {(EW+2){1'b0}});
    wire [3:0]    sh_amt  = (under > MAXSH) ? MAXSH4 : under[3:0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= IDLE;
            busy     <= 1'b0;
            sh_cnt   <= 4'd0;
            op_exp   <= {EW{1'b0}};
            op_sig   <= {SW{1'b0}};
            op_scale <= 8'd0;
            work_exp <= {EW{1'b0}};
            work_sig <= {SW{1'b0}};
            work_ovf <= 1'b0;
            work_uf  <= 1'b0;
            sticky   <= 1'b0;
            res_exp  <= {EW{1'b0}};
            res_sig  <= {SW{1'b0}};
            res_ovf  <= 1'b0;
            res_uf   <= 1'b0;
            no_ovf   <= 1'b1;
        end else if (ce) begin
            case (phase)
                IDLE: if (arm) begin
                    op_exp   <= exp_in;
                    op_sig   <= sig_in;
                    op_scale <= scale_in;
                    phase    <= ARMED;
                end
                ARMED: if (start) begin
                    busy   <= 1'b1;
                    sticky <= 1'b0;
                    phase  <= STARTED;
                    if (sum_ovf) begin
                        work_exp <= EXP_INF;
                        work_sig <= {SW{1'b0}};
                        work_ovf <= 1'b1;
                        work_uf  <= 1'b0;
                        sh_cnt   <= 4'd0;
                    end else if (sum_unf) begin
                        work_exp <= {EW{1'b0}};
                        work_sig <= op_sig;
                        work_ovf <= 1'b0;
                        work_uf  <= 1'b1;
                        sh_cnt   <= sh_amt;
                    end else begin
                        work_exp <= sum[EW-1:0];
                        work_sig <= op_sig;
                        work_ovf <= 1'b0;
                        work_uf  <= 1'b0;
                        sh_cnt   <= 4'd0;
                    end
                end
                STARTED: if (sh_cnt == 4'd0) phase <= FINISHED;
                FINISHED: phase <= IDLE;
            endcase
            if (busy) begin
                if (sh_cnt != 4'd0) begin
                    work_sig <= work_sig >> 1;
                    sticky   <= sticky | work_sig[0];
                    sh_cnt   <= sh_cnt - 4'd1;
                end else begin
                    res_exp <= work_exp;
                    res_sig <= work_sig;
                    res_ovf <= work_ovf;
                    res_uf  <= work_uf & (sticky | (work_sig == {SW{1'b0}}));
                    busy    <= 1'b0;
                    if (work_ovf) no_ovf <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    assign o_exp  = res_exp;
    assign o_sig  = res_sig;
    assign o_ovf  = res_ovf;
    assign o_uf   = res_uf;
    assign o_done = (phase == FINISHED);

    always @(posedge clk)
        if (pv && no_ovf && $stable(phase))
            assert ($stable(res_exp) && $stable(res_sig));
endmodule

module islip_alloc #(
    parameter N  = 4,
    parameter W  = 2,
    parameter CW = 64
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           step,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   rel,
    output reg  [N-1:0]   in_busy,
    output reg  [N*W-1:0] in_dst,
    output reg  [N-1:0]   out_busy,
    output reg  [N*W-1:0] out_src,
    output reg  [CW-1:0]  match_count,
    output reg            armed
);
    reg [N*W-1:0] g_ptr;
    reg [N*W-1:0] a_ptr;

    initial begin
        in_busy     = {N{1'b0}};
        in_dst      = {(N*W){1'b0}};
        out_busy    = {N{1'b0}};
        out_src     = {(N*W){1'b0}};
        g_ptr       = {(N*W){1'b0}};
        a_ptr       = {(N*W){1'b0}};
        match_count = {CW{1'b0}};
        armed       = 1'b0;
    end

    // grant phase: each free output picks a free requesting input, round robin from g_ptr
    integer gi, go, gk;
    reg [W-1:0]   tmp_g;
    reg [N-1:0]   gnt_v;
    reg [N*W-1:0] gnt_in;
    always @(*) begin
        gnt_v  = {N{1'b0}};
        gnt_in = {(N*W){1'b0}};
        tmp_g  = {W{1'b0}};
        for (go = 0; go < N; go = go + 1)
            for (gk = N-1; gk >= 0; gk = gk - 1) begin
                tmp_g = g_ptr[go*W +: W] + gk;
                for (gi = 0; gi < N; gi = gi + 1)
                    if (tmp_g == gi && !out_busy[go] && !in_busy[gi] && req[gi*N+go]) begin
                        gnt_v[go] = 1'b1;
                        gnt_in[go*W +: W] = gi;
                    end
            end
    end

    // accept phase: each free input accepts one granting output, round robin from a_ptr
    integer ai, ao, ak;
    reg [W-1:0]   tmp_a;
    reg [N-1:0]   acc_v;
    reg [N*W-1:0] acc_out;
    always @(*) begin
        acc_v   = {N{1'b0}};
        acc_out = {(N*W){1'b0}};
        tmp_a   = {W{1'b0}};
        for (ai = 0; ai < N; ai = ai + 1)
            for (ak = N-1; ak >= 0; ak = ak - 1) begin
                tmp_a = a_ptr[ai*W +: W] + ak;
                for (ao = 0; ao < N; ao = ao + 1)
                    if (tmp_a == ao && !in_busy[ai] && gnt_v[ao] && gnt_in[ao*W +: W] == ai) begin
                        acc_v[ai] = 1'b1;
                        acc_out[ai*W +: W] = ao;
                    end
            end
    end

    // next-state: releases tear down, accepted matches connect, pointers advance only on accept
    integer ni, no;
    reg [N-1:0]   in_busy_n;
    reg [N*W-1:0] in_dst_n;
    reg [N-1:0]   out_busy_n;
    reg [N*W-1:0] out_src_n;
    reg [N*W-1:0] g_ptr_n;
    reg [N*W-1:0] a_ptr_n;
    reg [W:0]     n_acc;
    always @(*) begin
        in_busy_n  = in_busy;
        in_dst_n   = in_dst;
        out_busy_n = out_busy;
        out_src_n  = out_src;
        g_ptr_n    = g_ptr;
        a_ptr_n    = a_ptr;
        n_acc      = {(W+1){1'b0}};
        for (ni = 0; ni < N; ni = ni + 1) begin
            if (rel[ni] && in_busy[ni])
                in_busy_n[ni] = 1'b0;
            if (acc_v[ni]) begin
                in_busy_n[ni]        = 1'b1;
                in_dst_n[ni*W +: W]  = acc_out[ni*W +: W];
                a_ptr_n[ni*W +: W]   = acc_out[ni*W +: W] + 1'b1;
                n_acc                = n_acc + 1'b1;
            end
            for (no = 0; no < N; no = no + 1) begin
                if (rel[ni] && in_busy[ni] && in_dst[ni*W +: W] == no)
                    out_busy_n[no] = 1'b0;
                if (acc_v[ni] && acc_out[ni*W +: W] == no) begin
                    out_busy_n[no]       = 1'b1;
                    out_src_n[no*W +: W] = ni;
                    g_ptr_n[no*W +: W]   = ni + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            in_busy     <= {N{1'b0}};
            in_dst      <= {(N*W){1'b0}};
            out_busy    <= {N{1'b0}};
            out_src     <= {(N*W){1'b0}};
            g_ptr       <= {(N*W){1'b0}};
            a_ptr       <= {(N*W){1'b0}};
            match_count <= {CW{1'b0}};
        end else if (step) begin
            in_busy     <= in_busy_n;
            in_dst      <= in_dst_n;
            out_busy    <= out_busy_n;
            out_src     <= out_src_n;
            g_ptr       <= g_ptr_n;
            a_ptr       <= a_ptr_n;
            match_count <= match_count + n_acc;
            if (|acc_v)
                armed <= 1'b1;
        end
    end

    // absence: two inputs never own the same output (after the first match)
    integer pi, pj;
    reg dup;
    always @(*) begin
        dup = 1'b0;
        for (pi = 0; pi < N; pi = pi + 1)
            for (pj = pi + 1; pj < N; pj = pj + 1)
                if (in_busy[pi] && in_busy[pj] && in_dst[pi*W +: W] == in_dst[pj*W +: W])
                    dup = 1'b1;
    end

    assert property (!armed || !dup);
endmodule

module frac_xmul_cmp #(
    parameter W = 32
) (
    input  wire           clk,
    input  wire           rst,
    // input channel: op=0 loads two fractions a/b and c/d, op=1 takes the reciprocal of both held fractions
    input  wire           in_valid,
    output wire           in_ready,
    input  wire           in_op,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    input  wire [W-1:0]   in_c,
    input  wire [W-1:0]   in_d,
    // output channel: registered cross products and relation result
    output reg            out_valid,
    input  wire           out_ready,
    output reg [2*W-1:0]  p_ad,
    output reg [2*W-1:0]  p_cb,
    output reg            lt_q,
    output reg            gt_q,
    output wire           eq_q
);
    initial begin
        out_valid = 1'b0;
        p_ad      = {2*W{1'b0}};
        p_cb      = {2*W{1'b0}};
        lt_q      = 1'b0;
        gt_q      = 1'b0;
    end

    // cross multiply: a/b vs c/d  <=>  a*d vs c*b (no division)
    wire [2*W-1:0] m_ad = in_a * in_d;
    wire [2*W-1:0] m_cb = in_c * in_b;

    assign in_ready = !out_valid || out_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    assign eq_q = !lt_q && !gt_q;

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            p_ad      <= {2*W{1'b0}};
            p_cb      <= {2*W{1'b0}};
            lt_q      <= 1'b0;
            gt_q      <= 1'b0;
        end else if (in_fire) begin
            out_valid <= 1'b1;
            if (in_op) begin
                // reciprocal of both fractions: b/a vs d/c -> b*c vs d*a, products and relation swap
                p_ad <= p_cb;
                p_cb <= p_ad;
                lt_q <= gt_q;
                gt_q <= lt_q;
            end else begin
                p_ad <= m_ad;
                p_cb <= m_cb;
                lt_q <= (m_ad < m_cb);
                gt_q <= (m_ad > m_cb);
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end
    end

    // Absence: the 'greater' result flag and products that are not greater never coexist
    wire prod_le = (p_ad <= p_cb);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv)
            assert (!($past(gt_q) && $past(prod_le)));
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module branch_resolve_unit #(
    parameter XLEN = 64,
    parameter INST_BYTES = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    // resolved branch packet from execute (valid/ready)
    input  wire            br_valid,
    output wire            br_ready,
    input  wire [XLEN-1:0] br_pc,
    input  wire            br_pred_taken,
    input  wire [XLEN-1:0] br_pred_target,
    input  wire            br_taken,
    input  wire [XLEN-1:0] br_target,
    // redirect / flush request to fetch (valid/ready)
    output reg             redir_valid,
    input  wire            redir_ready,
    output reg  [XLEN-1:0] redir_addr,
    output wire            flush,
    // monitor window control
    input  wire            mon_open,
    input  wire            mon_close
,
    output wire [XLEN-1:0] mispred_cnt_o,
    output wire [XLEN-1:0] redir_cnt_o
);
    localparam [XLEN-1:0] ONE  = 1;
    localparam [XLEN-1:0] STEP = INST_BYTES;

    reg [XLEN-1:0] pred_target_q = 0;
    reg            pred_taken_q  = 1'b0;
    reg            act_taken_q   = 1'b0;
    reg [XLEN-1:0] mispred_cnt   = 0;
    reg [XLEN-1:0] correct_cnt   = 0;
    reg [XLEN-1:0] redir_cnt     = 0;
    reg            win           = 1'b0;
    reg            pv            = 1'b0;
    initial begin redir_valid = 1'b0; redir_addr = 0; end

    assign br_ready = !redir_valid;
    wire accept   = br_valid && br_ready;
    wire send     = redir_valid && redir_ready;
    assign flush  = send;

    wire mispredict = (br_pred_taken != br_taken) ||
                      (br_taken && (br_pred_target != br_target));
    wire [XLEN-1:0] fix_addr = br_taken ? br_target : (br_pc + STEP);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pred_target_q <= 0;
            pred_taken_q  <= 1'b0;
            act_taken_q   <= 1'b0;
            mispred_cnt   <= 0;
            correct_cnt   <= 0;
            redir_cnt     <= 0;
            redir_valid   <= 1'b0;
            redir_addr    <= 0;
        end else begin
            if (accept) begin
                pred_target_q <= br_pred_target;
                pred_taken_q  <= br_pred_taken;
                act_taken_q   <= br_taken;
                if (mispredict) begin
                    mispred_cnt <= mispred_cnt + ONE;
                    redir_valid <= 1'b1;
                    redir_addr  <= fix_addr;
                end else begin
                    correct_cnt <= correct_cnt + ONE;
                end
            end else if (send) begin
                redir_valid <= 1'b0;
                redir_cnt   <= redir_cnt + ONE;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            win <= 1'b0;
        end else begin
            if (mon_open)       win <= 1'b1;
            else if (mon_close) win <= 1'b0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win && $rose(redir_valid))
            assert (mispred_cnt == redir_cnt + ONE);
    assign mispred_cnt_o = mispred_cnt;
    assign redir_cnt_o = redir_cnt;
endmodule

module frac_xmul_cmp #(
    parameter W = 32
) (
    input  wire           clk,
    input  wire           rst,
    // input channel: op=0 loads two fractions a/b and c/d, op=1 takes the reciprocal of both held fractions
    input  wire           in_valid,
    output wire           in_ready,
    input  wire           in_op,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    input  wire [W-1:0]   in_c,
    input  wire [W-1:0]   in_d,
    // output channel: registered cross products and relation result
    output reg            out_valid,
    input  wire           out_ready,
    output reg [2*W-1:0]  p_ad,
    output reg [2*W-1:0]  p_cb,
    output reg            lt_q,
    output reg            gt_q,
    output wire           eq_q
);
    initial begin
        out_valid = 1'b0;
        p_ad      = {2*W{1'b0}};
        p_cb      = {2*W{1'b0}};
        lt_q      = 1'b0;
        gt_q      = 1'b0;
    end

    // cross multiply: a/b vs c/d  <=>  a*d vs c*b (no division)
    wire [2*W-1:0] m_ad = in_a * in_d;
    wire [2*W-1:0] m_cb = in_c * in_b;

    assign in_ready = !out_valid || out_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    assign eq_q = !lt_q && !gt_q;

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            p_ad      <= {2*W{1'b0}};
            p_cb      <= {2*W{1'b0}};
            lt_q      <= 1'b0;
            gt_q      <= 1'b0;
        end else if (in_fire) begin
            out_valid <= 1'b1;
            if (in_op) begin
                // reciprocal of both fractions: b/a vs d/c -> b*c vs d*a, products and relation swap
                p_ad <= p_cb;
                p_cb <= p_ad;
                lt_q <= gt_q;
                gt_q <= lt_q;
            end else begin
                p_ad <= m_ad;
                p_cb <= m_cb;
                lt_q <= (m_ad < m_cb);
                gt_q <= (m_ad > m_cb);
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end
    end

    // Absence: the 'greater' result flag and products that are not greater never coexist
    wire prod_le = (p_ad <= p_cb);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv)
            assert (!($past(gt_q) && $past(prod_le)));
endmodule

module rational_branch_unit #(
    parameter DEPTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire in_op,
    input wire [31:0] in_a, in_b, in_c, in_d,
    input wire [63:0] br_pc,
    input wire br_pred_taken,
    input wire [63:0] br_pred_target, br_target,
    input wire redir_ready,
    input wire mon_open, mon_close,
    output wire redir_valid,
    output wire [63:0] redir_addr,
    output wire flush,
    output wire [63:0] a_mispred_cnt, a_redir_cnt,
    output wire a_br_ready,
    output wire b_out_valid, b_out_ready,
    output wire [63:0] b_p_ad, b_p_cb,
    output wire b_lt_q, b_gt_q, b_eq_q,
    output reg [$clog2(DEPTH+1)-1:0] q_count,
    output wire [$clog2(DEPTH+1)-1:0] unissued_count,
    output wire head_valid, retire,
    output wire [63:0] head_pc, head_pred_target, head_target,
    output wire head_pred_taken, head_taken,
    output wire [63:0] head_p_ad, head_p_cb
);
    localparam COUNT_W = $clog2(DEPTH+1);
    localparam [63:0] STEP = 64'd4;
    wire rst = !rst_n;
    wire issue = in_valid && in_ready;
    reg [63:0] meta_pc, meta_pred_target, meta_target;
    reg meta_pred_taken;
    reg [63:0] q_pc [0:DEPTH-1];
    reg [63:0] q_pred_target [0:DEPTH-1];
    reg [63:0] q_target [0:DEPTH-1];
    reg [63:0] q_p_ad [0:DEPTH-1];
    reg [63:0] q_p_cb [0:DEPTH-1];
    reg q_pred_taken [0:DEPTH-1];
    reg q_taken [0:DEPTH-1];

    assign head_valid = (q_count != 0);
    assign head_pc = q_pc[0];
    assign head_pred_target = q_pred_target[0];
    assign head_target = q_target[0];
    assign head_pred_taken = q_pred_taken[0];
    assign head_taken = q_taken[0];
    assign head_p_ad = q_p_ad[0];
    assign head_p_cb = q_p_cb[0];
    wire head_mispredict = (head_pred_taken != head_taken) ||
                          (head_taken && (head_pred_target != head_target));
    wire [63:0] head_fix_addr = head_taken ? head_target : head_pc + STEP;
    wire a_br_valid = head_valid && !redir_valid;
    wire branch_accept = a_br_valid && a_br_ready;
    assign retire = head_valid &&
                    ((branch_accept && !head_mispredict) || flush);
    assign b_out_ready = (q_count < DEPTH);
    wire enqueue = b_out_valid && b_out_ready;
    wire [COUNT_W-1:0] enqueue_index = q_count - {{(COUNT_W-1){1'b0}}, retire};
    assign unissued_count = q_count - {{(COUNT_W-1){1'b0}}, redir_valid};

    frac_xmul_cmp #(.W(32)) compare (
        .clk(clk), .rst(rst), .in_valid(in_valid), .in_ready(in_ready),
        .in_op(in_op), .in_a(in_a), .in_b(in_b), .in_c(in_c), .in_d(in_d),
        .out_valid(b_out_valid), .out_ready(b_out_ready),
        .p_ad(b_p_ad), .p_cb(b_p_cb),
        .lt_q(b_lt_q), .gt_q(b_gt_q), .eq_q(b_eq_q)
    );
    branch_resolve_unit #(.XLEN(64), .INST_BYTES(4)) resolve (
        .clk(clk), .rst_n(rst_n), .br_valid(a_br_valid), .br_ready(a_br_ready),
        .br_pc(head_pc), .br_pred_taken(head_pred_taken),
        .br_pred_target(head_pred_target), .br_taken(head_taken),
        .br_target(head_target), .redir_valid(redir_valid),
        .redir_ready(redir_ready), .redir_addr(redir_addr), .flush(flush),
        .mon_open(mon_open), .mon_close(mon_close),
        .mispred_cnt_o(a_mispred_cnt), .redir_cnt_o(a_redir_cnt)
    );

    // Metadata advances on exactly the comparator's input handshake.
    initial begin
        meta_pc = 0;
        meta_pred_target = 0;
        meta_target = 0;
        meta_pred_taken = 1'b0;
    end
    always @(posedge clk) begin
        if (rst) begin
            meta_pc <= 0;
            meta_pred_target <= 0;
            meta_target <= 0;
            meta_pred_taken <= 1'b0;
        end else if (issue) begin
            meta_pc <= br_pc;
            meta_pred_target <= br_pred_target;
            meta_target <= br_target;
            meta_pred_taken <= br_pred_taken;
        end
    end

    // Keep the oldest completion available until its redirect has been sent.
    integer init_i;
    initial begin
        q_count = 0;
        for (init_i = 0; init_i < DEPTH; init_i = init_i + 1) begin
            q_pc[init_i] = 0;
            q_pred_target[init_i] = 0;
            q_target[init_i] = 0;
            q_p_ad[init_i] = 0;
            q_p_cb[init_i] = 0;
            q_pred_taken[init_i] = 1'b0;
            q_taken[init_i] = 1'b0;
        end
    end
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q_count <= 0;
            for (i = 0; i < DEPTH; i = i + 1) begin
                q_pc[i] <= 0;
                q_pred_target[i] <= 0;
                q_target[i] <= 0;
                q_p_ad[i] <= 0;
                q_p_cb[i] <= 0;
                q_pred_taken[i] <= 1'b0;
                q_taken[i] <= 1'b0;
            end
        end else begin
            if (retire) begin
                for (i = 0; i < DEPTH-1; i = i + 1) begin
                    q_pc[i] <= q_pc[i+1];
                    q_pred_target[i] <= q_pred_target[i+1];
                    q_target[i] <= q_target[i+1];
                    q_p_ad[i] <= q_p_ad[i+1];
                    q_p_cb[i] <= q_p_cb[i+1];
                    q_pred_taken[i] <= q_pred_taken[i+1];
                    q_taken[i] <= q_taken[i+1];
                end
            end
            if (enqueue) begin
                q_pc[enqueue_index] <= meta_pc;
                q_pred_target[enqueue_index] <= meta_pred_target;
                q_target[enqueue_index] <= meta_target;
                q_p_ad[enqueue_index] <= b_p_ad;
                q_p_cb[enqueue_index] <= b_p_cb;
                q_pred_taken[enqueue_index] <= meta_pred_taken;
                q_taken[enqueue_index] <= b_lt_q;
            end
            case ({enqueue, retire})
                2'b10: q_count <= q_count + 1'b1;
                2'b01: q_count <= q_count - 1'b1;
                default: q_count <= q_count;
            endcase
        end
    end

    wire comparison_taken = (head_p_ad < head_p_cb);
    wire comparison_mispredict = (head_pred_taken != comparison_taken) ||
                                (comparison_taken && (head_pred_target != head_target));
    wire [63:0] comparison_fix_addr =
        comparison_taken ? head_target : head_pc + STEP;
    always @(posedge clk)
        if (retire)
            assert ((redir_valid == comparison_mispredict) &&
                    (!redir_valid || (redir_addr == comparison_fix_addr)));
endmodule

module ckpt_regfile #(
    parameter W = 32,
    parameter NREG = 4,
    parameter NCKPT = 4,
    parameter [31:0] TIMEOUT = 32'd6,
    parameter SW = $clog2(NCKPT),
    parameter RW = $clog2(NREG),
    parameter TRACE_DEPTH = 4,
    parameter QW = $clog2(TRACE_DEPTH),
    parameter BW = $clog2(TIMEOUT + 32'd1)
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire branch,
    input wire resolve,
    input wire mispredict,
    input wire [SW-1:0] rsv_id,
    input wire wr_en,
    input wire [RW-1:0] wr_addr,
    input wire [W-1:0] wr_data,
    output wire [NCKPT-1:0] o_mask,
    output wire [W-1:0] o_acc0,
    output wire o_busy,
    output wire o_branch_ready,
    output wire o_trace_valid,
    output wire o_trace_emit,
    output wire [W-1:0] o_trace_data,
    output wire [SW-1:0] o_trace_slot,
    output wire [BW-1:0] o_trace_budget,
    output wire [QW:0] o_trace_pending
);
    // active accumulator register file and checkpoint shadow copies
    reg [NREG*W-1:0] regs_q;
    reg [NCKPT*NREG*W-1:0] shadow_q;
    reg [NCKPT-1:0] ckpt_mask;
    reg [31:0] n_live;
    reg [31:0] wd;
    reg armed;
    reg [QW:0] trace_rptr, trace_wptr;
    reg [W-1:0] trace_data [0:TRACE_DEPTH-1];
    reg [SW-1:0] trace_slot [0:TRACE_DEPTH-1];
    reg [BW-1:0] trace_budget [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_out_data;
    reg [SW-1:0] trace_out_slot;
    reg [BW-1:0] trace_out_budget;
    reg trace_out_valid;
    integer ti;
    wire [QW:0] trace_count = trace_wptr - trace_rptr;
    wire [QW:0] trace_pending = trace_count + trace_out_valid;
    wire trace_empty = (trace_wptr == trace_rptr);
    wire trace_full = (trace_wptr[QW] != trace_rptr[QW]) &&
                      (trace_wptr[QW-1:0] == trace_rptr[QW-1:0]);
    wire trace_emit = step && !wr_en && trace_out_valid;
    wire trace_pop = step && !trace_empty &&
                     (!trace_out_valid || trace_emit);

    initial begin
        regs_q = {NREG*W{1'b0}};
        shadow_q = {NCKPT*NREG*W{1'b0}};
        ckpt_mask = {NCKPT{1'b0}};
        n_live = 32'd0;
        wd = 32'd0;
        armed = 1'b1;
        trace_rptr = {(QW+1){1'b0}};
        trace_wptr = {(QW+1){1'b0}};
        trace_out_data = {W{1'b0}};
        trace_out_slot = {SW{1'b0}};
        trace_out_budget = {BW{1'b0}};
        trace_out_valid = 1'b0;
        for (ti = 0; ti < TRACE_DEPTH; ti = ti + 1) begin
            trace_data[ti] = {W{1'b0}};
            trace_slot[ti] = {SW{1'b0}};
            trace_budget[ti] = {BW{1'b0}};
        end
    end

    // lowest free checkpoint slot
    reg [SW-1:0] free_slot;
    integer k;
    always @(*) begin
        free_slot = {SW{1'b0}};
        for (k = NCKPT-1; k >= 0; k = k - 1)
            if (!ckpt_mask[k]) free_slot = k;
    end

    wire live        = (n_live != 32'd0);
    wire timeout     = live && (wd == 32'd1);
    wire do_rollback = mispredict && ckpt_mask[rsv_id];
    wire do_free     = resolve && ckpt_mask[rsv_id];
    wire do_alloc    = branch && o_branch_ready;
    wire trace_push = step && !timeout && !do_rollback && do_alloc;
    assign o_branch_ready = step && !timeout && !do_rollback &&
                            (n_live != NCKPT) && !trace_full &&
                            (live || (trace_empty && !trace_out_valid));

    reg [NCKPT-1:0] mask_nxt;
    reg [31:0] live_nxt;
    always @(*) begin
        mask_nxt = ckpt_mask;
        live_nxt = n_live;
        if (do_free) begin
            mask_nxt[rsv_id] = 1'b0;
            live_nxt = live_nxt - 32'd1;
        end
        if (do_alloc) begin
            mask_nxt[free_slot] = 1'b1;
            live_nxt = live_nxt + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            regs_q <= {NREG*W{1'b0}};
            ckpt_mask <= {NCKPT{1'b0}};
            n_live <= 32'd0;
            wd <= 32'd0;
        end else if (step) begin
            if (timeout) begin
                // deadline reached: force-commit all outstanding checkpoints
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
            end else if (do_rollback) begin
                regs_q <= shadow_q[rsv_id*NREG*W +: NREG*W];
                ckpt_mask <= {NCKPT{1'b0}};
                n_live <= 32'd0;
                wd <= 32'd0;
                armed <= 1'b0;
            end else begin
                if (do_alloc)
                    shadow_q[free_slot*NREG*W +: NREG*W] <= regs_q;
                if (wr_en)
                    regs_q[wr_addr*W +: W] <= wr_data;
                ckpt_mask <= mask_nxt;
                n_live <= live_nxt;
                if (live_nxt == 32'd0)
                    wd <= 32'd0;
                else if (!live)
                    wd <= TIMEOUT;
                else
                    wd <= wd - 32'd1;
            end
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            trace_rptr <= {(QW+1){1'b0}};
            trace_wptr <= {(QW+1){1'b0}};
            trace_out_data <= {W{1'b0}};
            trace_out_slot <= {SW{1'b0}};
            trace_out_budget <= {BW{1'b0}};
            trace_out_valid <= 1'b0;
            for (ti = 0; ti < TRACE_DEPTH; ti = ti + 1) begin
                trace_data[ti] <= {W{1'b0}};
                trace_slot[ti] <= {SW{1'b0}};
                trace_budget[ti] <= {BW{1'b0}};
            end
        end else begin
            if (trace_push) begin
                trace_data[trace_wptr[QW-1:0]] <= regs_q[W-1:0];
                trace_slot[trace_wptr[QW-1:0]] <= free_slot;
                trace_budget[trace_wptr[QW-1:0]] <= live ? wd - 32'd1 : TIMEOUT;
                trace_wptr <= trace_wptr + 1'b1;
            end
            if (trace_pop) begin
                trace_out_data <= trace_data[trace_rptr[QW-1:0]];
                trace_out_slot <= trace_slot[trace_rptr[QW-1:0]];
                trace_out_budget <= trace_budget[trace_rptr[QW-1:0]];
                trace_out_valid <= 1'b1;
                trace_rptr <= trace_rptr + 1'b1;
            end else if (trace_emit)
                trace_out_valid <= 1'b0;
        end
    end

    assign o_mask = ckpt_mask;
    assign o_acc0 = regs_q[W-1:0];
    assign o_busy = live;
    assign o_trace_valid = trace_out_valid;
    assign o_trace_emit = trace_emit;
    assign o_trace_data = trace_out_data;
    assign o_trace_slot = trace_out_slot;
    assign o_trace_budget = trace_out_budget;
    assign o_trace_pending = trace_pending;

    // before the first rollback: an outstanding checkpoint never sees an expired deadline
    always @(*) assert (!armed || ckpt_mask == {NCKPT{1'b0}} || wd != 32'd0);
    always @(*) assert (!o_trace_emit ||
        (o_trace_budget != {BW{1'b0}} && wd <= o_trace_budget));
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [31:0] debug_status
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
        if (acc) begin
            if (dbg_accept_count != 8'hff)
                dbg_accept_count <= dbg_accept_count + 1'b1;
        end
        if (rel) begin
            if (dbg_complete_count != 8'hff)
                dbg_complete_count <= dbg_complete_count + 1'b1;
        end
        if (out_valid && !out_ready) begin
            if (dbg_stall_cycles != 8'hff) begin
                dbg_stall_cycles <= dbg_stall_cycles + 1'b1;
                if (dbg_stall_cycles >= dbg_peak_stall)
                    dbg_peak_stall <= dbg_stall_cycles + 1'b1;
            end
            if (dbg_stall_cycles >= 8'd63)
                dbg_timeout <= 1'b1;
        end else begin
            dbg_stall_cycles <= 8'd0;
        end
    end
    assign debug_status = {dbg_timeout, 7'd0, dbg_peak_stall,
                           dbg_complete_count, dbg_accept_count};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
,
    output wire [15:0] lim_o,
    output wire [15:0] occ_w_o,
    output wire [15:0] rc_w_o,
    output wire [PW-1:0] rp_w_o,
    output wire [15:0] wc_w_o,
    output wire [PW-1:0] wp_w_o
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
    assign lim_o = lim;
    assign occ_w_o = occ_w;
    assign rc_w_o = rc_w;
    assign rp_w_o = rp_w;
    assign wc_w_o = wc_w;
    assign wp_w_o = wp_w;
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
,
    output wire [31:0] bitcnt_o,
    output wire busy_o,
    output wire in_frame_o,
    output wire [FRAME_W-1:0] shreg_o
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign in_frame_o = in_frame;
    assign shreg_o = shreg;
endmodule

module axi_uart_tx (
    input wire clk,
    input wire rst_n,
    input wire s_ce, m_ce,
    input wire i_load,
    input wire [15:0] i_lim,
    input wire baud_tick,
    input wire s_aw_valid,
    input wire [15:0] s_aw_addr,
    output wire s_aw_ready,
    input wire s_w_valid,
    input wire [15:0] s_w_data,
    output wire s_w_ready,
    output wire s_b_valid,
    output wire [15:0] s_b_resp,
    input wire s_b_ready,
    input wire s_ar_valid,
    input wire [15:0] s_ar_addr,
    output wire s_ar_ready,
    output wire s_r_valid,
    output wire [15:0] s_r_data,
    input wire s_r_ready,
    output wire txd,
    output wire [15:0] a_lim, a_occ_w, a_rc_w, a_wc_w,
    output wire [4:0] a_rp_w, a_wp_w,
    output wire [31:0] uart_bitcnt,
    output wire uart_busy, uart_in_frame,
    output wire [10:0] uart_shreg,
    output wire [15:0] address_o,
    output wire address_pending_o, tx_wait_o,
    output wire response_pending_o, response_error_o,
    output wire uart_online_o
);
    localparam [15:0] TX_ADDR = 16'h0000;
    localparam [15:0] COUNT_ADDR = 16'h0004;

    wire a_aw_valid, a_aw_ready, a_w_valid, a_w_ready;
    wire [15:0] a_aw_addr, a_w_data;
    wire a_b_valid, a_b_ready;
    wire [15:0] a_b_resp;
    wire a_ar_valid, a_ar_ready, a_r_valid, a_r_ready;
    wire [15:0] a_ar_addr, a_r_data;
    wire uart_valid, uart_ready;

    reg [15:0] address_hold = 16'd0;
    reg address_pending = 1'b0;
    reg tx_wait = 1'b0;
    reg response_pending = 1'b0;
    reg response_error = 1'b0;
    reg uart_online = 1'b0;

    assign address_o = address_hold;
    assign address_pending_o = address_pending;
    assign tx_wait_o = tx_wait;
    assign response_pending_o = response_pending;
    assign response_error_o = response_error;
    assign uart_online_o = uart_online;

    wire address_is_tx = (address_hold == TX_ADDR);
    assign a_aw_ready = uart_online && !address_pending;
    assign a_w_ready = uart_online && address_pending && !tx_wait &&
                       !response_pending && (!address_is_tx || uart_ready);
    assign uart_valid = m_ce && uart_online && address_pending &&
                        !tx_wait && !response_pending && address_is_tx && a_w_valid;
    wire address_take = m_ce && a_aw_valid && a_aw_ready;
    wire write_take = m_ce && a_w_valid && a_w_ready;
    wire uart_take = uart_valid && uart_ready;
    wire write_reject = write_take && !address_is_tx;

    assign a_b_valid = response_pending;
    assign a_b_resp = response_error ? 16'd3 : 16'd0;
    wire response_take = m_ce && a_b_valid && a_b_ready;

    // The read port reports status without disturbing a pending write.
    assign a_r_valid = uart_online && a_ar_valid;
    assign a_ar_ready = uart_online && a_r_ready;
    assign a_r_data = (a_ar_addr == TX_ADDR) ? {15'd0, uart_busy} :
                      (a_ar_addr == COUNT_ADDR) ? uart_bitcnt[15:0] : 16'hffff;

    axi_cdc_bridge bridge (
        .clk(clk), .s_ce(s_ce), .m_ce(m_ce),
        .i_load(i_load), .i_lim(i_lim),
        .s_aw_valid(s_aw_valid), .s_aw_addr(s_aw_addr),
        .s_aw_ready(s_aw_ready),
        .m_aw_valid(a_aw_valid), .m_aw_addr(a_aw_addr),
        .m_aw_ready(a_aw_ready),
        .s_w_valid(s_w_valid), .s_w_data(s_w_data),
        .s_w_ready(s_w_ready),
        .m_w_valid(a_w_valid), .m_w_data(a_w_data),
        .m_w_ready(a_w_ready),
        .m_b_valid(a_b_valid), .m_b_resp(a_b_resp),
        .m_b_ready(a_b_ready),
        .s_b_valid(s_b_valid), .s_b_resp(s_b_resp),
        .s_b_ready(s_b_ready),
        .s_ar_valid(s_ar_valid), .s_ar_addr(s_ar_addr),
        .s_ar_ready(s_ar_ready),
        .m_ar_valid(a_ar_valid), .m_ar_addr(a_ar_addr),
        .m_ar_ready(a_ar_ready),
        .m_r_valid(a_r_valid), .m_r_data(a_r_data),
        .m_r_ready(a_r_ready),
        .s_r_valid(s_r_valid), .s_r_data(s_r_data),
        .s_r_ready(s_r_ready),
        .lim_o(a_lim), .occ_w_o(a_occ_w),
        .rc_w_o(a_rc_w), .rp_w_o(a_rp_w),
        .wc_w_o(a_wc_w), .wp_w_o(a_wp_w)
    );

    uart_tx_word #(.DATA_W(8)) uart (
        .clk(clk), .rst_n(rst_n), .baud_tick(baud_tick),
        .s_valid(uart_valid), .s_ready(uart_ready),
        .s_data(a_w_data[7:0]), .txd(txd), .o_busy(),
        .bitcnt_o(uart_bitcnt), .busy_o(uart_busy),
        .in_frame_o(uart_in_frame), .shreg_o(uart_shreg)
    );

    // Allow the UART and the bus-side join to leave reset together.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            uart_online <= 1'b0;
        else
            uart_online <= 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            address_hold <= 16'd0;
            address_pending <= 1'b0;
            tx_wait <= 1'b0;
            response_pending <= 1'b0;
            response_error <= 1'b0;
        end else if (m_ce) begin
            // AW may run ahead while a previous character is shifting.
            if (address_take) begin
                address_hold <= a_aw_addr;
                address_pending <= 1'b1;
            end
            if (write_take)
                address_pending <= 1'b0;
            if (uart_take) begin
                tx_wait <= 1'b1;
                response_error <= 1'b0;
            end
            if (write_reject) begin
                response_pending <= 1'b1;
                response_error <= 1'b1;
            end
            // Completion is retained until the response FIFO has space.
            if (tx_wait && !uart_busy) begin
                tx_wait <= 1'b0;
                response_pending <= 1'b1;
                response_error <= 1'b0;
            end
            if (response_take)
                response_pending <= 1'b0;
        end
    end

    always @(posedge clk)
        if (response_pending_o && !response_error_o)
            assert (!uart_busy && uart_bitcnt == 32'd11);
endmodule

module ntt_phase_dispatch #(
    parameter W = 16,
    parameter PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire clk,
    input  wire cfg_valid,
    output wire cfg_ready,
    input  wire [W-1:0] cfg_data,
    input  wire [W-1:0] profile_select,
    input  wire start,
    input  wire run,
    input  wire finish,
    input  wire [W-1:0] remaining,
    input  wire [W-1:0] launch_latency,
    output reg  [W-1:0] step = 16'd0,
    output reg  [W-1:0] quantum = 16'd1,
    output wire [W*PROFILES-1:0] profiles,
    output reg  [1:0] cfg_state = 2'd0,
    output reg  [$clog2(PROFILES)-1:0] cfg_index = 0,
    output reg  [W-1:0] cfg_pending = 16'd0,
    output reg  [W-1:0] cfg_prepared = 16'd1,
    output wire cfg_apply
);
    localparam INDEX_W = $clog2(PROFILES);
    localparam [INDEX_W-1:0] LAST_PROFILE = PROFILES - 1;
    reg [W-1:0] cap [0:PROFILES-1];
    wire [INDEX_W-1:0] selected = profile_select % PROFILES;
    integer init_profile;
    initial begin
        for (init_profile = 0; init_profile < PROFILES; init_profile = init_profile + 1) begin
            cap[init_profile] = 16'd1;
        end
    end
    genvar p;
    generate
        for (p = 0; p < PROFILES; p = p + 1) begin: expose_profiles
            assign profiles[p*W +: W] = cap[p];
        end
    endgenerate
    assign cfg_ready = (cfg_state == 2'd0);
    assign cfg_apply = (cfg_state == 2'd2);

    function [W-1:0] choose_step;
        input [W-1:0] left;
        input [W-1:0] limit;
        begin
            if (left <= 16'd1)
                choose_step = 16'd1;
            else if (left - 16'd1 < limit)
                choose_step = left - 16'd1;
            else
                choose_step = limit;
        end
    endfunction

    always @(posedge clk) begin
        case (cfg_state)
            2'd0: begin
                if (cfg_valid && cfg_ready) begin
                    cfg_pending <= cfg_data;
                    cfg_state <= 2'd1;
                end
            end
            2'd1: begin
                if (cfg_pending == 16'd0)
                    cfg_prepared <= 16'd1;
                else if (cfg_pending > MAX_BURST)
                    cfg_prepared <= MAX_BURST;
                else
                    cfg_prepared <= cfg_pending;
                cfg_state <= 2'd2;
            end
            2'd2: begin
                cap[cfg_index] <= cfg_prepared;
                if (cfg_index == LAST_PROFILE)
                    cfg_index <= {INDEX_W{1'b0}};
                else
                    cfg_index <= cfg_index + 1'b1;
                cfg_state <= 2'd0;
            end
            default: cfg_state <= 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (start) begin
            quantum <= cap[selected];
            step <= choose_step(launch_latency, cap[selected]);
        end else if (finish) begin
            step <= 16'd0;
        end else if (run) begin
            step <= choose_step(remaining - step, quantum);
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter BURST_PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output wire         cfg_ready,
    output wire         cfg_busy,
    output wire [W-1:0] burst_step,
    output wire [W*BURST_PROFILES-1:0] burst_profiles
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;
    wire [W-1:0] burst_quantum;
    wire [1:0] cfg_state;
    wire [$clog2(BURST_PROFILES)-1:0] cfg_write_index;
    wire [W-1:0] cfg_pending;
    wire [W-1:0] cfg_prepared;
    wire cfg_apply;
    assign cfg_busy = (cfg_state != 2'd0);

    ntt_phase_dispatch #(
        .W(W), .PROFILES(BURST_PROFILES), .MAX_BURST(MAX_BURST)
    ) phase_dispatch (
        .clk(clk), .cfg_valid(load_cfg), .cfg_ready(cfg_ready),
        .cfg_data(cfg_lat), .profile_select(stage),
        .start(start), .run(busy && ce && !last), .finish(retire),
        .remaining(cd), .launch_latency(lat_q),
        .step(burst_step), .quantum(burst_quantum),
        .profiles(burst_profiles), .cfg_state(cfg_state),
        .cfg_index(cfg_write_index), .cfg_pending(cfg_pending),
        .cfg_prepared(cfg_prepared), .cfg_apply(cfg_apply)
    );

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (cfg_apply) lat_cfg <= cfg_pending;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - burst_step;
                phase <= phase + burst_step;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16,
    parameter DEPTH = 4 // power-of-two capture depth
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
    output wire [1:0]   o_rem,
    output wire [$clog2(DEPTH):0] buffered,
    output wire [W-1:0] capture_value,
    output wire [W-1:0] next_prefix
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0]   phase   = S_IDLE;
    reg [1:0]   rem     = 2'd0;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;

    localparam PTR_W = $clog2(DEPTH);
    reg [W-1:0] prefix_mem [0:DEPTH-1];
    reg [W-1:0] capture_prefix = {W{1'b0}};
    reg [PTR_W:0] wr_ptr = {(PTR_W+1){1'b0}};
    reg [PTR_W:0] rd_ptr = {(PTR_W+1){1'b0}};
    reg [W-1:0] queued_prefix [0:DEPTH-1];
    wire [PTR_W:0] q_used = wr_ptr - rd_ptr;
    wire q_empty = (wr_ptr == rd_ptr);
    wire q_full = (wr_ptr[PTR_W] != rd_ptr[PTR_W]) &&
                  (wr_ptr[PTR_W-1:0] == rd_ptr[PTR_W-1:0]);
    wire [W-1:0] accepted_bits = cnt + q_used;
    wire consume = (phase == S_RUN) && !q_empty;
    integer init_i;
    integer view_i;
    integer clear_i;

    assign in_ready = ((phase == S_ARM) || (phase == S_RUN)) &&
                      !q_full && (accepted_bits < limit);
    wire acc = in_valid && in_ready;
    assign buffered = q_used;
    assign capture_value = capture_prefix;
    assign next_prefix = q_empty ? {W{1'b0}} : queued_prefix[0];

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;

    initial begin
        for (init_i = 0; init_i < DEPTH; init_i = init_i + 1)
            prefix_mem[init_i] = {W{1'b0}};
    end

    always @(*) begin
        for (view_i = 0; view_i < DEPTH; view_i = view_i + 1) begin
            queued_prefix[view_i] =
                prefix_mem[(rd_ptr[PTR_W-1:0] + view_i) % DEPTH];
        end
    end

    always @(posedge clk) begin
        if (((phase == S_IDLE) && arm) ||
            ((phase == S_DONE) && clr)) begin
            wr_ptr <= {(PTR_W+1){1'b0}};
            rd_ptr <= {(PTR_W+1){1'b0}};
            capture_prefix <= {W{1'b0}};
            for (clear_i = 0; clear_i < DEPTH; clear_i = clear_i + 1) begin
                prefix_mem[clear_i] <= {W{1'b0}};
            end
        end else begin
            if (acc) begin
                prefix_mem[wr_ptr[PTR_W-1:0]] <=
                    {capture_prefix[W-2:0], in_bit};
                capture_prefix <= {capture_prefix[W-2:0], in_bit};
                wr_ptr <= wr_ptr + 1'b1;
            end
            if (consume) rd_ptr <= rd_ptr + 1'b1;
        end
    end

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (phase == S_ARM) begin
            if (acc && ((q_used == DEPTH-1) ||
                        (accepted_bits + 16'd1 == limit)))
                phase <= S_RUN;
        end else if (consume) begin
            rem     <= rnext(rem, queued_prefix[0][0]);
            val     <= queued_prefix[0];
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (acc)
            assert ((capture_prefix >> accepted_bits) == {W{1'b0}});

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_mag,
    input  wire         peer_sign,
    output wire         peer_out_valid,
    input  wire         peer_out_ready,
    output wire [W-1:0] peer_out_min1,
    output wire [W-1:0] peer_out_min2,
    output wire [W-1:0] peer_out_idx,
    output wire         peer_out_sign,
    output wire [31:0] debug_status
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PCW = (DEG > 1) ? $clog2(DEG) : 1;
    reg [W-1:0] peer_min1 [1:CHANNELS-1], peer_min2 [1:CHANNELS-1];
    reg [PCW-1:0] peer_count [1:CHANNELS-1], peer_idx [1:CHANNELS-1];
    reg peer_done [1:CHANNELS-1], peer_sign_prod [1:CHANNELS-1];
    reg cache_owner;
    reg [W-1:0] shared_min;
    initial cache_owner = 1'b1;
    initial shared_min = {W{1'b1}};
    integer lane;
    initial begin
        for (lane = 1; lane < CHANNELS; lane = lane + 1) begin
            peer_min1[lane] = {W{1'b1}}; peer_min2[lane] = {W{1'b1}};
            peer_count[lane] = {PCW{1'b0}}; peer_idx[lane] = {PCW{1'b0}};
            peer_done[lane] = 1'b0; peer_sign_prod[lane] = 1'b0;
        end
    end
    wire lane_req = in_valid && (state == S_ACCUM);
    wire peer_req = peer_valid && !peer_done[1];

    assign in_ready = (state == S_ACCUM) && !(peer_req && !cache_owner);
    assign peer_ready = !peer_done[1] && !(lane_req && cache_owner);
    wire peer_acc = peer_valid && peer_ready;
    wire peer_rel = peer_out_valid && peer_out_ready;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
    wire fold_fire = acc || peer_acc;
    wire [W-1:0] fold_mag = peer_acc ? peer_mag : in_mag;
    wire [W-1:0] fold_floor = (cache_owner == peer_acc) ? shared_min : (peer_acc ? peer_min1[1] : min1);
    wire [W-1:0] fold_limit = peer_acc ? peer_min2[1] : min2;
    wire fold_lower = fold_mag < fold_floor;
    wire [W-1:0] fold_min1 = fold_lower ? fold_mag : fold_floor;
    wire [W-1:0] fold_min2 = fold_lower ? fold_floor :
                           ((fold_mag < fold_limit) ? fold_mag : fold_limit);

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            min1 <= fold_min1;
            min2 <= fold_min2;
            if (fold_lower) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    always @(posedge clk) begin
        for (lane = 1; lane < CHANNELS; lane = lane + 1) begin
            if (peer_acc) begin
                peer_min1[lane] <= fold_min1; peer_min2[lane] <= fold_min2;
                peer_sign_prod[lane] <= peer_sign_prod[lane] ^ peer_sign;
                if (fold_lower) peer_idx[lane] <= peer_count[lane];
                if (peer_count[lane] == DEG - 1) begin
                    peer_count[lane] <= {PCW{1'b0}}; peer_done[lane] <= 1'b1;
                end else peer_count[lane] <= peer_count[lane] + 1'b1;
            end else if (peer_rel) begin
                peer_min1[lane] <= {W{1'b1}}; peer_min2[lane] <= {W{1'b1}};
                peer_idx[lane] <= {PCW{1'b0}}; peer_sign_prod[lane] <= 1'b0; peer_done[lane] <= 1'b0;
            end
        end
        if (fold_fire) begin
            shared_min <= fold_min1; cache_owner <= peer_acc;
        end else if ((!cache_owner && rel) || (cache_owner && peer_rel))
            shared_min <= {W{1'b1}};
    end
    assign peer_out_valid = peer_done[1];
    assign peer_out_min1 = peer_min1[1];
    assign peer_out_min2 = peer_min2[1];
    assign peer_out_idx = peer_idx[1];
    assign peer_out_sign = peer_sign_prod[1];
    always @(posedge clk) if (peer_acc && cache_owner) assert (fold_min2 >= shared_min);
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
        if (acc) begin
            if (dbg_accept_count != 8'hff)
                dbg_accept_count <= dbg_accept_count + 1'b1;
        end
        if (rel) begin
            if (dbg_complete_count != 8'hff)
                dbg_complete_count <= dbg_complete_count + 1'b1;
        end
        if (out_valid && !out_ready) begin
            if (dbg_stall_cycles != 8'hff) begin
                dbg_stall_cycles <= dbg_stall_cycles + 1'b1;
                if (dbg_stall_cycles >= dbg_peak_stall)
                    dbg_peak_stall <= dbg_stall_cycles + 1'b1;
            end
            if (dbg_stall_cycles >= 8'd63)
                dbg_timeout <= 1'b1;
        end else begin
            dbg_stall_cycles <= 8'd0;
        end
    end
    assign debug_status = {dbg_timeout, 7'd0, dbg_peak_stall,
                           dbg_complete_count, dbg_accept_count};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module ddr3_cmd_queue #(
    parameter DEPTH = 12,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data,
    input  wire          cfg_load,
    input  wire [31:0]   cfg_wm,
    output wire          almost_full,
    output wire [31:0]   occupancy
,
    output wire [31:0] count_o,
    output wire rd_lap_o,
    output wire [AW-1:0] rptr_o,
    output wire [AW-1:0] wptr_o,
    output wire wr_lap_o
);
    localparam AW = $clog2(DEPTH);
    localparam [AW-1:0] LAST = DEPTH - 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = {AW{1'b0}};
    reg [AW-1:0] rptr = {AW{1'b0}};
    reg          wr_lap = 1'b0;
    reg          rd_lap = 1'b0;
    reg [31:0]   count = 32'd0;
    reg [31:0]   wm = 32'd8;
    reg          armed = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    wire full  = (wptr == rptr) && (wr_lap != rd_lap);
    wire empty = (wptr == rptr) && (wr_lap == rd_lap);
    assign in_ready  = !full;
    assign out_valid = !empty;
    assign out_data  = mem[rptr];

    wire push = in_valid && in_ready;
    wire pop  = out_valid && out_ready;

    // T inputs of the two lap toggle flip-flops
    wire wr_t = push && (wptr == LAST);
    wire rd_t = pop  && (rptr == LAST);

    always @(posedge clk) begin
        if (push) begin
            mem[wptr] <= in_data;
            wptr <= (wptr == LAST) ? {AW{1'b0}} : wptr + 1'b1;
        end
        if (pop)
            rptr <= (rptr == LAST) ? {AW{1'b0}} : rptr + 1'b1;
        if (wr_t) wr_lap <= ~wr_lap;
        if (rd_t) rd_lap <= ~rd_lap;
        case ({push, pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
        if (cfg_load) begin
            wm    <= cfg_wm;
            armed <= 1'b0;
        end
    end

    assign almost_full = (count >= wm);
    assign occupancy   = count;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $rose(wr_lap))
            assert (count <= DEPTH);
    assign count_o = count;
    assign rd_lap_o = rd_lap;
    assign rptr_o = rptr;
    assign wptr_o = wptr;
    assign wr_lap_o = wr_lap;
endmodule

module qp_zins_mux #(
    parameter DEPTH = 16,
    parameter DW = 32,
    parameter SW = $clog2(DEPTH)
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_load,
    input  wire [31:0]   i_limit,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [SW-1:0] in_qp,
    input  wire [DW-1:0] in_data,
    input  wire          i_drain,
    output wire [DW-1:0] o_data,
    output wire          o_valid
,
    output wire [31:0] cnt_o,
    output wire [DEPTH-1:0] mask_o
);
    reg [DEPTH*DW-1:0] data_flat;
    reg [DEPTH-1:0]    mask;
    reg [SW-1:0]       sel;
    reg [31:0]         cnt;
    reg [31:0]         limit;
    reg                win;

    initial data_flat = {(DEPTH*DW){1'b0}};
    initial mask = {DEPTH{1'b0}};
    initial sel = {SW{1'b0}};
    initial cnt = 32'd0;
    initial limit = DEPTH;
    initial win = 1'b0;

    wire hit = mask[sel];
    assign in_ready = !mask[in_qp] && (cnt < limit);
    wire in_fire = in_valid && in_ready;
    wire drn_hit = i_drain && hit;

    wire [DEPTH-1:0] one_m = {{(DEPTH-1){1'b0}}, 1'b1};
    wire [DEPTH-1:0] set_m = in_fire ? (one_m << in_qp) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_m = drn_hit ? (one_m << sel) : {DEPTH{1'b0}};

    // zero-insertion multiplexer: selected slot if valid, else constant zero
    assign o_valid = hit;
    assign o_data  = hit ? data_flat[sel*DW +: DW] : {DW{1'b0}};

    always @(posedge clk) begin
        if (i_reset) begin
            mask  <= {DEPTH{1'b0}};
            sel   <= {SW{1'b0}};
            cnt   <= 32'd0;
            win   <= 1'b0;
            limit <= i_limit;
        end else begin
            if (i_load)
                limit <= i_limit;
            if (in_fire)
                data_flat[in_qp*DW +: DW] <= in_data;
            mask <= (mask & ~clr_m) | set_m;
            cnt  <= cnt + (in_fire ? 32'd1 : 32'd0) - (drn_hit ? 32'd1 : 32'd0);
            if (i_drain)
                sel <= (sel == DEPTH-1) ? {SW{1'b0}} : sel + 1'b1;
            if (i_load)
                win <= 1'b0;
            else if (in_fire)
                win <= 1'b1;
        end
    end

    always @(posedge clk)
        if (win) assert (cnt <= DEPTH);

    always @(posedge clk)
        if (win) assert (cnt != 32'd0 || o_data == {DW{1'b0}});
    assign cnt_o = cnt;
    assign mask_o = mask;
endmodule

module ddr3_qp_window #(
    parameter DW = 32,
    parameter QDEPTH = 4,
    parameter FLIGHT_LIMIT = 8
) (
    input wire clk,
    input wire i_reset,
    input wire in_valid,
    output wire in_ready,
    input wire [DW-1:0] in_data,
    input wire cfg_load,
    input wire [31:0] cfg_wm,
    input wire i_load,
    input wire [31:0] i_limit,
    input wire i_drain,
    output wire [DW-1:0] o_data,
    output wire o_valid,
    output wire almost_full,
    output wire [31:0] occupancy,
    output wire [31:0] a_count_o,
    output wire [3:0] a_rptr_o,
    output wire [3:0] a_wptr_o,
    output wire a_rd_lap_o,
    output wire a_wr_lap_o,
    output wire a_out_valid,
    output wire a_out_ready,
    output wire [DW-1:0] a_out_data,
    output wire [31:0] b_cnt_o,
    output wire [15:0] b_mask_o,
    output reg [$clog2(QDEPTH+1)-1:0] q_count_o,
    output reg [$clog2(QDEPTH)-1:0] q_rptr_o,
    output reg [$clog2(QDEPTH)-1:0] q_wptr_o,
    output reg [$clog2(FLIGHT_LIMIT+1)-1:0] flight_o
);
    localparam A_DEPTH = 12;
    localparam B_DEPTH = 16;
    localparam SW = $clog2(B_DEPTH);
    localparam QAW = $clog2(QDEPTH);
    localparam QCW = $clog2(QDEPTH+1);
    localparam FCW = $clog2(FLIGHT_LIMIT+1);
    localparam [QAW-1:0] QLAST = QDEPTH-1;

    reg [DW-1:0] q_mem [0:QDEPTH-1];
    wire [DW-1:0] q_head = q_mem[q_rptr_o];
    wire [SW-1:0] b_in_qp = q_head[SW-1:0];
    wire b_in_ready;
    wire b_in_valid = !i_reset && (q_count_o != 0);
    wire q_push = a_out_valid && a_out_ready;
    wire q_pop = b_in_valid && b_in_ready;
    wire retire = !i_reset && i_drain && o_valid;

    // Reserve an end-to-end credit until the selected QP is drained.
    assign a_out_ready = !i_reset && (q_count_o < QDEPTH) &&
                         (flight_o < FLIGHT_LIMIT);

    ddr3_cmd_queue #(.DEPTH(A_DEPTH), .DW(DW)) cmd_queue (
        .clk(clk), .in_valid(in_valid), .in_ready(in_ready),
        .in_data(in_data), .out_valid(a_out_valid),
        .out_ready(a_out_ready), .out_data(a_out_data),
        .cfg_load(cfg_load), .cfg_wm(cfg_wm),
        .almost_full(almost_full), .occupancy(occupancy),
        .count_o(a_count_o), .rd_lap_o(a_rd_lap_o),
        .rptr_o(a_rptr_o), .wptr_o(a_wptr_o),
        .wr_lap_o(a_wr_lap_o)
    );

    qp_zins_mux #(.DEPTH(B_DEPTH), .DW(DW), .SW(SW)) qp_mux (
        .clk(clk), .i_reset(i_reset), .i_load(i_load),
        .i_limit(i_limit), .in_valid(b_in_valid),
        .in_ready(b_in_ready), .in_qp(b_in_qp),
        .in_data(q_head), .i_drain(i_drain), .o_data(o_data),
        .o_valid(o_valid), .cnt_o(b_cnt_o), .mask_o(b_mask_o)
    );

    integer j;
    initial begin
        q_count_o = {QCW{1'b0}};
        q_rptr_o = {QAW{1'b0}};
        q_wptr_o = {QAW{1'b0}};
        flight_o = {FCW{1'b0}};
        for (j = 0; j < QDEPTH; j = j + 1)
            q_mem[j] = {DW{1'b0}};
    end

    always @(posedge clk) begin
        if (i_reset) begin
            q_count_o <= {QCW{1'b0}};
            q_rptr_o <= {QAW{1'b0}};
            q_wptr_o <= {QAW{1'b0}};
            flight_o <= {FCW{1'b0}};
            for (j = 0; j < QDEPTH; j = j + 1)
                q_mem[j] <= {DW{1'b0}};
        end else begin
            if (q_push) begin
                q_mem[q_wptr_o] <= a_out_data;
                q_wptr_o <= (q_wptr_o == QLAST) ?
                            {QAW{1'b0}} : q_wptr_o + 1'b1;
            end
            if (q_pop)
                q_rptr_o <= (q_rptr_o == QLAST) ?
                            {QAW{1'b0}} : q_rptr_o + 1'b1;
            case ({q_push, q_pop})
                2'b10: q_count_o <= q_count_o + 1'b1;
                2'b01: q_count_o <= q_count_o - 1'b1;
                default: q_count_o <= q_count_o;
            endcase
            case ({q_push, retire})
                2'b10: flight_o <= flight_o + 1'b1;
                2'b01: flight_o <= flight_o - 1'b1;
                default: flight_o <= flight_o;
            endcase
        end
    end

    always @(posedge clk)
        assert ((q_count_o + b_cnt_o) <= FLIGHT_LIMIT);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
endmodule

module ntt_phase_dispatch #(
    parameter W = 16,
    parameter PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire clk,
    input  wire cfg_valid,
    output wire cfg_ready,
    input  wire [W-1:0] cfg_data,
    input  wire [W-1:0] profile_select,
    input  wire start,
    input  wire run,
    input  wire finish,
    input  wire [W-1:0] remaining,
    input  wire [W-1:0] launch_latency,
    output reg  [W-1:0] step = 16'd0,
    output reg  [W-1:0] quantum = 16'd1,
    output wire [W*PROFILES-1:0] profiles,
    output reg  [1:0] cfg_state = 2'd0,
    output reg  [$clog2(PROFILES)-1:0] cfg_index = 0,
    output reg  [W-1:0] cfg_pending = 16'd0,
    output reg  [W-1:0] cfg_prepared = 16'd1,
    output wire cfg_apply
);
    localparam INDEX_W = $clog2(PROFILES);
    localparam [INDEX_W-1:0] LAST_PROFILE = PROFILES - 1;
    reg [W-1:0] cap [0:PROFILES-1];
    wire [INDEX_W-1:0] selected = profile_select % PROFILES;
    integer init_profile;
    initial begin
        for (init_profile = 0; init_profile < PROFILES; init_profile = init_profile + 1) begin
            cap[init_profile] = 16'd1;
        end
    end
    genvar p;
    generate
        for (p = 0; p < PROFILES; p = p + 1) begin: expose_profiles
            assign profiles[p*W +: W] = cap[p];
        end
    endgenerate
    assign cfg_ready = (cfg_state == 2'd0);
    assign cfg_apply = (cfg_state == 2'd2);

    function [W-1:0] choose_step;
        input [W-1:0] left;
        input [W-1:0] limit;
        begin
            if (left <= 16'd1)
                choose_step = 16'd1;
            else if (left - 16'd1 < limit)
                choose_step = left - 16'd1;
            else
                choose_step = limit;
        end
    endfunction

    always @(posedge clk) begin
        case (cfg_state)
            2'd0: begin
                if (cfg_valid && cfg_ready) begin
                    cfg_pending <= cfg_data;
                    cfg_state <= 2'd1;
                end
            end
            2'd1: begin
                if (cfg_pending == 16'd0)
                    cfg_prepared <= 16'd1;
                else if (cfg_pending > MAX_BURST)
                    cfg_prepared <= MAX_BURST;
                else
                    cfg_prepared <= cfg_pending;
                cfg_state <= 2'd2;
            end
            2'd2: begin
                cap[cfg_index] <= cfg_prepared;
                if (cfg_index == LAST_PROFILE)
                    cfg_index <= {INDEX_W{1'b0}};
                else
                    cfg_index <= cfg_index + 1'b1;
                cfg_state <= 2'd0;
            end
            default: cfg_state <= 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (start) begin
            quantum <= cap[selected];
            step <= choose_step(launch_latency, cap[selected]);
        end else if (finish) begin
            step <= 16'd0;
        end else if (run) begin
            step <= choose_step(remaining - step, quantum);
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter BURST_PROFILES = 4,
    parameter MAX_BURST = 4,
    parameter JOURNAL_DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output wire         cfg_ready,
    output wire         cfg_busy,
    output wire [W-1:0] burst_step,
    output wire [W*BURST_PROFILES-1:0] burst_profiles,
    output wire         journal_ready,
    output wire [$clog2(JOURNAL_DEPTH):0] journal_queued,
    output wire         telemetry_valid,
    output wire [W-1:0] telemetry_stage,
    output wire [W-1:0] telemetry_budget,
    output wire [W-1:0] telemetry_issued,
    output wire [W-1:0] telemetry_saved,
    output wire [W-1:0] telemetry_paused,
    output wire [W*STAGES-1:0] stage_samples,
    output wire [W*STAGES-1:0] stage_budget_totals,
    output wire [W*STAGES-1:0] stage_issue_totals,
    output wire [W*STAGES-1:0] stage_saving_totals,
    output wire [W*STAGES-1:0] stage_pause_totals,
    output wire [W*STAGES-1:0] stage_min_issues,
    output wire [W*STAGES-1:0] stage_max_issues,
    output wire [W*STAGES-1:0] stage_peak_budgets
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam JOURNAL_ADDR_W = $clog2(JOURNAL_DEPTH);
    localparam JOURNAL_PTR_W = JOURNAL_ADDR_W + 1;
    localparam STAGE_ADDR_W = (STAGES > 1) ? $clog2(STAGES) : 1;
    localparam [JOURNAL_ADDR_W-1:0] LAST_JOURNAL = JOURNAL_DEPTH - 1;
    localparam [1:0] AUDIT_IDLE = 2'd0;
    localparam [1:0] AUDIT_MEASURE = 2'd1;
    localparam [1:0] AUDIT_ACCUMULATE = 2'd2;
    localparam [1:0] AUDIT_COMMIT = 2'd3;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    reg [W-1:0] issued_steps = 16'd0;
    reg [W-1:0] pause_cycles = 16'd0;
    reg [W-1:0] event_budget [0:JOURNAL_DEPTH-1];
    reg [W-1:0] event_issued [0:JOURNAL_DEPTH-1];
    reg [W-1:0] event_paused [0:JOURNAL_DEPTH-1];
    reg [STAGE_ADDR_W-1:0] event_stage [0:JOURNAL_DEPTH-1];
    reg [JOURNAL_PTR_W-1:0] journal_wr = {JOURNAL_PTR_W{1'b0}};
    reg [JOURNAL_PTR_W-1:0] journal_rd = {JOURNAL_PTR_W{1'b0}};
    reg [1:0] audit_state = AUDIT_IDLE;
    reg [W-1:0] audit_budget = 16'd1;
    reg [W-1:0] audit_issued = 16'd1;
    reg [W-1:0] audit_saved = 16'd0;
    reg [W-1:0] audit_paused = 16'd0;
    reg [STAGE_ADDR_W-1:0] audit_tag = {STAGE_ADDR_W{1'b0}};
    reg [W-1:0] pending_samples = 16'd0;
    reg [W-1:0] pending_budget = 16'd0;
    reg [W-1:0] pending_issued = 16'd0;
    reg [W-1:0] pending_saved = 16'd0;
    reg [W-1:0] pending_paused = 16'd0;
    reg [W-1:0] pending_min = 16'd0;
    reg [W-1:0] pending_max = 16'd0;
    reg [W-1:0] pending_peak_budget = 16'd0;
    reg [W-1:0] stat_samples [0:STAGES-1];
    reg [W-1:0] stat_budget [0:STAGES-1];
    reg [W-1:0] stat_issued [0:STAGES-1];
    reg [W-1:0] stat_saved [0:STAGES-1];
    reg [W-1:0] stat_paused [0:STAGES-1];
    reg [W-1:0] stat_min [0:STAGES-1];
    reg [W-1:0] stat_max [0:STAGES-1];
    reg [W-1:0] stat_peak_budget [0:STAGES-1];
    integer init_journal;
    integer init_stat;
    wire [JOURNAL_ADDR_W-1:0] journal_head = journal_rd[JOURNAL_ADDR_W-1:0];
    wire journal_empty = (journal_wr == journal_rd);
    wire journal_full = (journal_wr[JOURNAL_ADDR_W] != journal_rd[JOURNAL_ADDR_W]) &&
                        (journal_wr[JOURNAL_ADDR_W-1:0] == journal_rd[JOURNAL_ADDR_W-1:0]);
    wire journal_pop = ce && (audit_state == AUDIT_IDLE) &&
                       !journal_empty;
    wire [JOURNAL_PTR_W:0] telemetry_held;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    initial begin
        for (init_journal = 0; init_journal < JOURNAL_DEPTH; init_journal = init_journal + 1) begin
            event_budget[init_journal] = 16'd0;
            event_issued[init_journal] = 16'd0;
            event_paused[init_journal] = 16'd0;
            event_stage[init_journal] = {STAGE_ADDR_W{1'b0}};
        end
        for (init_stat = 0; init_stat < STAGES; init_stat = init_stat + 1) begin
            stat_samples[init_stat] = 16'd0;
            stat_budget[init_stat] = 16'd0;
            stat_issued[init_stat] = 16'd0;
            stat_saved[init_stat] = 16'd0;
            stat_paused[init_stat] = 16'd0;
            stat_min[init_stat] = 16'd0;
            stat_max[init_stat] = 16'd0;
            stat_peak_budget[init_stat] = 16'd0;
        end
    end
    function [W-1:0] saturated_add;
        input [W-1:0] left;
        input [W-1:0] right;
        reg [W:0] total;
        begin
            total = {1'b0, left} + {1'b0, right};
            if (total[W])
                saturated_add = {W{1'b1}};
            else
                saturated_add = total[W-1:0];
        end
    endfunction
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;
    assign journal_ready = !journal_full;
    assign journal_queued = (journal_wr[JOURNAL_ADDR_W] == journal_rd[JOURNAL_ADDR_W]) ?
        ({1'b0, journal_wr[JOURNAL_ADDR_W-1:0]} - {1'b0, journal_rd[JOURNAL_ADDR_W-1:0]}) :
        (JOURNAL_DEPTH + {1'b0, journal_wr[JOURNAL_ADDR_W-1:0]} - {1'b0, journal_rd[JOURNAL_ADDR_W-1:0]});
    assign telemetry_held = {1'b0, journal_queued} +
        ((audit_state != AUDIT_IDLE) ? 1'b1 : 1'b0);
    assign telemetry_valid = ce && (audit_state == AUDIT_COMMIT);
    assign telemetry_stage = audit_tag;
    assign telemetry_budget = audit_budget;
    assign telemetry_issued = audit_issued;
    assign telemetry_saved = audit_saved;
    assign telemetry_paused = audit_paused;
    genvar s;
    generate
        for (s = 0; s < STAGES; s = s + 1) begin: expose_stage_statistics
            assign stage_samples[s*W +: W] = stat_samples[s];
            assign stage_budget_totals[s*W +: W] = stat_budget[s];
            assign stage_issue_totals[s*W +: W] = stat_issued[s];
            assign stage_saving_totals[s*W +: W] = stat_saved[s];
            assign stage_pause_totals[s*W +: W] = stat_paused[s];
            assign stage_min_issues[s*W +: W] = stat_min[s];
            assign stage_max_issues[s*W +: W] = stat_max[s];
            assign stage_peak_budgets[s*W +: W] = stat_peak_budget[s];
        end
    endgenerate

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last && journal_ready;
    wire [W-1:0] burst_quantum;
    wire [1:0] cfg_state;
    wire [$clog2(BURST_PROFILES)-1:0] cfg_write_index;
    wire [W-1:0] cfg_pending;
    wire [W-1:0] cfg_prepared;
    wire cfg_apply;
    assign cfg_busy = (cfg_state != 2'd0);

    ntt_phase_dispatch #(
        .W(W), .PROFILES(BURST_PROFILES), .MAX_BURST(MAX_BURST)
    ) phase_dispatch (
        .clk(clk), .cfg_valid(load_cfg), .cfg_ready(cfg_ready),
        .cfg_data(cfg_lat), .profile_select(stage),
        .start(start), .run(busy && ce && !last), .finish(retire),
        .remaining(cd), .launch_latency(lat_q),
        .step(burst_step), .quantum(burst_quantum),
        .profiles(burst_profiles), .cfg_state(cfg_state),
        .cfg_index(cfg_write_index), .cfg_pending(cfg_pending),
        .cfg_prepared(cfg_prepared), .cfg_apply(cfg_apply)
    );

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (cfg_apply) lat_cfg <= cfg_pending;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce && (!last || journal_ready)) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - burst_step;
                phase <= phase + burst_step;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end
    always @(posedge clk) begin
        if (start || retire) begin
            issued_steps <= 16'd0;
            pause_cycles <= 16'd0;
        end else if (busy) begin
            if (ce && !last)
                issued_steps <= issued_steps + 16'd1;
            if (!ce && !last)
                pause_cycles <= saturated_add(pause_cycles, 16'd1);
        end
    end
    always @(posedge clk) begin
        if (retire) begin
            event_budget[journal_wr[JOURNAL_ADDR_W-1:0]] <= lat_q;
            event_issued[journal_wr[JOURNAL_ADDR_W-1:0]] <= issued_steps + 16'd1;
            event_paused[journal_wr[JOURNAL_ADDR_W-1:0]] <= pause_cycles;
            event_stage[journal_wr[JOURNAL_ADDR_W-1:0]] <= stage[STAGE_ADDR_W-1:0];
            if (journal_wr[JOURNAL_ADDR_W-1:0] == LAST_JOURNAL)
                journal_wr <= {!journal_wr[JOURNAL_ADDR_W], {JOURNAL_ADDR_W{1'b0}}};
            else
                journal_wr <= journal_wr + 1'b1;
        end
        if (journal_pop) begin
            if (journal_rd[JOURNAL_ADDR_W-1:0] == LAST_JOURNAL)
                journal_rd <= {!journal_rd[JOURNAL_ADDR_W], {JOURNAL_ADDR_W{1'b0}}};
            else
                journal_rd <= journal_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (ce) begin
            case (audit_state)
                AUDIT_IDLE: begin
                    if (journal_pop) begin
                        audit_budget <= event_budget[journal_head];
                        audit_issued <= event_issued[journal_head];
                        audit_paused <= event_paused[journal_head];
                        audit_tag <= event_stage[journal_head];
                        audit_state <= AUDIT_MEASURE;
                    end
                end
                AUDIT_MEASURE: begin
                    audit_saved <= audit_budget - audit_issued;
                    audit_state <= AUDIT_ACCUMULATE;
                end
                AUDIT_ACCUMULATE: begin
                    pending_samples <= saturated_add(
                        stat_samples[audit_tag], 16'd1);
                    pending_budget <= saturated_add(
                        stat_budget[audit_tag], audit_budget);
                    pending_issued <= saturated_add(
                        stat_issued[audit_tag], audit_issued);
                    pending_saved <= saturated_add(
                        stat_saved[audit_tag], audit_saved);
                    pending_paused <= saturated_add(
                        stat_paused[audit_tag], audit_paused);
                    if ((stat_min[audit_tag] == 16'd0) ||
                        (audit_issued < stat_min[audit_tag]))
                        pending_min <= audit_issued;
                    else
                        pending_min <= stat_min[audit_tag];
                    if (audit_issued > stat_max[audit_tag])
                        pending_max <= audit_issued;
                    else
                        pending_max <= stat_max[audit_tag];
                    if (audit_budget > stat_peak_budget[audit_tag])
                        pending_peak_budget <= audit_budget;
                    else
                        pending_peak_budget <= stat_peak_budget[audit_tag];
                    audit_state <= AUDIT_COMMIT;
                end
                AUDIT_COMMIT: begin
                    stat_samples[audit_tag] <= pending_samples;
                    stat_budget[audit_tag] <= pending_budget;
                    stat_issued[audit_tag] <= pending_issued;
                    stat_saved[audit_tag] <= pending_saved;
                    stat_paused[audit_tag] <= pending_paused;
                    stat_min[audit_tag] <= pending_min;
                    stat_max[audit_tag] <= pending_max;
                    stat_peak_budget[audit_tag] <= pending_peak_budget;
                    audit_state <= AUDIT_IDLE;
                end
                default: audit_state <= AUDIT_IDLE;
            endcase
        end
    end
    always @(posedge clk) begin
        if (telemetry_valid)
            assert ((audit_saved < audit_budget) &&
                    (audit_tag < STAGES));
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module ldpc_edge_ingress #(
    parameter W = 32,
    parameter FRAME = 24,
    parameter DEPTH = 4,
    parameter IW = $clog2(FRAME),
    parameter CW = $clog2(DEPTH + 1)
) (
    input wire clk,
    input wire offer,
    output wire ready,
    input wire [W-1:0] mag_i,
    input wire sign_i,
    input wire take,
    output wire valid,
    output wire [W-1:0] mag_o,
    output wire sign_o,
    output wire [IW-1:0] index_o,
    output reg [CW-1:0] queued,
    output reg [IW-1:0] next_idx,
    output wire [DEPTH*IW-1:0] queued_idx
);
    reg [W-1:0] magnitude [0:DEPTH-1];
    reg polarity [0:DEPTH-1];
    reg [IW-1:0] edge_index [0:DEPTH-1];
    integer i, n;
    wire pop = valid && take;
    wire push = offer && ready;
    assign valid = (queued != 0);
    assign ready = (queued < DEPTH) || pop;
    assign mag_o = magnitude[0];
    assign sign_o = polarity[0];
    assign index_o = edge_index[0];
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin: export_tags
            assign queued_idx[g*IW +: IW] = edge_index[g];
        end
    endgenerate
    initial begin
        queued = 0;
        next_idx = 0;
        for (n = 0; n < DEPTH; n = n + 1) begin
            magnitude[n] = {W{1'b0}};
            polarity[n] = 1'b0;
            edge_index[n] = 0;
        end
    end
    always @(posedge clk) begin
        case ({push, pop})
            2'b10: queued <= queued + 1'b1;
            2'b01: queued <= queued - 1'b1;
            default: queued <= queued;
        endcase
        if (pop) begin
            for (i = 0; i < DEPTH-1; i = i + 1) begin
                magnitude[i] <= magnitude[i+1];
                polarity[i] <= polarity[i+1];
                edge_index[i] <= edge_index[i+1];
            end
        end
        if (push) begin
            magnitude[queued - pop] <= mag_i;
            polarity[queued - pop] <= sign_i;
            edge_index[queued - pop] <= next_idx;
            if (next_idx == FRAME - 1)
                next_idx <= 0;
            else
                next_idx <= next_idx + 1'b1;
        end
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] pending_edges
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    localparam IIW = $clog2(DEG);
    wire ingress_valid, ingress_sign;
    wire [W-1:0] ingress_mag;
    wire [IIW-1:0] ingress_idx, ingress_next_idx;
    wire [INGRESS_DEPTH*IIW-1:0] ingress_tags;
    wire ingress_take = (state == S_ACCUM);
    ldpc_edge_ingress #(
        .W(W), .FRAME(DEG), .DEPTH(INGRESS_DEPTH)
    ) ingress (
        .clk(clk), .offer(in_valid), .ready(in_ready),
        .mag_i(in_mag), .sign_i(in_sign), .take(ingress_take),
        .valid(ingress_valid), .mag_o(ingress_mag),
        .sign_o(ingress_sign), .index_o(ingress_idx),
        .queued(pending_edges), .next_idx(ingress_next_idx),
        .queued_idx(ingress_tags)
    );
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = ingress_valid && ingress_take;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ ingress_sign;
            if (ingress_mag < min1) begin
                min2    <= min1;
                min1    <= ingress_mag;
                min_idx <= ingress_idx;
            end else if (ingress_mag < min2) begin
                min2 <= ingress_mag;
            end
            if (ingress_idx == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
    always @(posedge clk) if (pv && rel && ingress_valid) assert (ingress_idx == 0);
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
    parameter TILE_COLS = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
    output wire busy
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = pipeline_active && (bridge_level != 0);
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0);

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(o_valid), .out_ready(o_ready), .out_data(o_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
parameter DEPTH = 4,
parameter TRACE_DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
output wire         head_cached,
output wire         trace_valid,
output reg  [W-1:0] trace_data,
output wire [2:0]   trace_kind,
output wire         trace_last,
output wire [$clog2(TRACE_DEPTH):0] trace_pending,
output wire         completion_wait
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam TRACE_ADDR_W = $clog2(TRACE_DEPTH);
    localparam TRACE_PTR_W = TRACE_ADDR_W + 1;
    localparam [TRACE_ADDR_W-1:0] TRACE_LAST_SLOT = TRACE_DEPTH - 1;
    localparam TRACE_WORDS = 8;
    localparam TRACE_WORD_W = $clog2(TRACE_WORDS);

    reg [W-1:0] trace_stage_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_bf_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_a_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_b_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_w_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_cycles_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_sum_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_dif_mem [0:TRACE_DEPTH-1];
    reg [TRACE_PTR_W-1:0] trace_wr = {TRACE_PTR_W{1'b0}};
    reg [TRACE_PTR_W-1:0] trace_rd = {TRACE_PTR_W{1'b0}};
    reg [W-1:0] trace_stage_r = 16'd0;
    reg [W-1:0] trace_bf_r = 16'd0;
    reg [W-1:0] trace_a_r = 16'd0;
    reg [W-1:0] trace_b_r = 16'd0;
    reg [W-1:0] trace_w_r = 16'd0;
    reg [W-1:0] trace_cycles_r = 16'd0;
    reg [W-1:0] trace_sum_r = 16'd0;
    reg [W-1:0] trace_dif_r = 16'd0;
    reg trace_active = 1'b0;
    reg [TRACE_WORD_W-1:0] trace_word = {TRACE_WORD_W{1'b0}};
    integer trace_init;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    wire [TRACE_ADDR_W-1:0] trace_head_slot = trace_rd[TRACE_ADDR_W-1:0];
    wire [TRACE_ADDR_W-1:0] trace_tail_slot =
        (trace_wr[TRACE_ADDR_W-1:0] == 0) ? TRACE_LAST_SLOT : trace_wr[TRACE_ADDR_W-1:0] - 1'b1;
    wire trace_empty = (trace_wr == trace_rd);
    wire trace_full = (trace_wr[TRACE_ADDR_W] != trace_rd[TRACE_ADDR_W]) &&
                      (trace_wr[TRACE_ADDR_W-1:0] == trace_rd[TRACE_ADDR_W-1:0]);
    wire trace_load = ce && !trace_active && !trace_empty;
    wire trace_beat = trace_active && out_ready;
    wire trace_pop = trace_beat && trace_last;
    assign trace_valid = trace_active;
    assign trace_kind = trace_word;
    assign trace_last = (trace_word == TRACE_WORDS - 1);
    assign completion_wait = busy && trace_full && (phase == lat_q - 16'd1);
    assign trace_pending = (trace_wr[TRACE_ADDR_W] == trace_rd[TRACE_ADDR_W]) ?
        ({1'b0, trace_wr[TRACE_ADDR_W-1:0]} - {1'b0, trace_rd[TRACE_ADDR_W-1:0]}) :
        (TRACE_DEPTH + {1'b0, trace_wr[TRACE_ADDR_W-1:0]} - {1'b0, trace_rd[TRACE_ADDR_W-1:0]});

    initial begin
        for (trace_init = 0; trace_init < TRACE_DEPTH; trace_init = trace_init + 1) begin
            trace_stage_mem[trace_init] = 16'd0;
            trace_bf_mem[trace_init] = 16'd0;
            trace_a_mem[trace_init] = 16'd0;
            trace_b_mem[trace_init] = 16'd0;
            trace_w_mem[trace_init] = 16'd0;
            trace_cycles_mem[trace_init] = 16'd0;
            trace_sum_mem[trace_init] = 16'd0;
            trace_dif_mem[trace_init] = 16'd0;
        end
    end

    always @(*) begin
        case (trace_word)
            3'd0: trace_data = trace_stage_r;
            3'd1: trace_data = trace_bf_r;
            3'd2: trace_data = trace_a_r;
            3'd3: trace_data = trace_b_r;
            3'd4: trace_data = trace_w_r;
            3'd5: trace_data = trace_cycles_r;
            3'd6: trace_data = trace_sum_r;
            3'd7: trace_data = trace_dif_r;
            default: trace_data = 16'd0;
        endcase
    end

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
wire retire = busy && ce && last && !trace_full;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (retire) begin
            trace_stage_mem[trace_wr[TRACE_ADDR_W-1:0]] <= stage;
            trace_bf_mem[trace_wr[TRACE_ADDR_W-1:0]] <= bf_idx;
            trace_a_mem[trace_wr[TRACE_ADDR_W-1:0]] <= a_r;
            trace_b_mem[trace_wr[TRACE_ADDR_W-1:0]] <= b_r;
            trace_w_mem[trace_wr[TRACE_ADDR_W-1:0]] <= w_r;
            trace_cycles_mem[trace_wr[TRACE_ADDR_W-1:0]] <= phase + 16'd1;
            trace_sum_mem[trace_wr[TRACE_ADDR_W-1:0]] <= sum_mod;
            trace_dif_mem[trace_wr[TRACE_ADDR_W-1:0]] <= dif_mod;
            if (trace_wr[TRACE_ADDR_W-1:0] == TRACE_LAST_SLOT)
                trace_wr <= {!trace_wr[TRACE_ADDR_W], {TRACE_ADDR_W{1'b0}}};
            else
                trace_wr <= trace_wr + 1'b1;
        end
        if (trace_pop) begin
            if (trace_rd[TRACE_ADDR_W-1:0] == TRACE_LAST_SLOT)
                trace_rd <= {!trace_rd[TRACE_ADDR_W], {TRACE_ADDR_W{1'b0}}};
            else
                trace_rd <= trace_rd + 1'b1;
        end
    end

    always @(posedge clk) begin
        if (trace_load) begin
            trace_stage_r <= trace_stage_mem[trace_head_slot];
            trace_bf_r <= trace_bf_mem[trace_head_slot];
            trace_a_r <= trace_a_mem[trace_head_slot];
            trace_b_r <= trace_b_mem[trace_head_slot];
            trace_w_r <= trace_w_mem[trace_head_slot];
            trace_cycles_r <= trace_cycles_mem[trace_head_slot];
            trace_sum_r <= trace_sum_mem[trace_head_slot];
            trace_dif_r <= trace_dif_mem[trace_head_slot];
            trace_active <= 1'b1;
            trace_word <= {TRACE_WORD_W{1'b0}};
        end else if (trace_beat) begin
            if (trace_pop) begin
                trace_active <= 1'b0;
                trace_word <= {TRACE_WORD_W{1'b0}};
            end else begin
                trace_word <= trace_word + 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (trace_active)
            assert ((trace_cycles_r != 16'd0) &&
                    (trace_stage_r < STAGES) && (trace_bf_r < NBF) &&
                    (!(out_valid && (trace_pending == 1)) ||
                     ((trace_sum_r == out_a) && (trace_dif_r == out_b))));
    end

    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
end else if (busy && ce && (!last || !trace_full)) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
output wire [1:0]   o_rem,
input  wire         peer_valid, peer_bit, peer_clr,
output wire         peer_ready, peer_done, peer_div3,
output wire [1:0]   peer_rem,
output wire [W-1:0] peer_value
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;
localparam integer CHANNELS = 2, PCW = $clog2(MAXBITS + 1);

    reg [1:0]   phase   = S_IDLE;
wire [1:0] rem;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;
reg [$clog2(CHANNELS)-1:0] owner = 0;
reg [1:0] alu_rem = 2'd0, parked_rem = 2'd0;
reg [W-1:0] peer_val = {W{1'b0}};
reg [PCW-1:0] peer_cnt = {PCW{1'b0}};

wire lane_active = (phase == S_ARM) || (phase == S_RUN);
wire grant_peer = peer_valid && !peer_done && (!lane_active || !in_valid || owner == 0);
assign in_ready = lane_active && !grant_peer;
assign peer_ready = !peer_done && (!lane_active || !in_valid || owner == 0);
    wire acc = in_valid && in_ready;
wire peer_acc = peer_valid && peer_ready;

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;
assign rem = (owner == 0) ? alu_rem : parked_rem;
assign peer_rem = (owner == 0) ? parked_rem : alu_rem;
assign peer_done = (peer_cnt == MAXBITS);
assign peer_div3 = (peer_rem == 2'd0);
assign peer_value = peer_val;
wire main_clear = ((phase == S_IDLE) && arm) || ((phase == S_DONE) && clr);
wire peer_clear = peer_done && peer_clr;
wire [1:0] active_ctx = (owner ? peer_clear : main_clear) ? 2'd0 : alu_rem;
wire [1:0] parked_ctx = (owner ? main_clear : peer_clear) ? 2'd0 : parked_rem;
always @(posedge clk) begin
    if (acc || peer_acc) begin
        alu_rem <= rnext((owner == grant_peer) ? active_ctx : parked_ctx,
                         grant_peer ? peer_bit : in_bit);
        parked_rem <= (owner == grant_peer) ? parked_ctx : active_ctx;
        owner <= grant_peer;
    end else begin
        alu_rem <= active_ctx;
        parked_rem <= parked_ctx;
    end
    if (peer_clear) begin
        peer_cnt <= {PCW{1'b0}};
        peer_val <= {W{1'b0}};
    end else if (peer_acc) begin
        peer_cnt <= peer_cnt + 1'b1;
        peer_val <= {peer_val[W-2:0], peer_bit};
    end
end

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (acc) begin
            val     <= {val[W-2:0], in_bit};
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
always @(posedge clk)
    if (peer_done)
        assert (peer_div3 == ((peer_val % 16'd3) == 16'd0));
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
parameter TILE_COLS = 4,
parameter ANALYTICS_DEPTH = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
output wire busy,
output wire analysis_ready,
output wire [$clog2(ANALYTICS_DEPTH):0] analysis_level,
output reg analysis_enabled,
output reg analysis_report_valid,
output reg [7:0] analysis_min_y,
output reg [7:0] analysis_max_y,
output reg [7:0] analysis_peak_edge,
output reg [7:0] analysis_chroma_separation,
output reg [23:0] analysis_first_pixel,
output reg [23:0] analysis_last_pixel
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

    localparam ANALYSIS_PTR_W = $clog2(ANALYTICS_DEPTH);
    localparam TILE_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    reg [23:0] analysis_pixels [0:ANALYTICS_DEPTH-1];
    reg [TILE_POS_W-1:0] analysis_pos [0:ANALYTICS_DEPTH-1];
    reg [ANALYSIS_PTR_W:0] analysis_rd_ptr, analysis_wr_ptr;
    reg [TILE_POS_W-1:0] analysis_cursor;
    reg analysis_work_valid, analysis_work_phase;
    reg analysis_work_first, analysis_work_last;
    reg [23:0] analysis_work_pixel;
    reg [TILE_POS_W-1:0] analysis_work_pos;
    reg [7:0] analysis_min_acc, analysis_max_acc;
    reg [7:0] analysis_edge_acc, analysis_chroma_acc;
    reg [7:0] analysis_previous_y;
    reg [23:0] analysis_first_acc;
    reg [7:0] analysis_next_min, analysis_next_max;
    reg [7:0] analysis_next_edge, analysis_next_chroma;
    reg [7:0] analysis_y_delta, analysis_chroma_delta;
    integer aj;

    wire bridge_offer = pipeline_active && (bridge_level != 0);
    wire analysis_empty = analysis_rd_ptr == analysis_wr_ptr;
    wire analysis_full =
        (analysis_rd_ptr[ANALYSIS_PTR_W-1:0] ==
         analysis_wr_ptr[ANALYSIS_PTR_W-1:0]) &&
        (analysis_rd_ptr[ANALYSIS_PTR_W] !=
         analysis_wr_ptr[ANALYSIS_PTR_W]);
    wire analysis_take = analysis_enabled && !analysis_empty &&
                         !analysis_work_valid;
    wire analysis_put = bridge_pop;
    wire analysis_finish = analysis_work_valid && analysis_work_phase;
    wire [23:0] analysis_head_pixel =
        analysis_pixels[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [TILE_POS_W-1:0] analysis_head_pos =
        analysis_pos[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [7:0] analysis_y = analysis_work_pixel[23:16];
    wire [7:0] analysis_cb = analysis_work_pixel[15:8];
    wire [7:0] analysis_cr = analysis_work_pixel[7:0];
    wire [ANALYSIS_PTR_W+1:0] analysis_held =
        {1'b0, analysis_level} + analysis_work_valid;

    function [ANALYSIS_PTR_W:0] analysis_advance;
        input [ANALYSIS_PTR_W:0] ptr;
        begin
            if (ptr[ANALYSIS_PTR_W-1:0] == ANALYTICS_DEPTH-1)
                analysis_advance = {!ptr[ANALYSIS_PTR_W],
                                    {ANALYSIS_PTR_W{1'b0}}};
            else
                analysis_advance = ptr + 1'b1;
        end
    endfunction

    assign analysis_level =
        (analysis_wr_ptr[ANALYSIS_PTR_W] ==
         analysis_rd_ptr[ANALYSIS_PTR_W])
        ? analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0]
        : ANALYTICS_DEPTH + analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0];
    assign analysis_ready = !analysis_full || analysis_take;

    // Row boundaries suppress transitions between unrelated row endpoints.
    always @(*) begin
        analysis_y_delta = (analysis_y >= analysis_previous_y)
                         ? analysis_y - analysis_previous_y
                         : analysis_previous_y - analysis_y;
        analysis_chroma_delta = (analysis_cb >= analysis_cr)
                              ? analysis_cb - analysis_cr
                              : analysis_cr - analysis_cb;
        analysis_next_min = analysis_min_acc;
        analysis_next_max = analysis_max_acc;
        analysis_next_edge = analysis_edge_acc;
        analysis_next_chroma = analysis_chroma_acc;
        if (analysis_work_first) begin
            analysis_next_min = analysis_y;
            analysis_next_max = analysis_y;
            analysis_next_edge = 8'd0;
            analysis_next_chroma = analysis_chroma_delta;
        end else begin
            if (analysis_y < analysis_min_acc)
                analysis_next_min = analysis_y;
            if (analysis_y > analysis_max_acc)
                analysis_next_max = analysis_y;
            if (analysis_chroma_delta > analysis_chroma_acc)
                analysis_next_chroma = analysis_chroma_delta;
        end
        if ((analysis_work_pos % TILE_COLS) != 0 &&
            analysis_y_delta > analysis_next_edge)
            analysis_next_edge = analysis_y_delta;
    end

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = bridge_offer && analysis_ready;
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0);

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(o_valid), .out_ready(o_ready), .out_data(o_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    initial begin
        analysis_rd_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_wr_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_cursor = {TILE_POS_W{1'b0}};
        analysis_enabled = 1'b1;
        analysis_work_valid = 1'b0;
        analysis_work_phase = 1'b0;
        analysis_work_first = 1'b0;
        analysis_work_last = 1'b0;
        analysis_work_pixel = 24'd0;
        analysis_work_pos = {TILE_POS_W{1'b0}};
        analysis_min_acc = 8'hff;
        analysis_max_acc = 8'd0;
        analysis_edge_acc = 8'd0;
        analysis_chroma_acc = 8'd0;
        analysis_previous_y = 8'd0;
        analysis_first_acc = 24'd0;
        analysis_report_valid = 1'b0;
        analysis_min_y = 8'd0;
        analysis_max_y = 8'd0;
        analysis_peak_edge = 8'd0;
        analysis_chroma_separation = 8'd0;
        analysis_first_pixel = 24'd0;
        analysis_last_pixel = 24'd0;
        for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
            analysis_pixels[aj] = 24'd0;
            analysis_pos[aj] = {TILE_POS_W{1'b0}};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            analysis_rd_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_wr_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_cursor <= {TILE_POS_W{1'b0}};
            analysis_enabled <= 1'b1;
            analysis_work_valid <= 1'b0;
            analysis_work_phase <= 1'b0;
            analysis_work_first <= 1'b0;
            analysis_work_last <= 1'b0;
            analysis_work_pixel <= 24'd0;
            analysis_work_pos <= {TILE_POS_W{1'b0}};
            analysis_min_acc <= 8'hff;
            analysis_max_acc <= 8'd0;
            analysis_edge_acc <= 8'd0;
            analysis_chroma_acc <= 8'd0;
            analysis_previous_y <= 8'd0;
            analysis_first_acc <= 24'd0;
            analysis_report_valid <= 1'b0;
            analysis_min_y <= 8'd0;
            analysis_max_y <= 8'd0;
            analysis_peak_edge <= 8'd0;
            analysis_chroma_separation <= 8'd0;
            analysis_first_pixel <= 24'd0;
            analysis_last_pixel <= 24'd0;
            for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
                analysis_pixels[aj] <= 24'd0;
                analysis_pos[aj] <= {TILE_POS_W{1'b0}};
            end
        end else begin
            analysis_report_valid <= 1'b0;
            if (cfg_we && cfg_addr == 4'd9)
                analysis_enabled <= cfg_data[1];

            // Fork only transfers that were also accepted by the tile.
            if (analysis_put) begin
                analysis_pixels[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_in_data;
                analysis_pos[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_wr_row * TILE_COLS + b_wr_col;
                analysis_wr_ptr <= analysis_advance(analysis_wr_ptr);
            end
            if (analysis_take) begin
                analysis_work_valid <= 1'b1;
                analysis_work_phase <= 1'b0;
                analysis_work_pixel <= analysis_head_pixel;
                analysis_work_pos <= analysis_head_pos;
                analysis_work_first <= analysis_cursor == 0;
                analysis_work_last <= analysis_cursor == TILE_PIXELS-1;
                analysis_rd_ptr <= analysis_advance(analysis_rd_ptr);
                analysis_cursor <= (analysis_cursor == TILE_PIXELS-1)
                                 ? {TILE_POS_W{1'b0}}
                                 : analysis_cursor + 1'b1;
            end

            // Luma and chroma passes share the held pixel, not the FIFO port.
            if (analysis_work_valid) begin
                if (!analysis_work_phase) begin
                    analysis_min_acc <= analysis_next_min;
                    analysis_max_acc <= analysis_next_max;
                    analysis_edge_acc <= analysis_next_edge;
                    analysis_previous_y <= analysis_y;
                    if (analysis_work_first)
                        analysis_first_acc <= analysis_work_pixel;
                    analysis_work_phase <= 1'b1;
                end else begin
                    analysis_chroma_acc <= analysis_next_chroma;
                    analysis_work_valid <= 1'b0;
                    if (analysis_work_last) begin
                        analysis_report_valid <= 1'b1;
                        analysis_min_y <= analysis_min_acc;
                        analysis_max_y <= analysis_max_acc;
                        analysis_peak_edge <= analysis_edge_acc;
                        analysis_chroma_separation <= analysis_next_chroma;
                        analysis_first_pixel <= analysis_first_acc;
                        analysis_last_pixel <= analysis_work_pixel;
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (pipeline_active && analysis_take)
            assert (analysis_head_pos == analysis_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [31:0] debug_status,
    output wire [95:0] perf_status
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
        if (acc) begin
            if (dbg_accept_count != 8'hff)
                dbg_accept_count <= dbg_accept_count + 1'b1;
        end
        if (rel) begin
            if (dbg_complete_count != 8'hff)
                dbg_complete_count <= dbg_complete_count + 1'b1;
        end
        if (out_valid && !out_ready) begin
            if (dbg_stall_cycles != 8'hff) begin
                dbg_stall_cycles <= dbg_stall_cycles + 1'b1;
                if (dbg_stall_cycles >= dbg_peak_stall)
                    dbg_peak_stall <= dbg_stall_cycles + 1'b1;
            end
            if (dbg_stall_cycles >= 8'd63)
                dbg_timeout <= 1'b1;
        end else begin
            dbg_stall_cycles <= 8'd0;
        end
    end
    assign debug_status = {dbg_timeout, 7'd0, dbg_peak_stall,
                           dbg_complete_count, dbg_accept_count};
    reg [15:0] perf_frame_cycles;
    reg [15:0] perf_peak_cycles;
    reg [15:0] perf_negative_samples;
    reg [15:0] perf_zero_samples;
    reg [15:0] perf_minimum_ties;
    reg [15:0] perf_idle_cycles;
    reg        perf_active;
    initial perf_frame_cycles = 16'd0;
    initial perf_peak_cycles = 16'd0;
    initial perf_negative_samples = 16'd0;
    initial perf_zero_samples = 16'd0;
    initial perf_minimum_ties = 16'd0;
    initial perf_idle_cycles = 16'd0;
    initial perf_active = 1'b0;
    always @(posedge clk) begin
        if (acc && !perf_active) begin
            perf_active <= 1'b1;
            perf_frame_cycles <= 16'd1;
        end else if (perf_active && !rel) begin
            if (perf_frame_cycles != 16'hffff) begin
                perf_frame_cycles <= perf_frame_cycles + 1'b1;
            end
        end
        if (rel) begin
            perf_active <= 1'b0;
            if (perf_frame_cycles > perf_peak_cycles) begin
                perf_peak_cycles <= perf_frame_cycles;
            end
        end
        if (acc) begin
            if (in_sign && perf_negative_samples != 16'hffff) begin
                perf_negative_samples <= perf_negative_samples + 1'b1;
            end
            if ((in_mag == {W{1'b0}}) && perf_zero_samples != 16'hffff) begin
                perf_zero_samples <= perf_zero_samples + 1'b1;
            end
            if ((in_mag == min1) && perf_minimum_ties != 16'hffff) begin
                perf_minimum_ties <= perf_minimum_ties + 1'b1;
            end
        end
        if (in_ready && !in_valid) begin
            if (perf_idle_cycles != 16'hffff) begin
                perf_idle_cycles <= perf_idle_cycles + 1'b1;
            end
        end
    end
    assign perf_status = {perf_peak_cycles, perf_frame_cycles,
                          perf_negative_samples, perf_zero_samples,
                          perf_minimum_ties, perf_idle_cycles};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
output wire [W-1:0] q_mag,
input  wire         peer_in_valid,
output wire         peer_in_ready,
input  wire [W-1:0] peer_in_mag,
output wire         peer_out_valid,
input  wire         peer_out_ready,
output wire [W-1:0] peer_out_min1,
output wire [W-1:0] peer_out_min2
);
localparam CHANNELS = 2, MINIMA = 2, PEER_CW = (DEG > 1) ? $clog2(DEG) : 1;
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

reg [W-1:0] minima [0:CHANNELS*MINIMA-1];
wire [W-1:0] min1 = minima[0], min2 = minima[1];
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
integer mi;
initial for (mi = 0; mi < CHANNELS*MINIMA; mi = mi + 1) minima[mi] = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
reg [PEER_CW-1:0] peer_count;
reg peer_done;
reg [$clog2(CHANNELS)-1:0] owner_peer;
initial begin peer_count = 0; peer_done = 0; owner_peer = 1; end
wire frames_idle = (count == 0) && (peer_count == 0);
wire select_peer = frames_idle ? (peer_in_valid && !peer_done && (!in_valid || state != S_ACCUM || !owner_peer)) : owner_peer;
assign peer_in_ready = select_peer && !peer_done;
wire peer_acc = peer_in_valid && peer_in_ready;
wire [W-1:0] cmp_mag = select_peer ? peer_in_mag : in_mag;
wire [W-1:0] cmp_min1 = select_peer ? minima[MINIMA] : min1;
wire [W-1:0] cmp_min2 = select_peer ? minima[MINIMA+1] : min2;
wire new_first = cmp_mag < cmp_min1;
wire [W-1:0] step_min1 = new_first ? cmp_mag : cmp_min1;
wire [W-1:0] step_min2 = new_first ? cmp_min1 : ((cmp_mag < cmp_min2) ? cmp_mag : cmp_min2);
assign peer_out_valid = peer_done;
assign peer_out_min1 = minima[MINIMA], peer_out_min2 = minima[MINIMA+1];

assign in_ready  = (state == S_ACCUM) && !select_peer;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
wire [CHANNELS-1:0] lane_acc = {peer_acc, acc}, lane_rel = {peer_out_valid && peer_out_ready, rel};
integer lane;
always @(posedge clk) begin
    for (lane = 0; lane < CHANNELS; lane = lane + 1) begin
        if (lane_acc[lane] || lane_rel[lane]) begin
            minima[lane*MINIMA] <= lane_acc[lane] ? step_min1 : {W{1'b1}};
            minima[lane*MINIMA+1] <= lane_acc[lane] ? step_min2 : {W{1'b1}};
        end
    end
    if (acc || peer_acc) owner_peer <= select_peer;
    if (peer_acc) begin
        if (peer_count == DEG - 1) begin peer_count <= 0; peer_done <= 1; end
        else peer_count <= peer_count + 1'b1;
    end else if (lane_rel[1]) peer_done <= 0;
end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
if (new_first) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
always @(posedge clk) if (pv) assert ((count == 0) || (peer_count == 0));
endmodule

module column_predictive_encoder #(
    parameter ROWS = 4,
    parameter COLS = 4,
    parameter DEPTH = 4,
    parameter POS_W = (ROWS*COLS > 1) ? $clog2(ROWS*COLS) : 1
) (
    input wire clk,
    input wire rst_n,
    input wire s_valid,
    output wire s_ready,
    input wire [23:0] s_pixel,
    input wire [POS_W-1:0] s_position,
    output reg m_valid,
    input wire m_ready,
    output reg [23:0] m_delta,
    output reg [POS_W-1:0] m_position,
    output reg m_seed,
    output reg m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [$clog2(DEPTH)-1:0] rd_ptr,
    output reg [$clog2(DEPTH)-1:0] wr_ptr,
    output reg [POS_W-1:0] cursor,
    output wire taking,
    output wire [POS_W-1:0] head_position,
    output reg [DEPTH*POS_W-1:0] queued_positions,
    output reg work_valid
);
    localparam PTR_W = $clog2(DEPTH);
    localparam PIXELS = ROWS * COLS;
    reg [23:0] pixels [0:DEPTH-1];
    reg [POS_W-1:0] positions [0:DEPTH-1];
    reg [23:0] row_history [0:ROWS-1];
    reg work_phase;
    reg [23:0] work_pixel;
    reg [23:0] work_base;
    reg [23:0] work_delta;
    reg [POS_W-1:0] work_position;
    reg work_seed, work_last;
    integer q;
    integer r;
    integer p;

    wire putting = s_valid && s_ready;
    wire publishing = work_valid && work_phase && (!m_valid || m_ready);
    assign taking = m_ready && (level != 0) && !work_valid;
    assign s_ready = (level < DEPTH) || taking;
    assign head_position = positions[rd_ptr];

    always @(*) begin
        for (p = 0; p < DEPTH; p = p + 1)
            queued_positions[p*POS_W +: POS_W] = positions[p];
    end

    initial begin
        level = 0;
        rd_ptr = {PTR_W{1'b0}};
        wr_ptr = {PTR_W{1'b0}};
        cursor = {POS_W{1'b0}};
        work_valid = 1'b0;
        work_phase = 1'b0;
        work_pixel = 24'd0;
        work_base = 24'd0;
        work_delta = 24'd0;
        work_position = {POS_W{1'b0}};
        work_seed = 1'b0;
        work_last = 1'b0;
        m_valid = 1'b0;
        m_delta = 24'd0;
        m_position = {POS_W{1'b0}};
        m_seed = 1'b0;
        m_last = 1'b0;
        for (q = 0; q < DEPTH; q = q + 1) begin
            pixels[q] = 24'd0;
            positions[q] = {POS_W{1'b0}};
        end
        for (r = 0; r < ROWS; r = r + 1)
            row_history[r] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            level <= 0;
            rd_ptr <= {PTR_W{1'b0}};
            wr_ptr <= {PTR_W{1'b0}};
            cursor <= {POS_W{1'b0}};
            work_valid <= 1'b0;
            work_phase <= 1'b0;
            work_pixel <= 24'd0;
            work_base <= 24'd0;
            work_delta <= 24'd0;
            work_position <= {POS_W{1'b0}};
            work_seed <= 1'b0;
            work_last <= 1'b0;
            m_valid <= 1'b0;
            m_delta <= 24'd0;
            m_position <= {POS_W{1'b0}};
            m_seed <= 1'b0;
            m_last <= 1'b0;
            for (q = 0; q < DEPTH; q = q + 1) begin
                pixels[q] <= 24'd0;
                positions[q] <= {POS_W{1'b0}};
            end
            for (r = 0; r < ROWS; r = r + 1)
                row_history[r] <= 24'd0;
        end else begin
            case ({putting, taking})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (putting) begin
                pixels[wr_ptr] <= s_pixel;
                positions[wr_ptr] <= s_position;
                wr_ptr <= (wr_ptr == DEPTH-1)
                        ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end

            // Each row retains the preceding column's reconstructed pixel.
            // The first column is transmitted as independent seed samples.
            if (taking) begin
                work_valid <= 1'b1;
                work_phase <= 1'b0;
                work_pixel <= pixels[rd_ptr];
                work_position <= head_position;
                work_seed <= cursor < ROWS;
                work_last <= cursor == PIXELS-1;
                work_base <= (cursor < ROWS)
                           ? 24'd0 : row_history[cursor % ROWS];
                cursor <= (cursor == PIXELS-1)
                        ? {POS_W{1'b0}} : cursor + 1'b1;
                rd_ptr <= (rd_ptr == DEPTH-1)
                        ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
            end

            // Byte-wise modular subtraction is lossless; no saturation.
            if (work_valid && !work_phase) begin
                work_delta[23:16] <= work_pixel[23:16] - work_base[23:16];
                work_delta[15:8] <= work_pixel[15:8] - work_base[15:8];
                work_delta[7:0] <= work_pixel[7:0] - work_base[7:0];
                row_history[work_position % ROWS] <= work_pixel;
                work_phase <= 1'b1;
            end

            // A stalled output never prevents queue writes or corrupts history.
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (publishing) begin
                m_valid <= 1'b1;
                m_delta <= work_delta;
                m_position <= work_position;
                m_seed <= work_seed;
                m_last <= work_last;
                work_valid <= 1'b0;
            end
        end
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
parameter TILE_COLS = 4,
parameter ANALYTICS_DEPTH = 4,
parameter PREDICTION_DEPTH = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
output wire busy,
output wire analysis_ready,
output wire [$clog2(ANALYTICS_DEPTH):0] analysis_level,
output reg analysis_enabled,
output reg analysis_report_valid,
output reg [7:0] analysis_min_y,
output reg [7:0] analysis_max_y,
output reg [7:0] analysis_peak_edge,
output reg [7:0] analysis_chroma_separation,
output reg [23:0] analysis_first_pixel,
output reg [23:0] analysis_last_pixel,
output wire prediction_valid,
output wire [23:0] prediction_delta,
output wire [((TILE_ROWS*TILE_COLS > 1) ? $clog2(TILE_ROWS*TILE_COLS) : 1)-1:0] prediction_position,
output wire prediction_seed,
output wire prediction_last,
output wire prediction_ready,
output wire [$clog2(PREDICTION_DEPTH+1)-1:0] prediction_level
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    localparam PREDICTION_PTR_W = $clog2(PREDICTION_DEPTH);
    localparam PREDICTION_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    wire tile_output_valid, tile_output_ready;
    wire [23:0] tile_output_data;
    wire [PREDICTION_PTR_W-1:0] prediction_rd_ptr, prediction_wr_ptr;
    wire [PREDICTION_POS_W-1:0] prediction_cursor;
    wire [PREDICTION_POS_W-1:0] prediction_head_position;
    wire [PREDICTION_DEPTH*PREDICTION_POS_W-1:0] prediction_positions;
    wire prediction_take, prediction_work_valid;
    wire [PREDICTION_POS_W-1:0] prediction_input_position =
        b_rd_col * TILE_ROWS + b_rd_row;

    // Original pixels and encoder requests fork atomically at the tile.
    // Both output interfaces use o_ready for consumer pacing.
    assign o_valid = tile_output_valid && prediction_ready;
    assign o_data = tile_output_data;
    assign tile_output_ready = o_ready && prediction_ready;
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

    localparam ANALYSIS_PTR_W = $clog2(ANALYTICS_DEPTH);
    localparam TILE_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    reg [23:0] analysis_pixels [0:ANALYTICS_DEPTH-1];
    reg [TILE_POS_W-1:0] analysis_pos [0:ANALYTICS_DEPTH-1];
    reg [ANALYSIS_PTR_W:0] analysis_rd_ptr, analysis_wr_ptr;
    reg [TILE_POS_W-1:0] analysis_cursor;
    reg analysis_work_valid, analysis_work_phase;
    reg analysis_work_first, analysis_work_last;
    reg [23:0] analysis_work_pixel;
    reg [TILE_POS_W-1:0] analysis_work_pos;
    reg [7:0] analysis_min_acc, analysis_max_acc;
    reg [7:0] analysis_edge_acc, analysis_chroma_acc;
    reg [7:0] analysis_previous_y;
    reg [23:0] analysis_first_acc;
    reg [7:0] analysis_next_min, analysis_next_max;
    reg [7:0] analysis_next_edge, analysis_next_chroma;
    reg [7:0] analysis_y_delta, analysis_chroma_delta;
    integer aj;

    wire bridge_offer = pipeline_active && (bridge_level != 0);
    wire analysis_empty = analysis_rd_ptr == analysis_wr_ptr;
    wire analysis_full =
        (analysis_rd_ptr[ANALYSIS_PTR_W-1:0] ==
         analysis_wr_ptr[ANALYSIS_PTR_W-1:0]) &&
        (analysis_rd_ptr[ANALYSIS_PTR_W] !=
         analysis_wr_ptr[ANALYSIS_PTR_W]);
    wire analysis_take = analysis_enabled && !analysis_empty &&
                         !analysis_work_valid;
    wire analysis_put = bridge_pop;
    wire analysis_finish = analysis_work_valid && analysis_work_phase;
    wire [23:0] analysis_head_pixel =
        analysis_pixels[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [TILE_POS_W-1:0] analysis_head_pos =
        analysis_pos[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [7:0] analysis_y = analysis_work_pixel[23:16];
    wire [7:0] analysis_cb = analysis_work_pixel[15:8];
    wire [7:0] analysis_cr = analysis_work_pixel[7:0];
    wire [ANALYSIS_PTR_W+1:0] analysis_held =
        {1'b0, analysis_level} + analysis_work_valid;

    function [ANALYSIS_PTR_W:0] analysis_advance;
        input [ANALYSIS_PTR_W:0] ptr;
        begin
            if (ptr[ANALYSIS_PTR_W-1:0] == ANALYTICS_DEPTH-1)
                analysis_advance = {!ptr[ANALYSIS_PTR_W],
                                    {ANALYSIS_PTR_W{1'b0}}};
            else
                analysis_advance = ptr + 1'b1;
        end
    endfunction

    assign analysis_level =
        (analysis_wr_ptr[ANALYSIS_PTR_W] ==
         analysis_rd_ptr[ANALYSIS_PTR_W])
        ? analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0]
        : ANALYTICS_DEPTH + analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0];
    assign analysis_ready = !analysis_full || analysis_take;

    // Row boundaries suppress transitions between unrelated row endpoints.
    always @(*) begin
        analysis_y_delta = (analysis_y >= analysis_previous_y)
                         ? analysis_y - analysis_previous_y
                         : analysis_previous_y - analysis_y;
        analysis_chroma_delta = (analysis_cb >= analysis_cr)
                              ? analysis_cb - analysis_cr
                              : analysis_cr - analysis_cb;
        analysis_next_min = analysis_min_acc;
        analysis_next_max = analysis_max_acc;
        analysis_next_edge = analysis_edge_acc;
        analysis_next_chroma = analysis_chroma_acc;
        if (analysis_work_first) begin
            analysis_next_min = analysis_y;
            analysis_next_max = analysis_y;
            analysis_next_edge = 8'd0;
            analysis_next_chroma = analysis_chroma_delta;
        end else begin
            if (analysis_y < analysis_min_acc)
                analysis_next_min = analysis_y;
            if (analysis_y > analysis_max_acc)
                analysis_next_max = analysis_y;
            if (analysis_chroma_delta > analysis_chroma_acc)
                analysis_next_chroma = analysis_chroma_delta;
        end
        if ((analysis_work_pos % TILE_COLS) != 0 &&
            analysis_y_delta > analysis_next_edge)
            analysis_next_edge = analysis_y_delta;
    end

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = bridge_offer && analysis_ready;
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0) ||
                  (prediction_level != 0) || prediction_work_valid ||
                  prediction_valid;

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(tile_output_valid), .out_ready(tile_output_ready),
        .out_data(tile_output_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    column_predictive_encoder #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(PREDICTION_DEPTH),
        .POS_W(PREDICTION_POS_W)
    ) predictor (
        .clk(clk), .rst_n(rst_n),
        .s_valid(tile_output_valid && o_ready),
        .s_ready(prediction_ready), .s_pixel(tile_output_data),
        .s_position(prediction_input_position),
        .m_valid(prediction_valid), .m_ready(o_ready),
        .m_delta(prediction_delta), .m_position(prediction_position),
        .m_seed(prediction_seed), .m_last(prediction_last),
        .level(prediction_level),
        .rd_ptr(prediction_rd_ptr), .wr_ptr(prediction_wr_ptr),
        .cursor(prediction_cursor), .taking(prediction_take),
        .head_position(prediction_head_position),
        .queued_positions(prediction_positions),
        .work_valid(prediction_work_valid)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    initial begin
        analysis_rd_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_wr_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_cursor = {TILE_POS_W{1'b0}};
        analysis_enabled = 1'b1;
        analysis_work_valid = 1'b0;
        analysis_work_phase = 1'b0;
        analysis_work_first = 1'b0;
        analysis_work_last = 1'b0;
        analysis_work_pixel = 24'd0;
        analysis_work_pos = {TILE_POS_W{1'b0}};
        analysis_min_acc = 8'hff;
        analysis_max_acc = 8'd0;
        analysis_edge_acc = 8'd0;
        analysis_chroma_acc = 8'd0;
        analysis_previous_y = 8'd0;
        analysis_first_acc = 24'd0;
        analysis_report_valid = 1'b0;
        analysis_min_y = 8'd0;
        analysis_max_y = 8'd0;
        analysis_peak_edge = 8'd0;
        analysis_chroma_separation = 8'd0;
        analysis_first_pixel = 24'd0;
        analysis_last_pixel = 24'd0;
        for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
            analysis_pixels[aj] = 24'd0;
            analysis_pos[aj] = {TILE_POS_W{1'b0}};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            analysis_rd_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_wr_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_cursor <= {TILE_POS_W{1'b0}};
            analysis_enabled <= 1'b1;
            analysis_work_valid <= 1'b0;
            analysis_work_phase <= 1'b0;
            analysis_work_first <= 1'b0;
            analysis_work_last <= 1'b0;
            analysis_work_pixel <= 24'd0;
            analysis_work_pos <= {TILE_POS_W{1'b0}};
            analysis_min_acc <= 8'hff;
            analysis_max_acc <= 8'd0;
            analysis_edge_acc <= 8'd0;
            analysis_chroma_acc <= 8'd0;
            analysis_previous_y <= 8'd0;
            analysis_first_acc <= 24'd0;
            analysis_report_valid <= 1'b0;
            analysis_min_y <= 8'd0;
            analysis_max_y <= 8'd0;
            analysis_peak_edge <= 8'd0;
            analysis_chroma_separation <= 8'd0;
            analysis_first_pixel <= 24'd0;
            analysis_last_pixel <= 24'd0;
            for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
                analysis_pixels[aj] <= 24'd0;
                analysis_pos[aj] <= {TILE_POS_W{1'b0}};
            end
        end else begin
            analysis_report_valid <= 1'b0;
            if (cfg_we && cfg_addr == 4'd9)
                analysis_enabled <= cfg_data[1];

            // Fork only transfers that were also accepted by the tile.
            if (analysis_put) begin
                analysis_pixels[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_in_data;
                analysis_pos[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_wr_row * TILE_COLS + b_wr_col;
                analysis_wr_ptr <= analysis_advance(analysis_wr_ptr);
            end
            if (analysis_take) begin
                analysis_work_valid <= 1'b1;
                analysis_work_phase <= 1'b0;
                analysis_work_pixel <= analysis_head_pixel;
                analysis_work_pos <= analysis_head_pos;
                analysis_work_first <= analysis_cursor == 0;
                analysis_work_last <= analysis_cursor == TILE_PIXELS-1;
                analysis_rd_ptr <= analysis_advance(analysis_rd_ptr);
                analysis_cursor <= (analysis_cursor == TILE_PIXELS-1)
                                 ? {TILE_POS_W{1'b0}}
                                 : analysis_cursor + 1'b1;
            end

            // Luma and chroma passes share the held pixel, not the FIFO port.
            if (analysis_work_valid) begin
                if (!analysis_work_phase) begin
                    analysis_min_acc <= analysis_next_min;
                    analysis_max_acc <= analysis_next_max;
                    analysis_edge_acc <= analysis_next_edge;
                    analysis_previous_y <= analysis_y;
                    if (analysis_work_first)
                        analysis_first_acc <= analysis_work_pixel;
                    analysis_work_phase <= 1'b1;
                end else begin
                    analysis_chroma_acc <= analysis_next_chroma;
                    analysis_work_valid <= 1'b0;
                    if (analysis_work_last) begin
                        analysis_report_valid <= 1'b1;
                        analysis_min_y <= analysis_min_acc;
                        analysis_max_y <= analysis_max_acc;
                        analysis_peak_edge <= analysis_edge_acc;
                        analysis_chroma_separation <= analysis_next_chroma;
                        analysis_first_pixel <= analysis_first_acc;
                        analysis_last_pixel <= analysis_work_pixel;
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (pipeline_active && analysis_take)
            assert (analysis_head_pos == analysis_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active && prediction_take)
            assert (prediction_head_position == prediction_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
output wire [W-1:0] q_mag,
input  wire         peer_in_valid,
output wire         peer_in_ready,
input  wire [W-1:0] peer_in_mag,
output wire         peer_out_valid,
input  wire         peer_out_ready,
output wire [W-1:0] peer_out_min1,
output wire [W-1:0] peer_out_min2,
input  wire         aux_in_valid,
output wire         aux_in_ready,
input  wire [W-1:0] aux_in_mag,
input  wire         aux_in_sign,
output wire         aux_out_valid,
input  wire         aux_out_ready,
output wire [W-1:0] aux_out_min1,
output wire [W-1:0] aux_out_min2,
output wire         aux_out_sign
);
localparam CHANNELS = 3, MINIMA = 2, PEER_CW = (DEG > 1) ? $clog2(DEG) : 1;
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

reg [W-1:0] minima [0:CHANNELS*MINIMA-1];
wire [W-1:0] min1 = minima[0], min2 = minima[1];
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
integer mi;
initial for (mi = 0; mi < CHANNELS*MINIMA; mi = mi + 1) minima[mi] = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
reg [PEER_CW-1:0] peer_count;
reg peer_done;
reg owner_peer;
initial begin peer_count = 0; peer_done = 0; owner_peer = 1; end
reg [PEER_CW-1:0] aux_count;
reg aux_done, aux_owner, aux_sign_prod;
initial begin
    aux_count = 0;
    aux_done = 0;
    aux_owner = 1;
    aux_sign_prod = 0;
end
wire frames_idle = (count == 0) && (peer_count == 0);
wire all_frames_idle = frames_idle && (aux_count == 0);
wire pair_request = (in_valid && state == S_ACCUM) ||
                    (peer_in_valid && !peer_done);
wire select_aux = all_frames_idle ?
    (aux_in_valid && !aux_done && (!pair_request || !aux_owner)) : aux_owner;
wire select_peer = frames_idle ? (peer_in_valid && !peer_done && (!in_valid || state != S_ACCUM || !owner_peer)) : owner_peer;
assign peer_in_ready = select_peer && !peer_done && !select_aux;
assign aux_in_ready = select_aux && !aux_done;
wire peer_acc = peer_in_valid && peer_in_ready;
wire aux_acc = aux_in_valid && aux_in_ready;
wire [W-1:0] cmp_mag = select_aux ? aux_in_mag :
                          (select_peer ? peer_in_mag : in_mag);
wire [W-1:0] cmp_min1 = select_aux ? minima[2*MINIMA] :
                           (select_peer ? minima[MINIMA] : min1);
wire [W-1:0] cmp_min2 = select_aux ? minima[2*MINIMA+1] :
                           (select_peer ? minima[MINIMA+1] : min2);
wire new_first = cmp_mag < cmp_min1;
wire [W-1:0] step_min1 = new_first ? cmp_mag : cmp_min1;
wire [W-1:0] step_min2 = new_first ? cmp_min1 : ((cmp_mag < cmp_min2) ? cmp_mag : cmp_min2);
assign peer_out_valid = peer_done;
assign peer_out_min1 = minima[MINIMA], peer_out_min2 = minima[MINIMA+1];
assign aux_out_valid = aux_done;
assign aux_out_min1 = minima[2*MINIMA];
assign aux_out_min2 = minima[2*MINIMA+1];
assign aux_out_sign = aux_sign_prod;

assign in_ready  = (state == S_ACCUM) && !select_peer && !select_aux;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
wire [CHANNELS-1:0] lane_acc = {aux_acc, peer_acc, acc};
wire [CHANNELS-1:0] lane_rel = {aux_out_valid && aux_out_ready,
                              peer_out_valid && peer_out_ready, rel};
integer lane;
always @(posedge clk) begin
    for (lane = 0; lane < CHANNELS; lane = lane + 1) begin
        if (lane_acc[lane] || lane_rel[lane]) begin
            minima[lane*MINIMA] <= lane_acc[lane] ? step_min1 : {W{1'b1}};
            minima[lane*MINIMA+1] <= lane_acc[lane] ? step_min2 : {W{1'b1}};
        end
    end
    if (acc || peer_acc) owner_peer <= select_peer;
    if (acc || peer_acc || aux_acc) aux_owner <= select_aux;
    if (peer_acc) begin
        if (peer_count == DEG - 1) begin peer_count <= 0; peer_done <= 1; end
        else peer_count <= peer_count + 1'b1;
    end else if (lane_rel[1]) peer_done <= 0;
end
always @(posedge clk) begin
    if (aux_acc) begin
        aux_sign_prod <= aux_sign_prod ^ aux_in_sign;
        if (aux_count == DEG - 1) begin
            aux_count <= 0;
            aux_done <= 1;
        end else begin
            aux_count <= aux_count + 1'b1;
        end
    end else if (lane_rel[2]) begin
        aux_done <= 0;
        aux_sign_prod <= 0;
    end
end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
if (new_first) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
