        aux_done <= 0;
        aux_sign_prod <= 0;
    end
end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
if (new_first) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
