    assign q_mag = (q_idx == min_idx) ? min2 : min1;
localparam PERF_CW = 16;
reg [PERF_CW-1:0] perf_accepted [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_completed [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_input_stalls [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_output_stalls [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_stall_run [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_stall_peak [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_busy_cycles [0:CHANNELS-1];
wire [CHANNELS-1:0] perf_input_blocked = {aux_in_valid && !aux_in_ready,
    peer_in_valid && !peer_in_ready,
    in_valid && !in_ready};
wire [CHANNELS-1:0] perf_output_blocked = {aux_out_valid && !aux_out_ready,
    peer_out_valid && !peer_out_ready,
    out_valid && !out_ready};
wire [CHANNELS-1:0] perf_busy = {(aux_count != 0) || aux_done,
    (peer_count != 0) || peer_done,
    (count != 0) || out_valid};
integer perf_init;
initial begin
    for (perf_init = 0; perf_init < CHANNELS; perf_init = perf_init + 1) begin
        perf_accepted[perf_init] = 0;
        perf_completed[perf_init] = 0;
        perf_input_stalls[perf_init] = 0;
        perf_output_stalls[perf_init] = 0;
        perf_stall_run[perf_init] = 0;
        perf_stall_peak[perf_init] = 0;
        perf_busy_cycles[perf_init] = 0;
    end
end
integer perf_lane;
always @(posedge clk) begin
    for (perf_lane = 0; perf_lane < CHANNELS; perf_lane = perf_lane + 1) begin
        if (lane_acc[perf_lane] &&
            perf_accepted[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_accepted[perf_lane] <= perf_accepted[perf_lane] + 1'b1;
        end
        if (lane_rel[perf_lane] &&
            perf_completed[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_completed[perf_lane] <= perf_completed[perf_lane] + 1'b1;
        end
        if (perf_input_blocked[perf_lane] &&
            perf_input_stalls[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_input_stalls[perf_lane] <= perf_input_stalls[perf_lane] + 1'b1;
        end
        if (perf_busy[perf_lane] &&
            perf_busy_cycles[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_busy_cycles[perf_lane] <= perf_busy_cycles[perf_lane] + 1'b1;
        end
        if (perf_output_blocked[perf_lane]) begin
            if (perf_output_stalls[perf_lane] != {PERF_CW{1'b1}}) begin
                perf_output_stalls[perf_lane] <= perf_output_stalls[perf_lane] + 1'b1;
            end
            if (perf_stall_run[perf_lane] != {PERF_CW{1'b1}}) begin
                perf_stall_run[perf_lane] <= perf_stall_run[perf_lane] + 1'b1;
            end
            if (perf_stall_run[perf_lane] >= perf_stall_peak[perf_lane] &&
                perf_stall_run[perf_lane] != {PERF_CW{1'b1}}) begin
                perf_stall_peak[perf_lane] <= perf_stall_run[perf_lane] + 1'b1;
            end
        end else begin
            perf_stall_run[perf_lane] <= 0;
        end
    end
