    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

   // Ordered prefix-reliability records share the summary sink's ready.
   localparam GAP_DEPTH = 4;
   localparam GAP_AW = $clog2(GAP_DEPTH);
   localparam GAP_SW = (W > 1) ? $clog2(W) : 1;
   localparam [1:0] G_IDLE = 2'd0, G_DIFF = 2'd1,
                    G_NORM = 2'd2, G_PUBLISH = 2'd3;
   reg [GAP_AW:0] gap_wptr;
   reg [GAP_AW:0] gap_rptr;
   reg [W-1:0] gap_fifo_mag [0:GAP_DEPTH-1];
   reg         gap_fifo_sign [0:GAP_DEPTH-1];
   reg [W-1:0] gap_fifo_idx [0:GAP_DEPTH-1];
   reg [1:0] gap_state;
   reg [W-1:0] gap_operand;
   reg [W-1:0] gap_reference;
   reg [W-1:0] gap_exclusion;
   reg [W-1:0] gap_operand_idx;
   reg [W-1:0] gap_work;
   reg gap_operand_sign;
   reg [GAP_SW-1:0] gap_norm_shift;
   reg [W-1:0] gap_result_mag;
   reg [GAP_SW-1:0] gap_result_shift;
   reg gap_result_sign;
   reg gap_result_valid;
   integer gap_init;
   initial gap_wptr = 0;
   initial gap_rptr = 0;
   initial gap_state = G_IDLE;
   initial gap_operand = {W{1'b0}};
   initial gap_reference = {W{1'b0}};
   initial gap_exclusion = {W{1'b0}};
   initial gap_operand_idx = {W{1'b0}};
   initial gap_work = {W{1'b0}};
   initial gap_operand_sign = 1'b0;
   initial gap_norm_shift = 0;
   initial gap_result_mag = {W{1'b0}};
   initial gap_result_shift = 0;
   initial gap_result_sign = 1'b0;
   initial gap_result_valid = 1'b0;
   initial begin
       for (gap_init = 0; gap_init < GAP_DEPTH; gap_init = gap_init + 1) begin
           gap_fifo_mag[gap_init] = {W{1'b0}};
           gap_fifo_sign[gap_init] = 1'b0;
           gap_fifo_idx[gap_init] = {W{1'b0}};
       end
