   wire gap_take = !gap_empty && (gap_state == G_IDLE) &&
                   (!gap_result_valid || out_ready);
   assign gap_valid = gap_result_valid;
   assign gap_mantissa = gap_result_mag;
   assign gap_base = gap_reference;
   assign gap_sample = gap_operand;
   assign gap_idx = gap_operand_idx;
   assign gap_message = gap_exclusion;
   assign gap_exponent = gap_result_shift;
   assign gap_sign = gap_result_sign;

assign in_ready  = (state == S_ACCUM) && !gap_full;
assign out_valid = (state == S_DONE) && gap_empty &&
