                   gap_reference <= min1;
                   gap_operand_idx <= gap_fifo_idx[gap_rptr[GAP_AW-1:0]];
                   gap_exclusion <=
                       (gap_fifo_idx[gap_rptr[GAP_AW-1:0]] == min_idx) ? min2 : min1;
                   gap_operand_sign <= gap_fifo_sign[gap_rptr[GAP_AW-1:0]] ^ sign_prod;
