    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
