        if (rel) begin
            perf_active <= 1'b0;
            if (perf_frame_cycles > perf_peak_cycles) begin
                perf_peak_cycles <= perf_frame_cycles;
            end
        end
        if (acc) begin
            if (in_sign && perf_negative_samples != 16'hffff) begin
                perf_negative_samples <= perf_negative_samples + 1'b1;
            end
            if ((in_mag == {W{1'b0}}) && perf_zero_samples != 16'hffff) begin
                perf_zero_samples <= perf_zero_samples + 1'b1;
            end
            if ((in_mag == min1) && perf_minimum_ties != 16'hffff) begin
                perf_minimum_ties <= perf_minimum_ties + 1'b1;
            end
        end
        if (in_ready && !in_valid) begin
            if (perf_idle_cycles != 16'hffff) begin
                perf_idle_cycles <= perf_idle_cycles + 1'b1;
            end
        end
    end
    assign perf_status = {perf_peak_cycles, perf_frame_cycles,
                          perf_negative_samples, perf_zero_samples,
                          perf_minimum_ties, perf_idle_cycles};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
   always @(posedge clk) if (pv && gap_take)
       assert ((gap_used <= GAP_DEPTH) &&
               (gap_fifo_mag[gap_rptr[GAP_AW-1:0]] >= min1));
endmodule

module column_predictive_encoder #(
    parameter ROWS = 4,
    parameter COLS = 4,
    parameter DEPTH = 4,
    parameter POS_W = (ROWS*COLS > 1) ? $clog2(ROWS*COLS) : 1
) (
    input wire clk,
    input wire rst_n,
    input wire s_valid,
    output wire s_ready,
    input wire [23:0] s_pixel,
    input wire [POS_W-1:0] s_position,
    output reg m_valid,
    input wire m_ready,
    output reg [23:0] m_delta,
    output reg [POS_W-1:0] m_position,
    output reg m_seed,
    output reg m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [$clog2(DEPTH)-1:0] rd_ptr,
    output reg [$clog2(DEPTH)-1:0] wr_ptr,
    output reg [POS_W-1:0] cursor,
    output wire taking,
    output wire [POS_W-1:0] head_position,
    output reg [DEPTH*POS_W-1:0] queued_positions,
    output reg work_valid
);
    localparam PTR_W = $clog2(DEPTH);
    localparam PIXELS = ROWS * COLS;
    reg [23:0] pixels [0:DEPTH-1];
    reg [POS_W-1:0] positions [0:DEPTH-1];
    reg [23:0] row_history [0:ROWS-1];
    reg work_phase;
    reg [23:0] work_pixel;
    reg [23:0] work_base;
    reg [23:0] work_delta;
    reg [POS_W-1:0] work_position;
    reg work_seed, work_last;
    integer q;
    integer r;
    integer p;

    wire putting = s_valid && s_ready;
    wire publishing = work_valid && work_phase && (!m_valid || m_ready);
    assign taking = m_ready && (level != 0) && !work_valid;
    assign s_ready = (level < DEPTH) || taking;
    assign head_position = positions[rd_ptr];

    always @(*) begin
        for (p = 0; p < DEPTH; p = p + 1)
            queued_positions[p*POS_W +: POS_W] = positions[p];
    end

    initial begin
        level = 0;
        rd_ptr = {PTR_W{1'b0}};
        wr_ptr = {PTR_W{1'b0}};
        cursor = {POS_W{1'b0}};
        work_valid = 1'b0;
        work_phase = 1'b0;
        work_pixel = 24'd0;
        work_base = 24'd0;
        work_delta = 24'd0;
        work_position = {POS_W{1'b0}};
        work_seed = 1'b0;
        work_last = 1'b0;
        m_valid = 1'b0;
        m_delta = 24'd0;
        m_position = {POS_W{1'b0}};
        m_seed = 1'b0;
        m_last = 1'b0;
        for (q = 0; q < DEPTH; q = q + 1) begin
            pixels[q] = 24'd0;
            positions[q] = {POS_W{1'b0}};
        end
        for (r = 0; r < ROWS; r = r + 1)
            row_history[r] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            level <= 0;
            rd_ptr <= {PTR_W{1'b0}};
            wr_ptr <= {PTR_W{1'b0}};
            cursor <= {POS_W{1'b0}};
            work_valid <= 1'b0;
            work_phase <= 1'b0;
            work_pixel <= 24'd0;
            work_base <= 24'd0;
            work_delta <= 24'd0;
            work_position <= {POS_W{1'b0}};
            work_seed <= 1'b0;
            work_last <= 1'b0;
            m_valid <= 1'b0;
            m_delta <= 24'd0;
            m_position <= {POS_W{1'b0}};
            m_seed <= 1'b0;
            m_last <= 1'b0;
            for (q = 0; q < DEPTH; q = q + 1) begin
                pixels[q] <= 24'd0;
                positions[q] <= {POS_W{1'b0}};
            end
            for (r = 0; r < ROWS; r = r + 1)
                row_history[r] <= 24'd0;
        end else begin
            case ({putting, taking})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (putting) begin
                pixels[wr_ptr] <= s_pixel;
                positions[wr_ptr] <= s_position;
                wr_ptr <= (wr_ptr == DEPTH-1)
                        ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end

            // Each row retains the preceding column's reconstructed pixel.
            // The first column is transmitted as independent seed samples.
            if (taking) begin
                work_valid <= 1'b1;
                work_phase <= 1'b0;
                work_pixel <= pixels[rd_ptr];
                work_position <= head_position;
                work_seed <= cursor < ROWS;
                work_last <= cursor == PIXELS-1;
                work_base <= (cursor < ROWS)
                           ? 24'd0 : row_history[cursor % ROWS];
                cursor <= (cursor == PIXELS-1)
                        ? {POS_W{1'b0}} : cursor + 1'b1;
                rd_ptr <= (rd_ptr == DEPTH-1)
                        ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
            end

            // Byte-wise modular subtraction is lossless; no saturation.
            if (work_valid && !work_phase) begin
                work_delta[23:16] <= work_pixel[23:16] - work_base[23:16];
                work_delta[15:8] <= work_pixel[15:8] - work_base[15:8];
                work_delta[7:0] <= work_pixel[7:0] - work_base[7:0];
                row_history[work_position % ROWS] <= work_pixel;
                work_phase <= 1'b1;
            end

            // A stalled output never prevents queue writes or corrupts history.
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (publishing) begin
                m_valid <= 1'b1;
                m_delta <= work_delta;
                m_position <= work_position;
                m_seed <= work_seed;
                m_last <= work_last;
                work_valid <= 1'b0;
            end
        end
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
parameter TILE_COLS = 4,
parameter ANALYTICS_DEPTH = 4,
parameter PREDICTION_DEPTH = 4,
parameter PEER_DEPTH = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
output wire busy,
output wire analysis_ready,
output wire [$clog2(ANALYTICS_DEPTH):0] analysis_level,
output reg analysis_enabled,
output reg analysis_report_valid,
output reg [7:0] analysis_min_y,
output reg [7:0] analysis_max_y,
output reg [7:0] analysis_peak_edge,
output reg [7:0] analysis_chroma_separation,
output reg [23:0] analysis_first_pixel,
output reg [23:0] analysis_last_pixel,
output wire prediction_valid,
output wire [23:0] prediction_delta,
output wire [((TILE_ROWS*TILE_COLS > 1) ? $clog2(TILE_ROWS*TILE_COLS) : 1)-1:0] prediction_position,
output wire prediction_seed,
output wire prediction_last,
output wire prediction_ready,
output wire [$clog2(PREDICTION_DEPTH+1)-1:0] prediction_level,
input wire peer_valid,
output wire peer_ready,
input wire [23:0] peer_pixel,
input wire [23:0] peer_expected_crc,
output reg [$clog2(PEER_DEPTH+1)-1:0] peer_level,
output wire bus_peer,
output wire bus_first,
output wire bus_last,
output reg [((TILE_ROWS*TILE_COLS > 1) ? $clog2(TILE_ROWS*TILE_COLS) : 1)-1:0] bus_position,
output wire [23:0] pixel_lane_crc,
output wire [23:0] peer_lane_crc,
output reg bus_crc_valid,
output reg bus_crc_peer,
output reg bus_crc_error,
output reg [7:0] peer_crc_errors,
output reg peer_error_valid,
output reg [23:0] peer_error_expected,
output reg [23:0] peer_error_observed
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    localparam PREDICTION_PTR_W = $clog2(PREDICTION_DEPTH);
    localparam PREDICTION_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    wire tile_output_valid, tile_output_ready;
    wire [23:0] tile_output_data;
    wire [PREDICTION_PTR_W-1:0] prediction_rd_ptr, prediction_wr_ptr;
    wire [PREDICTION_POS_W-1:0] prediction_cursor;
    wire [PREDICTION_POS_W-1:0] prediction_head_position;
    wire [PREDICTION_DEPTH*PREDICTION_POS_W-1:0] prediction_positions;
    wire prediction_take, prediction_work_valid;
    wire [PREDICTION_POS_W-1:0] prediction_input_position =
        b_rd_col * TILE_ROWS + b_rd_row;

   localparam CHANNELS = 2;
   localparam BUS_LANE_W = (CHANNELS > 1) ? $clog2(CHANNELS) : 1;
   localparam PEER_PTR_W = $clog2(PEER_DEPTH);
   localparam [BUS_LANE_W-1:0] PIXEL_LANE = 0;
   localparam [BUS_LANE_W-1:0] PEER_LANE = 1;
   reg [23:0] peer_pixels [0:PEER_DEPTH-1];
   reg [23:0] peer_crc_tags [0:PEER_DEPTH-1];
   reg [PEER_PTR_W-1:0] peer_rd_ptr, peer_wr_ptr;
   reg bus_locked;
   reg [BUS_LANE_W-1:0] bus_owner, bus_turn, bus_select;
   reg [23:0] bus_crc_work;
   reg [23:0] bus_crc_history [0:CHANNELS-1];
   wire [CHANNELS-1:0] bus_requests;
   wire bus_fire;
   wire peer_push, peer_pop;
   wire peer_crc_bad;
   wire [23:0] bus_crc_next;
   integer peer_q;
   integer bus_c;

   // CRC-24, most significant bit first, over the transmitted pixel words.
   function [23:0] packet_crc24;
       input [23:0] previous_crc;
       input [23:0] payload;
       reg [23:0] fold;
       integer bit_index;
       begin
           fold = previous_crc;
           for (bit_index = 23; bit_index >= 0;
                bit_index = bit_index - 1) begin
               if (fold[23] ^ payload[bit_index])
                   fold = {fold[22:0], 1'b0} ^ 24'h864cfb;
               else
                   fold = {fold[22:0], 1'b0};
           end
           packet_crc24 = fold;
       end
   endfunction

   assign bus_requests[PIXEL_LANE] =
       tile_output_valid && prediction_ready;
   assign bus_requests[PEER_LANE] = peer_level != 0;

   // Packets cannot interleave. Reserving on an offer also holds the
   // selected lane stable when the first word encounters backpressure.
   always @(*) begin
       bus_select = PIXEL_LANE;
       if (bus_locked) begin
           bus_select = bus_owner;
       end else if (bus_requests[bus_turn]) begin
           bus_select = bus_turn;
       end else if (bus_requests[PIXEL_LANE]) begin
           bus_select = PIXEL_LANE;
       end else if (bus_requests[PEER_LANE]) begin
           bus_select = PEER_LANE;
       end
   end

   assign bus_peer = bus_select == PEER_LANE;
   assign bus_first = bus_position == 0;
   assign bus_last = bus_position == TILE_PIXELS-1;
   assign bus_fire = o_valid && o_ready;
   assign peer_pop = bus_fire && bus_peer;
   assign peer_push = peer_valid && peer_ready;
   assign peer_ready = (peer_level < PEER_DEPTH) || peer_pop;
   assign bus_crc_next = packet_crc24(
       bus_first ? 24'hffffff : bus_crc_work, o_data);
   assign peer_crc_bad = bus_peer &&
       (bus_crc_next != peer_crc_tags[peer_rd_ptr]);
   assign pixel_lane_crc = bus_crc_history[PIXEL_LANE];
   assign peer_lane_crc = bus_crc_history[PEER_LANE];

    // Original pixels and encoder requests fork atomically at the tile.
    // Both output interfaces use o_ready for consumer pacing.
   assign o_valid = bus_requests[bus_select];
   assign o_data = bus_peer ? peer_pixels[peer_rd_ptr] : tile_output_data;
   assign tile_output_ready = o_ready && prediction_ready && !bus_peer;
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
   wire sink_fire = o_valid && o_ready && !bus_peer;
    integer j;

    localparam ANALYSIS_PTR_W = $clog2(ANALYTICS_DEPTH);
    localparam TILE_POS_W = (TILE_PIXELS > 1) ? $clog2(TILE_PIXELS) : 1;
    reg [23:0] analysis_pixels [0:ANALYTICS_DEPTH-1];
    reg [TILE_POS_W-1:0] analysis_pos [0:ANALYTICS_DEPTH-1];
    reg [ANALYSIS_PTR_W:0] analysis_rd_ptr, analysis_wr_ptr;
    reg [TILE_POS_W-1:0] analysis_cursor;
    reg analysis_work_valid, analysis_work_phase;
    reg analysis_work_first, analysis_work_last;
    reg [23:0] analysis_work_pixel;
    reg [TILE_POS_W-1:0] analysis_work_pos;
    reg [7:0] analysis_min_acc, analysis_max_acc;
    reg [7:0] analysis_edge_acc, analysis_chroma_acc;
    reg [7:0] analysis_previous_y;
    reg [23:0] analysis_first_acc;
    reg [7:0] analysis_next_min, analysis_next_max;
    reg [7:0] analysis_next_edge, analysis_next_chroma;
    reg [7:0] analysis_y_delta, analysis_chroma_delta;
    integer aj;

    wire bridge_offer = pipeline_active && (bridge_level != 0);
    wire analysis_empty = analysis_rd_ptr == analysis_wr_ptr;
    wire analysis_full =
        (analysis_rd_ptr[ANALYSIS_PTR_W-1:0] ==
         analysis_wr_ptr[ANALYSIS_PTR_W-1:0]) &&
        (analysis_rd_ptr[ANALYSIS_PTR_W] !=
         analysis_wr_ptr[ANALYSIS_PTR_W]);
    wire analysis_take = analysis_enabled && !analysis_empty &&
                         !analysis_work_valid;
    wire analysis_put = bridge_pop;
    wire analysis_finish = analysis_work_valid && analysis_work_phase;
    wire [23:0] analysis_head_pixel =
        analysis_pixels[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [TILE_POS_W-1:0] analysis_head_pos =
        analysis_pos[analysis_rd_ptr[ANALYSIS_PTR_W-1:0]];
    wire [7:0] analysis_y = analysis_work_pixel[23:16];
    wire [7:0] analysis_cb = analysis_work_pixel[15:8];
    wire [7:0] analysis_cr = analysis_work_pixel[7:0];
    wire [ANALYSIS_PTR_W+1:0] analysis_held =
        {1'b0, analysis_level} + analysis_work_valid;

    function [ANALYSIS_PTR_W:0] analysis_advance;
        input [ANALYSIS_PTR_W:0] ptr;
        begin
            if (ptr[ANALYSIS_PTR_W-1:0] == ANALYTICS_DEPTH-1)
                analysis_advance = {!ptr[ANALYSIS_PTR_W],
                                    {ANALYSIS_PTR_W{1'b0}}};
            else
                analysis_advance = ptr + 1'b1;
        end
    endfunction

    assign analysis_level =
        (analysis_wr_ptr[ANALYSIS_PTR_W] ==
         analysis_rd_ptr[ANALYSIS_PTR_W])
        ? analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0]
        : ANALYTICS_DEPTH + analysis_wr_ptr[ANALYSIS_PTR_W-1:0] -
          analysis_rd_ptr[ANALYSIS_PTR_W-1:0];
    assign analysis_ready = !analysis_full || analysis_take;

    // Row boundaries suppress transitions between unrelated row endpoints.
    always @(*) begin
        analysis_y_delta = (analysis_y >= analysis_previous_y)
                         ? analysis_y - analysis_previous_y
                         : analysis_previous_y - analysis_y;
        analysis_chroma_delta = (analysis_cb >= analysis_cr)
                              ? analysis_cb - analysis_cr
                              : analysis_cr - analysis_cb;
        analysis_next_min = analysis_min_acc;
        analysis_next_max = analysis_max_acc;
        analysis_next_edge = analysis_edge_acc;
        analysis_next_chroma = analysis_chroma_acc;
        if (analysis_work_first) begin
            analysis_next_min = analysis_y;
            analysis_next_max = analysis_y;
            analysis_next_edge = 8'd0;
            analysis_next_chroma = analysis_chroma_delta;
        end else begin
            if (analysis_y < analysis_min_acc)
                analysis_next_min = analysis_y;
            if (analysis_y > analysis_max_acc)
                analysis_next_max = analysis_y;
            if (analysis_chroma_delta > analysis_chroma_acc)
                analysis_next_chroma = analysis_chroma_delta;
        end
        if ((analysis_work_pos % TILE_COLS) != 0 &&
            analysis_y_delta > analysis_next_edge)
            analysis_next_edge = analysis_y_delta;
    end

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = bridge_offer && analysis_ready;
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0) ||
                  (prediction_level != 0) || prediction_work_valid ||
                 prediction_valid || (peer_level != 0) || bus_locked;

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(tile_output_valid), .out_ready(tile_output_ready),
        .out_data(tile_output_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    column_predictive_encoder #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(PREDICTION_DEPTH),
        .POS_W(PREDICTION_POS_W)
    ) predictor (
        .clk(clk), .rst_n(rst_n),
       .s_valid(tile_output_valid && o_ready && !bus_peer),
        .s_ready(prediction_ready), .s_pixel(tile_output_data),
        .s_position(prediction_input_position),
        .m_valid(prediction_valid), .m_ready(o_ready),
        .m_delta(prediction_delta), .m_position(prediction_position),
        .m_seed(prediction_seed), .m_last(prediction_last),
        .level(prediction_level),
        .rd_ptr(prediction_rd_ptr), .wr_ptr(prediction_wr_ptr),
        .cursor(prediction_cursor), .taking(prediction_take),
        .head_position(prediction_head_position),
        .queued_positions(prediction_positions),
        .work_valid(prediction_work_valid)
    );

   // The peer supplies complete fixed-size packets in column order.
   // Its expected CRC sideband is significant on each packet's last word.
   initial begin
       peer_level = 0;
       peer_rd_ptr = {PEER_PTR_W{1'b0}};
       peer_wr_ptr = {PEER_PTR_W{1'b0}};
       bus_locked = 1'b0;
       bus_owner = PIXEL_LANE;
       bus_turn = PIXEL_LANE;
       bus_position = {PREDICTION_POS_W{1'b0}};
       bus_crc_work = 24'hffffff;
       bus_crc_valid = 1'b0;
       bus_crc_peer = 1'b0;
       bus_crc_error = 1'b0;
       peer_crc_errors = 8'd0;
       peer_error_valid = 1'b0;
       peer_error_expected = 24'd0;
       peer_error_observed = 24'd0;
       for (peer_q = 0; peer_q < PEER_DEPTH; peer_q = peer_q + 1) begin
           peer_pixels[peer_q] = 24'd0;
           peer_crc_tags[peer_q] = 24'd0;
       end
       for (bus_c = 0; bus_c < CHANNELS; bus_c = bus_c + 1)
           bus_crc_history[bus_c] = 24'd0;
   end

   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           peer_level <= 0;
           peer_rd_ptr <= {PEER_PTR_W{1'b0}};
           peer_wr_ptr <= {PEER_PTR_W{1'b0}};
           bus_locked <= 1'b0;
           bus_owner <= PIXEL_LANE;
           bus_turn <= PIXEL_LANE;
           bus_position <= {PREDICTION_POS_W{1'b0}};
           bus_crc_work <= 24'hffffff;
           bus_crc_valid <= 1'b0;
           bus_crc_peer <= 1'b0;
           bus_crc_error <= 1'b0;
           peer_crc_errors <= 8'd0;
           peer_error_valid <= 1'b0;
           peer_error_expected <= 24'd0;
           peer_error_observed <= 24'd0;
           for (peer_q = 0; peer_q < PEER_DEPTH; peer_q = peer_q + 1) begin
               peer_pixels[peer_q] <= 24'd0;
               peer_crc_tags[peer_q] <= 24'd0;
           end
           for (bus_c = 0; bus_c < CHANNELS; bus_c = bus_c + 1)
               bus_crc_history[bus_c] <= 24'd0;
       end else begin
           bus_crc_valid <= 1'b0;
           case ({peer_push, peer_pop})
               2'b10: peer_level <= peer_level + 1'b1;
               2'b01: peer_level <= peer_level - 1'b1;
               default: ;
           endcase
           if (peer_push) begin
               peer_pixels[peer_wr_ptr] <= peer_pixel;
               peer_crc_tags[peer_wr_ptr] <= peer_expected_crc;
               peer_wr_ptr <= (peer_wr_ptr == PEER_DEPTH-1)
                            ? {PEER_PTR_W{1'b0}} : peer_wr_ptr + 1'b1;
           end
           if (peer_pop) begin
               peer_rd_ptr <= (peer_rd_ptr == PEER_DEPTH-1)
                            ? {PEER_PTR_W{1'b0}} : peer_rd_ptr + 1'b1;
           end

           if (o_valid && !bus_locked) begin
               bus_locked <= 1'b1;
               bus_owner <= bus_select;
           end
           if (bus_fire) begin
               bus_crc_work <= bus_crc_next;
               if (bus_last) begin
                   bus_locked <= 1'b0;
                   bus_position <= {PREDICTION_POS_W{1'b0}};
                   bus_turn <= bus_peer ? PIXEL_LANE : PEER_LANE;
                   bus_crc_history[bus_select] <= bus_crc_next;
                   bus_crc_valid <= 1'b1;
                   bus_crc_peer <= bus_peer;
                   bus_crc_error <= peer_crc_bad;
                   if (peer_crc_bad) begin
                       if (!(&peer_crc_errors))
                           peer_crc_errors <= peer_crc_errors + 8'd1;
                       if (!peer_error_valid) begin
                           peer_error_valid <= 1'b1;
                           peer_error_expected <= peer_crc_tags[peer_rd_ptr];
                           peer_error_observed <= bus_crc_next;
                       end
                   end
               end else begin
                   bus_position <= bus_position + 1'b1;
               end
           end
       end
   end

   always @(posedge clk) begin
       if (pipeline_active && sink_fire)
           assert (bus_position == prediction_input_position);
   end

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    initial begin
        analysis_rd_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_wr_ptr = {(ANALYSIS_PTR_W+1){1'b0}};
        analysis_cursor = {TILE_POS_W{1'b0}};
        analysis_enabled = 1'b1;
        analysis_work_valid = 1'b0;
        analysis_work_phase = 1'b0;
        analysis_work_first = 1'b0;
        analysis_work_last = 1'b0;
        analysis_work_pixel = 24'd0;
        analysis_work_pos = {TILE_POS_W{1'b0}};
        analysis_min_acc = 8'hff;
        analysis_max_acc = 8'd0;
        analysis_edge_acc = 8'd0;
        analysis_chroma_acc = 8'd0;
        analysis_previous_y = 8'd0;
        analysis_first_acc = 24'd0;
        analysis_report_valid = 1'b0;
        analysis_min_y = 8'd0;
        analysis_max_y = 8'd0;
        analysis_peak_edge = 8'd0;
        analysis_chroma_separation = 8'd0;
        analysis_first_pixel = 24'd0;
        analysis_last_pixel = 24'd0;
        for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
            analysis_pixels[aj] = 24'd0;
            analysis_pos[aj] = {TILE_POS_W{1'b0}};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            analysis_rd_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_wr_ptr <= {(ANALYSIS_PTR_W+1){1'b0}};
            analysis_cursor <= {TILE_POS_W{1'b0}};
            analysis_enabled <= 1'b1;
            analysis_work_valid <= 1'b0;
            analysis_work_phase <= 1'b0;
            analysis_work_first <= 1'b0;
            analysis_work_last <= 1'b0;
            analysis_work_pixel <= 24'd0;
            analysis_work_pos <= {TILE_POS_W{1'b0}};
            analysis_min_acc <= 8'hff;
            analysis_max_acc <= 8'd0;
            analysis_edge_acc <= 8'd0;
            analysis_chroma_acc <= 8'd0;
            analysis_previous_y <= 8'd0;
            analysis_first_acc <= 24'd0;
            analysis_report_valid <= 1'b0;
            analysis_min_y <= 8'd0;
            analysis_max_y <= 8'd0;
            analysis_peak_edge <= 8'd0;
            analysis_chroma_separation <= 8'd0;
            analysis_first_pixel <= 24'd0;
            analysis_last_pixel <= 24'd0;
            for (aj = 0; aj < ANALYTICS_DEPTH; aj = aj + 1) begin
                analysis_pixels[aj] <= 24'd0;
                analysis_pos[aj] <= {TILE_POS_W{1'b0}};
            end
        end else begin
            analysis_report_valid <= 1'b0;
            if (cfg_we && cfg_addr == 4'd9)
                analysis_enabled <= cfg_data[1];

            // Fork only transfers that were also accepted by the tile.
            if (analysis_put) begin
                analysis_pixels[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_in_data;
                analysis_pos[analysis_wr_ptr[ANALYSIS_PTR_W-1:0]] <=
                    b_wr_row * TILE_COLS + b_wr_col;
                analysis_wr_ptr <= analysis_advance(analysis_wr_ptr);
            end
            if (analysis_take) begin
                analysis_work_valid <= 1'b1;
                analysis_work_phase <= 1'b0;
                analysis_work_pixel <= analysis_head_pixel;
                analysis_work_pos <= analysis_head_pos;
                analysis_work_first <= analysis_cursor == 0;
                analysis_work_last <= analysis_cursor == TILE_PIXELS-1;
                analysis_rd_ptr <= analysis_advance(analysis_rd_ptr);
                analysis_cursor <= (analysis_cursor == TILE_PIXELS-1)
                                 ? {TILE_POS_W{1'b0}}
                                 : analysis_cursor + 1'b1;
            end

            // Luma and chroma passes share the held pixel, not the FIFO port.
            if (analysis_work_valid) begin
                if (!analysis_work_phase) begin
                    analysis_min_acc <= analysis_next_min;
                    analysis_max_acc <= analysis_next_max;
                    analysis_edge_acc <= analysis_next_edge;
                    analysis_previous_y <= analysis_y;
                    if (analysis_work_first)
                        analysis_first_acc <= analysis_work_pixel;
                    analysis_work_phase <= 1'b1;
                end else begin
                    analysis_chroma_acc <= analysis_next_chroma;
                    analysis_work_valid <= 1'b0;
                    if (analysis_work_last) begin
                        analysis_report_valid <= 1'b1;
                        analysis_min_y <= analysis_min_acc;
                        analysis_max_y <= analysis_max_acc;
                        analysis_peak_edge <= analysis_edge_acc;
                        analysis_chroma_separation <= analysis_next_chroma;
                        analysis_first_pixel <= analysis_first_acc;
                        analysis_last_pixel <= analysis_work_pixel;
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (pipeline_active && analysis_take)
            assert (analysis_head_pos == analysis_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active && prediction_take)
            assert (prediction_head_position == prediction_cursor);
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module ntt_phase_dispatch #(
    parameter W = 16,
    parameter PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire clk,
    input  wire cfg_valid,
    output wire cfg_ready,
    input  wire [W-1:0] cfg_data,
    input  wire [W-1:0] profile_select,
    input  wire start,
    input  wire run,
    input  wire finish,
    input  wire [W-1:0] remaining,
    input  wire [W-1:0] launch_latency,
    output reg  [W-1:0] step = 16'd0,
    output reg  [W-1:0] quantum = 16'd1,
    output wire [W*PROFILES-1:0] profiles,
    output reg  [1:0] cfg_state = 2'd0,
    output reg  [$clog2(PROFILES)-1:0] cfg_index = 0,
    output reg  [W-1:0] cfg_pending = 16'd0,
    output reg  [W-1:0] cfg_prepared = 16'd1,
    output wire cfg_apply
);
    localparam INDEX_W = $clog2(PROFILES);
    localparam [INDEX_W-1:0] LAST_PROFILE = PROFILES - 1;
    reg [W-1:0] cap [0:PROFILES-1];
    wire [INDEX_W-1:0] selected = profile_select % PROFILES;
    integer init_profile;
    initial begin
        for (init_profile = 0; init_profile < PROFILES; init_profile = init_profile + 1) begin
            cap[init_profile] = 16'd1;
        end
    end
    genvar p;
    generate
        for (p = 0; p < PROFILES; p = p + 1) begin: expose_profiles
            assign profiles[p*W +: W] = cap[p];
        end
    endgenerate
    assign cfg_ready = (cfg_state == 2'd0);
    assign cfg_apply = (cfg_state == 2'd2);

    function [W-1:0] choose_step;
        input [W-1:0] left;
        input [W-1:0] limit;
        begin
            if (left <= 16'd1)
                choose_step = 16'd1;
            else if (left - 16'd1 < limit)
                choose_step = left - 16'd1;
            else
                choose_step = limit;
        end
    endfunction

    always @(posedge clk) begin
        case (cfg_state)
            2'd0: begin
                if (cfg_valid && cfg_ready) begin
                    cfg_pending <= cfg_data;
                    cfg_state <= 2'd1;
                end
            end
            2'd1: begin
                if (cfg_pending == 16'd0)
                    cfg_prepared <= 16'd1;
                else if (cfg_pending > MAX_BURST)
                    cfg_prepared <= MAX_BURST;
                else
                    cfg_prepared <= cfg_pending;
                cfg_state <= 2'd2;
            end
            2'd2: begin
                cap[cfg_index] <= cfg_prepared;
                if (cfg_index == LAST_PROFILE)
                    cfg_index <= {INDEX_W{1'b0}};
                else
                    cfg_index <= cfg_index + 1'b1;
                cfg_state <= 2'd0;
            end
            default: cfg_state <= 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (start) begin
            quantum <= cap[selected];
            step <= choose_step(launch_latency, cap[selected]);
        end else if (finish) begin
            step <= 16'd0;
        end else if (run) begin
            step <= choose_step(remaining - step, quantum);
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter BURST_PROFILES = 4,
    parameter MAX_BURST = 4,
    parameter PEER_DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output wire         cfg_ready,
    output wire         cfg_busy,
    output wire [W-1:0] burst_step,
    output wire [W*BURST_PROFILES-1:0] burst_profiles,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_a,
    input  wire [W-1:0] peer_b,
    input  wire [W-1:0] peer_w,
    input  wire [W-1:0] peer_latency,
    output wire [$clog2(PEER_DEPTH):0] peer_queued,
    output reg          peer_active = 1'b0,
    output reg  [W-1:0] peer_phase = 16'd0,
    output reg  [W-1:0] peer_remaining = 16'd0,
    output reg          out_owner = 1'b0
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam CHANNELS = 2;
    localparam LANE_W = $clog2(CHANNELS);
    localparam PEER_ADDR_W = $clog2(PEER_DEPTH);
    localparam PEER_PTR_W = PEER_ADDR_W + 1;
    localparam [PEER_ADDR_W-1:0] PEER_LAST_SLOT = PEER_DEPTH - 1;
    localparam FLIGHT_W = $clog2(DEPTH + PEER_DEPTH + 2);

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    reg [W-1:0] peer_q_a [0:PEER_DEPTH-1];
    reg [W-1:0] peer_q_b [0:PEER_DEPTH-1];
    reg [W-1:0] peer_q_w [0:PEER_DEPTH-1];
    reg [W-1:0] peer_q_lat [0:PEER_DEPTH-1];
    reg [PEER_PTR_W-1:0] peer_wr = {PEER_PTR_W{1'b0}};
    reg [PEER_PTR_W-1:0] peer_rd = {PEER_PTR_W{1'b0}};
    reg [LANE_W-1:0] next_lane = {LANE_W{1'b0}};
    wire [CHANNELS-1:0] request;
    reg [CHANNELS-1:0] grant;
    integer init_peer;
    wire [PEER_ADDR_W-1:0] peer_head = peer_rd[PEER_ADDR_W-1:0];
    wire peer_empty = (peer_wr == peer_rd);
    wire peer_full = (peer_wr[PEER_ADDR_W] != peer_rd[PEER_ADDR_W]) &&
                     (peer_wr[PEER_ADDR_W-1:0] == peer_rd[PEER_ADDR_W-1:0]);
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    initial begin
        for (init_peer = 0; init_peer < PEER_DEPTH; init_peer = init_peer + 1) begin
            peer_q_a[init_peer] = 16'd0;
            peer_q_b[init_peer] = 16'd0;
            peer_q_w[init_peer] = 16'd0;
            peer_q_lat[init_peer] = 16'd0;
        end
    end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;
    assign peer_ready = !peer_full;
    assign peer_queued = (peer_wr[PEER_ADDR_W] == peer_rd[PEER_ADDR_W]) ?
        ({1'b0, peer_wr[PEER_ADDR_W-1:0]} - {1'b0, peer_rd[PEER_ADDR_W-1:0]}) :
        (PEER_DEPTH + {1'b0, peer_wr[PEER_ADDR_W-1:0]} - {1'b0, peer_rd[PEER_ADDR_W-1:0]});
    wire peer_accept = peer_valid && peer_ready;
    wire peer_deliver = out_valid && out_ready && out_owner;
    wire [FLIGHT_W-1:0] held_items = {1'b0, queued} + {1'b0, peer_queued} +
        ((out_valid && !out_owner) ? 1'b1 : 1'b0);

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = grant[0];
    wire peer_last = (peer_phase == peer_q_lat[peer_head] - 16'd1);
    assign request[0] = busy && ce && last;
    assign request[1] = peer_active && ce && peer_last;
    always @(*) begin
        grant = {CHANNELS{1'b0}};
        if (!out_valid) begin
            if (request[0] && request[1])
                grant[next_lane] = 1'b1;
            else if (request[0])
                grant[0] = 1'b1;
            else if (request[1])
                grant[1] = 1'b1;
        end
    end
    always @(posedge clk) begin
        if (grant[0]) next_lane <= 1'b1;
        else if (grant[1]) next_lane <= 1'b0;
    end
    wire [W-1:0] burst_quantum;
    wire [1:0] cfg_state;
    wire [$clog2(BURST_PROFILES)-1:0] cfg_write_index;
    wire [W-1:0] cfg_pending;
    wire [W-1:0] cfg_prepared;
    wire cfg_apply;
    assign cfg_busy = (cfg_state != 2'd0);

    ntt_phase_dispatch #(
        .W(W), .PROFILES(BURST_PROFILES), .MAX_BURST(MAX_BURST)
    ) phase_dispatch (
        .clk(clk), .cfg_valid(load_cfg), .cfg_ready(cfg_ready),
        .cfg_data(cfg_lat), .profile_select(stage),
        .start(start), .run(busy && ce && !last), .finish(retire),
        .remaining(cd), .launch_latency(lat_q),
        .step(burst_step), .quantum(burst_quantum),
        .profiles(burst_profiles), .cfg_state(cfg_state),
        .cfg_index(cfg_write_index), .cfg_pending(cfg_pending),
        .cfg_prepared(cfg_prepared), .cfg_apply(cfg_apply)
    );

    wire [W-1:0] shared_a = grant[1] ? peer_q_a[peer_head] : a_r;
    wire [W-1:0] shared_b = grant[1] ? peer_q_b[peer_head] : b_r;
    wire [W-1:0] shared_w = grant[1] ? peer_q_w[peer_head] : w_r;
    wire [31:0] prod = shared_w * shared_b;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, shared_a} + {1'b0, t};
    wire [16:0] dif = {1'b0, shared_a} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (peer_accept) begin
            peer_q_a[peer_wr[PEER_ADDR_W-1:0]] <= peer_a;
            peer_q_b[peer_wr[PEER_ADDR_W-1:0]] <= peer_b;
            peer_q_w[peer_wr[PEER_ADDR_W-1:0]] <= peer_w;
            peer_q_lat[peer_wr[PEER_ADDR_W-1:0]] <=
                (peer_latency == 16'd0) ? 16'd1 : peer_latency;
            if (peer_wr[PEER_ADDR_W-1:0] == PEER_LAST_SLOT)
                peer_wr <= {!peer_wr[PEER_ADDR_W], {PEER_ADDR_W{1'b0}}};
            else
                peer_wr <= peer_wr + 1'b1;
        end
        if (peer_deliver) begin
            if (peer_rd[PEER_ADDR_W-1:0] == PEER_LAST_SLOT)
                peer_rd <= {!peer_rd[PEER_ADDR_W], {PEER_ADDR_W{1'b0}}};
            else
                peer_rd <= peer_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (peer_deliver) begin
            peer_active <= 1'b0;
            peer_remaining <= 16'd0;
            peer_phase <= 16'd0;
        end else if (ce) begin
            if (!peer_active && !peer_empty) begin
                peer_active <= 1'b1;
                peer_remaining <= peer_q_lat[peer_head];
                peer_phase <= 16'd0;
            end else if (peer_active && !peer_last) begin
                peer_remaining <= peer_remaining - 16'd1;
                peer_phase <= peer_phase + 16'd1;
            end
        end
    end
    always @(posedge clk) begin
        if (|grant) begin
            out_valid <= 1'b1;
            out_owner <= grant[1];
            out_a <= sum_mod;
            out_b <= dif_mod;
        end else if (out_valid && out_ready) begin
            out_valid <= 1'b0;
        end
    end
    always @(posedge clk) begin
        if (out_valid && out_owner)
            assert (peer_remaining == 16'd1);
    end
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (cfg_apply) lat_cfg <= cfg_pending;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce && (!last || grant[0])) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - burst_step;
                phase <= phase + burst_step;
            end
        end
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output reg  [31:0]  debug_status
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    reg [15:0] stat_accept = 16'd0;
    reg [15:0] stat_retire = 16'd0;
    reg [15:0] stat_inwait = 16'd0;
    reg [15:0] stat_outwait = 16'd0;
    reg [15:0] stat_busy = 16'd0;
    reg [15:0] stat_stall_run = 16'd0;
    reg [15:0] stat_stall_max = 16'd0;
    reg [PTR_W-1:0] stat_high_water = {PTR_W{1'b0}};
    reg [3:0] stat_events = 4'd0;
    reg [2:0] stat_page = 3'd0;
    reg [W-1:0] stat_last_lat = {W{1'b0}};
    reg [7:0] stat_epoch = 8'd0;
    reg [15:0] stat_checksum = 16'd0;
    initial begin
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (load_cfg) begin
            stat_epoch <= stat_epoch + 8'd1;
            stat_last_lat <= cfg_lat;
        end
        if (accept && stat_accept != 16'hffff)
            stat_accept <= stat_accept + 16'd1;
        if (retire && stat_retire != 16'hffff)
            stat_retire <= stat_retire + 16'd1;
        if (in_valid && !in_ready && stat_inwait != 16'hffff)
            stat_inwait <= stat_inwait + 16'd1;
        if (out_valid && !out_ready && stat_outwait != 16'hffff)
            stat_outwait <= stat_outwait + 16'd1;
        if (busy && ce && stat_busy != 16'hffff)
            stat_busy <= stat_busy + 16'd1;
        if (queued > stat_high_water)
            stat_high_water <= queued;
        if (accept)
            stat_checksum <= {stat_checksum[14:0], stat_checksum[15]} ^ in_a ^ in_b ^ in_w;
        if (out_valid && !out_ready) begin
            if (stat_stall_run != 16'hffff)
                stat_stall_run <= stat_stall_run + 16'd1;
            if (stat_stall_run >= stat_stall_max && stat_stall_run != 16'hffff)
                stat_stall_max <= stat_stall_run + 16'd1;
        end else begin
            stat_stall_run <= 16'd0;
        end
        if (in_valid && !in_ready)
            stat_events[0] <= 1'b1;
        if (out_valid && !out_ready)
            stat_events[1] <= 1'b1;
        if (accept && !ce)
            stat_events[2] <= 1'b1;
        if (load_cfg && busy)
            stat_events[3] <= 1'b1;
        if (ce) begin
            stat_page <= stat_page + 3'd1;
            case (stat_page)
                3'd0: debug_status <= {stat_retire, stat_accept};
                3'd1: debug_status <= {stat_outwait, stat_inwait};
                3'd2: debug_status <= {stat_stall_max, stat_stall_run};
                3'd3: debug_status <= {stat_checksum, stat_busy};
                3'd4: debug_status <= stat_high_water;
                3'd5: debug_status <= stat_last_lat;
                3'd6: debug_status <= {20'd0, stat_epoch, stat_events};
                3'd7: debug_status <= {24'd0, ce, busy, head_valid, q_full, q_empty, out_valid, in_valid, in_ready};
            endcase
        end
    end
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module search_fifo #(
    parameter DEPTH = 32,
    parameter DW = 16,
    parameter AW = $clog2(DEPTH)
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            in_valid,
    output wire            in_ready,
    input  wire [DW-1:0]   in_data,
    output wire            out_valid,
    input  wire            out_ready,
    output wire [DW-1:0]   out_data,
    input  wire            srch_valid,
    output wire            srch_ready,
    input  wire [DW-1:0]   srch_key,
    output wire            srch_present,
    output wire [DEPTH-1:0] srch_vec,
    output wire            res_valid,
    input  wire            res_ready,
    output wire [AW-1:0]   res_pos,
    output wire            res_hit,
    output wire            res_last,
    input  wire            cfg_we,
    input  wire [15:0]     cfg_timeout
,
    output wire armed_o,
    output wire busy_o,
    output wire [15:0] count_o,
    output wire [15:0] scan_left_o,
    output wire [15:0] timeout_q_o,
    output wire [15:0] timer_o
);
    localparam [15:0] DEPTH16 = DEPTH;

    reg [DEPTH*DW-1:0] mem;
    reg [DEPTH-1:0]    vld;
    reg [AW-1:0]       head, tail;
    reg [15:0]         count;
    reg                busy;
    reg [DW-1:0]       key_q;
    reg [AW-1:0]       scan_idx;
    reg [15:0]         scan_left;
    reg [15:0]         timer;
    reg [15:0]         timeout_q;
    reg                armed;

    initial begin
        mem = {(DEPTH*DW){1'b0}};
        vld = {DEPTH{1'b0}};
        head = {AW{1'b0}};
        tail = {AW{1'b0}};
        count = 16'd0;
        busy = 1'b0;
        key_q = {DW{1'b0}};
        scan_idx = {AW{1'b0}};
        scan_left = 16'd0;
        timer = 16'd0;
        timeout_q = DEPTH16;
        armed = 1'b1;
    end

    assign in_ready   = (count != DEPTH16) && !busy;
    assign out_valid  = (count != 16'd0);
    assign out_data   = mem[head*DW +: DW];
    assign srch_ready = !busy;
    assign res_valid  = busy;
    assign res_pos    = scan_idx;
    assign res_hit    = vld[scan_idx] && (mem[scan_idx*DW +: DW] == key_q);
    assign res_last   = (scan_left == 16'd1);

    genvar gi;
    generate
        for (gi = 0; gi < DEPTH; gi = gi + 1) begin : g_cmp
            assign srch_vec[gi] = vld[gi] && (mem[gi*DW +: DW] == srch_key);
        end
    endgenerate
    assign srch_present = |srch_vec;

    wire push_fire = in_valid && in_ready;
    wire pop_fire  = out_valid && out_ready;
    wire srch_fire = srch_valid && srch_ready;
    wire res_fire  = res_valid && res_ready;
    wire cfg_fire  = cfg_we && !busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mem <= {(DEPTH*DW){1'b0}};
            vld <= {DEPTH{1'b0}};
            head <= {AW{1'b0}};
            tail <= {AW{1'b0}};
            count <= 16'd0;
            busy <= 1'b0;
            key_q <= {DW{1'b0}};
            scan_idx <= {AW{1'b0}};
            scan_left <= 16'd0;
            timer <= 16'd0;
            timeout_q <= DEPTH16;
            armed <= 1'b1;
        end else begin
            if (push_fire) begin
                mem[tail*DW +: DW] <= in_data;
                vld[tail] <= 1'b1;
                tail <= tail + 1'b1;
            end
            if (pop_fire) begin
                vld[head] <= 1'b0;
                head <= head + 1'b1;
            end
            case ({push_fire, pop_fire})
                2'b10: count <= count + 16'd1;
                2'b01: count <= count - 16'd1;
                default: ;
            endcase

            if (srch_fire) begin
                key_q     <= srch_key;
                scan_idx  <= head;
                scan_left <= count;
                timer     <= timeout_q;
                busy      <= (count != 16'd0);
            end else if (res_fire) begin
                scan_idx  <= scan_idx + 1'b1;
                scan_left <= scan_left - 16'd1;
                if (timer != 16'd0)
                    timer <= timer - 16'd1;
                if (scan_left == 16'd1)
                    busy <= 1'b0;
            end

            if (cfg_fire) begin
                timeout_q <= cfg_timeout;
                armed     <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed && busy)
            assert (timer != 16'd0);
    assign armed_o = armed;
    assign busy_o = busy;
    assign count_o = count;
    assign scan_left_o = scan_left;
    assign timeout_q_o = timeout_q;
    assign timer_o = timer;
endmodule

module searchable_csc #(
    parameter BRIDGE_DEPTH = 4
) (
    input wire clk, rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire out_valid,
    input wire out_ready,
    output wire [24:0] out_data,
    input wire srch_valid,
    output wire srch_ready,
    input wire [24:0] srch_key,
    output wire srch_present,
    output wire [31:0] srch_vec,
    output wire res_valid,
    input wire res_ready,
    output wire [4:0] res_pos,
    output wire res_hit, res_last,
    input wire search_cfg_we,
    input wire [15:0] search_cfg_timeout,
    output wire [31:0] debug_status,
    output wire [2:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire b_in_valid, b_in_ready,
    output wire [24:0] b_in_data,
    output wire b_armed, b_busy,
    output wire [15:0] b_count, b_scan_left, b_timeout_q, b_timer,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] drained,
    output reg active
);
    localparam INGRESS_DEPTH = 4;
    localparam SEARCH_DEPTH = 32;
    localparam PTR_W = $clog2(BRIDGE_DEPTH);
    wire rst_n = !rst;
    wire a_reset = !active;
    wire a_i_ready;
    reg [24:0] pixels [0:BRIDGE_DEPTH-1];
    reg [PTR_W-1:0] rd_ptr, wr_ptr;
    integer k;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire bridge_push = a_o_valid && a_o_ready;
    wire sink_pop = out_valid && out_ready;
    assign i_ready = active && a_i_ready;
    assign a_o_ready = active && ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign b_in_valid = active && (bridge_level != 0);
    assign b_in_data = pixels[rd_ptr];

    csc_rgb2ycc #(.W(32), .INGRESS_DEPTH(INGRESS_DEPTH)) converter (
        .clk(clk), .rst(a_reset),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid && active), .i_ready(a_i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    search_fifo #(.DEPTH(SEARCH_DEPTH), .DW(25)) queue (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(out_valid), .out_ready(out_ready), .out_data(out_data),
        .srch_valid(srch_valid), .srch_ready(srch_ready), .srch_key(srch_key),
        .srch_present(srch_present), .srch_vec(srch_vec),
        .res_valid(res_valid), .res_ready(res_ready), .res_pos(res_pos),
        .res_hit(res_hit), .res_last(res_last),
        .cfg_we(search_cfg_we), .cfg_timeout(search_cfg_timeout),
        .armed_o(b_armed), .busy_o(b_busy), .count_o(b_count),
        .scan_left_o(b_scan_left), .timeout_q_o(b_timeout_q), .timer_o(b_timer)
    );

    // Hold the synchronous converter in reset through asynchronous reset release.
    initial begin
        active = 1'b0; bridge_level = 0; drained = 32'd0;
        rd_ptr = 0; wr_ptr = 0;
        for (k = 0; k < BRIDGE_DEPTH; k = k + 1) pixels[k] = 25'd0;
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            active <= 1'b0; bridge_level <= 0; drained <= 32'd0;
            rd_ptr <= 0; wr_ptr <= 0;
            for (k = 0; k < BRIDGE_DEPTH; k = k + 1) pixels[k] <= 25'd0;
        end else begin
            active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                pixels[wr_ptr] <= {a_o_last, a_o_y, a_o_cb, a_o_cr};
                wr_ptr <= (wr_ptr == BRIDGE_DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (bridge_pop)
                rd_ptr <= (rd_ptr == BRIDGE_DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
            if (sink_pop) drained <= drained + 32'd1;
        end
    end

    always @(posedge clk)
        if (active && (a_ingress_level == 0) && !a_o_valid &&
            (bridge_level == 0) && (b_count == 16'd0))
            assert (a_ingress_accepted == drained);
endmodule

module ntt_stage_profile #(
    parameter W = 16,
    parameter NBF = 12,
    parameter BANKS = 4
) (
    input  wire clk,
    input  wire sample_enable,
    input  wire sample_valid,
    output wire sample_ready,
    input  wire [W-1:0] sample_pos,
    input  wire [W-1:0] sample_stage,
    input  wire [W-1:0] sample_a,
    input  wire [W-1:0] sample_b,
    input  wire report_ready,
    output reg report_valid,
    output reg [W-1:0] report_stage,
    output reg [BANKS*W-1:0] report_min,
    output reg [BANKS*W-1:0] report_max,
    output reg [BANKS*W-1:0] report_sum,
    output reg [BANKS*W-1:0] report_distance,
    output reg [BANKS*W-1:0] report_signature,
    output reg [BANKS*$clog2((NBF+BANKS-1)/BANKS+1)-1:0] bank_samples
);
    localparam COUNT_W = $clog2((NBF+BANKS-1)/BANKS+1);
    localparam BANK_W = $clog2(BANKS);
    reg [W-1:0] live_min [0:BANKS-1];
    reg [W-1:0] live_max [0:BANKS-1];
    reg [W-1:0] live_sum [0:BANKS-1];
    reg [W-1:0] live_distance [0:BANKS-1];
    reg [W-1:0] live_signature [0:BANKS-1];
    reg [COUNT_W-1:0] samples [0:BANKS-1];
    reg [W-1:0] snap_min [0:BANKS-1];
    reg [W-1:0] snap_max [0:BANKS-1];
    reg [W-1:0] snap_sum [0:BANKS-1];
    reg [W-1:0] snap_distance [0:BANKS-1];
    reg [W-1:0] snap_signature [0:BANKS-1];
    wire [BANK_W-1:0] selected = sample_pos % BANKS;
    wire end_stage = (sample_pos == NBF - 1);
    wire fire = sample_valid && sample_ready;
    wire [W-1:0] pair_min = (sample_a < sample_b) ? sample_a : sample_b;
    wire [W-1:0] pair_max = (sample_a > sample_b) ? sample_a : sample_b;
    wire [W-1:0] pair_sum = sample_a + sample_b;
    wire [W-1:0] pair_distance = (sample_a >= sample_b) ?
        (sample_a - sample_b) : (sample_b - sample_a);
    wire [W-1:0] rotated_b = {sample_b[W-2:0], sample_b[W-1]};
    wire [W-1:0] next_signature =
        {live_signature[selected][W-2:0], live_signature[selected][W-1]} ^ sample_a ^ rotated_b;
    reg [W-1:0] next_min;
    reg [W-1:0] next_max;
    reg [W-1:0] next_sum;
    reg [W-1:0] next_distance;
    integer init_bank;
    integer pack_bank;
    integer write_bank;
    assign sample_ready = sample_enable &&
        (!end_stage || !report_valid || report_ready);
    initial begin
        report_valid = 1'b0;
        report_stage = 16'd0;
        for (init_bank = 0; init_bank < BANKS; init_bank = init_bank + 1) begin
            live_min[init_bank] = 16'd0;
            live_max[init_bank] = 16'd0;
            live_sum[init_bank] = 16'd0;
            live_distance[init_bank] = 16'd0;
            live_signature[init_bank] = 16'd0;
            samples[init_bank] = {COUNT_W{1'b0}};
            snap_min[init_bank] = 16'd0;
            snap_max[init_bank] = 16'd0;
            snap_sum[init_bank] = 16'd0;
            snap_distance[init_bank] = 16'd0;
            snap_signature[init_bank] = 16'd0;
        end
    end
    always @(*) begin
        next_min = (samples[selected] == 0 || pair_min < live_min[selected]) ?
            pair_min : live_min[selected];
        next_max = (samples[selected] == 0 || pair_max > live_max[selected]) ?
            pair_max : live_max[selected];
        next_sum = live_sum[selected] + pair_sum;
        next_distance = live_distance[selected] + pair_distance;
    end
    always @(*) begin
        for (pack_bank = 0; pack_bank < BANKS; pack_bank = pack_bank + 1) begin
            report_min[pack_bank*W +: W] = snap_min[pack_bank];
            report_max[pack_bank*W +: W] = snap_max[pack_bank];
            report_sum[pack_bank*W +: W] = snap_sum[pack_bank];
            report_distance[pack_bank*W +: W] = snap_distance[pack_bank];
            report_signature[pack_bank*W +: W] = snap_signature[pack_bank];
            bank_samples[pack_bank*COUNT_W +: COUNT_W] = samples[pack_bank];
        end
    end
    always @(posedge clk) begin
        if (report_valid && report_ready)
            report_valid <= 1'b0;
        if (fire) begin
            if (end_stage) begin
                report_valid <= 1'b1;
                report_stage <= sample_stage;
            end
            for (write_bank = 0; write_bank < BANKS; write_bank = write_bank + 1) begin
                if (end_stage) begin
                    snap_min[write_bank] <= (write_bank == selected) ?
                        next_min : live_min[write_bank];
                    snap_max[write_bank] <= (write_bank == selected) ?
                        next_max : live_max[write_bank];
                    snap_sum[write_bank] <= (write_bank == selected) ?
                        next_sum : live_sum[write_bank];
                    snap_distance[write_bank] <= (write_bank == selected) ?
                        next_distance : live_distance[write_bank];
                    snap_signature[write_bank] <= (write_bank == selected) ?
                        next_signature : live_signature[write_bank];
                    live_min[write_bank] <= 16'd0;
                    live_max[write_bank] <= 16'd0;
                    live_sum[write_bank] <= 16'd0;
                    live_distance[write_bank] <= 16'd0;
                    live_signature[write_bank] <= 16'd0;
                    samples[write_bank] <= {COUNT_W{1'b0}};
                end else if (write_bank == selected) begin
                    live_min[write_bank] <= next_min;
                    live_max[write_bank] <= next_max;
                    live_sum[write_bank] <= next_sum;
                    live_distance[write_bank] <= next_distance;
                    live_signature[write_bank] <= next_signature;
                    samples[write_bank] <= samples[write_bank] + 1'b1;
                end
            end
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter MON_BANKS = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output reg  [31:0]  debug_status,
    output wire         stage_stats_valid,
    output wire         stage_stats_take,
    output wire         stage_stats_blocked,
    output wire [W-1:0] stage_stats_stage,
    output wire [MON_BANKS*W-1:0] stage_stats_min,
    output wire [MON_BANKS*W-1:0] stage_stats_max,
    output wire [MON_BANKS*W-1:0] stage_stats_sum,
    output wire [MON_BANKS*W-1:0] stage_stats_distance,
    output wire [MON_BANKS*W-1:0] stage_stats_signature
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam MON_COUNT_W = $clog2((NBF+MON_BANKS-1)/MON_BANKS+1);
    localparam MON_TOTAL_W = $clog2(NBF+1);

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire diag_ready;
    wire [MON_BANKS*MON_COUNT_W-1:0] diag_samples;
    wire run_cycle = ce && (!last || diag_ready);
    wire retire = busy && last && diag_ready;
    assign stage_stats_blocked = busy && last && !diag_ready;
    assign stage_stats_take = stage_stats_valid && out_ready && !out_valid;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    ntt_stage_profile #(
        .W(W),
        .NBF(NBF),
        .BANKS(MON_BANKS)
    ) stage_profile (
        .clk(clk),
        .sample_enable(ce),
        .sample_valid(busy && last),
        .sample_ready(diag_ready),
        .sample_pos(bf_idx),
        .sample_stage(stage),
        .sample_a(sum_mod),
        .sample_b(dif_mod),
        .report_ready(out_ready && !out_valid),
        .report_valid(stage_stats_valid),
        .report_stage(stage_stats_stage),
        .report_min(stage_stats_min),
        .report_max(stage_stats_max),
        .report_sum(stage_stats_sum),
        .report_distance(stage_stats_distance),
        .report_signature(stage_stats_signature),
        .bank_samples(diag_samples)
    );
    reg [MON_TOTAL_W-1:0] diag_sample_total;
    integer diag_bank;
    always @(*) begin
        diag_sample_total = {MON_TOTAL_W{1'b0}};
        for (diag_bank = 0; diag_bank < MON_BANKS; diag_bank = diag_bank + 1)
            diag_sample_total = diag_sample_total +
                diag_samples[diag_bank*MON_COUNT_W +: MON_COUNT_W];
    end
    reg [15:0] stat_accept = 16'd0;
    reg [15:0] stat_retire = 16'd0;
    reg [15:0] stat_inwait = 16'd0;
    reg [15:0] stat_outwait = 16'd0;
    reg [15:0] stat_busy = 16'd0;
    reg [15:0] stat_stall_run = 16'd0;
    reg [15:0] stat_stall_max = 16'd0;
    reg [PTR_W-1:0] stat_high_water = {PTR_W{1'b0}};
    reg [3:0] stat_events = 4'd0;
    reg [2:0] stat_page = 3'd0;
    reg [W-1:0] stat_last_lat = {W{1'b0}};
    reg [7:0] stat_epoch = 8'd0;
    reg [15:0] stat_checksum = 16'd0;
    initial begin
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (load_cfg) begin
            stat_epoch <= stat_epoch + 8'd1;
            stat_last_lat <= cfg_lat;
        end
        if (accept && stat_accept != 16'hffff)
            stat_accept <= stat_accept + 16'd1;
        if (retire && stat_retire != 16'hffff)
            stat_retire <= stat_retire + 16'd1;
        if (in_valid && !in_ready && stat_inwait != 16'hffff)
            stat_inwait <= stat_inwait + 16'd1;
        if (out_valid && !out_ready && stat_outwait != 16'hffff)
            stat_outwait <= stat_outwait + 16'd1;
        if (busy && ce && stat_busy != 16'hffff)
            stat_busy <= stat_busy + 16'd1;
        if (queued > stat_high_water)
            stat_high_water <= queued;
        if (accept)
            stat_checksum <= {stat_checksum[14:0], stat_checksum[15]} ^ in_a ^ in_b ^ in_w;
        if (out_valid && !out_ready) begin
            if (stat_stall_run != 16'hffff)
                stat_stall_run <= stat_stall_run + 16'd1;
            if (stat_stall_run >= stat_stall_max && stat_stall_run != 16'hffff)
                stat_stall_max <= stat_stall_run + 16'd1;
        end else begin
            stat_stall_run <= 16'd0;
        end
        if (in_valid && !in_ready)
            stat_events[0] <= 1'b1;
        if (out_valid && !out_ready)
            stat_events[1] <= 1'b1;
        if (accept && !ce)
            stat_events[2] <= 1'b1;
        if (load_cfg && busy)
            stat_events[3] <= 1'b1;
        if (ce) begin
            stat_page <= stat_page + 3'd1;
            case (stat_page)
                3'd0: debug_status <= {stat_retire, stat_accept};
                3'd1: debug_status <= {stat_outwait, stat_inwait};
                3'd2: debug_status <= {stat_stall_max, stat_stall_run};
                3'd3: debug_status <= {stat_checksum, stat_busy};
                3'd4: debug_status <= stat_high_water;
                3'd5: debug_status <= stat_last_lat;
                3'd6: debug_status <= {20'd0, stat_epoch, stat_events};
                3'd7: debug_status <= {24'd0, ce, busy, head_valid, q_full, q_empty, out_valid, in_valid, in_ready};
            endcase
        end
    end
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && run_cycle) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (retire)
            assert (diag_sample_total == bf_idx);
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module preload_timer #(
    parameter W = 64,
    parameter [W-1:0] INIT_PERIOD = 64'd7
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         tick,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire         match,
    output wire         reload_evt
,
    output wire [W-1:0] cnt_o,
    output wire [W-1:0] deadline_o,
    output wire pending_o
);
    reg [W-1:0] cnt           = INIT_PERIOD;
    reg [W-1:0] period        = INIT_PERIOD;
    reg [W-1:0] cmp_active    = {W{1'b0}};
    reg [W-1:0] shadow_period = INIT_PERIOD;
    reg [W-1:0] shadow_cmp    = {W{1'b0}};
    reg [W-1:0] deadline      = {W{1'b0}};
    reg         pending       = 1'b0;
    reg         armed         = 1'b0;
    reg         pv            = 1'b0;

    assign in_ready   = !pending;
    wire   accept     = in_valid && in_ready;
    wire   due        = (deadline == {W{1'b0}});
    assign reload_evt = tick && (cnt == {W{1'b0}});
    assign match      = (cnt == cmp_active);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cnt           <= INIT_PERIOD;
            period        <= INIT_PERIOD;
            cmp_active    <= {W{1'b0}};
            shadow_period <= INIT_PERIOD;
            shadow_cmp    <= {W{1'b0}};
            pending       <= 1'b0;
            deadline      <= {W{1'b0}};
        end else begin
            if (tick) begin
                if (cnt == {W{1'b0}}) begin
                    if (pending) begin
                        cnt        <= shadow_period;
                        period     <= shadow_period;
                        cmp_active <= shadow_cmp;
                        pending    <= 1'b0;
                    end else begin
                        cnt <= period;
                    end
                end else begin
                    cnt <= cnt - 1'b1;
                end
                if (pending && (cnt != {W{1'b0}}) && !due)
                    deadline <= deadline - 1'b1;
            end
            if (accept) begin
                shadow_period <= in_period;
                shadow_cmp    <= in_cmp;
                pending       <= 1'b1;
                armed         <= 1'b1;
                deadline      <= tick ? ((cnt == {W{1'b0}}) ? period : (cnt - 1'b1)) : cnt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && pending && $rose(due))
            assert (cnt == {W{1'b0}});
    assign cnt_o = cnt;
    assign deadline_o = deadline;
    assign pending_o = pending;
endmodule

module mn_clken_gen #(
    parameter W = 64,
    parameter [W-1:0] M_DEF = 64'd3,
    parameter [W-1:0] N_DEF = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         req,
    input  wire         cfg_load,
    input  wire [W-1:0] cfg_m,
    input  wire [W-1:0] cfg_n,
    output wire         ce_out,
    output wire         busy
,
    output wire armed_o,
    output wire [W-1:0] cd_o,
    output wire [W-1:0] err_o,
    output wire [W-1:0] m_r_o,
    output wire [W-1:0] n_r_o,
    output wire timeout_o
);
    reg [W-1:0] m_r = M_DEF;
    reg [W-1:0] n_r = N_DEF;
    reg [W-1:0] err = {W{1'b0}};
    reg [W-1:0] cd  = {W{1'b0}};
    reg         armed = 1'b0;
    reg         timeout = 1'b0;

    wire [W:0]   sum  = {1'b0, err} + {1'b0, m_r};
    wire         hit  = (sum >= {1'b0, n_r});
    wire [W:0]   diff = sum - {1'b0, n_r};
    wire [W-1:0] err_nxt = step ? (hit ? diff[W-1:0] : sum[W-1:0]) : err;
    wire         cfg_ok = (cfg_n != {W{1'b0}}) && (cfg_m != {W{1'b0}}) && (cfg_m <= cfg_n);

    assign ce_out = step && hit;
    assign busy   = armed;

    always @(posedge clk) begin
        if (rst) begin
            m_r     <= M_DEF;
            n_r     <= N_DEF;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else if (cfg_load && cfg_ok) begin
            m_r     <= cfg_m;
            n_r     <= cfg_n;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else begin
            err <= err_nxt;
            if (!armed) begin
                if (req) begin
                    armed <= 1'b1;
                    cd    <= n_r - err_nxt;
                end
            end else if (step) begin
                if (hit)
                    armed <= 1'b0;
                else if (cd <= m_r)
                    timeout <= 1'b1;
                else
                    cd <= cd - m_r;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(armed))
            assert ($stable(timeout));
    assign armed_o = armed;
    assign cd_o = cd;
    assign err_o = err;
    assign m_r_o = m_r;
    assign n_r_o = n_r;
    assign timeout_o = timeout;
endmodule

module fractional_timer_system #(
    parameter W = 64,
    parameter [W-1:0] INIT_PERIOD = 64'd7,
    parameter [W-1:0] M_DEF = 64'd3,
    parameter [W-1:0] N_DEF = 64'd8
) (
    input wire clk,
    input wire rst,
    input wire tick,
    input wire step,
    input wire in_valid,
    output wire in_ready,
    input wire [W-1:0] in_period,
    input wire [W-1:0] in_cmp,
    input wire req,
    output wire req_ready,
    input wire cfg_load,
    output wire cfg_ready,
    input wire [W-1:0] cfg_m,
    input wire [W-1:0] cfg_n,
    output wire match,
    output wire reload_evt,
    output wire [W-1:0] cnt_o,
    output wire [W-1:0] deadline_o,
    output wire pending_o,
    output wire ce_out,
    output wire busy,
    output wire armed_o,
    output wire [W-1:0] cd_o,
    output wire [W-1:0] err_o,
    output wire [W-1:0] m_r_o,
    output wire [W-1:0] n_r_o,
    output wire timeout_o,
    output reg slot_valid = 1'b0,
    output reg [W-1:0] slot_period = {W{1'b0}},
    output reg [W-1:0] slot_cmp = {W{1'b0}}
);
    wire timer_ready;
    wire cfg_ok = (cfg_n != {W{1'b0}}) &&
                  (cfg_m != {W{1'b0}}) && (cfg_m <= cfg_n);
    wire cfg_accept = cfg_load && cfg_ready;
    wire req_accept = req && req_ready;
    wire completion_valid = ce_out && armed_o;
    wire generated_take = slot_valid && timer_ready;
    wire external_take = in_valid && in_ready;
    wire timer_valid = slot_valid || in_valid;
    wire [W-1:0] timer_period = slot_valid ? slot_period : in_period;
    wire [W-1:0] timer_cmp = slot_valid ? slot_cmp : in_cmp;

    assign cfg_ready = !busy && cfg_ok;
    assign req_ready = !busy && !slot_valid && !cfg_load;
    assign in_ready = timer_ready && !slot_valid;

    // Reserve the completion slot before starting a timed update.
    mn_clken_gen #(.W(W), .M_DEF(M_DEF), .N_DEF(N_DEF)) rate (
        .clk(clk), .rst(rst), .step(step),
        .req(req_accept), .cfg_load(cfg_accept),
        .cfg_m(cfg_m), .cfg_n(cfg_n),
        .ce_out(ce_out), .busy(busy), .armed_o(armed_o),
        .cd_o(cd_o), .err_o(err_o),
        .m_r_o(m_r_o), .n_r_o(n_r_o), .timeout_o(timeout_o)
    );

    // The tick input is independent of the configuration handshake.
    preload_timer #(.W(W), .INIT_PERIOD(INIT_PERIOD)) timer (
        .clk(clk), .rst(rst), .tick(tick),
        .in_valid(timer_valid), .in_ready(timer_ready),
        .in_period(timer_period), .in_cmp(timer_cmp),
        .match(match), .reload_evt(reload_evt),
        .cnt_o(cnt_o), .deadline_o(deadline_o), .pending_o(pending_o)
    );

    // A completed request snapshots its ratio before later reprogramming.
    // Buffered updates take priority over the external configuration port.
    always @(posedge clk) begin
        if (rst) begin
            slot_valid <= 1'b0;
            slot_period <= {W{1'b0}};
            slot_cmp <= {W{1'b0}};
        end else begin
            if (generated_take)
                slot_valid <= 1'b0;
            if (completion_valid) begin
                slot_valid <= 1'b1;
                slot_period <= n_r_o;
                slot_cmp <= m_r_o;
            end
        end
    end

    // Every generated update delivered to the timer is a legal schedule.
    always @(posedge clk)
        if (generated_take)
            assert ((timer_cmp != {W{1'b0}}) &&
                    (timer_period != {W{1'b0}}) &&
                    (timer_cmp <= timer_period));
endmodule

module ldpc_cnp_group_reduce #(
    parameter W = 32,
    parameter GROUPS = 4
) (
    input  wire clk,
    input  wire accept,
    input  wire clear,
    input  wire [W-1:0] edge_index,
    input  wire [W-1:0] magnitude,
    input  wire sign_bit,
    output reg [GROUPS*W-1:0] group_min1,
    output reg [GROUPS*W-1:0] group_min2,
    output reg [GROUPS-1:0] group_sign,
    output reg [W-1:0] folded_min1,
    output reg [W-1:0] folded_min2,
    output reg folded_sign
);
    localparam BW = $clog2(GROUPS);
    wire [BW-1:0] bank = edge_index % GROUPS;
    reg [W-1:0] low [0:GROUPS-1];
    reg [W-1:0] high [0:GROUPS-1];
    reg parity [0:GROUPS-1];
    reg [W-1:0] candidate_low, candidate_high;
    integer init_i, scan_i, reset_i;
    initial begin
        for (init_i = 0; init_i < GROUPS; init_i = init_i + 1) begin
            low[init_i] = {W{1'b1}};
            high[init_i] = {W{1'b1}};
            parity[init_i] = 1'b0;
        end
    end
    always @(*) begin
        folded_min1 = {W{1'b1}};
        folded_min2 = {W{1'b1}};
        folded_sign = 1'b0;
        for (scan_i = 0; scan_i < GROUPS; scan_i = scan_i + 1) begin
            group_min1[scan_i*W +: W] = low[scan_i];
            group_min2[scan_i*W +: W] = high[scan_i];
            group_sign[scan_i] = parity[scan_i];
            candidate_low = low[scan_i];
            candidate_high = high[scan_i];
            if (scan_i == bank) begin
                if (magnitude < low[scan_i]) begin
                    candidate_low = magnitude;
                    candidate_high = low[scan_i];
                end else if (magnitude < high[scan_i]) begin
                    candidate_high = magnitude;
                end
            end
            if (candidate_low < folded_min1) begin
                folded_min2 = folded_min1;
                folded_min1 = candidate_low;
            end else if (candidate_low < folded_min2) begin
                folded_min2 = candidate_low;
            end
            if (candidate_high < folded_min2)
                folded_min2 = candidate_high;
            folded_sign = folded_sign ^ parity[scan_i];
        end
        folded_sign = folded_sign ^ sign_bit;
    end
    always @(posedge clk) begin
        if (clear) begin
            for (reset_i = 0; reset_i < GROUPS; reset_i = reset_i + 1) begin
                low[reset_i] <= {W{1'b1}};
                high[reset_i] <= {W{1'b1}};
                parity[reset_i] <= 1'b0;
            end
        end else if (accept) begin
            parity[bank] <= parity[bank] ^ sign_bit;
            if (magnitude < low[bank]) begin
                high[bank] <= low[bank];
                low[bank] <= magnitude;
            end else if (magnitude < high[bank]) begin
                high[bank] <= magnitude;
            end
        end
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32,
    parameter GROUPS = 4
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [GROUPS*W-1:0] group_min1,
    output wire [GROUPS*W-1:0] group_min2,
    output wire [GROUPS-1:0] group_sign,
    output wire group_valid
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    wire [W-1:0] folded_min1, folded_min2;
    wire folded_sign;
    ldpc_cnp_group_reduce #(.W(W), .GROUPS(GROUPS)) group_reduce (
        .clk(clk), .accept(acc), .clear(rel),
        .edge_index(count), .magnitude(in_mag), .sign_bit(in_sign),
        .group_min1(group_min1), .group_min2(group_min2),
        .group_sign(group_sign), .folded_min1(folded_min1),
        .folded_min2(folded_min2), .folded_sign(folded_sign)
    );
    assign group_valid = (state == S_DONE);
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= folded_sign;
            min1 <= folded_min1;
            min2 <= folded_min2;
            if (in_mag < min1) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
endmodule

module uart_word_formatter #(
   parameter WORD_W = 16,
   parameter WORDS = (WORD_W / 4) + 4,
   parameter IW = $clog2(WORDS),
   parameter CW = $clog2(WORDS + 1)
) (
   input  wire                    clk,
   input  wire                    rst_n,
   input  wire                    ce,
   input  wire                    in_valid,
   output wire                    in_ready,
   input  wire [WORD_W-1:0]       in_word,
   input  wire                    in_packet,
   output wire                    byte_valid,
   input  wire                    byte_ready,
   output wire [WORD_W-1:0]       byte_data,
   input  wire                    tx_busy,
   output wire                    done,
   input  wire                    done_ready,
   output wire [1:0]              state_o,
   output wire [IW-1:0]           pos_o,
   output wire [CW-1:0]           span_o,
   output reg  [WORD_W*WORDS-1:0] words_o
);
   localparam DIGITS = WORD_W / 4;
   localparam [1:0] IDLE = 2'd0;
   localparam [1:0] SEND = 2'd1;
   localparam [1:0] WAIT_BYTE = 2'd2;
   localparam [1:0] DONE = 2'd3;
   localparam [CW-1:0] FULL_SPAN = WORDS;

   reg [1:0] state = IDLE;
   reg [IW-1:0] pos = 0;
   reg [CW-1:0] span = 1;
   reg [WORD_W-1:0] frame [0:WORDS-1];
   reg [WORD_W-1:0] encoded [0:WORDS-1];
   integer init_idx;
   integer build_idx;
   integer seq_idx;

   initial begin
       for (init_idx = 0; init_idx < WORDS; init_idx = init_idx + 1)
           frame[init_idx] = 0;
   end

   function [WORD_W-1:0] hex_symbol;
       input [3:0] nibble;
       begin
           if (nibble < 4'd10)
               hex_symbol = 16'h0030 + nibble;
           else
               hex_symbol = 16'h0041 + nibble - 16'd10;
       end
   endfunction

   // CRC-8/ATM, most significant payload bit first.
   function [7:0] crc_word;
       input [WORD_W-1:0] word;
       reg [7:0] residue;
       reg feedback;
       integer bit_idx;
       begin
           residue = 8'd0;
           feedback = 1'b0;
           for (bit_idx = WORD_W - 1; bit_idx >= 0; bit_idx = bit_idx - 1) begin
               feedback = residue[7] ^ word[bit_idx];
               residue = {residue[6:0], 1'b0};
               if (feedback)
                   residue = residue ^ 8'h07;
           end
           crc_word = residue;
       end
   endfunction

   wire [7:0] input_crc = crc_word(in_word);
   wire input_take = in_valid && in_ready;
   wire byte_take = byte_valid && byte_ready;

   assign in_ready = (state == IDLE);
   assign byte_valid = (state == SEND);
   assign byte_data = frame[pos];
   assign done = (state == DONE);
   assign state_o = state;
   assign pos_o = pos;
   assign span_o = span;

   // A packet carries the complete word and its checksum as printable text.
   // Raw writes use the same completion machinery, but only one symbol.
   always @(*) begin
       for (build_idx = 0; build_idx < WORDS; build_idx = build_idx + 1) begin
           encoded[build_idx] = 0;
           words_o[build_idx*WORD_W +: WORD_W] = frame[build_idx];
       end
       encoded[0] = 16'h003a;
       for (build_idx = 0; build_idx < DIGITS; build_idx = build_idx + 1)
           encoded[build_idx + 1] =
               hex_symbol(in_word[(DIGITS-1-build_idx)*4 +: 4]);
       encoded[DIGITS + 1] = hex_symbol(input_crc[7:4]);
       encoded[DIGITS + 2] = hex_symbol(input_crc[3:0]);
       encoded[WORDS - 1] = 16'h000a;
       if (!in_packet) begin
           for (build_idx = 0; build_idx < WORDS; build_idx = build_idx + 1)
               encoded[build_idx] = 0;
           encoded[0] = {8'd0, in_word[7:0]};
       end
   end

   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           state <= IDLE;
           pos <= 0;
           span <= 1;
           for (seq_idx = 0; seq_idx < WORDS; seq_idx = seq_idx + 1)
               frame[seq_idx] <= 0;
       end else if (ce) begin
           case (state)
               IDLE: begin
                   if (input_take) begin
                       for (seq_idx = 0; seq_idx < WORDS; seq_idx = seq_idx + 1)
                           frame[seq_idx] <= encoded[seq_idx];
                       pos <= 0;
                       span <= in_packet ? FULL_SPAN : 1;
                       state <= SEND;
                   end
               end
               SEND: begin
                   // Acceptance is not completion: retain the frame until
                   // the UART has shifted the accepted symbol's stop bit.
                   if (byte_take)
                       state <= WAIT_BYTE;
               end
               WAIT_BYTE: begin
                   if (!tx_busy) begin
                       if (({1'b0, pos} + 1'b1) == span) begin
                           state <= DONE;
                       end else begin
                           pos <= pos + 1'b1;
                           state <= SEND;
                       end
                   end
               end
               DONE: begin
                   // Keep completion and the encoded frame until acknowledged.
                   if (done_ready)
                       state <= IDLE;
               end
           endcase
       end
   end
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
,
    output wire [15:0] lim_o,
    output wire [15:0] occ_w_o,
    output wire [15:0] rc_w_o,
    output wire [PW-1:0] rp_w_o,
    output wire [15:0] wc_w_o,
    output wire [PW-1:0] wp_w_o
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
    assign lim_o = lim;
    assign occ_w_o = occ_w;
    assign rc_w_o = rc_w;
    assign rp_w_o = rp_w;
    assign wc_w_o = wc_w;
    assign wp_w_o = wp_w;
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
,
    output wire [31:0] bitcnt_o,
    output wire busy_o,
    output wire in_frame_o,
    output wire [FRAME_W-1:0] shreg_o
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign in_frame_o = in_frame;
    assign shreg_o = shreg;
endmodule

module axi_uart_tx (
    input wire clk,
    input wire rst_n,
    input wire s_ce, m_ce,
    input wire i_load,
    input wire [15:0] i_lim,
    input wire baud_tick,
    input wire s_aw_valid,
    input wire [15:0] s_aw_addr,
    output wire s_aw_ready,
    input wire s_w_valid,
    input wire [15:0] s_w_data,
    output wire s_w_ready,
    output wire s_b_valid,
    output wire [15:0] s_b_resp,
    input wire s_b_ready,
    input wire s_ar_valid,
    input wire [15:0] s_ar_addr,
    output wire s_ar_ready,
    output wire s_r_valid,
    output wire [15:0] s_r_data,
    input wire s_r_ready,
    output wire txd,
    output wire [15:0] a_lim, a_occ_w, a_rc_w, a_wc_w,
    output wire [4:0] a_rp_w, a_wp_w,
    output wire [31:0] uart_bitcnt,
    output wire uart_busy, uart_in_frame,
    output wire [10:0] uart_shreg,
    output wire [15:0] address_o,
    output wire address_pending_o, tx_wait_o,
    output wire response_pending_o, response_error_o,
   output wire uart_online_o,
   output wire [1:0] format_state_o,
   output wire [FORMAT_PW-1:0] format_pos_o,
   output wire [FORMAT_CW-1:0] format_span_o,
   output wire [16*FORMAT_WORDS-1:0] format_words_o
);
    localparam [15:0] TX_ADDR = 16'h0000;
    localparam [15:0] COUNT_ADDR = 16'h0004;
   localparam [15:0] PACKET_ADDR = 16'h0008;
   localparam FORMAT_WORDS = 8;
   localparam FORMAT_PW = $clog2(FORMAT_WORDS);
   localparam FORMAT_CW = $clog2(FORMAT_WORDS + 1);

    wire a_aw_valid, a_aw_ready, a_w_valid, a_w_ready;
    wire [15:0] a_aw_addr, a_w_data;
    wire a_b_valid, a_b_ready;
    wire [15:0] a_b_resp;
    wire a_ar_valid, a_ar_ready, a_r_valid, a_r_ready;
    wire [15:0] a_ar_addr, a_r_data;
    wire uart_valid, uart_ready;
   wire format_input_valid, format_input_ready;
   wire format_output_valid, format_done;
   wire [15:0] format_output_data;

    reg [15:0] address_hold = 16'd0;
    reg address_pending = 1'b0;
    reg tx_wait = 1'b0;
    reg response_pending = 1'b0;
    reg response_error = 1'b0;
    reg uart_online = 1'b0;

    assign address_o = address_hold;
    assign address_pending_o = address_pending;
    assign tx_wait_o = tx_wait;
    assign response_pending_o = response_pending;
    assign response_error_o = response_error;
    assign uart_online_o = uart_online;

    wire address_is_tx = (address_hold == TX_ADDR);
   wire address_is_packet = (address_hold == PACKET_ADDR);
   wire address_is_serial = address_is_tx || address_is_packet;
   assign format_input_valid = uart_online && address_pending &&
                               !tx_wait && !response_pending &&
                               address_is_serial && a_w_valid;
    assign a_aw_ready = uart_online && !address_pending;
   assign a_w_ready = uart_online && address_pending && !tx_wait &&
                      !response_pending && (!address_is_serial || format_input_ready);
   assign uart_valid = m_ce && uart_online && format_output_valid;
    wire address_take = m_ce && a_aw_valid && a_aw_ready;
    wire write_take = m_ce && a_w_valid && a_w_ready;
   wire format_take = write_take && address_is_serial;
   wire write_reject = write_take && !address_is_serial;

    assign a_b_valid = response_pending;
    assign a_b_resp = response_error ? 16'd3 : 16'd0;
    wire response_take = m_ce && a_b_valid && a_b_ready;

    // The read port reports status without disturbing a pending write.
    assign a_r_valid = uart_online && a_ar_valid;
    assign a_ar_ready = uart_online && a_r_ready;
    assign a_r_data = (a_ar_addr == TX_ADDR) ? {15'd0, uart_busy} :
                      (a_ar_addr == COUNT_ADDR) ? uart_bitcnt[15:0] : 16'hffff;

    axi_cdc_bridge bridge (
        .clk(clk), .s_ce(s_ce), .m_ce(m_ce),
        .i_load(i_load), .i_lim(i_lim),
        .s_aw_valid(s_aw_valid), .s_aw_addr(s_aw_addr),
        .s_aw_ready(s_aw_ready),
        .m_aw_valid(a_aw_valid), .m_aw_addr(a_aw_addr),
        .m_aw_ready(a_aw_ready),
        .s_w_valid(s_w_valid), .s_w_data(s_w_data),
        .s_w_ready(s_w_ready),
        .m_w_valid(a_w_valid), .m_w_data(a_w_data),
        .m_w_ready(a_w_ready),
        .m_b_valid(a_b_valid), .m_b_resp(a_b_resp),
        .m_b_ready(a_b_ready),
        .s_b_valid(s_b_valid), .s_b_resp(s_b_resp),
        .s_b_ready(s_b_ready),
        .s_ar_valid(s_ar_valid), .s_ar_addr(s_ar_addr),
        .s_ar_ready(s_ar_ready),
        .m_ar_valid(a_ar_valid), .m_ar_addr(a_ar_addr),
        .m_ar_ready(a_ar_ready),
        .m_r_valid(a_r_valid), .m_r_data(a_r_data),
        .m_r_ready(a_r_ready),
        .s_r_valid(s_r_valid), .s_r_data(s_r_data),
        .s_r_ready(s_r_ready),
        .lim_o(a_lim), .occ_w_o(a_occ_w),
        .rc_w_o(a_rc_w), .rp_w_o(a_rp_w),
        .wc_w_o(a_wc_w), .wp_w_o(a_wp_w)
    );

    uart_tx_word #(.DATA_W(8)) uart (
        .clk(clk), .rst_n(rst_n), .baud_tick(baud_tick),
        .s_valid(uart_valid), .s_ready(uart_ready),
       .s_data(format_output_data[7:0]), .txd(txd), .o_busy(),
        .bitcnt_o(uart_bitcnt), .busy_o(uart_busy),
        .in_frame_o(uart_in_frame), .shreg_o(uart_shreg)
    );

   uart_word_formatter #(
       .WORD_W(16), .WORDS(FORMAT_WORDS),
       .IW(FORMAT_PW), .CW(FORMAT_CW)
   ) formatter (
       .clk(clk), .rst_n(rst_n), .ce(m_ce),
       .in_valid(format_input_valid), .in_ready(format_input_ready),
       .in_word(a_w_data), .in_packet(address_is_packet),
       .byte_valid(format_output_valid),
       .byte_ready(uart_online && uart_ready),
       .byte_data(format_output_data), .tx_busy(uart_busy),
       .done(format_done), .done_ready(tx_wait),
       .state_o(format_state_o), .pos_o(format_pos_o),
       .span_o(format_span_o), .words_o(format_words_o)
   );

    // Allow the UART and the bus-side join to leave reset together.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            uart_online <= 1'b0;
        else
            uart_online <= 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            address_hold <= 16'd0;
            address_pending <= 1'b0;
            tx_wait <= 1'b0;
            response_pending <= 1'b0;
            response_error <= 1'b0;
        end else if (m_ce) begin
            // AW may run ahead while a previous character is shifting.
            if (address_take) begin
                address_hold <= a_aw_addr;
                address_pending <= 1'b1;
            end
            if (write_take)
                address_pending <= 1'b0;
           if (format_take) begin
                tx_wait <= 1'b1;
                response_error <= 1'b0;
            end
            if (write_reject) begin
                response_pending <= 1'b1;
                response_error <= 1'b1;
            end
            // Completion is retained until the response FIFO has space.
           if (tx_wait && format_done) begin
                tx_wait <= 1'b0;
                response_pending <= 1'b1;
                response_error <= 1'b0;
            end
            if (response_take)
                response_pending <= 1'b0;
        end
    end

    always @(posedge clk)
        if (response_pending_o && !response_error_o)
            assert (!uart_busy && uart_bitcnt == 32'd11);
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
parameter TILE_COLS = 4,
parameter CFG_DEPTH = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
output wire busy,
output wire cfg_ready,
output wire [$clog2(CFG_DEPTH+1)-1:0] cfg_queue_level,
output wire [$clog2(CFG_DEPTH+2)-1:0] cfg_held,
output reg [CFG_DEPTH-1:0] cfg_queued,
output wire [1:0] cfg_engine_state,
output reg cfg_done_valid,
output reg [3:0] cfg_done_addr,
output reg [31:0] cfg_done_data,
output reg [31:0] cfg_done_fence
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
localparam CFG_PTR_W = $clog2(CFG_DEPTH);
localparam [1:0] CFG_IDLE = 2'd0;
localparam [1:0] CFG_DRAIN = 2'd1;
localparam [1:0] CFG_ISSUE = 2'd2;
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

// Posted writes carry the boundary of the pixels using the old settings.
reg [31:0] cfg_data_mem [0:CFG_DEPTH-1];
reg [3:0] cfg_addr_mem [0:CFG_DEPTH-1];
reg [31:0] cfg_fence_mem [0:CFG_DEPTH-1];
reg [CFG_PTR_W:0] cfg_rd_pos, cfg_wr_pos;
reg [1:0] cfg_phase, cfg_phase_next;
reg [31:0] cfg_cmd_data;
reg [3:0] cfg_cmd_addr;
reg [31:0] cfg_cmd_fence;
integer cfg_slot;
integer cfg_init_i;

wire [CFG_PTR_W-1:0] cfg_rd_index = cfg_rd_pos[CFG_PTR_W-1:0];
wire [CFG_PTR_W-1:0] cfg_wr_index = cfg_wr_pos[CFG_PTR_W-1:0];
wire cfg_empty = cfg_rd_pos == cfg_wr_pos;
wire cfg_full = (cfg_rd_index == cfg_wr_index) &&
                (cfg_rd_pos[CFG_PTR_W] != cfg_wr_pos[CFG_PTR_W]);

// A mailbox acknowledgement must remain possible even with a full queue.
wire cfg_ack_select = (cfg_addr == 4'd14) && cfg_data[0];
wire cfg_accept = cfg_we && cfg_ready;
wire cfg_ack = cfg_accept && cfg_ack_select;
wire cfg_enqueue = cfg_accept && !cfg_ack_select;
wire cfg_fetch = pipeline_active && (cfg_phase == CFG_IDLE) && !cfg_empty;
wire cfg_drained = (a_ingress_level == 0) && !a_o_valid;
wire cfg_mailbox_free = !cfg_done_valid || cfg_ack;
wire cfg_apply = pipeline_active && (cfg_phase == CFG_ISSUE) &&
                 cfg_mailbox_free;
wire color_i_ready;
wire cfg_rgb_open;
wire [3:0] cfg_color_addr = cfg_apply ? cfg_cmd_addr : cfg_addr;

assign cfg_queue_level =
    (cfg_wr_pos[CFG_PTR_W] == cfg_rd_pos[CFG_PTR_W])
    ? ({1'b0, cfg_wr_index} - {1'b0, cfg_rd_index})
    : (CFG_DEPTH + {1'b0, cfg_wr_index} - {1'b0, cfg_rd_index});
assign cfg_held = cfg_queue_level + (cfg_phase != CFG_IDLE);
assign cfg_engine_state = cfg_phase;
assign cfg_ready = cfg_ack_select || !cfg_full || cfg_fetch;

// Only the RGB stream pauses; configuration admission and tile draining run.
assign cfg_rgb_open = pipeline_active && cfg_empty &&
                      (cfg_phase == CFG_IDLE) &&
                      !(cfg_we && !cfg_ack_select);
assign i_ready = cfg_rgb_open && color_i_ready;

// Expose physical queue occupancy for software's posted-write diagnostics.
always @(*) begin
    for (cfg_slot = 0; cfg_slot < CFG_DEPTH; cfg_slot = cfg_slot + 1) begin
        if (cfg_wr_pos[CFG_PTR_W] == cfg_rd_pos[CFG_PTR_W]) begin
            cfg_queued[cfg_slot] = (cfg_rd_index <= cfg_slot) &&
                                   (cfg_slot < cfg_wr_index);
        end else begin
            cfg_queued[cfg_slot] = (cfg_rd_index <= cfg_slot) ||
                                   (cfg_slot < cfg_wr_index);
        end
    end
end

// Separate memory fetch, old-pixel drainage, and the configuration bus cycle.
always @(*) begin
    cfg_phase_next = cfg_phase;
    case (cfg_phase)
        CFG_IDLE: begin
            if (cfg_fetch)
                cfg_phase_next = CFG_DRAIN;
        end
        CFG_DRAIN: begin
            if (cfg_drained)
                cfg_phase_next = CFG_ISSUE;
        end
        CFG_ISSUE: begin
            if (cfg_apply)
                cfg_phase_next = CFG_IDLE;
        end
        default: cfg_phase_next = CFG_IDLE;
    endcase
end

initial begin
    cfg_rd_pos = {(CFG_PTR_W+1){1'b0}};
    cfg_wr_pos = {(CFG_PTR_W+1){1'b0}};
    cfg_phase = CFG_IDLE;
    cfg_cmd_data = 32'd0;
    cfg_cmd_addr = 4'd0;
    cfg_cmd_fence = 32'd0;
    cfg_done_valid = 1'b0;
    cfg_done_addr = 4'd0;
    cfg_done_data = 32'd0;
    cfg_done_fence = 32'd0;
    for (cfg_init_i = 0; cfg_init_i < CFG_DEPTH; cfg_init_i = cfg_init_i + 1) begin
        cfg_data_mem[cfg_init_i] = 32'd0;
        cfg_addr_mem[cfg_init_i] = 4'd0;
        cfg_fence_mem[cfg_init_i] = 32'd0;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cfg_rd_pos <= {(CFG_PTR_W+1){1'b0}};
        cfg_wr_pos <= {(CFG_PTR_W+1){1'b0}};
        for (cfg_init_i = 0; cfg_init_i < CFG_DEPTH; cfg_init_i = cfg_init_i + 1) begin
            cfg_data_mem[cfg_init_i] <= 32'd0;
            cfg_addr_mem[cfg_init_i] <= 4'd0;
            cfg_fence_mem[cfg_init_i] <= 32'd0;
        end
    end else begin
        if (cfg_enqueue) begin
            cfg_data_mem[cfg_wr_index] <= cfg_data;
            cfg_addr_mem[cfg_wr_index] <= cfg_addr;
            cfg_fence_mem[cfg_wr_index] <= a_ingress_accepted;
            if (cfg_wr_index == CFG_DEPTH-1)
                cfg_wr_pos <= {~cfg_wr_pos[CFG_PTR_W],
                               {CFG_PTR_W{1'b0}}};
            else
                cfg_wr_pos <= cfg_wr_pos + 1'b1;
        end
        if (cfg_fetch) begin
            if (cfg_rd_index == CFG_DEPTH-1)
                cfg_rd_pos <= {~cfg_rd_pos[CFG_PTR_W],
                               {CFG_PTR_W{1'b0}}};
            else
                cfg_rd_pos <= cfg_rd_pos + 1'b1;
        end
    end
end

// The execution stage also makes simultaneous full-queue read/write safe.
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cfg_phase <= CFG_IDLE;
        cfg_cmd_data <= 32'd0;
        cfg_cmd_addr <= 4'd0;
        cfg_cmd_fence <= 32'd0;
    end else begin
        cfg_phase <= cfg_phase_next;
        if (cfg_fetch) begin
            cfg_cmd_data <= cfg_data_mem[cfg_rd_index];
            cfg_cmd_addr <= cfg_addr_mem[cfg_rd_index];
            cfg_cmd_fence <= cfg_fence_mem[cfg_rd_index];
        end
    end
end

// Completion remains readable until acknowledged; replacement is atomic.
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cfg_done_valid <= 1'b0;
        cfg_done_addr <= 4'd0;
        cfg_done_data <= 32'd0;
        cfg_done_fence <= 32'd0;
    end else begin
        if (cfg_apply) begin
            cfg_done_valid <= 1'b1;
            cfg_done_addr <= cfg_cmd_addr;
            cfg_done_data <= cfg_cmd_data;
            cfg_done_fence <= cfg_cmd_fence;
        end else if (cfg_ack) begin
            cfg_done_valid <= 1'b0;
        end
    end
end

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = pipeline_active && (bridge_level != 0);
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
a_o_valid || (bridge_level != 0) || (tile_held != 0) ||
!cfg_empty || (cfg_phase != CFG_IDLE) || cfg_done_valid;

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
.cfg_we(cfg_apply), .cfg_addr(cfg_color_addr), .cfg_data(cfg_cmd_data),
.i_valid(i_valid && cfg_rgb_open), .i_ready(color_i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(o_valid), .out_ready(o_ready), .out_data(o_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end

always @(posedge clk) begin
    if (pipeline_active && cfg_apply)
        assert ((cfg_cmd_fence == a_out_cnt) &&
                (a_ingress_level == 0) && !a_o_valid);
end
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5,
    parameter PEER_DEPTH = 4
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready,
    input  wire        peer_w_valid,
    input  wire [15:0] peer_w_data,
    output wire        peer_w_ready,
    output wire        m_w_peer
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;
    localparam CHANNELS = 2;
    localparam LANE_W = $clog2(CHANNELS);
    localparam PEER_PW = $clog2(PEER_DEPTH);
    localparam PEER_CW = $clog2(PEER_DEPTH + 1);
    localparam [PEER_PW-1:0] PEER_LAST = PEER_DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    reg [15:0] peer_mem [0:PEER_DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
        for (i = 0; i < PEER_DEPTH; i = i + 1) begin
            peer_mem[i] = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    reg [PEER_PW-1:0] peer_wp = 0, peer_rp = 0;
    reg [PEER_CW-1:0] peer_count = 0;
    reg [LANE_W-1:0] w_turn = 0, w_owner = 0;
    reg w_locked = 1'b0;
    reg [LANE_W-1:0] w_sel;
    reg [CHANNELS-1:0] w_grant;
    integer arb_lane;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire peer_full = (peer_count >= PEER_DEPTH);
    wire peer_empty = (peer_count == 0);
    wire peer_push = s_ce && peer_w_valid && !peer_full;
    wire peer_pop = m_ce && m_w_ready && w_grant[1];
    wire w_transfer = m_ce && m_w_ready && m_w_valid;
    wire [CHANNELS-1:0] w_request;
    assign w_request[0] = !empty_w;
    assign w_request[1] = !peer_empty;

    always @(*) begin
        w_sel = w_turn;
        if (w_locked)
            w_sel = w_owner;
        else if (!w_request[1])
            w_sel = 1'b0;
        else if (!w_request[0])
            w_sel = 1'b1;
        for (arb_lane = 0; arb_lane < CHANNELS; arb_lane = arb_lane + 1)
            w_grant[arb_lane] = w_request[arb_lane] && (w_sel == arb_lane);
    end

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready && w_grant[0];
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = |w_grant;
    assign m_w_data   = (w_sel == 1'b0) ? mem_w[rp_w] : peer_mem[peer_rp];
    assign peer_w_ready = !peer_full;
    assign m_w_peer = (w_sel == 1'b1);
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (peer_push) begin
            peer_mem[peer_wp] <= peer_w_data;
            peer_wp <= (peer_wp == PEER_LAST) ? {PEER_PW{1'b0}} : peer_wp + 1'b1;
        end
        if (peer_pop)
            peer_rp <= (peer_rp == PEER_LAST) ? {PEER_PW{1'b0}} : peer_rp + 1'b1;
        case ({peer_push, peer_pop})
            2'b10: peer_count <= peer_count + 1'b1;
            2'b01: peer_count <= peer_count - 1'b1;
            default: peer_count <= peer_count;
        endcase
    end

    always @(posedge clk) begin
        if (w_transfer) begin
            w_turn <= (w_sel == 1'b0) ? 1'b1 : 1'b0;
            w_locked <= 1'b0;
        end else if (m_w_valid) begin
            w_locked <= 1'b1;
            w_owner <= w_sel;
        end
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));

    always @(posedge clk)
        if (pv && m_ce && w_locked)
            assert (w_grant[w_owner]);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
   output wire [31:0] debug_status,
   output wire         prefix_valid,
   output wire [W-1:0] prefix_input_mag,
   output wire         prefix_input_sign,
   output wire [W-1:0] prefix_min1,
   output wire [W-1:0] prefix_min2,
   output wire [W-1:0] prefix_index,
   output wire         prefix_sign,
   output wire         prefix_last,
   output wire [W-1:0] prefix_reference,
   output wire [W-1:0] prefix_improvement,
   output wire [W-1:0] prefix_extrinsic_mag,
   output wire         prefix_extrinsic_sign
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

   assign in_ready  = (state == S_ACCUM) && !prefix_full;
   assign out_valid = (state == S_DONE) && prefix_empty;
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
   localparam PREFIX_DEPTH = 4;
   localparam PREFIX_AW = $clog2(PREFIX_DEPTH);
   reg [W-1:0] prefix_mag_mem [0:PREFIX_DEPTH-1];
   reg [W-1:0] prefix_first_mem [0:PREFIX_DEPTH-1];
   reg [W-1:0] prefix_second_mem [0:PREFIX_DEPTH-1];
   reg [W-1:0] prefix_index_mem [0:PREFIX_DEPTH-1];
   reg prefix_input_sign_mem [0:PREFIX_DEPTH-1];
   reg prefix_parity_mem [0:PREFIX_DEPTH-1];
   reg prefix_min_edge_mem [0:PREFIX_DEPTH-1];
   reg [PREFIX_AW:0] prefix_wr;
   reg [PREFIX_AW:0] prefix_rd;
   reg [W-1:0] prefix_reference_reg;
   reg [PREFIX_AW-1:0] prefix_distance [0:PREFIX_DEPTH-1];
   wire prefix_empty = (prefix_wr == prefix_rd);
   wire prefix_full =
       (prefix_wr[PREFIX_AW] != prefix_rd[PREFIX_AW]) &&
       (prefix_wr[PREFIX_AW-1:0] == prefix_rd[PREFIX_AW-1:0]);
   wire [PREFIX_AW:0] prefix_used = prefix_wr - prefix_rd;
   wire prefix_pop = prefix_valid && out_ready;
   wire [W-1:0] prefix_next_first =
       (in_mag < min1) ? in_mag : min1;
   wire [W-1:0] prefix_next_second =
       (in_mag < min1) ? min1 :
       ((in_mag < min2) ? in_mag : min2);
   integer prefix_init;
   initial begin
       prefix_wr = 0;
       prefix_rd = 0;
       prefix_reference_reg = {W{1'b1}};
       for (prefix_init = 0; prefix_init < PREFIX_DEPTH; prefix_init = prefix_init + 1) begin
           prefix_mag_mem[prefix_init] = {W{1'b0}};
           prefix_first_mem[prefix_init] = {W{1'b1}};
           prefix_second_mem[prefix_init] = {W{1'b1}};
           prefix_index_mem[prefix_init] = {W{1'b0}};
           prefix_input_sign_mem[prefix_init] = 1'b0;
           prefix_parity_mem[prefix_init] = 1'b0;
           prefix_min_edge_mem[prefix_init] = 1'b0;
       end
   end
   // out_ready acknowledges prefix records before the frame summary.
   always @(posedge clk) begin
       if (acc)
           prefix_wr <= prefix_wr + 1'b1;
       if (prefix_pop)
           prefix_rd <= prefix_rd + 1'b1;
       // Capture a reference only when installing a new FIFO head.
       if ((prefix_empty && acc) || prefix_pop)
           prefix_reference_reg <= acc ? prefix_next_first : min1;
       for (integer slot = 0; slot < PREFIX_DEPTH; slot = slot + 1) begin
           if (acc && prefix_wr[PREFIX_AW-1:0] == slot) begin
               prefix_mag_mem[slot] <= in_mag;
               prefix_first_mem[slot] <= prefix_next_first;
               prefix_second_mem[slot] <= prefix_next_second;
               prefix_index_mem[slot] <= count;
               prefix_input_sign_mem[slot] <= in_sign;
               prefix_parity_mem[slot] <= sign_prod ^ in_sign;
               prefix_min_edge_mem[slot] <= (in_mag < min1) || (count == min_idx);
           end
       end
   end
   always @(*) begin
       for (integer slot = 0; slot < PREFIX_DEPTH; slot = slot + 1)
           prefix_distance[slot] = slot - prefix_rd[PREFIX_AW-1:0];
   end
   assign prefix_valid = !prefix_empty;
   assign prefix_input_mag = prefix_mag_mem[prefix_rd[PREFIX_AW-1:0]];
   assign prefix_input_sign = prefix_input_sign_mem[prefix_rd[PREFIX_AW-1:0]];
   assign prefix_min1 = prefix_first_mem[prefix_rd[PREFIX_AW-1:0]];
   assign prefix_min2 = prefix_second_mem[prefix_rd[PREFIX_AW-1:0]];
   assign prefix_index = prefix_index_mem[prefix_rd[PREFIX_AW-1:0]];
   assign prefix_sign = prefix_parity_mem[prefix_rd[PREFIX_AW-1:0]];
   assign prefix_last = (prefix_index == DEG - 1);
   assign prefix_reference = prefix_reference_reg;
   assign prefix_improvement = prefix_min1 - prefix_reference;
   assign prefix_extrinsic_mag = prefix_min_edge_mem[prefix_rd[PREFIX_AW-1:0]]
                               ? prefix_min2 : prefix_min1;
   assign prefix_extrinsic_sign = prefix_sign ^ prefix_input_sign;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
    reg [7:0] dbg_accept_count;
    reg [7:0] dbg_complete_count;
    reg [7:0] dbg_stall_cycles;
    reg [7:0] dbg_peak_stall;
    reg       dbg_timeout;
    initial dbg_accept_count = 8'd0;
    initial dbg_complete_count = 8'd0;
    initial dbg_stall_cycles = 8'd0;
    initial dbg_peak_stall = 8'd0;
    initial dbg_timeout = 1'b0;
    always @(posedge clk) begin
        if (acc) begin
            if (dbg_accept_count != 8'hff)
                dbg_accept_count <= dbg_accept_count + 1'b1;
        end
        if (rel) begin
            if (dbg_complete_count != 8'hff)
                dbg_complete_count <= dbg_complete_count + 1'b1;
        end
        if (out_valid && !out_ready) begin
            if (dbg_stall_cycles != 8'hff) begin
                dbg_stall_cycles <= dbg_stall_cycles + 1'b1;
                if (dbg_stall_cycles >= dbg_peak_stall)
                    dbg_peak_stall <= dbg_stall_cycles + 1'b1;
            end
            if (dbg_stall_cycles >= 8'd63)
                dbg_timeout <= 1'b1;
        end else begin
            dbg_stall_cycles <= 8'd0;
        end
    end
    assign debug_status = {dbg_timeout, 7'd0, dbg_peak_stall,
                           dbg_complete_count, dbg_accept_count};

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
   always @(posedge clk) if (pv && prefix_pop)
       assert (prefix_improvement <= prefix_input_mag);
endmodule

module ntt_twiddle_cache #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter ENTRIES = 4,
    parameter SCORE_W = 2
) (
    input  wire clk,
    input  wire request_valid,
    output wire request_ready,
    input  wire [W-1:0] request_key,
    input  wire response_ready,
    output wire response_valid,
    output wire busy,
    output reg [W-1:0] response_key,
    output reg [W-1:0] response_value,
    output reg [1:0] state,
    output reg [ENTRIES-1:0] line_valid,
    output reg [ENTRIES*W-1:0] line_keys,
    output reg [ENTRIES*W-1:0] line_values,
    output reg [ENTRIES*SCORE_W-1:0] line_scores,
    output reg [$clog2(ENTRIES)-1:0] replacement_cursor
);
    localparam INDEX_W = $clog2(ENTRIES);
    localparam [INDEX_W-1:0] LAST_LINE = ENTRIES - 1;
    localparam [1:0] IDLE = 2'd0;
    localparam [1:0] LOOKUP = 2'd1;
    localparam [1:0] NORMALIZE = 2'd2;
    localparam [1:0] RESPONSE = 2'd3;
    localparam [SCORE_W-1:0] MAX_SCORE = {SCORE_W{1'b1}};
    reg [W-1:0] key_mem [0:ENTRIES-1];
    reg [W-1:0] value_mem [0:ENTRIES-1];
    reg [SCORE_W-1:0] score_mem [0:ENTRIES-1];
    reg hit_found;
    reg [INDEX_W-1:0] hit_index;
    reg [INDEX_W-1:0] victim_index;
    reg invalid_found;
    reg [SCORE_W-1:0] lowest_score;
    integer init_line;
    integer pack_line;
    integer lookup_line;
    integer replacement_step;
    integer replacement_line;
    integer update_line;
    wire [W-1:0] normalize_operand =
        (state == NORMALIZE) ? response_key : {W{1'b0}};
    wire [W-1:0] normalized_value = normalize_operand % Q;
    assign request_ready = (state == IDLE);
    assign response_valid = (state == RESPONSE);
    assign busy = (state != IDLE);
    initial begin
        state = IDLE;
        response_key = 16'd0;
        response_value = 16'd0;
        line_valid = {ENTRIES{1'b0}};
        replacement_cursor = {INDEX_W{1'b0}};
        for (init_line = 0; init_line < ENTRIES; init_line = init_line + 1) begin
            key_mem[init_line] = 16'd0;
            value_mem[init_line] = 16'd0;
            score_mem[init_line] = {SCORE_W{1'b0}};
        end
    end
    always @(*) begin
        for (pack_line = 0; pack_line < ENTRIES; pack_line = pack_line + 1) begin
            line_keys[pack_line*W +: W] = key_mem[pack_line];
            line_values[pack_line*W +: W] = value_mem[pack_line];
            line_scores[pack_line*SCORE_W +: SCORE_W] = score_mem[pack_line];
        end
    end
    always @(*) begin
        hit_found = 1'b0;
        hit_index = {INDEX_W{1'b0}};
        for (lookup_line = 0; lookup_line < ENTRIES; lookup_line = lookup_line + 1) begin
            if (!hit_found && line_valid[lookup_line] &&
                key_mem[lookup_line] == response_key) begin
                hit_found = 1'b1;
                hit_index = lookup_line[INDEX_W-1:0];
            end
        end
    end
    // Prefer unused lines, then the least frequently reused line.
    // Rotating the scan origin distributes ties across the cache.
    always @(*) begin
        victim_index = replacement_cursor;
        invalid_found = 1'b0;
        lowest_score = MAX_SCORE;
        replacement_line = 0;
        for (replacement_step = 0; replacement_step < ENTRIES;
             replacement_step = replacement_step + 1) begin
            replacement_line = replacement_cursor + replacement_step;
            if (replacement_line >= ENTRIES)
                replacement_line = replacement_line - ENTRIES;
            if (!line_valid[replacement_line]) begin
                if (!invalid_found)
                    victim_index = replacement_line[INDEX_W-1:0];
                invalid_found = 1'b1;
            end else if (!invalid_found &&
                         score_mem[replacement_line] < lowest_score) begin
                victim_index = replacement_line[INDEX_W-1:0];
                lowest_score = score_mem[replacement_line];
            end
        end
    end
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (request_valid) begin
                    response_key <= request_key;
                    state <= LOOKUP;
                end
            end
            LOOKUP: begin
                if (hit_found) begin
                    response_value <= value_mem[hit_index];
                    if (score_mem[hit_index] != MAX_SCORE)
                        score_mem[hit_index] <= score_mem[hit_index] + 1'b1;
                    state <= RESPONSE;
                end else begin
                    state <= NORMALIZE;
                end
            end
            NORMALIZE: begin
                response_value <= normalized_value;
                for (update_line = 0; update_line < ENTRIES;
                     update_line = update_line + 1) begin
                    if (update_line == victim_index) begin
                        key_mem[update_line] <= response_key;
                        value_mem[update_line] <= normalized_value;
                        line_valid[update_line] <= 1'b1;
                        score_mem[update_line] <=
                            {{(SCORE_W-1){1'b0}}, 1'b1};
                    end else if (line_valid[update_line] &&
                                 score_mem[update_line] != 0) begin
                        score_mem[update_line] <= score_mem[update_line] - 1'b1;
                    end
                end
                if (victim_index == LAST_LINE)
                    replacement_cursor <= {INDEX_W{1'b0}};
                else
                    replacement_cursor <= victim_index + 1'b1;
                state <= RESPONSE;
            end
            RESPONSE: begin
                if (response_ready)
                    state <= IDLE;
            end
        endcase
    end
endmodule

module ntt_stage_profile #(
    parameter W = 16,
    parameter NBF = 12,
    parameter BANKS = 4
) (
    input  wire clk,
    input  wire sample_enable,
    input  wire sample_valid,
    output wire sample_ready,
    input  wire [W-1:0] sample_pos,
    input  wire [W-1:0] sample_stage,
    input  wire [W-1:0] sample_a,
    input  wire [W-1:0] sample_b,
    input  wire report_ready,
    output reg report_valid,
    output reg [W-1:0] report_stage,
    output reg [BANKS*W-1:0] report_min,
    output reg [BANKS*W-1:0] report_max,
    output reg [BANKS*W-1:0] report_sum,
    output reg [BANKS*W-1:0] report_distance,
    output reg [BANKS*W-1:0] report_signature,
    output reg [BANKS*$clog2((NBF+BANKS-1)/BANKS+1)-1:0] bank_samples
);
    localparam COUNT_W = $clog2((NBF+BANKS-1)/BANKS+1);
    localparam BANK_W = $clog2(BANKS);
    reg [W-1:0] live_min [0:BANKS-1];
    reg [W-1:0] live_max [0:BANKS-1];
    reg [W-1:0] live_sum [0:BANKS-1];
    reg [W-1:0] live_distance [0:BANKS-1];
    reg [W-1:0] live_signature [0:BANKS-1];
    reg [COUNT_W-1:0] samples [0:BANKS-1];
    reg [W-1:0] snap_min [0:BANKS-1];
    reg [W-1:0] snap_max [0:BANKS-1];
    reg [W-1:0] snap_sum [0:BANKS-1];
    reg [W-1:0] snap_distance [0:BANKS-1];
    reg [W-1:0] snap_signature [0:BANKS-1];
    wire [BANK_W-1:0] selected = sample_pos % BANKS;
    wire end_stage = (sample_pos == NBF - 1);
    wire fire = sample_valid && sample_ready;
    wire [W-1:0] pair_min = (sample_a < sample_b) ? sample_a : sample_b;
    wire [W-1:0] pair_max = (sample_a > sample_b) ? sample_a : sample_b;
    wire [W-1:0] pair_sum = sample_a + sample_b;
    wire [W-1:0] pair_distance = (sample_a >= sample_b) ?
        (sample_a - sample_b) : (sample_b - sample_a);
    wire [W-1:0] rotated_b = {sample_b[W-2:0], sample_b[W-1]};
    wire [W-1:0] next_signature =
        {live_signature[selected][W-2:0], live_signature[selected][W-1]} ^ sample_a ^ rotated_b;
    reg [W-1:0] next_min;
    reg [W-1:0] next_max;
    reg [W-1:0] next_sum;
    reg [W-1:0] next_distance;
    integer init_bank;
    integer pack_bank;
    integer write_bank;
    assign sample_ready = sample_enable &&
        (!end_stage || !report_valid || report_ready);
    initial begin
        report_valid = 1'b0;
        report_stage = 16'd0;
        for (init_bank = 0; init_bank < BANKS; init_bank = init_bank + 1) begin
            live_min[init_bank] = 16'd0;
            live_max[init_bank] = 16'd0;
            live_sum[init_bank] = 16'd0;
            live_distance[init_bank] = 16'd0;
            live_signature[init_bank] = 16'd0;
            samples[init_bank] = {COUNT_W{1'b0}};
            snap_min[init_bank] = 16'd0;
            snap_max[init_bank] = 16'd0;
            snap_sum[init_bank] = 16'd0;
            snap_distance[init_bank] = 16'd0;
            snap_signature[init_bank] = 16'd0;
        end
    end
    always @(*) begin
        next_min = (samples[selected] == 0 || pair_min < live_min[selected]) ?
            pair_min : live_min[selected];
        next_max = (samples[selected] == 0 || pair_max > live_max[selected]) ?
            pair_max : live_max[selected];
        next_sum = live_sum[selected] + pair_sum;
        next_distance = live_distance[selected] + pair_distance;
    end
    always @(*) begin
        for (pack_bank = 0; pack_bank < BANKS; pack_bank = pack_bank + 1) begin
            report_min[pack_bank*W +: W] = snap_min[pack_bank];
            report_max[pack_bank*W +: W] = snap_max[pack_bank];
            report_sum[pack_bank*W +: W] = snap_sum[pack_bank];
            report_distance[pack_bank*W +: W] = snap_distance[pack_bank];
            report_signature[pack_bank*W +: W] = snap_signature[pack_bank];
            bank_samples[pack_bank*COUNT_W +: COUNT_W] = samples[pack_bank];
        end
    end
    always @(posedge clk) begin
        if (report_valid && report_ready)
            report_valid <= 1'b0;
        if (fire) begin
            if (end_stage) begin
                report_valid <= 1'b1;
                report_stage <= sample_stage;
            end
            for (write_bank = 0; write_bank < BANKS; write_bank = write_bank + 1) begin
                if (end_stage) begin
                    snap_min[write_bank] <= (write_bank == selected) ?
                        next_min : live_min[write_bank];
                    snap_max[write_bank] <= (write_bank == selected) ?
                        next_max : live_max[write_bank];
                    snap_sum[write_bank] <= (write_bank == selected) ?
                        next_sum : live_sum[write_bank];
                    snap_distance[write_bank] <= (write_bank == selected) ?
                        next_distance : live_distance[write_bank];
                    snap_signature[write_bank] <= (write_bank == selected) ?
                        next_signature : live_signature[write_bank];
                    live_min[write_bank] <= 16'd0;
                    live_max[write_bank] <= 16'd0;
                    live_sum[write_bank] <= 16'd0;
                    live_distance[write_bank] <= 16'd0;
                    live_signature[write_bank] <= 16'd0;
                    samples[write_bank] <= {COUNT_W{1'b0}};
                end else if (write_bank == selected) begin
                    live_min[write_bank] <= next_min;
                    live_max[write_bank] <= next_max;
                    live_sum[write_bank] <= next_sum;
                    live_distance[write_bank] <= next_distance;
                    live_signature[write_bank] <= next_signature;
                    samples[write_bank] <= samples[write_bank] + 1'b1;
                end
            end
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter MON_BANKS = 4,
    parameter TW_ENTRIES = 4,
    parameter TW_SCORE_W = 2
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output reg  [31:0]  debug_status,
    output wire         stage_stats_valid,
    output wire         stage_stats_take,
    output wire         stage_stats_blocked,
    output wire [W-1:0] stage_stats_stage,
    output wire [MON_BANKS*W-1:0] stage_stats_min,
    output wire [MON_BANKS*W-1:0] stage_stats_max,
    output wire [MON_BANKS*W-1:0] stage_stats_sum,
    output wire [MON_BANKS*W-1:0] stage_stats_distance,
    output wire [MON_BANKS*W-1:0] stage_stats_signature,
    output wire tw_busy,
    output wire [1:0] tw_state,
    output wire [W-1:0] tw_key,
    output wire [W-1:0] tw_value,
    output wire [TW_ENTRIES-1:0] tw_cache_valid,
    output wire [TW_ENTRIES*W-1:0] tw_cache_keys,
    output wire [TW_ENTRIES*W-1:0] tw_cache_values,
    output wire [TW_ENTRIES*TW_SCORE_W-1:0] tw_cache_scores,
    output wire [$clog2(TW_ENTRIES)-1:0] tw_replacement
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam MON_COUNT_W = $clog2((NBF+MON_BANKS-1)/MON_BANKS+1);
    localparam MON_TOTAL_W = $clog2(NBF+1);

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire tw_request_valid = !head_valid && !q_empty;
    wire tw_request_ready;
    wire tw_response_valid;
    wire tw_response_take = ce && !head_valid && tw_response_valid;
    wire start = ce && head_valid && !busy && !out_valid;
    wire diag_ready;
    wire [MON_BANKS*MON_COUNT_W-1:0] diag_samples;
    wire run_cycle = ce && (!last || diag_ready);
    wire retire = busy && last && diag_ready;
    assign stage_stats_blocked = busy && last && !diag_ready;
    assign stage_stats_take = stage_stats_valid && out_ready && !out_valid;

    wire [W-1:0] multiplier_b =
        (w_r == 16'd0 || w_r == 16'd1) ? {W{1'b0}} : b_r;
    wire [31:0] prod = w_r * multiplier_b;
    wire [31:0] reduction_input = (w_r == 16'd1) ? b_r : prod;
    wire [W-1:0] t = reduction_input % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    ntt_twiddle_cache #(
        .W(W),
        .Q(Q),
        .ENTRIES(TW_ENTRIES),
        .SCORE_W(TW_SCORE_W)
    ) twiddle_cache (
        .clk(clk),
        .request_valid(ce && tw_request_valid),
        .request_ready(tw_request_ready),
        .request_key(q_w[head_slot]),
        .response_ready(ce && !head_valid),
        .response_valid(tw_response_valid),
        .busy(tw_busy),
        .response_key(tw_key),
        .response_value(tw_value),
        .state(tw_state),
        .line_valid(tw_cache_valid),
        .line_keys(tw_cache_keys),
        .line_values(tw_cache_values),
        .line_scores(tw_cache_scores),
        .replacement_cursor(tw_replacement)
    );
    ntt_stage_profile #(
        .W(W),
        .NBF(NBF),
        .BANKS(MON_BANKS)
    ) stage_profile (
        .clk(clk),
        .sample_enable(ce),
        .sample_valid(busy && last),
        .sample_ready(diag_ready),
        .sample_pos(bf_idx),
        .sample_stage(stage),
        .sample_a(sum_mod),
        .sample_b(dif_mod),
        .report_ready(out_ready && !out_valid),
        .report_valid(stage_stats_valid),
        .report_stage(stage_stats_stage),
        .report_min(stage_stats_min),
        .report_max(stage_stats_max),
        .report_sum(stage_stats_sum),
        .report_distance(stage_stats_distance),
        .report_signature(stage_stats_signature),
        .bank_samples(diag_samples)
    );
    reg [MON_TOTAL_W-1:0] diag_sample_total;
    integer diag_bank;
    always @(*) begin
        diag_sample_total = {MON_TOTAL_W{1'b0}};
        for (diag_bank = 0; diag_bank < MON_BANKS; diag_bank = diag_bank + 1)
            diag_sample_total = diag_sample_total +
                diag_samples[diag_bank*MON_COUNT_W +: MON_COUNT_W];
    end
    reg [15:0] stat_accept = 16'd0;
    reg [15:0] stat_retire = 16'd0;
    reg [15:0] stat_inwait = 16'd0;
    reg [15:0] stat_outwait = 16'd0;
    reg [15:0] stat_busy = 16'd0;
    reg [15:0] stat_stall_run = 16'd0;
    reg [15:0] stat_stall_max = 16'd0;
    reg [PTR_W-1:0] stat_high_water = {PTR_W{1'b0}};
    reg [3:0] stat_events = 4'd0;
    reg [2:0] stat_page = 3'd0;
    reg [W-1:0] stat_last_lat = {W{1'b0}};
    reg [7:0] stat_epoch = 8'd0;
    reg [15:0] stat_checksum = 16'd0;
    initial begin
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (load_cfg) begin
            stat_epoch <= stat_epoch + 8'd1;
            stat_last_lat <= cfg_lat;
        end
        if (accept && stat_accept != 16'hffff)
            stat_accept <= stat_accept + 16'd1;
        if (retire && stat_retire != 16'hffff)
            stat_retire <= stat_retire + 16'd1;
        if (in_valid && !in_ready && stat_inwait != 16'hffff)
            stat_inwait <= stat_inwait + 16'd1;
        if (out_valid && !out_ready && stat_outwait != 16'hffff)
            stat_outwait <= stat_outwait + 16'd1;
        if (busy && ce && stat_busy != 16'hffff)
            stat_busy <= stat_busy + 16'd1;
        if (queued > stat_high_water)
            stat_high_water <= queued;
        if (accept)
            stat_checksum <= {stat_checksum[14:0], stat_checksum[15]} ^ in_a ^ in_b ^ in_w;
        if (out_valid && !out_ready) begin
            if (stat_stall_run != 16'hffff)
                stat_stall_run <= stat_stall_run + 16'd1;
            if (stat_stall_run >= stat_stall_max && stat_stall_run != 16'hffff)
                stat_stall_max <= stat_stall_run + 16'd1;
        end else begin
            stat_stall_run <= 16'd0;
        end
        if (in_valid && !in_ready)
            stat_events[0] <= 1'b1;
        if (out_valid && !out_ready)
            stat_events[1] <= 1'b1;
        if (accept && !ce)
            stat_events[2] <= 1'b1;
        if (load_cfg && busy)
            stat_events[3] <= 1'b1;
        if (ce) begin
            stat_page <= stat_page + 3'd1;
            case (stat_page)
                3'd0: debug_status <= {stat_retire, stat_accept};
                3'd1: debug_status <= {stat_outwait, stat_inwait};
                3'd2: debug_status <= {stat_stall_max, stat_stall_run};
                3'd3: debug_status <= {stat_checksum, stat_busy};
                3'd4: debug_status <= stat_high_water;
                3'd5: debug_status <= stat_last_lat;
                3'd6: debug_status <= {20'd0, stat_epoch, stat_events};
                3'd7: debug_status <= {24'd0, ce, busy, head_valid, q_full, q_empty, out_valid, in_valid, in_ready};
            endcase
        end
    end
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (tw_response_take) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= tw_value;
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && run_cycle) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (start)
            assert (tw_key == q_w[head_slot] && w_r == tw_key % Q);
    end

    always @(posedge clk) begin
        if (retire)
            assert (diag_sample_total == bf_idx);
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule
